// @ts-nocheck
/* ⚠ 自动生成，勿手改 —— 源：client/prototype/snowlab.html
   重新生成：python client/tools/extract_snowlab_runtime.py

   这是雪人兄弟式关卡的**引擎无关运行时**（物理 / 关卡生成 / 裹球 / 推球 / 绘制）。
   绘制原样保留：一套 Canvas 2D 代码（960x600）。SnowlabBattle 开一块
   960x600 的离屏 canvas 喂进来，再把这块 canvas 作为 **DOM 层**铺在 Cocos
   画布上面 —— 不走 Cocos 渲染管线（为什么这么做见 SnowlabBattle 文件头，
   和 GroveBattle 是同一个理由：Battle 场景里一个 Canvas / RenderRoot2D 都没有）。

   **为什么整份文件 `@ts-nocheck`：**
   源是手写的原型（7000 行、几百个未标注形参）。按 strict 打开会立刻刷出
   1500+ 条 implicit-any，把真正的错误埋掉 —— 这正是 `runtime-sanity.js` 当年
   单开一道、只守 TS2304 那四个致命码的原因。这里的信任链换成两条更好用的：
     · `tools/snowlab-runtime-check.js`：把本文件编译出来真跑 900 帧，
       和 html 版逐帧对坐标（同一个种子必须一像素不差）
     · `tools/_snowlab-check.js`（226 项）：断言的仍然是同一份玩法源码

   导出：
     snowlabAttachCanvas(canvas)  绑定画布（顺带按 dpr 放大后备缓冲）
     snowlabBoot(seed?)           开局。seed 不给 = 随机
     snowlabTick(dt) / snowlabRender()   每帧推进 / 绘制
     SNOWLAB                      调试导出，和浏览器里的 window.SNOWLAB 同一份
   ========================================================================= */

"use strict";

import { INLINE_ART } from './SnowlabArt';

/* ===========================================================================
   PAWPACK · 随机箱洞试验台
   ---------------------------------------------------------------------------
   **这个文件不是游戏，是量具。**

   任务只有一件：把「吐雪 → 裹成球 → 推球砸箱 → 砸开箱墙见到门」这一条闭环
   跑起来，并且把三个数当场量出来：

     ① 裹一只怪平均几发   ② 碎一口箱几发   ③ 一颗球撞碎几个箱

   为什么单开一个文件、不直接改 grove.html：主线 21599 行、27 屏、1463 项冒烟
   断言，而这一版动的是**输入通道**（近身糊 → 远程吐）和**资源模型**（球额度 →
   弹药），两处都在主线最底层。先在试验台把数值跑顺，再决定要不要搬。

   数值全部集中在下方的 NUM 表里，改表就能重跑，不用翻代码。

   ---------------------------------------------------------------------------
   这一版长什么样（2026-10-28 重做）
   ---------------------------------------------------------------------------
   **Q 版卡通地牢，不是雪洞。** 调色板全是亮暖色（木 / 砖 / 石 / 地窖四种房间
   主题，每层换一种），所有实体统一 3px 暖褐描边 —— 描边比配色更决定"Q 不 Q"：
   箱子铺满整层后，没有描边的色块会连成一片砖墙，玩家读不出"这是一口一口
   独立的箱子"，也就读不出"能拆"。

   **箱子是主角，不是装饰。** 关卡从"手写坐标"改成"程序生成"之后，
   箱子不是撒出来的，是砌出来的：先算一张 20 列的堆高图，再按图生成。
   一关平均 114 口，每层中位 28 口。它们同时是墙、是路、是盖子：
     峰值封顶 3 格（144px）—— 站上去头顶 186，不顶 200 的净空；
     相邻列高差 ≤2 格（96px）—— 小于跳高 123，整片箱山都爬得上去；
     上行只能走洞口：洞正下方一列 3 格（井梯）+ 按 W 爬上去。
        （光跳不行 —— 洞是镂空的，跳上去正好落回洞里。见 wellClimb 的注释）

   **层数 3~5（4 层占一半）。** 4~8 层时每层的箱子会被摊薄，越深越空，
   正好和"很多木箱"相反。

   **探索必须有确定的回报。** 金箱必掉一片雪之碎片，HUD 常驻「宝物 x / y」，
   玩家能知道自己还漏了几个。随机掉落做不到这件事。
   =========================================================================== */

/* ---------------------------------------------------------------- 画布 */
const W = 960, H = 600;
/* 画布由 SnowlabBattle 通过 snowlabAttachCanvas 注入；jsdom / 断言里可以是 null，
   那种情况下 draw() 第一行就 return —— 逻辑和渲染因此可以分开验。 */
let cv: any = null;
let ctx: any = null;

/* ---------------------------------------------------------------- 数值表
   全部可调。改这里，不碰逻辑。 */
const NUM = {
  /* 弹药。用户 2026-10-28 拍板：单关初始 100 发。
     这个数看着宽裕，其实是**刚好卡住**的：
     6 只怪 × 6 发（满饱）+ 16 口木箱 × 3 发 = 84 发，只剩 16。
     也就是说「全用子弹开路」这条路走不到头，必须靠球省。 */
  ammoStart: 100,

  /* 裹成球要几发。三档饱食度。
     ** 6 / 4 的倒挂是待验证的疑点 **：饱的时候反而更费，说不过去。
     先按用户拍的值跑，跑完看手感再定。HUD 会实时显示当前档位的发数。 */
  snowShots: { full: 6, half: 4, hungry: 10 },

  bellyStart: 100,
  bellyFull: 70,          // ≥70 = 满饱
  bellyHalf: 35,          // ≥35 = 半饱，以下 = 全饿
  bellyPerBall: 14,       // 造一颗球掉多少
  bellyPerShard: 20,      // 吃一片雪之碎片回多少

  /* 吐雪投掷物。**2026-10-29 用户第 3 条：「我方单位的子弹 射程需要远点
     并且要有特色 符合宠物的特征 丢出去是下落的 类似横向丢出去的石头」**

     上一版是 speed 620 × life 0.24 = **149px 的一根直线**，短、平、六只共用一套。
     而主线 `grove.html` 的 `HEROES` 里六只**各有各的武器**（溜溜球 / 音波 /
     坚果 / 萝卜 / 飞刀 / 影子）—— 那是 10-20 就做好了的，我在 snowlab 里
     重写时丢了。用户问「为啥代码要单独写 不能兼并能融合吗」，指的就是这个。

     **为什么没有把 grove 那六把武器原样搬过来**：grove 的武器是"直接伤害"，
     而 snowlab 的子弹只干一件事 —— 给敌人加雪点，满 6 发裹成球。
     搬伤害会绕开裹球，整条玩法断掉。所以只搬两样：
     ① 抛物线的飞行方式；② "每只长得不一样"的识别度。

     弹道：横向初速 + 轻微上扬 + 重力下坠。
     `vy0 = -80 / g = 520` 是从"同高度还能打中多远"倒推的 ——
     子弹掉到敌人胸口（≈30px）时 x 已经走了 327px，是原来的 2.2 倍。
     再远就砸地：射程有上限，但不再需要贴脸。 */
  shot: {
    cd: 0.16,
    lock: 0.14,        // 出手时锁移动：这是「喷的代价」，连喷 = 站桩
    /* 每只一套。**靠飞行方式区分，不靠配色区分** ——
       缩到 8px 的子弹上涂什么颜色都一样，但"走直线"和"甩弧线"一眼分得开。
       参数从 grove 的六把武器继承手感（刀最快最直、萝卜最远、坚果最重）。 */
    pets: {
      cat: { speed: 620, life: 0.62, vy0: -80, grav: 520, r: 8,  kind: 'yoyo'   },
      dog: { speed: 700, life: 0.55, vy0: -60, grav: 400, r: 9,  kind: 'bone'   },
      ham: { speed: 520, life: 0.90, vy0: -40, grav: 620, r: 10, kind: 'nut'    },
      rab: { speed: 760, life: 0.75, vy0: -50, grav: 380, r: 8,  kind: 'carrot' },
      ox:  { speed: 820, life: 0.50, vy0: -30, grav: 300, r: 9,  kind: 'knife'  },
      fox: { speed: 680, life: 0.45, vy0: -30, grav: 360, r: 7,  kind: 'shadow' },
    },
  },

  /* 球。半径沿用 grove 的 22 + 2.8/点，上限提到 +24。
     两点 = 一只怪的量；**砸碎一口箱子算 2.0 点，也就是大半只怪** ——
     用户 2026-10-28：「球砸箱子 球是不能变大的」，他要的是砸箱有即时回报。
     每档之间必须拉开肉眼能分辨的差距（冰墙只认特大球，读不出档位就无从计划）。 */
  ball: { baseR: 22, perAbsorb: 2.8, maxAbsorb: 24, life: 16, fric: 260, maxR: 46,
          /* **life 4.6 → 16（2026-10-28）。**
             用户问「成球之后怎么推呢」—— 查下来一半是没提示，另一半是
             **根本来不及**：4.6 秒里要绕到球后面、对准方向、助跑，然后球
             自己"散了"。玩家看到的是"怪没了、球也没了"，学不到任何东西。
             16 秒够走三四个来回，"融化"只用来防止场上堆满死球。
             推一次回满（见 pushBalls），所以真正在用的球不会中途消失。 */
          /* **撞碎箱子不涨体积。**（2026-10-28 用户否掉的旧设计）
             理由两条：
               ① 常识上说不通 —— 雪球撞碎木箱，凭什么把木屑吃进去变大；
               ② 玩法上它是捷径 —— 一关一百多口箱子，砸三口就从小球变特大球，
                  「裹住敌人」这个核心操作直接被绕过，冰墙也就成了摆设。

             球唯一的长大来源是**吞掉敌人**：裹住算，被球碾死也算
             （`killFoe` 里同样加 absorbFoe）。所以"把怪杀光了会不会卡在
             冰墙前"依然有解 —— 杀怪本身就在喂球，不需要箱子来兜底。

             absorbFoe = 2.0 而不是 1.0：门厅只有 3 只怪，档位阈值是
             2 / 4 / 6，裹一只是"中"、两只才"大"。1.0 的时候门厅攒不出
             能破冰墙的球 —— 这是数值上过不去，不是玩家操作问题。 */
          absorbFoe: 2.0, absorbBox: 0,

          /* **落砸的起判速度（2026-10-28 第四轮）。**
             用户：「球掉下去 是可以杂碎箱子」。
             球停在地上时 vy 是 0（落地那一帧就被清零），所以"落到箱顶上
             砸不砸"完全可以由 vy 判：320 对应一次 24px 以上的真实下落，
             "从箱子边缘滚下去"（48px 落差、落地 vy 449）稳稳过线，
             而"在箱顶滚"（vy 恒 0）永远不过线 —— 不需要额外的状态位。
             落 240px（一层）的 vy 是 1004：木箱必碎、石箱（560）必碎、
             铁箱（1150）不会碎，正好把"什么材质的箱顶能落球"读出来。 */
          crushVy: 320 },

  /* 推球力度。沿用 grove 的 620 → 1209（助跑满格约 380px）。 */
  push: { base: 620, runGain: 0.95, runFull: 380 },

  /* 玩家跳跃。**`airJump` = 空中还能再跳几次**（2026-10-28 第二轮）。
     重力 2100、jump 720 → 单跳高 123。
     为什么是"二段跳"而不是"加高单跳"：单跳一旦到 144，所有 3 格箱山
     都能直上，"箱子是路"那套攀爬就整个失效了。见 stepPlayer 里的算术。

     **`airJumpV` 比首跳高（2026-10-28 第四轮）：790。**
     楼板改成半透层之后（能跳上去、也能按下从上面下来），"上到上一层"
     需要脚从本层地板抬到 240 —— 而 720 的二段跳只有 246，
     顶点余量 6px：必须"在第一跳的最高点按第二跳"才成立，那不是轻松，
     是帧数考试。790 的二段跳给 123 + 149 = 272，余量 32px。
     首跳不动（123），所以层内的"3 格箱山要绕"这条没被破坏。 */
  hero: { jump: 720, airJump: 1, airJumpV: 790 },

  /* 箱子。**这里是整套材质系统的核心表**：
     hp        = 子弹要几发才碎（Infinity = 子弹完全无效）
     minPow    = 球要多大的动量才能砸碎（0 = 随便推都碎）
     keepSpeed = 砸碎后球保留多少速度（穿透感就靠这一列）
     minTier   = 球至少要几档（0小 1中 2大 3特大）

     **冰墙的 minTier 从 2 降到 1（2026-10-28），是一次"弹药算术"修正。**
     球只有两个来源：裹住敌人（一颗球 = 一只怪）、球撞死敌人（+2 体积）。
     一关平均 6.8 只怪，门厅固定 3 只。要求 tier 2（absorbed ≥ 4）意味着
     **一颗能破冰的球要吃 3 只怪**（裹 1 + 撞死 2）—— 门厅的怪刚够造一颗，
     容错为零：玩家先用雪弹打死一只、或者让一只怪掉进洞里、或者球没撞准，
     就直接死局，而门上没有任何补救办法。
     改成 tier 1（absorbed ≥ 2，1 裹 + 1 撞 = 2 只怪一颗），门厅留一只余量。
     门槛的意义没变 —— 新球的本金是 1，仍然**必须吞掉一只敌人才够档**，
     "球再大点才行"照样会弹出来教玩家。 */
  box: {
    wood:  { hp: 3,        minPow: 0,    keepSpeed: 0.82, minTier: 0, name: '木箱' },
    stone: { hp: Infinity, minPow: 560,  keepSpeed: 0.46, minTier: 0, name: '石箱' },
    iron:  { hp: Infinity, minPow: 1150, keepSpeed: 0.30, minTier: 0, name: '铁箱' },
    ice:   { hp: Infinity, minPow: 1550, keepSpeed: 0.36, minTier: 1, name: '冰墙' },
  },

  /* 掉弹。**这一列是「用球才回本」的唯一实现**：
     木箱被子弹砸碎几乎不回本（10%），被球砸碎才值钱（40%）。
     不靠 HP 磨，靠掉率拉价值差 —— 玩家自己会算出来，不用教。 */
  drop: {
    shardByBall: 0.40,
    shardByShot: 0.10,
    shardAmmoMin: 3,
    shardAmmoMax: 5,
  },

  /* **3 只，不是杀光。** 两件事同时成立才行：
     ① 怪分布在三层，要求杀光会逼玩家返回上层找漏网的 —— 那是「返程」不是「探索」；
     ② **必须 <= 底层怪数**。这关是单向往下的（掉下去就上不来），
        玩家一路不杀直接挖到底，手上就只剩底层的怪。如果底层只有 2 只
        而目标是 4，门永远开不了 = 死局。底层放 3 只，门槛写 3，卡不住。 */
  killTarget: 3,
  hpStart: 3,
  hpInvuln: 1.2,

  /* 贴脸保底：跑动中撞上敌人，自己掉 1 血、敌人吃 2 点雪。
     零弹时的唯一出路，代价是血 —— 保底是**机制**，不是系统施舍。 */
  bodyCoat: 2,

  /* ---------------- 敌方品种 ----------------
     用户 2026-10-28：「宠物可以简单跳跃 一个箱子的高度走动待机」「宠物太少了
     没有发射子弹攻击的地方」「单位的子弹要符合宠物特点 小兔子丢萝卜
     狗狗是骨头 射程需要远点 还有一个子弹平行丢出去 需要有下落感」。

     **同一天下午改口**：「敌方为什么用我方的宠物呢」。这句话订正了上一版的
     方向：兔 / 狗 / 刺猬是**我方**的宠物形象，不该出现在敌方阵列里。
     所以这一层叫 `breed`（品种）不叫 `pet`，三只都是**敌人**：

       · `moss` 苔泥团 —— 矮胖、一撮苔草、慢；扔泥球
       · `fang` 尖牙兽 —— 低伏四足、前突长口鼻、跑得快；甩牙
       · `grub` 霜甲虫 —— 分节硬壳、六条小腿、背上一排冰棱；弹冰锥

     上一版靠"耳朵竖 / 垂 / 一圈刺"区分，那是**萌宠**的做法。
     敌人要靠**轮廓的体块关系**区分：圆团 / 横向拉长 / 拱起的硬壳 ——
     缩到 34px 时，这三者的外轮廓没有一处是重合的。

     **三个字段管三件事，各管各的：**
       · `jump`  起跳初速。重力 2100 → 520 跳 64px，刚好一个箱子（48）富余
       · `cdA/B` 两次射击的间隔区间（秒）。只用来**拉开节奏**，不用来控难度
       · `range` 水平射界。投掷物会掉，太远根本打不到，所以它要跟
                 `ebullet` 的射程一起看，不能单独调 */
  /* ---- 三种敌人，**三套动法** ------------------------------------------
     用户 2026-10-28 的原话：「不希望（上下跳动） 有的可以跳 要适配啊
     那种很多脚的昆虫只适合爬 有的可以跳下　我只是举例子　要你自己去创新设计」。

     所以 `gait` 不是一个"性格参数"，是**从体态推出来的必然结果**：
     长着四条腿的东西才会跳，长着十几条腿的东西只能贴地爬，
     一条腿都没有的东西既不会走也不会跳。

     以前三只共用一套"走路 + 遇坎就跳"，于是**多足甲虫在箱堆上蹦来蹦去**，
     比它的体态先出卖了自己。现在按体态分：

       moss 轮状苔藓团 · slide · 无腿 → 贴地滑，靠身体前倾推进，草叶拖在后面
       fang 四足尖牙兽 · run   · 有腿 → 跑，遇坎起跳（唯一会跳的）
       grub 多足霜甲虫 · crawl · 多足 → 贴地爬，**不跳**；20px 以内的坎直接蹭上去

     `jump: 0` 就是"这条腿不会跳"，物理层见到它就不起跳（不再有
     "多足甲虫原地弹跳"这种和自己体态打架的动作）。 */
  breed: {
    moss: { speed: 84,  jump: 0,   gait: 'slide', cdA: 1.9, cdB: 2.9, range: 300, bullet: 'mud'   },
    fang: { speed: 148, jump: 545, gait: 'run',   cdA: 1.5, cdB: 2.3, range: 350, bullet: 'tooth' },
    grub: { speed: 100, jump: 0,   gait: 'crawl', cdA: 2.3, cdB: 3.3, range: 270, bullet: 'shard' },
  },
  /* 爬行类的"蹭坎"高度：多足贴地爬，20px 以内的矮坎不需要跳，
     身体一抬就过去了。再高就掉头 —— 甲虫翻不过一整个箱子，这是对的。 */
  crawlStep: 20,

  /* 敌方投掷物。**"平行丢出去 + 有下落感"是靠这三条实现的：**
       ① 水平初速恒定（不瞄准玩家 —— 会瞄准就没有"侧身躲开"这个动作了）
       ② `vy0 = -60` 轻轻上扬，让弹道先平后坠，读起来像"被扔出去"
       ③ `g = 210` 只有角色的 1/10

     **数值是解方程解出来的，不是拍的。** 约束是"从离地 24px 的高度扔出去，
     落地时水平走了 300px 上下，途中明显下垂"。g 用 2100（玩家重力）的话，
     0.4 秒就砸在脚边，所谓"射程"根本不存在；g 太小又读不出弧线。
     210 的时候：先平着出去，顶点只比出手点高 9px（60²/(2·210)），
     之后一路加速下坠 —— 这正是"平行丢出去、但有下落感"该有的样子。

     `spd` 三档：泥球慢（苔泥团抛得重）、牙最快（尖牙兽甩头甩出去）、
     冰锥居中。弹速和形状一起变，才叫"这东西是它扔的"。 */
  ebullet: {
    spd: { mud: 330, tooth: 420, shard: 380 },
    vy: -60, g: 210, life: 2.4, r: 9, windup: 0.42, maxAlive: 7,
  },
};

/* ---------------------------------------------------------------- 工具 */
const clamp = (v, a, b) => v < a ? a : v > b ? b : v;
const sign = v => v < 0 ? -1 : 1;
const rnd = (a, b) => a + Math.random() * (b - a);
function rr(g, x, y, w, h, r) {
  r = Math.min(r, w / 2, h / 2);
  g.beginPath();
  g.moveTo(x + r, y);
  g.arcTo(x + w, y, x + w, y + h, r);
  g.arcTo(x + w, y + h, x, y + h, r);
  g.arcTo(x, y + h, x, y, r);
  g.arcTo(x, y, x + w, y, r);
  g.closePath();
}

/* ---------------------------------------------------------------- 关卡
   **随机生成的纵向下行关，层数 4~8，每层一个箱室。**

   用户 2026-10-28 的三次反馈连起来看是一条线：
     ① 「箱子明显不够，空间设计感太简陋，只能体会到一颗球在砸一个箱子」
     ② 「层与层太远了，你可以设置很多层，有很多木箱」
     ③ 「L1 到 L6 应该是随机布局吧，首先不一定是 6 层，其次也有可能有斜坡，
        而且每层不一定只有一个出口去下一层，可以灵活空间设计」

   ①的答案是纵深，②的答案是很多层 × 240，③的答案是**别再手写坐标**。
   手写坐标只能手写出一张图；要"灵活"，就得让关卡是算出来的：

     · 层数 4~8 随机，层高锁死 240
     · 每层 1~2 个下行口（34% 的层给两个），位置在三个槽位里随机
     · 下行口三种封法：覆霜木箱 / 冰墙 / 敞开（敞开的要自己看出来）
     · 每层地形 1~2 组：平台 + 配套坡（能直接走上去，不用跳），
       或者一段孤立的雪包（上坡 + 下坡，两端都落地）
     · 箱子 9~13 口一层，越深越硬；每层 1~3 只怪
     · 门厅的门位置也随机，外面裹两列冰

   **层高必须锁死 240，这是全关唯一不能随机的数。**
   净空 = 240 − 板厚 40 = 200；玩家高 42、跳高 123。站在 h 高的箱子上
   想上到上一层，起跳空间 (200−h−42)，需要上升 (240−h)，两者**恒差 82** ——
   与层高取值无关。

   **所以"能上能下"只能靠洞口 + 井梯，不能靠堆箱子。**（2026-10-28 加）
   上一层地板上那个洞就是唯一的上行通道：洞正下方必须有一列摞到 3 格
   （144），144 + 123 = 267 才越过上一层地板（240）。但洞是**镂空**的，
   光能跳上去没用 —— 落点正好在洞里，还是会掉回来。真正的上行靠两件事：
     ① 洞口正下方那一列 3 格箱堆（井梯），旁边各垫 1 格当台阶；
     ② 站在梯顶按 W 就"爬"上去（`wellClimb`），不是跳。
   门厅不做井梯（见生成器里 wells 的注释）。

   **随机和可解是两件平行的事。** 生成器出图之后必须过 `validateLevel()`：
   相邻两层的洞不能重叠（否则一穿两层）、每个洞正下方必须接得住（否则
   掉进下一层的洞里连环坠）、地形不能盖住本层的出口、地表出生点不能悬空、
   门厅怪数必须够 killTarget、怪不能生在雪包里（会永久卡在坡体内）。
   不过就换种子重掷，最多 80 次。随机负责新鲜，校验负责不死局。

   **"放之前先验，别放完再筛"** —— 地形按"平台 + 配套坡"整段验，箱子给坡让位，
   怪先枚举整层的可站点再抽。这三条都是同一个教训：事后过滤会把能用的东西
   一起扔掉，数量直接塌（坡从 2.4 条/关掉到 1.3 条就是这么来的）。
   ---------------------------------------------------------------- */

const WALL_L = 24, WALL_R = 936;

const GEN = {
  topY: 340,          // 地表地板高度
  floorH: 240,        // 层高（不可随机，见上）
  /* **楼板 40 → 20。** 40px 的板在画面上是一条又厚又长的褐色横梁，
     几乎整屏不间断，看着像天花板压下来（用户 2026-10-28 截图圈的正是它）。
     20px 才是"楼板"该有的厚度。
     顺带把净空从 200 抬到 220：井梯 3 格 144 + 身高 42 = 186，
     剩下 28px 头顶空间，爬梯时不再贴着脸。
     先试过 20 —— 在 960 宽的画面上细得像一条胶带，反而显得廉价。
     26 是"看得出是一块板、又不是横梁"的那一档。 */
  thick: 26,
  /* **层数收到 3~5，而且 4 层占一半。**
     4~8 层的时候，每层只够塞十来口箱子：层数越多的关越空，
     "很多木箱"和"随机层数"直接打架。现在改成少而厚 ——
     层数少了，同样的箱子预算就能在每层堆出真正的箱山。 */
  minFloors: 3,
  maxFloors: 5,
  /* 三个下行口槽位，48 对齐，**槽与槽之间留 72px 空档**。
     相邻两层不能共用槽位 —— 共用就有概率让上下两个洞的 x 重叠，
     人从上面掉下来直接穿过下面那个洞，一次掉两层。
     空档是第二道保险：槽紧挨着的话（比如 336 结束、336 开始），
     两层的洞会正好贴边，加上"玩家宽 30"的安全余量照样算重叠。 */
  slots: [[48, 288], [360, 600], [672, 912]],
};

let WORLD_H = 1580, GROUND_Y = 1540;
let FLOORS = [], LAYER_CN = [], HOLES = [], LAYERS = [];
/* **怪物自己的随机源**（巡逻换向的间隔、初始朝向）。
   原来这里写的是 Math.random —— 同一个种子跑两次，怪走的路不一样，
   "出图 / 断言能复现"这条直接作废。注意 `rnd()` 也是 Math.random 的，
   它只能用于视觉（震屏、雪粒），**任何影响玩法的随机都必须过这里**。 */
let FR = () => 0.5;
let LEVEL_SEED = null;

/* mulberry32。**不能用 Math.random**：出图和断言都要能复现同一张关卡，
   否则"随机布局"等于"不可测"。 */
function rngFrom(seed) {
  let a = seed >>> 0;
  return function () {
    a = (a + 0x6D2B79F5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), 1 | t);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/** 一块实心体在 x 处的顶面高度。**斜坡是全场唯一的非矩形件**，
    其余（地板、平台、箱子）都直接返回 s.y。 */
function surfY(s, x) {
  if (!s || s.kind !== 'ramp') return s ? s.y : WORLD_H;
  const t = clamp((x - s.x) / s.w, 0, 1);
  return s.y - s.rise * t;
}

function genLevel(seed) {
  const R = rngFrom(seed);
  const ri = (a, b) => a + Math.floor(R() * (b - a + 1));
  const chance = p => R() < p;
  const pickOne = a => a[Math.floor(R() * a.length)];

  /* 3~5 层，**4 层占 50%**（3 层 25% / 5 层 25%）。
     均匀取的话"要么太多要么太少"的观感会一直在，加权之后有个默认形状。 */
  const nF = 3 + (chance(0.55) ? 1 : 0) + (chance(0.45) ? 1 : 0);
  const floors = [];
  for (let i = 0; i < nF; i++) floors.push(GEN.topY + i * GEN.floorH);

  const NAME_POOL = ['地表', '浅井', '箱室', '工坊', '门厅'];
  const layerCN = floors.map((_, k) => (k === nF - 1 ? '门厅' : NAME_POOL[Math.min(k, NAME_POOL.length - 1)]));

  /* ================= ⓪ 深度 → 难度 =================
     用户 2026-10-29：「关卡的复杂度需要有序递进」。

     **"有序"这两个字是关键，不是"越深越难"。** 原来每层参数各自掷骰子
     （`chance(0.55)` 决定多一个口、`pickOne` 决定堆多高、`chance(0.30)`
     决定有没有 runner），于是第 2 层可能比第 4 层还热闹 —— 玩家读不出
     "我在往下走"，只觉得"随机"。随机负责新鲜，**曲线负责节奏**，两者不能
     互相冒充。

     现在所有参数都从 `tierOf(k)` 这一个数来：0 = 地表，1 = 门厅。
     它只做一次除法，但从此"这一层该有多难"只有一个答案，
     断言也能直接验：`tier[k+1] > tier[k]`，且各项难度指标单调不降。

     **tier 只是"难度预算"，不是"层数"。** 3 层和 5 层的一关，
     tier 都是 0 → 0.5 → 1，这样短关不会因为层少就一路简单到底。 */
  const tierOf = k => (nF <= 1 ? 0 : k / (nF - 1));

  /* ================= ① 下行口 =================
     **每层 1~3 个，平均 1.9 个 —— 楼板不许再是一整条。**

     原来固定 1 个、偶尔 2 个，还按 3 个"槽位"轮转，于是每一层都是一块
     几乎整屏不断的板、边上开一个洞。用户 2026-10-28 直接圈出来了：
     "非要搞这么厚的横梁，而且那么长"。楼板长不是厚度问题，是**它真的
     从来没断过**。

     现在改成按 x 区间避让：
       · 同层的口之间至少隔一列（48）—— 挨在一起就等于一条 240 宽的
         大豁口，楼板会碎成一条一条，箱子没地方摞；
       · 上下两层的口不重叠（留 48）—— 重叠就是"从上面掉下来直接穿过
         下面那个洞"，一次掉两层。
     "槽位"这个抽象就此作废：它保证的正是"相邻层不同槽"，而区间检测
     比它更准、还没有"槽用完了只能全放开"的漏洞。 */
  const layers = [];
  let prevHoles = [];
  for (let k = 0; k < nF - 1; k++) {
    /* **每层 1~2 个。** 试过 3 个，两个后果都是硬伤：
       ① 三个口加上"洞口之间至少留一列"，一层能摞箱子的列只剩十来列，
          地表层箱子掉到 7 口（门槛 12）—— 玩法材料被结构吃光了；
       ② 三个口加余量之后连成一片，下一层**一个口都放不下去**
          （200 个种子里撞到 2 次"第 1 层没有出口"）。
       所以从"多加口"改成"加宽口"：1~2 个口，但最宽 240 —— 洞本身在
       画面上就占了四分之一屏，"一屏里三个通行点"这件事照样成立。 */
    /* **递进第一项：洞越深越窄。**
       浅层给宽口（192）—— 一进关就看见"这里能下去"，是教学；
       深层给窄口（96）—— 要贴着边找、跳下去还得对准，那是难度。
       这是"复杂度递进"里唯一一条纯空间的部分，其余都是数量。 */
    const tier = tierOf(k);
    const want = 1 + (chance(0.55) ? 1 : 0);
    const holes = [];
    for (let i = 0; i < want; i++) {
      for (let t = 0; t < 26; t++) {
        /* 宽度三档。144 是主力（玩家 30 宽，跳进去有余量）；
           192 是"大豁口"，一层里有它就不用找井梯了；
           96 是窄口，得贴边才跳得上去。 */
        /* **最宽 192。** 试过 240：两个 240 的洞加间隔就是 528px，
           一层只剩 9 列能摞箱子，地表层的箱子直接掉到 9 口（门槛 12），
           怪也找不到落脚点（"第 0 层没有怪"）。192 已经是"洞占了五分之一屏"，
           两个口加起来楼板断成三段，每段不超过 380 —— 视觉上早就不像横梁了。 */
        /* **第一个口最宽，第二个口收窄。** 两个 192 加间隔 48 就是 432px，
           一层只剩 10 列能摞箱子，而地表层还要被地形和出生点各吃掉一两列 ——
           200 个种子里有 4 个卡在"第 0 层箱子 9 口"（门槛 12）。
           总宽控制在 288 以内之后，最窄也还有 13 列。 */
        /* **最宽 144（2026-10-29）。** 原来浅层有 192 的"大豁口"，
           但 192 把楼板切成两段之后**跳不过去**：水平 300 × 滞空 0.686
           = 205px，理论够，实际要起跳点、落点、速度全对，十几像素的余量
           不是容错。我按"能不能走过去"做了 BFS（见 unreachableCols）：
           192 的洞在 200 个种子里制造了几百个走不到的孤段 ——
           而孤段里的怪打不到，门就永远打不开，是硬死局。
           "大豁口"的视觉改由"两个洞"承担（下一行），不靠单个洞加宽。 */
        const w = i === 0
          ? (tier >= 0.60 ? pickOne([96, 144, 144]) : 144)
          : pickOne([96, 96, 144]);
        const x = 48 * ri(0, Math.floor((912 - w) / 48));
        /* 同层两个口之间至少隔一列（48）—— 隔着 0 就不是两个口，是一条豁口。 */
        if (holes.some(h => x < h.x + h.w + 48 && x + w + 48 > h.x)) continue;
        /* 层间留 24：**校验用的就是 24**，生成侧比它松一点才不会自己把自己锁死
           （写 48 时，上一层放两个 192 的洞，下一层就一个口都放不下了）。 */
        if (prevHoles.some(h => x < h.x + h.w + 24 && x + w + 24 > h.x)) continue;
        /* **任何一段不少于 96（两列）。**
           一列宽（48）的碎段是真正的孤岛：玩家掉进去，两侧都是 144 的箱墙、
           上面是楼板，除了砸箱子没有出路，而砸出来的空间还是只有一列。
           实测这种段在浅层出现得最多（浅层洞宽、段也少）。
           判据放在"接受这个洞之前" —— 事后筛会把整层的洞删光。 */
        {
          const all = holes.concat([{ x, w }]).sort((a, b) => a.x - b.x);
          let segMin = 960, cxx = 0;
          for (const h of all) { segMin = Math.min(segMin, h.x - cxx); cxx = h.x + h.w; }
          segMin = Math.min(segMin, 960 - cxx);
          if (segMin < 96) continue;
        }
        const r = R();
        /* **封口只给本层的第一个口。** 口多了的意义就是"好几条路都通"，
           全都封上就白改了。冰墙仍然只从 t ≥ 0.4 开始（前面几层玩家还没有
           够档的球，封上等于直接关死）；霜箱从地表就有 —— 它是"这底下
           还有一层"这条探索线的第一个老师。

           概率跟着 tier 走：地表 34%、门厅 86%（冰 + 霜合计）。
           **这不是"随机得更凶"，是"越深越少敞开的口"** —— 玩家在浅层
           学会"口可能有盖板"，深层就该为这件事付出更多弹药。 */
        let cover = 'none';
        if (i === 0) {
          if (tier >= 0.4 && r < 0.10 + tier * 0.30) cover = 'ice';
          else if (r < 0.34 + tier * 0.26) cover = 'frost';
        }
        holes.push({ x, w, cover, floorY: floors[k] });
        break;
      }
    }
    /* **兜底：这一层一个口都没放下。**
       每个口试 26 次，撞的全是那三条"同层隔 48 / 层间留 24 / 任何一段不少于 96"。
       三条都合理，但它们**合起来可能无解** —— 上面一层放了两个宽口，
       这层就怎么摆都撞线，结果是"这一层根本没有出口"：
       玩家掉下来就困在里头，不是难度，是死局。
       实测 200 个种子里 1 个（种子 119 的第 1 层）。

       兜底顺序是**先放宽间距、最后才放宽段宽** —— 段宽是唯一
       "放宽了就变成孤岛"的一条，能不动就不动。三段都试不出来
       就硬开在屏幕中间，并且**不封口**（封住的兜底出口等于没兜底）。 */
    if (!holes.length && k < nF - 1) {
      const fw = tier >= 0.60 ? 96 : 144;
      const fitsAt = (x, gapPrev, minSeg) => {
        if (x < 0 || x + fw > 960) return false;
        if (prevHoles.some(h => x < h.x + h.w + gapPrev && x + fw + gapPrev > h.x)) return false;
        const segMin = Math.min(x, 960 - x - fw);
        return segMin >= minSeg;
      };
      let placed = false;
      for (const [minSeg, gap] of [[96, 24], [96, 0], [48, 0]]) {
        for (let x = 0; x + fw <= 960 && !placed; x += 48) {
          if (!fitsAt(x, gap, minSeg)) continue;
          holes.push({ x, w: fw, cover: 'none', floorY: floors[k] });
          placed = true;
        }
        if (placed) break;
      }
      if (!placed) holes.push({ x: 432, w: 96, cover: 'none', floorY: floors[k] });
    }
    holes.sort((a, b) => a.x - b.x);
    layers.push({ floorY: floors[k], holes, tier });
    prevHoles = holes;
  }
  layers.push({ floorY: floors[nF - 1], holes: [], tier: 1 });   // 门厅：没有下行口

  /* ================= ② 地板段 =================
     被洞切开。段宽决定了这一层能不能放平台/怪。 */
  function segsOf(floorY, holes) {
    const out = [];
    /* **`floor: true` 是"半透楼板"的标记**（2026-10-28 第四轮）。
       楼板对玩家是"只挡落下、不挡上跳"的一层 —— 见 stepBody 里那条 skip。
       平台/斜坡没有这个标记，所以它们照旧是实心的。 */
    let cx = 0;
    for (const h of holes) {
      if (h.x > cx) out.push({ x: cx, y: floorY, w: h.x - cx, h: GEN.thick, floor: true });
      cx = h.x + h.w;
    }
    if (cx < 960) out.push({ x: cx, y: floorY, w: 960 - cx, h: GEN.thick, floor: true });
    return out;
  }
  layers.forEach(l => { l.segs = segsOf(l.floorY, l.holes); });

  /* **出生点 x 在这里就得定下来。**
     原来是最后一步才算的，于是 ⑥ 放怪时根本不知道出生点在哪 ——
     结果开局有一只怪站在玩家 30px 旁边，一进关就掉血（出图放大才看见）。
     它只依赖第一层的地板段，所以能提前算。

     **对齐到列边界（2026-10-28）。** 原来 `startSeg.x + 36` 常落在 40，
     而玩家宽 30 —— 人骑在 0/48 两列的缝上，于是"出生点清箱"不得不把
     **两整列**箱子都删掉。地表层能摞箱子的列本来就只剩十来个，
     一次少两列（4~6 口）直接把这一层打到门槛以下：200 个种子里
     有 30 多个首掷过不了校验，全部是这个原因。
     现在让玩家整个人落在同一列里（`col*48+9`，占 9~39），清箱只清一列。 */
  const startSeg = layers[0].segs.filter(s => s.w >= 120)[0] || layers[0].segs[0];
  const startCol = (() => {
    const want = clamp(startSeg.x + 36, startSeg.x + 4, Math.max(startSeg.x + 4, startSeg.x + startSeg.w - 46));
    return clamp(Math.floor((want + 15) / 48), 0, 19);
  })();
  const startX = Math.max(6, Math.min(WALL_R - 44, startCol * 48 + 9));

  /* ================= ③ 地形 =================
     平台（跳得上，高差 114 < 跳高 123）和斜坡（**走上去，不用跳**）。
     斜坡只在"接平台"时出现得最多：它把"上台"这件事拆成两种解法，
     跳跃之外多一条路。偶尔也放一条孤坡当起伏。 */
  layers.forEach((l, k) => {
    const out = [];
    if (k < nF - 1) {
      /* **两处都要避开：上一层的落点带（会被接在半空）、本层的洞口（会把路盖住）。**
         只避开落点带的话，平台或斜坡会正好架在洞口上 ——
         尤其"敞开"型洞口，本来就是让玩家靠眼睛找的，被一块平台压住之后
         这一层根本没有出口可用了。 */
      const dz0 = (k > 0 ? layers[k - 1].holes.map(h => [h.x - 24, h.x + h.w + 24]) : [])
        .concat(l.holes.map(h => [h.x - 24, h.x + h.w + 24]));
      /* **一个 [x, x+w) 是否两道带都躲开了。**
         所有地形（平台、配套坡、孤坡）都必须先过这一关再落位 ——
         第一版只有平台本体过了，坡是"延伸出去"的（`px + w` 往右、`px - rw`
         往左），那一段压根没验；孤坡更是一路裸奔，`rx` 直接 48..912 随便取。
         结果就是坡横跨在洞口上，把唯一的出口盖掉。 */
      const freeOf = (x, w) => !dz0.some(z => x < z[1] && x + w > z[0]);

      /* **地形要让位给箱子。** 平台和箱山在功能上是重复的（都是"能站的高台"），
         但平台占的列是死的、箱子占的列是能拆的。箱子变核心之后，
         平台从"每层多半有"降到"偶尔一个"，宽度也从 3~4 格收到 2~3 格 ——
         它现在的角色是"石头打的台子"，给箱堆丘陵一个材质对比。 */
      /* **候选段门槛 240 → 144。** 240 是"平台最窄 96 + 坡 144"算出来的，
         但那个数只对**带坡**的那种成立；一台不带坡的平台只要 96~144。
         之前把门槛写成 240，等于要求"每一台平台都必须配得起坡" ——
         一层被两个洞切成三段时，中间那段常常只有 144~192 宽，
         于是整层的平台全被否掉，一关只剩 0.8 条坡。
         现在分开：平台只要 144，带坡的另找 ≥ 240 的段（下一行）。 */
      const wide = l.segs.filter(s => s.w >= 144);
      const wantRamp = chance(0.78);
      /* **坡长也要抖开。** 原来固定 144，于是每一关每一层看到的都是
         同一条 38° 的坡 —— 用户说的"太规矩"有一半是这个：不是画法问题，
         是**全场的坡都长得一样**。现在 144 / 168 / 192 三档，坡度落在
         26°~38°，同一个画面里两条坡不会是一个斜度。 */
      const RAMP_W = 144;
      let placed = false;
      /* **0.4 → 0.58。** 楼板断成两三段之后，"每层都放得下地形"的段
         少了，斜坡掉到平均 0.76 条/关。用户抱怨过"斜坡太规矩"——
         变成"几乎没有斜坡"显然更糟。 */
      if (wide.length && chance(0.78 + tierOf(k) * 0.12)) {
        /* **候选段池按"平台 + 坡"的总宽挑。**
           只要平台的话 240 就够，可一旦带坡，平台 96~192 + 坡 144~192
           就是 240~384 —— 从 240 宽的段里随机取位，坡**必然**跨到段尾外面，
           而段尾外面就是洞口，`freeOf` 一路否掉，重试 12 次也全白跑。
           这正是"平均每关只有 1.3 条坡、四分之一的关一条坡都没有"的原因。 */
        /* **门槛按"平台最窄 + 坡"算，不是按"平台最宽 + 坡"。**
           平台宽是 96~144，所以最省的一条路是 96 + 144 = 240。
           原来写 192 + 144 = 336 —— 楼板断成两三段之后，一条 336 的段
           已经很少见了，斜坡直接从"平均 1.1 条"掉到 0.8 条。 */
        /* **两轮：先试"平台 + 坡"，这一轮全失败再退成"光平台"。**
           原来只有一轮，`pool0`（≥240 的段）非空就直接用它 —— 可是
           `freeOf` 还要躲开本层洞和上层落点带的 ±24，一个 240 宽的段
           被躲掉两头之后常常只剩一百多，带坡永远凑不齐 240（平台 96 +
           坡 144）。12 次重试全白跑，`placed` 保持 false，于是这一层
           连一台光平台都没有 —— 实测 68% 的地形掷骰最后只落地 46%。
           **"放不下坡"不等于"放不下台子"**，这两个不该绑在一起失败。 */
        for (const withRamp of (wantRamp ? [true, false] : [false])) {
          const pool0 = withRamp ? l.segs.filter(s => s.w >= 96 + RAMP_W) : wide;
          const pool = pool0.length ? pool0 : wide;
          /* **位置重试，不是"撞上就整块丢掉"。**
             落点带上不能有地形（会把人接在半空），但直接丢弃的话，
             一半以上的层会连一台平台都没有 —— 地形多样性直接没了。 */
          for (let t = 0; t < 12 && !placed; t++) {
            const cand = pickOne(pool);
            const cw = 48 * ri(2, 3);
            const room = Math.max(0, Math.floor((cand.w - cw) / 48));
            const cx = cand.x + 48 * ri(0, room);
            if (!freeOf(cx, cw)) continue;
            /* **台面高度两档：96 / 114。** 跳高是 123，两档都在射程内；
               原来固定 114，全场的台子顶面在同一条水平线上，一眼就是
               "编辑器里刷的"。96 那一档还能让人从台子上直接跳上 2 格箱顶。 */
            const py = l.floorY - (chance(0.45) ? 114 : 96);
            /* **坡和平台是一个整体，要么整段放得下，要么这个坡不要。**
               先随机排左右顺序，再挑第一个"整段都在本层地板里、且不压洞口"
               的一边 —— 不能先定边再验，否则随机选中的那一边正好压洞口时，
               只能把整台平台一起扔掉。 */
            let ramp = null;
            if (withRamp) {
              const sides = chance(0.5) ? ['R', 'L'] : ['L', 'R'];
              for (const sd of sides) {
                if (sd === 'R' && cx + cw + RAMP_W <= cand.x + cand.w && cx + cw + RAMP_W <= 912 && freeOf(cx + cw, RAMP_W)) {
                  /* 坡在平台右侧：左端接台面（高），右端接地面（低）→ rise 为负 */
                  ramp = { x: cx + cw, y: py, w: RAMP_W, h: GEN.thick, base: l.floorY, rise: py - l.floorY, kind: 'ramp' };
                  break;
                }
                if (sd === 'L' && cx - RAMP_W >= cand.x && cx - RAMP_W >= 48 && freeOf(cx - RAMP_W, RAMP_W)) {
                  /* 坡在平台左侧：左端接地，右端接台面 → rise 为正 */
                  ramp = { x: cx - RAMP_W, y: l.floorY, w: RAMP_W, h: GEN.thick, base: l.floorY, rise: l.floorY - py, kind: 'ramp' };
                  break;
                }
              }
              /* 带坡的这次没谈成就不算数，换位置重来 —— 否则会出现
                 "平台摆在段中间、两边都是空地却没有坡"的怪形状。 */
              if (!ramp) continue;
            }
            /* **h 18 → 34。** 18px 是一块"板"，画出来就是一条横着的厚线，
               再怎么加纹理也还是直尺画的边。34 才够画成一个"悬在墙上的
               土石台子"，底面能做出瘤状起伏。碰撞只认顶面和侧面，
               加厚不影响跳跃和阻挡（净空 200，台底下照样走得过人）。 */
            out.push({ x: cx, y: py, w: cw, h: 34 });
            if (ramp) out.push(ramp);
            placed = true;
          }
        }
      }
      /* **0.30 → 0.44。** 楼板断成两三段之后，能放"平台带坡"的段少了
         （那要求段 ≥ 240 并且整段让开洞口），坡就只剩土丘这一条来源。
         土丘一次贡献两段坡，提概率是最省的做法。 */
      if (!placed && chance(0.72 + tierOf(k) * 0.12)) {
        /* **孤坡必须是"上坡 + 下坡"两段,不能是一条单边楔子。**
           单边楔子的高端悬空:一堵 76px 的垂直墙(斜坡不做水平阻挡,
           因为整块包围盒会造成"坡变成墙"),玩家从高端那头走进来会直接
           穿进坡里;雪线的圆头还会从墙角探出来一截,像长了个嘴。
           拆成两段之后两个低端都落回本层地面,坡度也对称 ——
           球顺着滚会先减速再加速,正好是"起伏"该有的手感。 */
        /* **孤坡的两段比例决定它读成"坡"还是"帐篷"。**
           96×64 的成对土包坡度 34°，两块正好拼成一个尖顶 ——
           一整张图看过去就是个三角屋顶，没有任何"可以走上去"的暗示。
           摊到 120×44（20°）之后，人字变平缓，配合钉上去的木板踏面
           才读得出"这是个土丘，走上去就行"。

           **不能再往宽放。** 试过 132：地形是按"列（48px）与包围盒相交"
           吃列的，132 宽会连着吃掉 4 列，有坡的那层箱子掉到 11 口
           （门槛 12），200 种子里 135 / 172 两关直接判红。
           现在宽度取 108~132、高度取 38~50，坡度落在 16°~24° —— 幅度不大，
           但两座土丘不会是一个模子倒出来的。 */
        const MOUND_RISE = 38 + ri(0, 12);                // 38~50
        /* **两侧坡度必须不一样。** 96 + 144 的坡长配 40 左右的落差，
           迎风面 23°、背风面 15° —— 对称的两个人字拼起来一定是"三角屋顶"
           （这是上一版被一眼看穿的地方），一边陡一边缓才像被风堆出来的雪梁。

           **总宽 192 / 240 两档（2026-10-29）。** 原来锁死 240，而一层被
           两个洞切过之后，"不压落点带的连续 240"经常凑不出来 —— 雪包
           是唯一一次能贡献两条坡的地形，它放不下，平均坡数就上不去。
           192 档用 96 + 96，配 38~50 的落差是 21°~27°，不比 240 档陡。
           代价是多吃掉一列箱子的可能（192 占 4 列，240 占 5 列）—— 换得回来。 */
        const MOUND_W = chance(0.45) ? 192 : 240;
        const wL = MOUND_W === 192 ? 96 : (chance(0.5) ? 96 : 144);
        const wR = MOUND_W - wL;
        for (let t = 0; t < 8; t++) {
          const rx = 48 * ri(1, Math.floor((912 - MOUND_W) / 48));
          if (!freeOf(rx, MOUND_W)) continue;
          /* cap: 1 → 顶点扣一顶东西（画在 drawRamp 里）：室内是压一块石头，
             地表是一顶雪帽。人字顶点太尖，顶一下才不像三角屋顶。 */
          out.push({ x: rx, y: l.floorY, w: wL, h: GEN.thick, base: l.floorY, rise: MOUND_RISE, kind: 'ramp', cap: 1 });
          out.push({ x: rx + wL, y: l.floorY - MOUND_RISE, w: wR, h: GEN.thick, base: l.floorY, rise: -MOUND_RISE, kind: 'ramp' });
          break;
        }
      }
    }
    /* **地形不能压在落点带上。**
       平台上如果还放着一口箱子，从上一层掉下来的人会被它接在半空 ——
       砸开洞口只掉一个箱子的高度（48px），玩家就卡在那儿了。
       校验只查了"洞正下方是下一层地板"，管不到"中途有没有东西接着"。 */
    /* **±48 而不是 ±24。** 井梯是 3 格高的硬列，旁边一列如果是地形（canAdd
       被地形锁死），高差 3 一样削不平。留整整一列缓冲，井梯左右就能自由削坡。 */
    const dz = k > 0 ? layers[k - 1].holes.map(h => [h.x - 48, h.x + h.w + 48]) : [];
    l.terrain = out.filter(t => !dz.some(z => t.x < z[1] && t.x + t.w > z[0]));
  });

  /* ================= ④ 箱子 =================
     **这一版箱子不是"撒"出来的，是"砌"出来的。**
     用户原话：「箱子可以当做走路的 也是可以探索解密的核心」。
     要让它同时当墙、当路、当盖子，就得先有结构 ——
     先算一张**列堆高图**（20 列 × 每列堆几层），再按图生成。

       ① 落点带（上一层洞口正下方）必须是 0，否则会把人接在半空
       ② 本层洞口列有下限：霜箱 1 层、冰墙 2 层；**霜箱允许再往上摞**，
          于是玩家先看到一坨箱山、砸开才露出底下的霜 —— 探索就落在这里
       ③ 箱山剖面是金字塔（1-2-3-2-1），**相邻高差永远 ≤ 1 格**：
          一格 48、跳高 123，所以整座山都爬得上去 —— 箱子真的是路
       ④ **峰值封顶 3 格（144）。** 净空只有 200（层高 240 − 板厚 40）、
          玩家高 42，站在 3 格顶上头顶在 186，刚好不顶天花板；4 格就是 234，
          人会卡进天花板里。这个数不是美术偏好，是净空倒算出来的
       ⑤ 任意两坨箱体之间至少留 2 列（96px）：地面永远走得通
     */
  const boxes = [];
  /* `barrel` = 木桶。**和木箱同一个碰撞盒、不同的视觉与耐久。**
     不做成"能滚的圆桶"是故意的：滚动物体要另写一套物理和一套阻挡规则，
     为一个纯装饰性的变体不值得。桶的用途是"打破整层的规整感" ——
     一排排 48×48 的方箱里插一个圆柱，眼睛立刻就知道那里不是墙。
     耐久 2 发（比木箱少一发），因为木桶本来就是薄板拼的。 */
  const B = (x, y, mat, opt) => boxes.push({
    x, y, w: 48, h: 48, mat,
    hp: (opt && opt.barrel) ? 2 : NUM.box[mat].hp, dead: false, hitT: 0, taught: false,
    fell: 0,                     // 掉过多久（>0 之后不再认"被夹住"这一条，见 stepBoxFall）
    frost: !!(opt && opt.frost),
    loot: !!(opt && opt.loot),
    barrel: !!(opt && opt.barrel),
  });

  /** 这一层的落点带：上一层洞口正下方。**不能摆箱子** ——
      砸开上层，剩下那口盖板会顺着洞塌下来，跟这里的箱子叠在同一格就穿模了。 */
  function dropZones(k) {
    const out = [];
    if (k > 0) for (const h of layers[k - 1].holes) out.push([h.x - 24, h.x + h.w + 24]);
    return out;
  }
  const hitsRange = (x, w, rs) => rs.some(r => x < r[1] && x + w > r[0]);

  /* ---- 门厅先摆：门壳 + 喂球箱 ----
     **必须先摆。** 先平铺再补喂球的话，两边会抢同一格：撞出"一格叠两口箱"
     的假象，而且一旦抢输就凑不够 —— 玩家把怪清光之后就是死局。
     顺序本身就是一条正确性约束，不是排版偏好。
     喂球箱从 3 口提到 5 口：箱子变成核心玩法之后，弹药经济也得松一点。 */
  const lastY = floors[nF - 1];
  /* **门不再钉在右半边。**（2026-10-29，用户：「下关的门不要定死固定位置」）

     原来 `48 * ri(12, 17)` = 576~816，也就是永远在画面右侧 60%~85%。
     玩三关就会形成习惯："门在右边"。于是整层的前半段变成纯赶路，
     空间设计退化成一条从左上到右下的斜线。

     现在 3~17 列全宽随机（144~816），只躲一条：**上一层的落点带**。
     不是为了好看 —— 从上面掉下来正好落在门壳顶上，人会卡在两格冰之间
     往上爬，而门在脚底下，读起来像"掉到门上"。
     40 次里挑不到合适的就退回中间偏右（一关最多一次，不影响观感）。 */
  const hallDrop = layers[nF - 2].holes.map(h => [h.x - 48, h.x + h.w + 48]);
  let doorCol = 12;
  for (let t = 0; t < 40; t++) {
    const c = 3 + Math.floor(R() * 15);          // 3 ~ 17 列
    if (hallDrop.some(z => c * 48 < z[1] && (c + 1) * 48 > z[0])) continue;
    doorCol = c;
    break;
  }
  const doorX = 48 * doorCol;
  /* ================= 门：小门，而且藏在箱子里 =================
     用户 2026-10-29：「门不需要那么大啊　需要隐藏到箱子里」。

     原来门是 48×92 —— 一格宽、将近两格高，两侧还各垫两格冰墙当门框。
     结果整块门厅最显眼的东西就是它：**一进去就看见门，只剩"砸冰"一个动作**，
     探索的部分（找到门）等于没做。

     现在门只有 32×40（一格之内，两格高一格宽的门框感靠画法给），
     而且**整扇被压在木箱底下**：门所在那一格就是一口普通木箱，
     门画在箱子后面（绘制顺序：门先、箱子后）。砸开那一口，门才露出来 ——
     `stepDoor` 里本来就有"从被盖住变成露出来"的那一次闪光和飘字
     （「找到门了」），这个机制一直都在，只是原来门太大了，
     冰壳一碎整个人比门还窄，"藏"这件事根本没发生。

     **埋多深跟深度走**：门厅 tier ≥ 0.55 埋两层（要连拆两口），
     否则只埋一层。这就是"机制随深度多样"里最便宜的一条 ——
     不加新东西，只是让深层的终点多花一发弹药。 */
  const DOOR_W = 32, DOOR_H = 40;
  const door = {
    x: doorX + 8, y: lastY - DOOR_H, w: DOOR_W, h: DOOR_H,
    open: false, openT: 0,
  };
  const hallTaken = [];        // 门厅里已被占掉的 x，箱山要避开
  const buryH = (layers[nF - 2].tier >= 0.55 ? 2 : 1);
  for (let j = 0; j < buryH; j++) B(doorX, lastY - 48 * (j + 1), 'wood');
  hallTaken.push(doorX);
  hallTaken.push(doorX - 48);   // 门前留一格空地，不然打不开的门等于墙
  hallTaken.push(doorX - 96);
  /* 门厅喂球木箱。**注意它们不再是"喂球"用的了** —— 球撞箱子已经不涨体积
     （2026-10-28），涨体积只认吞敌人。留 5 口的原因是**弹药经济**：
     门厅的怪会挡枪，先拆几口清出射界；顺带也是"箱子能堆"的最后一次演示。 */
  {
    const hallZones = layers[nF - 2].holes.map(h => [h.x - 24, h.x + h.w + 24]);
    const all = [];
    for (let x = 48; x + 48 <= doorX - 96; x += 48) all.push(x);
    const free = all.filter(x => !hitsRange(x, 48, hallZones));
    /* 两轮：先避开落点带，不够 5 口就放宽。**落点带只是防"塌下来的盖板箱
       跟这里的箱子穿模"，是观感问题；喂球箱数量是死局问题。观感可以让一步。** */
    const src = free.length >= 5 ? free : all;
    const picks = [];
    for (let t = 0; t < 60 && picks.length < 5 && src.length; t++) {
      const x = src[Math.floor(R() * src.length)];
      if (picks.some(p => Math.abs(p - x) < 48)) continue;
      picks.push(x);
    }
    // 兜底：门右侧
    for (let x = doorX + 96; picks.length < 5 && x + 48 <= 912; x += 48) {
      if (picks.some(p => Math.abs(p - x) < 48)) continue;
      picks.push(x);
    }
    for (const x of picks) { B(x, lastY - 48, 'wood'); hallTaken.push(x); }
    if (picks.length) B(picks[0], lastY - 96, 'wood');    // 叠一口，给"箱子能堆"一个样本
  }

  const COLS = 20;      // 960 / 48

  layers.forEach((l, k) => {
    const dz = dropZones(k);
    const isHall = k === nF - 1;
    const pWood = Math.max(0.36, 1 - k * 0.10);
    /* **普通箱子不出冰。**
       冰在这一关里只有两个意思：封住下行口的墙、包住门的外壳。
       让它也当普通材质之后，"这是一堵墙"和"这是一口能砸的箱子"
       长得一模一样 —— 一种视觉语言一旦有两种解释，就等于没有。 */
    /* ---- 机制登场表（按 tier，不按 k）----
       用户 2026-10-29：「后期复杂化 机制多样化」。
       **"多样化"不是"什么都多一点"，是"每一段深度有一个新东西第一次出现"**：

         tier 0     ：木箱 / 石箱 / 霜箱（教学层：箱子能爬、能拆、能挖穿）
         tier ≥.30  ：runner（会追人的怪）
         tier ≥.45  ：铁箱（砸不动的墙 —— 逼玩家绕路或者养大球）
         tier ≥.55  ：门厅的门压两层箱子（要连拆两口才看见门）
         tier ≥.60  ：窄洞 96 + 冰封洞口（越深越少敞开的口）
         tier 越高   ：金箱越容易出（探索奖励在深层要更明显）

       全部用 tier 判，**不用 k 判** —— 否则 3 层关的 k 只到 2，
       一半机制在短关里永远不出现，同一份难度曲线在两种关长上不是一回事。 */
    const tierL = l.tier || 0;
    const matRoll = r => r < pWood ? 'wood'
      : (r < pWood + (1 - pWood) * 0.52 ? 'stone' : (tierL >= 0.45 ? 'iron' : 'stone'));

    /* ---- ① 列模型 ---- */
    const HGT = new Array(COLS).fill(0);
    const canAdd = new Array(COLS).fill(true);
    const MAX0 = new Array(COLS).fill(3);    // 列模型阶段就能定下的上限
    /* 这一列是哪种洞口（-1 = 不是洞口）。削坡要用它 —— 见 setH 的注释。 */
    const holeCol = new Array(COLS).fill(-1);

    /* ---- 井口缘 ---- 洞口**左侧**紧邻的那一列不放箱子（见 ① 里的注释）。
       **只清一侧。** 两侧都清等于每个洞吃掉两列箱子，地表层直接从 15 列
       掉到 11 列，200 个种子里首掷只有 98 个过校验（原来 198）。
       井梯固定摞在洞口的左列（见下），玩家爬上去也是往左扒 —— 左侧才是
       真正要用的那块落脚台面，右侧留不留空对"能不能跳上去"没有影响。 */
    const rimCol = new Array(COLS).fill(false);
    /* 洞口**右**邻列：只限高、不腾空（限高不损失箱数） */
    const rimRCol = new Array(COLS).fill(false);
    for (const o of l.holes) {
      const li = Math.ceil(o.x / 48) - 1;
      if (li >= 0 && li < COLS) rimCol[li] = true;
      const ri2 = Math.floor((o.x + o.w) / 48);
      if (ri2 >= 0 && ri2 < COLS) rimRCol[ri2] = true;
    }
    /* **薄层不腾井口缘。** 地表层经常是"2 个洞吃掉 4 列 + 地形吃 3 列"，
       再抠掉井口缘就只剩 6~10 列，箱子直接掉到 6 口（门槛 12）——
       200 个种子里首掷从 198 掉到 191。层薄的时候宁可让玩家走按 W 的
       井梯（那条路一直都在），也不要把箱子掏空。 */
    const boxCols = (() => {
      let n = 0;
      for (let i = 0; i < COLS; i++) {
        const x = i * 48;
        if (l.terrain.some(t => x + 48 > t.x && x < t.x + t.w)) continue;
        if (l.holes.some(o => x + 48 > o.x && x < o.x + o.w)) continue;
        if (!l.segs.some(s => x >= s.x && x + 48 <= s.x + s.w)) continue;
        n++;
      }
      return n;
    })();
    const rimOK = boxCols >= 10;

    /* 上行井梯 = 上一层洞口正下方的那几列。用法见下面的注释。
       **门厅（最后一层）不做井梯。** 门厅是终点：门壳和 5 口喂球箱占掉
       八九列，那些列必须是 0 格（否则门打不开、球喂不出来），井梯硬要在
       旁边摞 3 格就永远削不平 —— 200 个种子里 149 次红在这里。
       门厅的怪数 ≥ killTarget，玩家到了那里就能凑够，不需要回上一层补。 */
    /* **列必须完全落在洞口里。** 用 floor 取"包含洞口左边缘的那一列"时，
       如果洞口没对齐 48（比如洞从 360 起、列从 336 起），那一列有一半是
       在地板下面的 —— 玩家站上去，头顶正好顶着上层地板，一跳就撞回来，
       根本升不起来（实测上升 14px 就被打回地面）。用 ceil 往洞里收一列。 */
    const wells = (k > 0 && k < nF - 1 ? layers[k - 1].holes : []).map(hd => {
      let a = Math.ceil(hd.x / 48);
      let b = Math.floor((hd.x + hd.w) / 48) - 1;
      if (b < a) { a = Math.floor(hd.x / 48); b = a; }   // 窄洞不对齐时的兜底
      return [clamp(a, 0, COLS - 1), clamp(b, 0, COLS - 1)];
    });

    for (let i = 0; i < COLS; i++) {
      const x = i * 48;
      if (isHall && hallTaken.indexOf(x) >= 0) { canAdd[i] = false; continue; }
      /* **地形占掉的列不摞箱子。** 平台面在 floorY-114，
         3 格箱山在 floorY-144，硬摞上去会直接穿插。 */
      if (l.terrain.some(t => x + 48 > t.x && x < t.x + t.w)) { canAdd[i] = false; continue; }
      /* **井口缘：洞口左右紧邻的那两列不摞箱子。**（2026-10-28 加）
         用户原话：「上下层玩家直接可以跳」。

         **这一条才是"能不能跳上去"的开关，不是跳高。** 之前每一层的洞口
         都被两摞 3 格箱山夹着：玩家站井梯顶（脚在上层地板下 96）起跳，
         脚能越过上层地板 27px —— 可是左边是 0..洞口 的整段楼板、右边是
         一整摞箱子，**没有一块可以落脚的空台面**，横向一碰就被顶回来，
         于是永远只能靠按 W 的瞬移。实测 26 个层位里纯跳只成功 1 个；
         把起跳速度从 720 提到 860（跳高 123→176）也只到 4 个 ——
         加高解决不了"没地方站"。
         留出这一列之后，井口边上就有一块 48 宽的台面可以扒、可以落。 */
      if (rimOK && rimCol[i]) { HGT[i] = 0; canAdd[i] = false; MAX0[i] = 0; continue; }
      /* **洞口右邻列限高 2 格。** 左邻是井口缘（0 格），右边如果是 3 格，
         跨这个洞就只有"从右往左"能用 —— 往左是下坡，往右要上 3 格
         （144 > 跳高 123）。单向通行在 BFS 里就是半个死胡同：
         从左边那段出发，永远过不到右边。 */
      if (rimRCol[i]) MAX0[i] = Math.min(MAX0[i], 2);
      const hole = l.holes.find(o => x + 48 > o.x && x < o.x + o.w);
      if (hole) {
        holeCol[i] = hole.cover;
        if (hole.cover === 'ice') { HGT[i] = 2; canAdd[i] = false; }
        else if (hole.cover === 'frost') {
          /* **霜箱允许被埋。** 35% 的洞口在盖板上再摞 1~2 层普通箱：
             玩家看到的是一坨箱山，砸开才露出底下的霜 —— 这就是"探索"。
             敞口（none）不埋，它的卖点本来就是"一眼看见"。 */
          /* **霜箱上只压 0~1 层。** 压 2 层的话这一列就是 3 格高，
             旁边的空地是 0，高差 3 跨不过去（跳高只有 123）。
             "埋住"的效果靠"这一列比周围高一头"就够了。 */
          HGT[i] = 1 + (chance(0.4) ? 1 : 0);
          canAdd[i] = true;
        } else { canAdd[i] = false; }
        continue;
      }

      /* 段外列不摞箱子。**这条要在井梯之前** —— 段外的列下面是空的，
         井梯摞在段边界外侧就是一座悬空的塔，玩家既上不去也跳不过来。 */
      if (!l.segs.some(s => x >= s.x && x + 48 <= s.x + s.w)) { canAdd[i] = false; continue; }

      /* ---- 上行井梯 ----
         **这里原来写的是 `MAX0[i] = 1`，等于把上行通道焊死了。**
         玩家在下一层要回到上一层，唯一的路就是上一层地板上的那个洞：
             站 3 格箱顶（144），跳 123 → 267，越过上一层地板（240）✓
             站 2 格（96）  ，跳 123 → 219，差 21px，永远上不去      ✗
         所以洞口正下方这几列必须摞到 3 格。它同时是"掉下来的落点"和
         "爬回去的井梯"—— 两件事共用同一摞箱子：掉下去要砸穿三口，
         爬上去要跳三格，成本是对称的。

         盖板还封着的时候上不去（撞头），这正好是"先砸开才能走"的复习。 */
      /* **一口井只留一列做梯，其余列只垫 1 格。**
         全垫 3 格的话，玩家挖穿掉下来会落在 144 高处，得连砸三口才落地 ——
         "我明明挖穿了怎么还在半空"。垫 1 格（48）砸一口就到底，
         想上去时横移两格走到梯子那列再跳（高差 2 格 = 96 < 跳高 123）。
         视觉上正好是"井底竖着一把梯子"，不用额外解释。 */
      const inWell = wells.some(w => i >= w[0] && i <= w[1]);
      if (inWell) {
        const isLadder = wells.some(w => i === w[0]);
        HGT[i] = isLadder ? 3 : 1;
        MAX0[i] = isLadder ? 3 : 1;
        continue;
      }

      /* 落点带往外一列只压到 2：**别让每次掉下来都接在三格高处**，
         但也不能留空 —— 1 格（48）太矮，玩家会以为自己已经落到地板上了。 */
      if (hitsRange(x, 48, dz)) MAX0[i] = 2;
    }

    /* ---- ② 箱堆地形 ----
       用户 2026-10-28：「箱子你没必要那么规矩 现在又感觉很密密麻麻 也可以有桶装啊」。

       **改成"一堆一堆地摞"，堆与堆之间留平地走廊。**

       上一版是"每列独立随机 + 削坡"，铺得很满，代价是整层被箱子铺成一条
       连续高地 —— 两个后果用户都点到了：
         · 看起来像地形、不像箱子（密密麻麻）
         · 走在上面每两格就上下 48px，人一路在颠（他另外说的"晃来晃去"，
           一半是这个，不是镜头）
       所以现在反过来：**先摆堆，堆之间必然是平的。**
         · 连续可用的列切成 1~4 列的堆，堆内中间高两头矮（自然的堆形）
         · **堆之间至少 1 列平地**，30% 的地方留 2 列
         · 堆峰 1~3 格，仍然受"相邻高差 ≤ 2"的削坡兜底
       箱子总数反而不掉：堆内是实心的，4 列 × 2 格 = 8 口，
       同样宽度散着铺只有 4~6 口。

       三条硬约束（都是撞墙撞出来的）：
       · **上限 3 格 = 144。** 净空只有 200（层高 240 − 板厚 40）、玩家 42，
         站 3 格顶上头顶 186，刚好不顶天花板；4 格就是 234，人会卡进去
       · **相邻高差 ≤ 2 格 = 96 < 跳高 123。** 这条是"箱子是路"的全部保证，
         破了它箱子就退化成墙
       · 洞口盖板列有最低高度（霜箱 1~2 层 / 冰墙 2 层），削坡不许把它削没 ——
         削没了这一层就没有出口 */
    const LOCK = new Array(COLS).fill(-1);   // >=0：洞口盖板列，值是最低高度
    const MAXH = MAX0.slice();               // 本列最高能堆几层
    for (let i = 0; i < COLS; i++) if (HGT[i] > 0) LOCK[i] = HGT[i];

    /* ---- ②-0 出生点那一列不摆箱子 ----
       **玩家就站在这一列，箱子会把他埋住。** 原来是在全部生成完之后
       "把这一列的箱子删掉"（见下面「出生点清箱」），可那时候 `topUp` 早就
       按 HGT 把箱子数补到门槛了 —— 删完只剩 7 口，门槛 8 口，校验红。
       实测 200 个种子里 3 个首掷死在这里：种子 68 的 H 合计 8 口、
       实际只剩 7 口；种子 153 的 H 合计 9 口、实际只剩 6 口（邻列补丁又删了 2 口）。

       现在改成"生成前就标成不可摞"，箱子数从源头就是对的，
       也省掉了"删完再补"这种自己骗自己的循环。
       **洞口 / 覆霜盖板 / 井梯列除外** —— 那些列的箱子是"出口的封口"，
       清掉等于把这一层的出口拆了。 */
    if (k === 0 && canAdd[startCol] && holeCol[startCol] === -1 &&
        !wells.some(w => startCol >= w[0] && startCol <= w[1])) {
      HGT[startCol] = 0; MAXH[startCol] = 0; canAdd[startCol] = false;
    }

    /* ---- ②-1 切游程：连续"能摞箱子"的列 ---- */
    const freeCol = new Array(COLS).fill(false);
    for (let i = 0; i < COLS; i++) if (canAdd[i] && LOCK[i] < 0) freeCol[i] = true;
    const runs = [];
    for (let i = 0; i < COLS; i++) {
      if (!freeCol[i]) continue;
      let j = i;
      while (j + 1 < COLS && freeCol[j + 1]) j++;
      runs.push([i, j]);
      i = j;
    }

    /* ---- ②-1.5 主通道：先划走廊，再摆箱子 ----
       用户 2026-10-29：「空间设计要合理 不要有死胡同路」。

       **"死胡同"在这里不是"被墙围住"—— 箱子都能砸。** 它指的是：
       玩家钻进两座 3 格箱山之间的缝里，前后都被 144 挡住（跳高只有 123），
       唯一的出路是"砸"。一次两次叫战斗，整关都是就叫"没有空间设计"。

       原来的做法是"堆之间至少留 1 列平地"，但那是**副产品**：
       堆宽 1~4 随机、空地 30% 才给 2 列，于是有的段连着五六列全是堆。
       现在反过来 —— **先按 3~5 列的节奏把走廊钉死，箱子只能堆在走廊之间。**
       走廊列恒为 0 格（不摆堆、补箱也不碰），相邻列限高 2 格：
       于是从走廊爬上任何一座箱山，高差都不超过 2 格（96 < 跳高 123）。
       这是"任何一处都能回到主路"的几何保证，不是靠概率碰运气。
       它同时是 BFS 校验（见 validateLevel 第 13 条）的物理基础。 */
    const corridor = new Array(COLS).fill(false);
    /* **井梯列和它左右一列不许当走廊。** 井梯是硬性的 3 格（那是"上到上一层"
       唯一的路），走廊是硬的 0 格 —— 两者贴在一起就是高差 3（144 > 跳高 123），
       走廊自己成了沟底。第一版没排除，200 个种子里 204 次撞"相邻列高差 3"。 */
    const nearWell = i => wells.some(w => i >= w[0] - 1 && i <= w[1] + 1);
    for (const run of runs) {
      /* 起点在游程内抖 0~1 列，**不能固定从 run[0] 开始** ——
         否则每层走廊都落在 0、4、9、13 列，纵向看下去是一排等距竖井。 */
      /* **起点不许越过游程末端。** 长 1 的游程（一列）配上门 0~1 的抖动，
         有 50% 的机会直接跳过整段 —— 整层的游程都短的时候就是"这一层
         一条走廊都没有"，断言里 800 个层位中撞了 3 次。 */
      let c = Math.min(run[1], run[0] + Math.floor(R() * 2));
      while (c <= run[1]) {
        if (!nearWell(c)) corridor[c] = true;
        /* **4~6 列一条，不是 3~5。** 3 列一条时一屏有 6 条走廊，
           吃掉的箱子列太多：200 个种子里首掷通过率从 98% 掉到 96%
           （"这一层箱子只有 8 口 < 门槛 10"）。走廊是"能回到主路"的保证，
           不需要多到像网 —— 一屏 4 条已经很够走了。 */
        c += 4 + Math.floor(R() * 3);
      }
    }
    /* **兜底：一条走廊都没划出来。** 游程太碎（都被洞口 / 地形切成单列），
       或者仅有的几条游程紧贴井梯（`nearWell` 把它们全排除了）。
       这时挑最长的那条游程的中点当走廊 —— **有路可回**这件事比
       "走廊落在好看的节奏上"重要得多。 */
    if (!corridor.some(v => v)) {
      const offWell = r => { for (let i = r[0]; i <= r[1]; i++) if (!nearWell(i)) return i; return -1; };
      let pick = -1, bestLen = -1;
      for (const r of runs) {
        const i = offWell(r);
        if (i < 0) continue;
        if (r[1] - r[0] > bestLen) { bestLen = r[1] - r[0]; pick = i; }
      }
      if (pick < 0) for (const r of runs) if (r[1] - r[0] > bestLen) { bestLen = r[1] - r[0]; pick = r[0]; }
      if (pick >= 0) corridor[pick] = true;
    }
    for (let i = 0; i < COLS; i++) {
      if (!corridor[i]) continue;
      HGT[i] = 0;
      MAXH[i] = 0;
      canAdd[i] = false;                   // 补箱子那一轮也填不进来
    }
    /* 走廊两侧限高 2 格。**这一条比"走廊本身是 0 格"更关键**：
       走廊 0、旁边 3 的话高差 3 = 144 > 跳高 123，走廊就成了沟底，
       主路自己变成了死胡同。 */
    for (let i = 0; i < COLS; i++) {
      if (corridor[i]) continue;
      if ((i > 0 && corridor[i - 1]) || (i + 1 < COLS && corridor[i + 1]))
        MAXH[i] = Math.min(MAXH[i], 2);
    }

    /* ---- ②-2 摆堆 ---- */
    /* **整层的箱子预算。** 堆模型不管住总数的话，撞上"可用列特别多"的层
       还是会铺到 30 多格 —— 那就是用户说的"密密麻麻"。
       （第一版给到 26，中位数还是 23 口 —— 加上井梯和洞口盖板就满了，
       而用户说的"密密麻麻"正是这个中位数。）
       预算用完就停止摆堆，剩下的列保持平地（正好是想要的呼吸）。 */
    /* **递进第二项：箱子越深越密。**
       预算 = 20 列 × (0.58 → 0.80)。地表 12 格、门厅 16 格。
       浅层箱子少是为了"看得清路"—— 玩家刚进来要先学会箱山能爬；
       深层铺满，横向移动就得先拆出一条路。
       **上限只有 0.80，不给 1.0**：铺满整层之后主通道也没了，
       那不是我想要的那种难。 */
    /* **总内容量按层数补偿。**（2026-10-29 用户：「层数与内容量需要差异化补偿」）
       同一条 tier 曲线，3 层关只有 2 个内容层、5 层关有 4 个 ——
       按每层固定密度算，短关的总箱子数只有长关的 55%，玩起来"这一关像半关"。
       补偿系数取**半补偿**（开方）：3 层 ×1.41、4 层 ×1.15、5 层 ×1.0。
       全补偿（×2）会让短关每层堆到 22 格，那是我自己都打不过去的密度；
       半补偿之后三档总量落在 34 / 48 / 56 格，差得没那么刺眼了。 */
    const szK = Math.sqrt(4 / Math.max(1, nF - 1));
    let budget = Math.round(COLS * (0.58 + (l.tier || 0) * 0.22) * szK);
    l.boxBudget = budget;          // 只给断言看：这是"难度预算"，和实际的箱子数略有出入
    for (const run of runs) {
      const a = run[0], b = run[1];
      let c = a;
      while (c <= b && budget > 0) {
        /* 堆宽 1~4。**宽度取随机而不是固定 3**，不然整层是等宽的方块阵列，
           又回到"规矩"上去了。 */
        const gw = Math.min(b - c + 1, 1 + Math.floor(R() * 4));
        /* **递进第三项：堆越深越高。**
           地表最多 2 格（3 格箱山在浅层只当"远处的高处"看，不当路），
           门厅才允许整层都是 3 格。跳高 123、一格 48 ——
           2 格差 96 随便跳，3 格差 144 跳不上去，必须绕。
           "绕"就是深度换来的复杂度，而且它不需要加任何新机制。 */
        const peak = Math.min(3, (l.tier || 0) < 0.34
          ? pickOne([1, 1, 2, 2])
          : (l.tier || 0) < 0.67 ? pickOne([1, 2, 2, 3, 3])
            : pickOne([2, 2, 3, 3, 3]));
        for (let t = 0; t < gw; t++) {
          if (budget <= 0) break;
          /* 走廊列不摆。堆在走廊处断开，断口就是通道。 */
          if (corridor[c + t]) continue;
          let h = peak;
          /* 堆形：宽堆的两端矮一级。窄堆不降 —— 1 列再降就是平地，堆就消失了。 */
          if (gw >= 3 && (t === 0 || t === gw - 1)) h = Math.max(1, peak - 1);
          /* 20% 的列再掉一级。**"不规矩"就靠这一下**，但只掉一格 ——
             掉两格会出现 3 格深的口袋，玩家进去要跳两次才出来。 */
          if (h > 1 && chance(0.20)) h -= 1;
          const hh = clamp(h, 1, MAXH[c + t]);
          budget -= hh;
          HGT[c + t] = hh;
        }
        c += gw;
        /* 堆间空地：1 列是底线，浅层 42% 的地方给 2 列，深层只有 12%。
           **两堆紧贴着的话玩家还是在连续的高低地形上走**，等于没改；
           反过来全留两列空地，深层就变成了"一堆孤岛"，那也不难，只是空。
           空地从 42% 收到 12%，就是"越往下越挤"最直接的表达。 */
        if (c <= b) c += 1 + (chance(0.42 - (l.tier || 0) * 0.30) ? 1 : 0);
      }
    }

    /* ---- ②-3 补箱子到门槛 ----
       堆模型天生比"每列都填"少。取一次总数，不够就补 ——
       **顺序是"先给已有的堆加高、再填堆间的空地"**：
       加高只是让堆更鼓，平地还在；反过来先填空地，整层又会变回连续地形，
       那就等于没改。只有在堆全部顶到 MAXH 还凑不够时才去填空地，
       而且填出来只有 1 格（矮台，不挡视线、不挡路）。

       **做成函数而不是一次性代码块**（2026-10-29）：坑修（②-4）会压低
       某些列，压完箱子数可能掉到门槛以下（实测 6 个种子的地表层掉到 7 口）。
       所以要在坑修之后再补一次 —— 两处用同一套逻辑，只能是一个函数。 */
    const makesPit = (i, v) => {
      const H = HGT.slice();
      H[i] = v;
      for (const j of [i - 1, i, i + 1]) {
        if (j <= 0 || j >= COLS - 1) continue;
        if (H[j - 1] - H[j] >= 2 && H[j + 1] - H[j] >= 2) return true;
      }
      return false;
    };
    function topUp() {
      /* **地表层（k = 0）门槛再低一档。** 它同时被"两个下行口 + 地形 + 出生点列"
         吃掉，能摞的列常常只剩十来列；下面每一层都有完整地板，按 10 走。 */
      /* **门槛要和"这层几何上摞得下几口"取小。**
         有的种子地表层被地形 / 洞口缘 / 走廊 / 楼板断口吃掉大半列，能摞箱子的
         只剩 2~6 列 —— 这时"8 口"是物理上达不到的，`topUp` 跑完还是 4 口，
         校验红，`buildLevel` 只好重掷。实测种子 68 的地表只有 13、14 两列能摞。
         这不是"生成器差一点"，是"门槛没有考虑地形"，所以门槛自己要让步：
         上限 = Σ(能摞的列 × 它的层数上限) + Σ(锁死的列已经有的箱数)。
         断言那边用同一条公式（读 `l.colMax`），两边不会各说各话。 */
      const cap = (() => {
        let s = 0;
        for (let i = 0; i < COLS; i++) s += canAdd[i] ? MAXH[i] : HGT[i];
        return s;
      })();
      const need = Math.min((k === 0 || k === nF - 1) ? 8 : 10, cap);
      let cnt = 0;
      for (let i = 0; i < COLS; i++) cnt += HGT[i];
      const grow = (i, room) => {
        if (!canAdd[i] || LOCK[i] >= 0) return 0;
        const add = Math.min(room, MAXH[i] - HGT[i]);
        if (add <= 0) return 0;
        /* **补箱子不许造出新坑。** 加高一列会把它的邻居变成沟底 ——
           这正是"补到门槛"和"没有球坑"两条约束打架的地方，
           打架的结果必须是"少一口箱子"，不能是"多一个球坑"。 */
        if (makesPit(i, HGT[i] + add)) return 0;
        HGT[i] += add;
        cnt += add;
        return add;
      };
      for (let pass = 0; pass < 2 && cnt < need + 1; pass++) {
        /* 先加堆（一次 1 格，避免某堆突然长成一根柱子），再填空地 */
        for (const stacked of [true, false]) {
          for (let i = 0; i < COLS && cnt < need + 1; i++) {
            if ((HGT[i] > 0) !== stacked) continue;
            grow(i, 1);
          }
        }
      }
    }
    topUp();

    /* 削坡：相邻不得超过 2 格。**优先抬高矮的那一边**（不损失箱子），
       矮的那边不能加（地形 / 落点带）时才压高的。 */
    const setH = (j, v) => {
      if (j < 0 || j >= COLS) return;
      const hv = clamp(Math.round(v), Math.max(0, LOCK[j]), MAXH[j]);
      if (!canAdd[j]) {
        /* **敞开的洞口列是"默认不摞箱子"，不是"绝对不能摞"。**
           井梯是硬性的 3 格，它旁边如果正好是一个 0 格的敞口洞，
           高差 3 削不平（144 > 跳高 123），玩家连井梯都爬不上去 ——
           200 个种子里 116 个死在这里。允许敞口洞抬到 1 格就够了：
           洞口上多一口能砸的木箱，敞口"一眼看见"的卖点没变。 */
        if (holeCol[j] === 'none' && hv >= 1) HGT[j] = 1;
        return;
      }
      HGT[j] = hv;
    };
    const smooth = () => {
      for (let round = 0; round < 10; round++) {
        let moved = false;
        for (let i = 0; i + 1 < COLS; i++) {
          const df = HGT[i] - HGT[i + 1];
          if (Math.abs(df) <= 2) continue;
          moved = true;
          if (df > 2) {
            if (canAdd[i + 1]) setH(i + 1, HGT[i] - 2);
            else setH(i, HGT[i + 1] + 2);
          } else {
            if (canAdd[i]) setH(i, HGT[i + 1] - 2);
            else setH(i + 1, HGT[i] + 2);
          }
        }
        if (!moved) break;
      }
    };

    /* ---- ②-4 填掉"球坑" ----
       用户 2026-10-29：「主要是球进入了死胡同 比如上坡 完全推不上去了」。
       削坡保证的是"人能翻过去"（高差 ≤2 格），**对球没有任何保证** ——
       球只会被水平推。两座 3 格箱山夹一条 1 列宽的缝，球滚进缝底
       就永远出不来：左脚 144、右脚 144，中间 48。

       修法：**抬沟底，不削两邻。** 削邻居会连锁（削完右边又是新的高差，
       而削一次就少一格箱子）；抬自己只动一列，而且抬完的高度正好是
       "比矮的那边低一格" —— 球滚进去也翻得出来。
       抬不动（地形/落点带锁死）就压低高的那一侧。 */
    const fillPits = () => {
    for (let round = 0; round < 4; round++) {
      const pits = ballPits(HGT);
      if (!pits.length) break;
      for (const i of pits) {
        const lo = Math.min(HGT[i - 1], HGT[i + 1]);
        /* 抬自己：抬到"比矮的那边还低一格"。`MAXH` 可能是 0（走廊列），
           那样就抬不动 —— 这时必须落到下面压邻居的分支，
           不能 `continue`（第一版就是这里 continue 了，5 轮全白跑，
           200 个种子里 56 个卡在"还剩一个球坑"）。 */
        const raiseTo = Math.min(lo - 1, MAXH[i]);
        if (canAdd[i] && raiseTo > HGT[i]) { HGT[i] = raiseTo; continue; }
        /* 压邻居：挑**矮的**那一边压到 `HGT[i]+1`，变化最小。
           高的那边压下来要连降两级，会把一座箱子山挖平。 */
        /* `LOCK[j] <= HGT[i]` 这一条不能少：覆霜盖板列 `canAdd` 是 true，
           但 `LOCK` 把它的下限锁在 2 格 —— 不排除的话 setH 会"设置成功"
           却什么都没变（clamp 回 2），然后在 `continue` 里把最后一招也跳过。 */
        const cands = [i - 1, i + 1].filter(j =>
          j > 0 && j < COLS - 1 && canAdd[j] && HGT[j] > HGT[i] + 1 && LOCK[j] <= HGT[i]);
        cands.sort((a, b) => HGT[a] - HGT[b]);
        if (cands.length) { setH(cands[0], HGT[i] + 1); continue; }
        /* 最后一招：**在主通道里垫一格。**
           走到这里说明两边的邻居都压不下去（它们是洞口盖板，被 `LOCK`
           锁死在 2 格）而自己是走廊列、抬不动。实测 200 个种子里还有 4 个
           卡在这种"2-0-2 且两边都是盖板"的位置上。
           走廊的保证本来是"从它爬上任何箱山，高差 ≤2 格"——
           垫到 1 格（差 1 格）这条保证仍然成立，只是多了一口能砸的木箱。
           一条 1 格高的雪坎，比"球滚进去 16 秒出不来"划算得多。 */
        if (LOCK[i] < 0 && !l.terrain.some(t => i * 48 + 48 > t.x && i * 48 < t.x + t.w)) {
          HGT[i] = 1; MAXH[i] = Math.max(MAXH[i], 1);
        }
      }
    }
    };
    /* ================= 三条约束互相打架，只能轮流收敛 =================
       ① 相邻高差 ≤ 2（人爬得上去）
       ② 没有球坑（球滚不进去出不来）
       ③ 箱子够门槛（不然这一层没内容）
       它们不是独立的：补箱子会造出高差和球坑，削坡会削掉箱子，
       填坑又会抬出一列新的高差。**所以不能各自跑一遍就完事** ——
       实测补箱子跑在削坡之后，直接把地表层造出"3 格紧挨 0 格"，
       整段 8~19 列判成走不到。

       现在的顺序：削坡 / 填坑 交替 3 轮 → 补箱子 → 再交替 2 轮 →
       最后才是 ②-5（够不够得着）和木桶/金箱的选点。
       补箱子用 `grow` 里的 makesPit 守卫，削坡和填坑都用 clamp，
       所以这套交替一定收敛。 */
    for (let it = 0; it < 3; it++) { smooth(); fillPits(); }
    topUp();
    for (let it = 0; it < 2; it++) { smooth(); fillPits(); }

    /* ---- ②-5 "3 格以上的列，至少要有一侧够得着" ----
       削坡保证的是"相邻高差 ≤ 2"，但它抬不动被 LOCK 锁死的列 ——
       井梯（3 格）就是锁死的那种。于是一个 3 格井梯和两边的 0 格并排时，
       削坡改不了任何一边，**这一整段从外面进不来**（高差 144 > 跳高 123）。

       判据和 `unreachableCols` 用的是同一条：想站上 h 格，得先有一侧 ≥ h-2。
       修法是抬一侧（补一口箱子），抬不动就把自己压到 2 格。
       抬高只抬到 h-2，不会和削坡打架。 */
    for (let round = 0; round < 3; round++) {
      let moved = false;
      /* **首尾两列也要查。** 第 0 列左边是墙、只能从右边上，
         所以它"够不够得着"的判据和中间一样，跳过它就会留下
         "3 格贴墙 + 邻列 0 格"的死段（实测 3 个种子栽在这里）。 */
      for (let i = 0; i < COLS; i++) {
        if (HGT[i] < 3) continue;
        const okL = i > 0 && HGT[i - 1] >= HGT[i] - 2;
        const okR = i < COLS - 1 && HGT[i + 1] >= HGT[i] - 2;
        if (okL || okR) continue;
        const inSeg = j => l.segs.some(s => j * 48 >= s.x && (j + 1) * 48 <= s.x + s.w);
        const v = HGT[i] - 2;
        const cand = [i - 1, i + 1].filter(j =>
          j > 0 && j < COLS - 1 && inSeg(j) && canAdd[j] && MAXH[j] >= v &&
          LOCK[j] <= v && HGT[j] < v && !makesPit(j, v));
        if (cand.length) { HGT[cand[0]] = v; moved = true; }
        else { HGT[i] = 2; moved = true; }
      }
      if (!moved) break;
    }
    /* 金箱放在最高的那一列顶上（h >= 3 才有）。**这是"探索"的奖励落点** ——
       爬上去才够得着，砸开有东西。每层最多一个。 */
    let lootCol = -1;
    {
      const tops = [];
      for (let i = 0; i < COLS; i++) if (HGT[i] >= 2 && canAdd[i]) tops.push(i);
      if (tops.length && chance(0.50 + (l.tier || 0) * 0.40)) lootCol = tops[Math.floor(R() * tops.length)];
    }

    /* ---- 桶 ----
       用户 2026-10-28：「也可以有桶装啊」。

       **桶的作用是打破方块的节奏，不是"换个材质的箱子"。** 一排排 48×48
       的木箱里插一个圆柱，眼睛立刻读出"这里不是墙"。所以它只出现在
       堆里、每层 1~2 个，位置挑堆的最底层（像被人随手搁下）或堆顶。
       洞口盖板列不参与（那里必须是能被砸开/被埋的立方块），金箱也不换。 */
    const barrels = [];
    {
      const cand = [];
      for (let i = 0; i < COLS; i++) {
        if (HGT[i] < 1 || !canAdd[i]) continue;
        if (l.holes.some(o => i * 48 + 48 > o.x && i * 48 < o.x + o.w)) continue;
        cand.push(i);
      }
      const nb = Math.min(cand.length, 1 + ri(0, 1));
      const usedB = [];
      for (let t = 0; t < 40 && usedB.length < nb; t++) {
        const i = cand[Math.floor(R() * cand.length)];
        if (usedB.indexOf(i) >= 0) continue;
        usedB.push(i);
        const j = chance(0.55) ? 0 : HGT[i] - 1;
        barrels.push(i + ":" + j);
      }
    }

    /* ---- ③ 按图生成 ---- */
    for (let i = 0; i < COLS; i++) {
      const h = HGT[i];
      if (h <= 0) continue;
      const x = i * 48;
      const hole = l.holes.find(o => x + 48 > o.x && x < o.x + o.w);
      const isLoot = (i === lootCol);
      for (let j = 0; j < h; j++) {
        const y = l.floorY - 48 * (j + 1);
        if (hole && hole.cover === 'ice') { if (j < 2) B(x, y, 'ice'); continue; }
        if (hole && hole.cover === 'frost' && j === 0) { B(x, y, 'wood', { frost: true }); continue; }
        const lootHere = (isLoot && j === h - 1);
        /* 桶只在普通木箱的位置上换，不碰金箱。 */
        if (!lootHere && barrels.indexOf(i + ":" + j) >= 0) { B(x, y, 'wood', { barrel: true }); continue; }
        B(x, y, matRoll(R()), lootHere ? { loot: true } : null);
      }
    }

    /* 每列的落脚面（箱子顶）。⑥ 放怪、⑦ 摆地面道具都用它 ——
       **不能再假设"地面就是 floorY"**：箱子铺开之后地面几乎全被占了。 */
    l.colHgt = HGT;
    l.colAdd = canAdd;
    /* **每列"还能补几口箱子"的上限。** 断言要靠它算"这一层几何上最多能有几口" ——
       有的种子地表层被地形 / 洞口缘 / 走廊 / 楼板断口吃掉大半列，只剩两三列能摞，
       这时"门槛 8 口"是物理上达不到的，不是生成器的锅，也不该靠重掷去碰运气。
       两条不能算进去的：
       · `LOCK >= 0` 的列（洞口盖板 / 井梯）高度是锁死的，只能算现有的箱数
         —— 种子 154 的第 19 列栽在这上面：覆霜盖板锁在 2 格，按 `MAXH` 算出来的
         门槛永远补不满；
       · **再往上加就造出球坑的格子不算**。判据和 `topUp` 里的守卫是同一个
         `makesPit` —— 种子 154 第 19 列本身能从 1 补到 2，可那样第 18 列
         （0 格）就成了"2-0-2"的死沟，所以它其实补不上。 */
    l.colCap = [];
    for (let i = 0; i < COLS; i++) {
      if (!canAdd[i] || LOCK[i] >= 0) { l.colCap.push(HGT[i]); continue; }
      let v = HGT[i];
      while (v < MAXH[i] && !makesPit(i, v + 1)) v++;
      l.colCap.push(v);
    }
    l.colTop = [];
    for (let i = 0; i < COLS; i++) l.colTop.push(l.floorY - 48 * HGT[i]);
    /* 主通道要能被画出来（见 drawTrail）。**这不是装饰** ——
       走廊在几何上是硬的，可玩家看不出哪一列是"路"、哪一列只是"恰好没摆箱子"。 */
    l.corridor = corridor;
  });

  /* ---- 出生点清箱 + 重算列顶 ----
     **这两步必须在 ⑥⑦ 之前做。** 原来放在 ⑧（最后），于是：
     箱子生成时算出的 `colTop` 还是"这列有 3 层"，
     出生点一清就是整整一列的箱子被删掉，而 ⑥ 的怪 / ⑦ 的路牌、木桶
     早就按那个过期的列顶摆好了 —— 地表那张图右上角两个路牌悬在半空，
     离地 140px，看着像删不掉的 UI。删箱不改 R() 序列，前移是安全的。

     **用"删箱子"而不是"往右挪"** —— 挪的写法要在"还在段内"和
     "不压箱子"之间反复试，试不出来就把人推到洞上；
     直接删掉占位的那口箱子，一步到位，而且玩家永远看不出区别。 */
  for (let i = boxes.length - 1; i >= 0; i--) {
    const b = boxes[i];
    /* **y 的上界不能省。** 第一版只写了"底边在地表以上 140 以内"，
       而这句话对深层恒真（门厅的箱子当然比地表低得多），
       结果地表清箱子时把整张图里 x 靠近出生点的箱子全删了 ——
       门厅的喂球箱就这样少了两口，直接踩死局线。 */
    /* **只清出生点那一列。** 玩家的 x 现在对齐到列（见 startCol 的注释），
       整条命都在同一列里，删不到隔壁。 */
    if (b.x === startCol * 48 &&
        b.y + b.h > GEN.topY - 140 && b.y < GEN.topY + 20) boxes.splice(i, 1);
  }

  /* ---- 出生点清箱的补丁：两侧邻列压到 2 格 ----
     **削坡跑在清箱之前，它以为出生点那一列还是原来的高度。**
     清成 0 之后，紧挨着的 3 格井梯就变成"高差 144"的硬墙（跳高只有 123），
     那一整段（含井梯本身）从出生点根本过不去 —— BFS 会把它们全判成走不到。

     实测种子 68：地表 HGT = 0,0,0,0,0,0,**0**,3,0,…，
     出生点清掉第 6 列之后，第 7 列的 3 格井梯把 8~19 列整段封在后面。

     修法是删掉两侧邻列最高那一口箱子（压到 2 格）。
     代价是那一格井梯只剩 2 格、回不到上一层 —— 但那条路本来就是"回头"的
     备选，而"整段过不去"是硬伤。两害相权，压井梯。 */
  for (const jc of [startCol - 1, startCol + 1]) {
    if (jc <= 0 || jc >= 19) continue;
    for (let i = boxes.length - 1; i >= 0; i--) {
      const b = boxes[i];
      if (b.x !== jc * 48) continue;
      if (!(b.y + b.h > GEN.topY - 200 && b.y < GEN.topY + 20)) continue;
      /* 只删"第 3 格及以上"（y 比第 2 格还高）—— 删到剩 2 格为止，
         第 1、2 格必须留着，否则又变成新的高差。 */
      if (b.y >= GEN.topY - 96 - 1) continue;
      boxes.splice(i, 1);
    }
  }

  /* 重算列顶：只认"属于本层"的箱子（底边在本层地板上，顶不超过 3 格）。 */
  layers.forEach(l => {
    if (!l.colTop) return;
    for (let i = 0; i < COLS; i++) {
      let top = l.floorY;
      for (const b of boxes) {
        if (b.x + b.w <= i * 48 || b.x >= (i + 1) * 48) continue;
        if (b.y >= l.floorY || b.y + b.h <= l.floorY - 220) continue;
        if (b.y < top) top = b.y;
      }
      l.colTop[i] = top;
    }
  });

  /* ================= ⑥ 怪 =================
     `y` 是**头顶**，站在 y=K 的面上就写 K-30，写 K 会埋进地里。 */
  const spawns = [];
  layers.forEach((l, k) => {
    /* **2~4 只，不再是 1~3 只。** 用户 2026-10-28 两次提到：
       「怪物可以搞多点」「宠物太少了」。
       怪就是弹药 —— 裹住一只才有一颗球，球碾死一只才够档破冰。
       怪少的时候"没球可推"不是数值问题，是材料问题。
       门厅固定 3 只不动，那个数是死局线（见 NUM.killTarget 的注释）。 */
    /* **递进第五项：怪越深越多，2 → 3 → 4，不再掷骰子。**
       用户 2026-10-28 说过「怪物可以搞多点」，但"每层随机 2~4 只"的问题是
       第 2 层可能比第 4 层更满 —— 数量是玩家最能直接感到的难度，
       它必须单调。门厅固定 3 只（那是 killTarget 的死局线）。
       阈值 0.22 / 0.60 而不是 1/3、2/3：5 层关的 tier 是 0/0.25/0.5/0.75/1，
       用三等分会把第 1、2 层都压成 2 只，前两层一样空。 */
    const tier = l.tier || 0;
    /* **层数补偿**：3~4 层关每层多一只（见 ②-2 里箱子预算的同一段注释）。
       门厅不动 —— 门厅那 3 只是 killTarget 的死局线。 */
    const want = (k === nF - 1) ? 3
      : 2 + (tier >= 0.22 ? 1 : 0) + (tier >= 0.60 ? 1 : 0) + (nF <= 4 ? 1 : 0);
    /* **候选点按"列"取，不按 8px 步长扫。**
       箱子铺开之后地面几乎每一处都摞着东西，用连续扫描的话一层的候选点
       会被 200 口箱子切成几十个碎点，"取不住"就成了缺怪。
       一列一个点，最多 20 个，够用而且稳。 */
    /* **两轮：先躲出生点，候选不够再放开。**
       地表层的可用列本来就少（箱子占掉大半），再挖掉出生点周围 130px，
       会出现一只怪都放不下的关（200 个种子里撞过一次）。
       怪贴脸是观感问题，缺怪是死局问题 —— 先保后者。 */
    let cands = [];
    for (let i = 0; i < COLS; i++) {
      const x = i * 48;
      const inSeg = l.segs.some(s => x >= s.x && x + 48 <= s.x + s.w);
      if (!inSeg) continue;
      if (k === 0 && Math.abs(x + 24 - startX) < 130) continue;   // 开局别贴脸
      /* **落脚面是"箱子顶"，不是地板。** 怪站在箱山上是合理的 ——
         箱子是路，谁都能走；而且箱子被砸掉之后它自然会掉下来。 */
      const gy = (l.colTop && l.colTop[i] != null) ? l.colTop[i] : l.floorY;
      /* **太高的箱顶不放**：雪弹是水平飞的，站在 2 格（96）以上玩家打不到。 */
      if (l.floorY - gy > 100) continue;
      /* **左右相邻列比自己高 = 站进凹槽里。** 怪宽 34、列宽 48，
         本列站得下，可旁边那列多摞一格，它往前走 7px 就撞到箱墙。
         这种位置不硬排除（排除之后有的层一只怪都挑不出来），
         而是打个 open 标记排在后面 —— 候选够的时候用开阔的，
         不够才退而求其次；真落进 14px 的凹槽，stepFoes 会让它站定，
         不会再每帧撞墙来回抽。 */
      const hiL = (l.colTop && l.colTop[i - 1] != null) ? l.colTop[i - 1] : l.floorY;
      const hiR = (l.colTop && l.colTop[i + 1] != null) ? l.colTop[i + 1] : l.floorY;
      const open = hiL >= gy - 8 && hiR >= gy - 8;
      /* 洞口正上方不放：那是"往下走"的地方，站着怪等于堵门。 */
      if (l.holes.some(h => x + 48 > h.x - 8 && x < h.x + h.w + 8)) continue;
      /* **门的正前方不放。** 门是 32×40，怪是 34×33 —— 站上去正好把门
         整块盖住，出图上就是"一扇门里塞了一只虫"，玩家根本看不见门。
         门本来就被箱子埋着（那是设计），再被怪盖一层就找不着了。
         只加在主筛里、**不加在兜底里**：兜底是"这层实在没地方了"，
         那时缺怪是死局，挡门只是观感。 */
      if (k === nF - 1 && x + 48 > door.x - 10 && x < door.x + door.w + 10) continue;
      /* 斜坡上不放：`colTop` 只认箱子，认不出坡面 —— 怪会站在坡体内部
         （脚的 y 停在坡底、坡面却高出一截，垂直贴面判据永远不成立）。 */
      if (l.terrain.some(t => t.kind === 'ramp' && t.x - 12 < x + 48 && t.x + t.w + 12 > x)) continue;
      cands.push({ x: x + 7, y: gy, open });
    }
    if (!cands.length) {
      for (let i = 0; i < COLS; i++) {
        const x = i * 48;
        if (!l.segs.some(s => x >= s.x && x + 48 <= s.x + s.w)) continue;
        const gy = (l.colTop && l.colTop[i] != null) ? l.colTop[i] : l.floorY;
        /* **兜底只排除"根本站不住"的列，不再卡 100px。**
           原来这里也照抄了主筛选的 `> 100`，于是"整层箱子都很高"的层
           会连一只怪都放不出来（5 号种子第 2 层就是这样，一关只剩 8 只）。
           宠物现在会跳、玩家也会爬上箱山，3 格（144）是站得住的上限。 */
        if (l.floorY - gy > 144) continue;
        if (l.holes.some(h => x + 48 > h.x - 8 && x < h.x + h.w + 8)) continue;
        if (l.terrain.some(t => t.kind === 'ramp' && t.x - 12 < x + 48 && t.x + t.w + 12 > x)) continue;
        cands.push({ x: x + 7, y: gy, open: false });
      }
    }
    if (!cands.length) return;
    /* **优先挑开阔位**：候选里够的话，先只用"左右不比它高"的那些。 */
    const openOnes = cands.filter(c => c.open);
    const all = (openOnes.length >= want ? openOnes : cands).slice();
    /* **不再"候选用完就整池重来"。**
       原来 `if (!pool.length) pool = all.slice()` —— 那一行等于允许两只怪
       落在同一个位置上，出图上就是"蓝色甲虫压着一团绿色苔藓"，
       看起来像一只长了两层壳的怪。用户说的"乱得没办法辨"里，这一条占了很大比重。
       现在改成**两档间距**：先按 96（约 2.6 个身位）挑，确实不够再降到 56；
       两档都没有空位就**少放一只**，叠在一起比少一只难看得多。

       `y` 也跟着改成 `FOE_H`：原来写死 -30 是旧身高（30），
       敌人加高到 33 之后，出生第一帧会陷进地面 3px。 */
    const used = [];
    for (let i = 0; i < want; i++) {
      let pool = all.filter(o => used.every(u => Math.abs(o.x - u) >= 96));
      if (!pool.length) pool = all.filter(o => used.every(u => Math.abs(o.x - u) >= 56));
      if (!pool.length) {
        /* 两档都不够时**挑离已有怪最远的那个位置**，而不是干脆不放。
           直接 break 会让"箱子把这一层塞满"的种子少一只怪
           （5 号种子就掉到 7 只，撞在"一关至少 8 只"那条上）——
           关卡生成的基本盘不能为了排布好看而缩水，最多是"离得近一点"。 */
        let best = null, bestD = -1;
        for (const o of all) {
          const d = used.reduce((m, u) => Math.min(m, Math.abs(o.x - u)), Infinity);
          if (d > bestD) { bestD = d; best = o; }
        }
        if (!best) break;
        pool = [best];
      }
      const c = pool[Math.floor(R() * pool.length)];
      used.push(c.x);
      spawns.push({
        x: Math.round(c.x), y: Math.round(c.y) - FOE_H, layer: k,
        /* **递进第六项：会追人的 fang 越深越多。**
           地表 0%、第 2 层约 27%、门厅约 57%。追击型敌人逼玩家换位，
           巡逻型只看距离 —— 前者是"复杂"，后者只是"多"。
           **不用 `k > 1` 判**：3 层关的 k 只有 0/1/2，按 k 判的话
           短关一只 fang 都没有，同一份难度曲线在 3 层和 5 层上不一样。 */
        kind: (tier >= 0.30 && chance(0.10 + tier * 0.50)) ? 'runner' : 'crawler',
      });
    }
  });

  /* ================= ⑥.5 黑洞（吐怪的巢）=================
     用户 2026-10-28：「可以搞个生成怪物的黑洞，可以到处走」。

     **它解决的是"怪打完就没了"这件事。** 一关十只怪，玩家用雪弹打光之后
     就只剩砸箱子；而"球"的唯一来源是敌人 —— 怪清光等于玩法断电。
     黑洞提供一条"还会再长出来"的来源，但**有配额**（3~5 只），
     不会变成无限刷怪机：配额用完它就暗下去，仍然挂在那儿当场景。

     **只放在第 1 层以下。** 地表层是教学层，一进关旁边就有台吐怪机，
     玩家还没学会吐雪就被围死了。 */
  const nests = [];
  {
    const nWant = 1 + (chance(0.5) ? 1 : 0);
    const used = [];
    for (let t = 0; t < 60 && nests.length < nWant; t++) {
      const k = 1 + Math.floor(R() * Math.max(1, nF - 1));
      if (k >= nF) continue;
      const l = layers[k];
      const segs = l.segs.filter(s => s.w >= 144);
      if (!segs.length) continue;
      const seg = segs[Math.floor(R() * segs.length)];
      /* **黑洞必须坐在地板上，不能跟着箱山顶走。**
         2026-10-28 之前取的是 `colTop[col]` —— 那一列堆了两格箱子时，黑洞就
         悬在箱堆顶上，读起来是"墙上贴了一个紫色椭圆"（用户指着截图说
         "太突兀了""可以地下做个玄关"）。它本来就是"地面塌出来的一个口"。

         **做法是换一列，不是把箱子删掉。** 删箱子看着更直接，但那是拿掉一摞
         可能被井梯当踏脚的地形 —— 实测 26 次"跳回上一层"里有 4 次因此上不去。
         挑一列本来就空着的地面，零副作用。 */
      const cols = Math.max(1, Math.floor((seg.w - 48) / 48));
      const col0 = Math.floor(seg.x / 48);
      let col = -1;
      for (let cc = 0; cc < 6 && col < 0; cc++) {
        const c = col0 + Math.floor(R() * cols);
        const top0 = (l.colTop && l.colTop[c] != null) ? l.colTop[c] : l.floorY;
        if (top0 === l.floorY) col = c;
      }
      if (col < 0) continue;
      const x = clamp(col * 48 + 24, seg.x + 24, seg.x + seg.w - 24);
      /* 洞口正上方不放：那是唯一的上下通道，堵在那里等于封路。 */
      if (l.holes.some(h => x + 30 > h.x - 8 && x - 30 < h.x + h.w + 8)) continue;
      if (used.some(u => Math.abs(u - x) < 240)) continue;
      used.push(x);
      nests.push({
        x, y: l.floorY, layer: k,
        left: 3 + Math.floor(R() * 3),       // 3~5 只配额
        cd: 1.4 + R() * 1.2,                 // 开局先缓一下
        dir: R() < 0.5 ? -1 : 1,
        seed: Math.floor(R() * 1000),
      });
    }
  }

  /* ================= ⑥.6 实体小道具（陶罐 / 小箱）=================
     **用户 2026-10-28：「又不形成阻挡啥的 就是个图贴上去」。**

     上一版罐子和木箱是 deco —— 画在场景里但没有碰撞，人从中间穿过去。
     一个"看起来能装东西"的容器穿得过去，这片场景就没有可信度了。

     所以把"落地容器"整类搬进 `boxes`：同一套碰撞、同一套被打碎、同一套掉弹。
     规则变得只有一条 —— **看着能撞的，就真能撞。**
     （木桶早就这样；货架太大，会堵路，直接不做这个种类。） */
  {
    const PROPS = [
      { kind: 'jar', w: 22, h: 30, mat: 'stone' },
      { kind: 'crate', w: 30, h: 30, mat: 'wood' },
    ];
    for (let k = 0; k < nF; k++) {
      const l = layers[k];
      const n = 1 + (chance(0.55) ? 1 : 0);
      for (let i = 0; i < n; i++) {
        const p = PROPS[Math.floor(R() * PROPS.length)];
        let px = null, py = 0;
        for (let t = 0; t < 20 && px == null; t++) {
          const c = Math.floor(R() * COLS);
          const cxp = c * 48 + 24;
          /* 不压本层洞口（那是唯一的上下通道）、不压出生点、不压门厅 */
          if (l.holes.some(h => cxp + 30 > h.x - 16 && cxp - 30 < h.x + h.w + 16)) continue;
          if (k === 0 && Math.abs(cxp - startX) < 96) continue;
          if (door && cxp + 30 > door.x - 20 && cxp - 30 < door.x + door.w + 20) continue;
          /* **不摆在斜坡上。** `colTop` 只认箱子，认不出坡面 ——
             摆上去就是"一只 30×30 的小箱浮在坡面上"，玩家走过去会被它
             反复顶起来又掉下去（实测在下坡那条断言里量到 13 次落地翻转）。
             这条规则放怪那一处早就有（见 ⑥），道具这里一直漏着。 */
          if (l.terrain.some(t => t.kind === 'ramp' && t.x - 24 < cxp + 30 && t.x + t.w + 24 > cxp - 30)) continue;
          const top = (l.colTop && l.colTop[c] != null) ? l.colTop[c] : l.floorY;
          px = cxp; py = top;
        }
        if (px == null) continue;
        boxes.push({
          x: px - p.w / 2, y: py - p.h, w: p.w, h: p.h, mat: p.mat,
          hp: 1, dead: false, hitT: 0, taught: false, fell: 0,
          frost: false, loot: false, barrel: false,
          jar: p.kind === 'jar',
          prop: true,
        });
      }
    }
  }

  /* ================= ⑦ 装饰 =================
     **"场景丰富"不是往里塞东西，是塞对的东西。**
     每一件道具都在说一句"这里有人住过"：吊灯 = 有人点灯；
     木桶罐子 = 有人存货；路牌 = 有人留过路；蛛网 = 很久没人来了。
     用户要的"商业化场景"其实就是这种可读性 —— 空白和杂乱都不行。

     **全部是纯装饰，不碰碰撞。** 位置只受三条约束：
     不压洞口、不浮空（地面件踩在本列落脚面上）、不互相重叠。
     绘制上统一排在箱子之后，箱子会自然地把道具挡在后面。
     */
  const deco = [];
  const CEIL_KINDS = ['lamp', 'chandelier', 'lantern', 'beam', 'rope', 'vine', 'web', 'flag'];
  /* **落地容器不在这里了**（barrel / jar / crate 都搬去 ⑥.6 当实体）。
     这一池只剩"不装东西、撞不撞无所谓"的小物件：路牌、蘑菇、断梯。 */
  const FLOOR_KINDS = ['sign', 'mush', 'stones', 'stump', 'ladder'];

  for (let k = 0; k < nF; k++) {
    /* **`usedX` 必须每层重置。** 放在层循环外面的话它会跨层累积，
       第 4 层时已有二三十个占位点，新道具根本找不到 62px 的空档 ——
       层越深越空，正好和"场景要丰富"相反（截图才看出来）。 */
    const usedX = [];
    const l = layers[k];
    const fY = l.floorY;
    /* 天花板 = 上一层地板底面；地表层没有天花板，用屏幕上方当"屋梁"。 */
    const cY = k > 0 ? floors[k - 1] + GEN.thick : GEN.topY - 150;
    /* **两份避让表，不能合成一份。**
       天花板件只需要让开"上面那层的洞口"（挂灯会堵住从上层下来的通道）；
       地面件只需要让开"本层的洞口"（摆在洞上就是浮在空里）。
       曾经把两边 push 进同一个数组，一层两个洞 + 上层两个洞 = 四条 ±40 的区间，
       加上采样半径 34，几乎把 960px 宽的整条都盖住了 ——
       采样 24 次全落空，103 层里有 22 层一件装饰都没有，
       表面上是"随机不够密"，实际是约束互斥。 */
    const avoidDown = l.holes.map(h => [h.x - 40, h.x + h.w + 40]);
    const avoidUp = k > 0 ? layers[k - 1].holes.map(h => [h.x - 40, h.x + h.w + 40]) : [];

    /* **按"种类"抽，不按"个数"抽。** 按个数抽会抽出"每层五个木桶"，
       重复感比空着更糟。每层 3~6 种，每种 1~3 件。 */
    /* **地表层没有天花板，所以一件"挂件"都不能放。**
       这里曾经只滤掉 web / vine，结果旗子、吊灯、绳子全挂在
       `topY-150` 的半空 —— 地表那张图右上角就飘着一面红旗，
       像游戏里有个删不掉的 UI。地表的顶是天空，只放落地的东西。 */
    const pool = k === 0 ? FLOOR_KINDS : CEIL_KINDS.concat(FLOOR_KINDS);
    const chosen = [];
    /* **种类池从 12 涨到 15，抽取数也要跟着涨**：停在 4~6 的话，
       每层挂件数量没变但摊薄到更多种类上，实际密度反而下降。 */
    const nKind = Math.min(pool.length, 5 + ri(0, 3));
    for (let t = 0; t < 60 && chosen.length < nKind; t++) {
      const c = pool[Math.floor(R() * pool.length)];
      if (chosen.indexOf(c) >= 0) continue;
      chosen.push(c);
    }
    /* **主灯每层保底（地表层除外，它上面是天空）。**
       光照是场景的第一层秩序：有的层有一盏主灯、有的层没有，
       整片看过去就是"这几层是随手拼的"。十五种里抽五六种，
       单靠随机大概只有一半的关能抽到枝形吊灯 —— 那就等于没有规律。 */
    if (k > 0 && chosen.indexOf('chandelier') < 0) chosen.push('chandelier');
    for (const kind of chosen) {
      /* 地表不放梯子。**地表上面是天空，梯子没地方靠** ——
         一根 100px 高的直梯竖在雪地中间，读起来就是"能爬"，而它其实不能。
         地下才有"靠墙"这个语境，也才有"这里塌过"的叙事。 */
      if (kind === 'ladder' && k === 0) continue;
      const isCeil = CEIL_KINDS.indexOf(kind) >= 0;
      let n = ri(1, (kind === 'mush' || kind === 'jar' || kind === 'vine') ? 3 : 2);
      /* 吊灯每层至少一盏：**它是地下唯一的光源**，没有它整层是平光。
         但同层已经有枝形吊灯（三簇烛火 + 一圈大光晕）时，吊灯退回"补光"，
         一盏就够 —— 两个大光源同层会把木墙打成一片均匀的黄色，反而没有体积。 */
      if (kind === 'lamp' && k > 0) {
        n = chosen.indexOf('chandelier') >= 0 ? 1 : Math.max(n, 2);
      }
      /* 主灯一盏。它是画面上最亮的东西，两盏就开始抢主角。 */
      if (kind === 'chandelier') n = 1;
      /* 断梯子是"痕迹"，不是货架 —— 一层一件，多了像工地。 */
      if (kind === 'ladder') n = 1;
      for (let i = 0; i < n; i++) {
        let x = null;
        for (let t = 0; t < 30; t++) {
          const cxx = 44 + Math.round(R() * 852);
          if (hitsRange(cxx, 34, isCeil ? avoidUp : avoidDown)) continue;
          /* 地表别摆在出生点旁边。**路牌是左右各伸出 26px 的，贴着人放
             就读成"角色举着一块牌子"** —— 缩略图上一眼就看见。 */
          if (k === 0 && Math.abs(cxx - startX) < 70) continue;
          /* **后 10 次把间距放宽到 44。** 地表层被两个洞口切成三小段，
             62px 的间距在碎成三段的地面上采不满 —— 40 个种子里会有 1 层
             只剩 2 件装饰，整层看着就是"没做完"。挤一点比秃着强。 */
          if (usedX.some(u => Math.abs(u - cxx) < (t < 20 ? 62 : 44))) continue;
          /* **梯子必须站在真地板上。** 它是 100px 高的立式道具，站在箱山顶上
             就读作"一架够不到任何地方的梯子"；木桶和蘑菇站在箱上是"堆场"，
             梯子站在箱上是"bug"。所以这一类要额外卡一条：本列没有箱子。 */
          if (kind === 'ladder') {
            const gi0 = clamp(Math.floor(cxx / 48), 0, COLS - 1);
            const top0 = (l.colTop && l.colTop[gi0] != null) ? l.colTop[gi0] : fY;
            if (top0 !== fY) continue;
          }
          x = cxx;
          break;
        }
        if (x == null) continue;
        const gi = clamp(Math.floor(x / 48), 0, COLS - 1);
        /* 地面件踩在"本列落脚面"上 —— 可能是地板，也可能是箱山顶。
           木桶摆在箱山上比摆在地上更好看，那是"堆场"该有的样子。 */
        const gy = isCeil ? cY : ((l.colTop && l.colTop[gi] != null) ? l.colTop[gi] : fY);
        usedX.push(x);
        deco.push({
          x, y: isCeil ? gy : gy + 1, kind, layer: k,
          /* 绘制分两批用：挂件在箱子后面，落地件在箱子前面。
             落地件站在箱顶时，只要相邻列比它高，就会被后画的箱子吞掉 ——
             地表层箱子密，整层装饰在图上直接"消失"了。 */
          ceil: isCeil,
          w: 0, h: 0, seed: Math.round(x * 13 + k * 97),
        });
      }
    }
  }

  /* ================= ⑧ 出生点 =================
     地表第一段地板的左侧。**不能在洞口上**，也不能头顶压着箱子。
     `startX` 在 ② 之后就定好了；占位箱子的清理已经前移到 ⑥ 之前
     （见那里的注释），这里只负责落最终坐标。 */

  /* 兜底：全关一口金箱都没有（各层都掷空）。**探索奖励不能是"可能没有"** ——
     没有金箱，整关就只剩"搬箱子下楼"，没有"拆开有东西"这一层意思。
     挑最高的一口非冰墙箱子补上（y 最小 = 位置最高）。 */
  if (!boxes.some(b => b.loot)) {
    let best = null;
    for (const b of boxes) {
      if (b.mat === 'ice' || b.frost) continue;
      if (!best || b.y < best.y) best = b;
    }
    if (best) best.loot = true;
  }

  const plats = [];
  layers.forEach(l => {
    for (const s of l.segs) plats.push(s);
    for (const t of l.terrain) plats.push(t);
  });

  WORLD_H = lastY + GEN.thick + 40;
  GROUND_Y = lastY;
  FLOORS = floors;
  LAYER_CN = layerCN;
  LAYERS = layers;
  /* 所有洞的 x 区间，按层序扁平展开（只在断言里用）。
     **别拿它的下标当层号** —— 一层的洞可能有两个，下标和层号会错位；
     要"第 k 层的洞"请用 LAYERS[k].holes。 */
  HOLES = [];
  layers.forEach(l => l.holes.forEach(h => HOLES.push([h.x, h.x + h.w])));

  return {
    seed, nFloors: nF,
    floors, layers, plats, boxes, deco, door, spawns, nests,
    start: { x: startX, y: GEN.topY - PLAYER_H },
    worldH: WORLD_H, groundY: GROUND_Y,
  };
}

/** **每层的"走不走得通"，用脚量，不用眼看。**

    用户 2026-10-29：「空间设计要合理 不要有死胡同路」。

    生成器里已经有"主通道"（②-1.5）保证走廊列恒为 0、相邻列 ≤2 格，
    但那是**局部**的：它保证"从走廊上得去任何一座箱山"，不保证
    "任何一座箱山都连得上走廊"。地形（平台/雪包）会把走廊切断，
    洞会把楼板切成几段，箱子塌下来又会改列顶 —— 这些组合起来
    只能靠一遍 BFS 量。

    **移动能力就是判据，不是拍脑袋的阈值：**
      · 相邻列高差 ≤ 2 格（96）→ 直接走过去（跳高 123）
      · 中间隔着洞、洞宽 ≤ 144 → 跳过去（水平 300 × 滞空 0.686 = 205px，
        留 60px 给"落点没对准"；192 宽的洞理论上也够，但太紧，不认）
      · 地形（平台 96/114 高）不算阻挡：净空 214 − 114 = 100 > 身高 42，
        人从台子底下直接走过去，BFS 按地板算正好。

    返回没走到的列号。空数组 = 这一层是连通的。 */
function unreachableCols(L, k) {
  const COLS = 20;
  const l = L.layers[k];
  const stand = new Array(COLS).fill(false);
  for (let i = 0; i < COLS; i++) {
    const x = i * 48;
    stand[i] = l.segs.some(s => x >= s.x && x + 48 <= s.x + s.w);
  }
  const top = l.colTop || new Array(COLS).fill(l.floorY);
  const seen = new Array(COLS).fill(false);
  const q = [];
  if (k === 0) q.push(clamp(Math.floor(L.start.x / 48), 0, COLS - 1));
  else for (const h of L.layers[k - 1].holes) {
    for (let i = 0; i < COLS; i++) {
      const x = i * 48;
      if (x + 48 > h.x && x < h.x + h.w) q.push(i);
    }
  }
  /* **没有入口的层不算"走不到"，直接放行。**
     上一层如果没开出洞（生成残缺），这一层的起点集合就是空的，
     全 20 列都会被报成"走不到" —— 那是另一件事，由校验第 3 条
     「每层都得有洞」负责报。两条一起红会把失败原因指错地方
     （实测 seed 119 报的是"20 列走不到"，真因是上一层没出口）。 */
  if (!q.length) return [];
  while (q.length) {
    const i = q.pop();
    if (i < 0 || i >= COLS || seen[i] || !stand[i]) continue;
    seen[i] = true;
    /* ① 走到隔壁 */
    for (const j of [i - 1, i + 1]) {
      if (j < 0 || j >= COLS || seen[j] || !stand[j]) continue;
      /* **只限上坡，不限下坡。** 从 3 格箱顶走到地面是"走下去"（会掉下来），
         不是"跳上去" —— 判据必须是"j 最多比 i 高 96"。

         **原来的写法 `top[j] <= top[i] + 96` 是反的**（2026-10-29 发现）：
         y 向下增大，`top` 小 = 高，于是这条式子限制的是"j 最多比 i 低 96"，
         也就是**下坡限 96、上坡不限** —— 正好和注释相反。
         它一直没暴露，是因为削坡保证了 |高差| ≤ 2，两个方向都在 96 内；
         这一版"井梯 3 格 + 邻列 0 格"的组合（削坡动不了井梯，它被 LOCK 锁死）
         让它现形：地表层整段 8~19 列被判成"走不到"。 */
      if (top[j] >= top[i] - 96) q.push(j);
    }
    /* ② 跳过洞 */
    for (const d of [-1, 1]) {
      let j = i + d, gap = 0;
      while (j >= 0 && j < COLS && !stand[j]) { gap += 48; j += d; }
      if (j < 0 || j >= COLS || seen[j] || gap <= 0) continue;
      if (gap <= 144 && top[j] >= top[i] - 96) q.push(j);
    }
  }
  const miss = [];
  for (let i = 0; i < COLS; i++) if (stand[i] && !seen[i]) miss.push(i);
  return miss;
}

/* ================= 球有没有"死胡同" =================
   用户 2026-10-29：「空间设计要合理 不要有死胡同路 …… 主要是球进入了死胡同
   　比如上坡 完全推不上去了」。

   **这和 `unreachableCols` 是两个问题。** 那个问的是"人走不走得到"（人有二段跳、
   能翻 2 格），这个问的是"球推不推得出来" —— 球不会跳，只能被水平推，
   被推进一个四周都比它高一格以上的坑里就永久卡死（冰墙、铁箱、石台都砸不动）。

   判据只看列高：**左右相邻列都比本列高 ≥2 格** = 一格宽、两格深的窄沟。
   为什么是 2 格而不是 1 格：1 格的台阶球能翻过去（见 `ballHitBox` 里的
   "翻越"分支），2 格翻不过。这一条的实物形态就是"两座三格箱山夹一条缝"，
   一眼就能在结构图上认出来。

   **多列宽的坑不在这里管。** 它们靠 `colTop` 之外的通用约束兜（堆间至少留一列、
   走廊两侧限高 2 格），而且宽坑里球能横向滚，玩家也进得去推。 */
function ballPits(H) {
  const out = [];
  for (let i = 1; i + 1 < H.length; i++) {
    if (H[i - 1] - H[i] >= 2 && H[i + 1] - H[i] >= 2) out.push(i);
  }
  return out;
}

/** 一层里"球推不出来"的列。洞口列（脚下没地板）不算 —— 球掉下去是设计好的。 */
function ballStuckCols(L, k) {
  const COLS = 20;
  const l = L.layers[k];
  const stand = new Array(COLS).fill(false);
  for (let i = 0; i < COLS; i++) {
    const x = i * 48;
    stand[i] = l.segs.some(s => x >= s.x && x + 48 <= s.x + s.w);
  }
  return ballPits(l.colHgt || new Array(COLS).fill(0)).filter(i => stand[i]);
}

/** 生成后的自检。**这些不是"最好有"，是"没有就得死局"。** */
function validateLevel(L, verbose) {
  const bad = [];
  const F = L.floors, N = F.length;

  // 1. 相邻两层的洞不能重叠 —— 重叠就能一穿两层，中间那层等于不存在
  for (let k = 0; k + 1 < N; k++) {
    for (const p of L.layers[k].holes) {
      for (const q of L.layers[k + 1].holes) {
        if (p.x < q.x + q.w + 24 && q.x < p.x + p.w + 24) bad.push('洞第' + k + '/' + (k + 1) + '层重叠');
      }
    }
  }

  // 2. 每个洞正下方必须接得住（玩家宽 30，取洞内两端各内缩 20 验两次）
  for (let k = 0; k + 1 < N; k++) {
    const next = L.layers[k + 1].segs;
    for (const h of L.layers[k].holes) {
      for (const px of [h.x + 20, h.x + h.w - 20]) {
        if (!next.some(s => px >= s.x && px <= s.x + s.w)) bad.push('洞第' + k + '层没接住');
      }
    }
  }

  // 2a. 地形不能压在本层洞口上（会把唯一的出口盖住）
  for (let k = 0; k < N; k++) {
    for (const t of L.layers[k].terrain) {
      for (const h of L.layers[k].holes) {
        if (t.x < h.x + h.w + 16 && h.x < t.x + t.w + 16) bad.push('第' + k + '层地形盖住洞口');
      }
    }
  }

  // 2b. 落点带上不能有地形件（否则掉下去被平台接在半空，等于没掉）
  for (let k = 1; k < N; k++) {
    const dz = L.layers[k - 1].holes.map(h => [h.x - 24, h.x + h.w + 24]);
    for (const t of L.layers[k].terrain) {
      if (dz.some(z => t.x < z[1] && t.x + t.w > z[0])) bad.push('第' + k + '层地形接住了落点');
    }
  }

  // 3. 每层都得有洞（最后一层除外），且不能全被别的东西盖住
  for (let k = 0; k + 1 < N; k++) if (!L.layers[k].holes.length) bad.push('第' + k + '层没有出口');

  // 4. 出生点脚下是实心
  if (!L.layers[0].segs.some(s => L.start.x + 15 >= s.x && L.start.x + 15 <= s.x + s.w)) bad.push('出生点悬空');

  // 5. 门厅怪数 >= killTarget（单向关卡，一路不杀也得凑得够）
  /* **按 layer 判层，不能按 y 阈值。**
     箱子变成地形之后，门厅的怪会站在 2 格箱顶（y 比地板高 96），
     用 `y >= 地板 - 100` 判的话它会被算成"不在门厅"，于是校验报
     "门厅怪 1 < 3"、其实场上有 3 只 —— 白重掷了几十个种子。 */
  const hallFoes = L.spawns.filter(s => s.layer === N - 1).length;
  if (hallFoes < NUM.killTarget) bad.push('门厅怪 ' + hallFoes + ' < 门槛 ' + NUM.killTarget);

  // 6. 门厅必须有喂球木箱（清光怪之后的唯一活路）
  const feed = L.boxes.filter(b => b.mat === 'wood' && !b.frost && b.y >= F[N - 1] - 60 && b.y <= F[N - 1]).length;
  if (feed < 3) bad.push('门厅喂球箱 ' + feed + ' < 3');

  // 7. 每层至少一只怪
  for (let k = 0; k < N; k++) {
    if (!L.spawns.some(s => s.layer === k)) bad.push('第' + k + '层没有怪');
  }

  // 8. 怪不能生在斜坡/雪包里（脚的 y 停在坡底、坡面却高出一截 → 永远贴在坡体内）
  for (const sp of L.spawns) {
    const k = sp.layer;
    for (const t of L.layers[k].terrain) {
      if (t.kind !== 'ramp') continue;
      if (t.x - 12 < sp.x + 34 && t.x + t.w + 12 > sp.x) bad.push('第' + k + '层怪生在地形里');
    }
  }

  /* 9~12：箱子结构。**这是"箱子当路"能不能成立的四个硬条件** ——
     少一条，箱子就退化成墙、或者退化成纯装饰。 */
  for (let k = 0; k < N; k++) {
    const l = L.layers[k];
    const H = l.colHgt || [];
    /* 9. 本层箱子够多。这是"探索材料"的底线 ——
       用户抱怨的就是"箱子很少，这点内容怎么探索"。门厅要留给门和通道，标准低一档。 */
    const cnt = L.boxes.filter(b => b.y < F[k] - 1 && b.y + b.h > F[k] - 200).length;
    /* 14 口是下限，不是目标 —— 生成侧的实际中位数在 20 上下走。
       **门槛设太高会让 buildLevel 反复重掷**，而重掷只会换种子，
       不会让某一层突然多出箱子（地形占的列是固定的）。
       **门槛还要和"这一层几何上摞得下几口"取小**（和生成侧 `topUp` 同一条公式）：
       地形 / 洞口缘 / 走廊 / 楼板断口会把地表层的可摞列吃到只剩两三列，
       这时 8 口是物理上达不到的，红在这条上只会让 buildLevel 白重掷几十次。 */
    const cap = (l.colCap && l.colCap.length) ? l.colCap.reduce((a, b) => a + b, 0) : Infinity;
    const need = Math.min((k === 0 || k === N - 1) ? 8 : 10, cap);
    if (cnt < need) bad.push('第' + k + '层箱子只有 ' + cnt + '（要 ≥' + need + '）');
    /* 10. 相邻列高差 ≤ 2 格（96 < 跳高 123）—— 再高就爬不上去，箱山变墙 */
    for (let i = 0; i + 1 < H.length; i++) {
      if (Math.abs(H[i] - H[i + 1]) > 2) bad.push('第' + k + '层第' + i + '列高差 ' + Math.abs(H[i] - H[i + 1]));
    }
    /* 11. 至少 1 列低点（高度 ≤1）。
       **原来要求"≥2 列完全空"，被削坡打回来了** —— 削坡优先抬高低的那边，
       会把 0 抬成 1。其实"低点"就够：一层里总要有个落脚处，不必是光地面。 */
    let flats = 0;
    for (let i = 0; i < H.length; i++) if (H[i] <= 1) flats++;
    if (flats < 1) bad.push('第' + k + '层一个低点都没有');
  }
  /* 12. 全关至少一口金箱（探索的奖励落点，没有它就只剩"搬箱子"） */
  if (!L.boxes.some(b => b.loot)) bad.push('没有金箱');

  /* 13. **每层都走通，不许有走不到的列。**（2026-10-29）
     "走不到"在这个玩法里不是小事：那一列的箱子/怪玩家永远够不着，
     钱箱可能就埋在里面；如果是怪，**杀不够数门就不开** —— 那是硬死局。
     判据见 unreachableCols，按真实移动能力（2 格高差 / 144 宽的洞）。 */
  for (let k = 0; k < N; k++) {
    const miss = unreachableCols(L, k);
    if (miss.length) bad.push('第' + k + '层有 ' + miss.length + ' 列走不到（列 ' + miss.slice(0, 4).join(',') + '）');
  }

  /* 14. **球不会跳，所以"人能走到"不等于"球推得出来"。**（2026-10-29）
     判据见 ballPits：左右都比本列高 2 格 = 一条 1 列宽的深沟，
     球滚进去之后怎么推都出不来（只能等它 16 秒后自己化掉）。
     这一条和 13 是互补的：13 管人、14 管球，缺一个都会在实机上出现
     "我在上面看着球，推不到它" —— 那不是难度，是关卡的错。 */
  for (let k = 0; k < N; k++) {
    const pits = ballStuckCols(L, k);
    if (pits.length) bad.push('第' + k + '层有 ' + pits.length + ' 个球坑（列 ' + pits.slice(0, 4).join(',') + '）');
  }

  if (verbose && bad.length) console.log('  ✗ 校验未过：' + bad.join(' / '));
  return bad.length === 0;
}

/** 换种子重掷，直到过校验。80 次都不过就返回最后一个 —— 宁可跑起来，
    让断言把它抓出来，也不要卡在初始化里。 */
function buildLevel(seed) {
  const base = (seed == null ? 1 : seed) >>> 0;
  let last = null;
  for (let t = 0; t < 80; t++) {
    const s = (base + t * 7919) >>> 0;
    const L = genLevel(s);
    last = L;
    if (validateLevel(L)) { L.seed = s; return L; }
  }
  return last;
}

/* ---------------------------------------------------------------- 状态 */
const S = {
  t: 0,
  phase: 'play',            // play | clear
  /* 镜头。世界高 1560，屏幕 600 —— 只有跟着人往下走，才谈得上"纵深"。
     只做纵向（横向世界正好一屏宽），这样玩家永远看得见整张地图的宽度，
     不会因为横向滚动而丧失方位感。
     **k 是"吸附在哪一层"**，不是连续坐标 —— 见 updateCamera。 */
  cam: { y: 0, k: 0 },
  clearT: 0,
  p: null,
  foes: [], shots: [], balls: [], frags: [], texts: [], shards: [],
  /* **冲击环。** 球砸碎箱子那一下要有"力从这里发出去"的形状 ——
     只靠碎片和震屏，读起来是"东西碎了"，不是"被撞碎了"。
     一圈迅速扩散、迅速消失的白环，是最便宜也最准的表达。 */
  rings: [],
  /* 宠物扔出来的东西（胡萝卜 / 骨头 / 刺球）。**和玩家的 `shots` 完全分开** ——
     两者速度、重力、命中对象都不一样，混在一个数组里每个系统都要写两遍判据。 */
  ebullets: [],
  /* 黑洞（吐怪巢）。见 stepNests —— 每关 1~2 个，会慢慢走，有配额。 */
  nests: [],
  boxes: [], plats: [], deco: [], door: null,
  ammo: 0, belly: 0, hp: 0, invuln: 0,
  killed: 0, killedTarget: 0,
  shake: 0, flash: 0, hitStop: 0,
  /* 最近一次冲击的**方向**（单位向量）。震屏只给幅度的话，
     画面是"在抖"；给了方向，才是"被从右边撞了一下"。
     不设的时候是 (0,0) —— 纯震颤，适合没有明确来向的坠落/爆裂。 */
  shakeDX: 0, shakeDY: 0,
  keys: {},
  /* 量具面板开关。跑原型时开着（要看数值），出图 / 给人看设计时关掉 ——
     这块面板压在右上角，正好盖住第 1~2 层右侧那段浮台上的箱子。 */
  showMeter: true,
  // 量具：这个面板是给"跑原型"看的，不是给玩家看的
  stat: {
    shots: 0, hitFoe: 0, hitBox: 0,
    coats: 0, shotsPerCoat: [],       // 每只怪用了多少发
    boxByShot: 0, boxByBall: 0,
    ballChain: 0, ballChainMax: 0,    // 一颗球最多连碎几个
    kills: 0, killByBall: 0,
    hardHint: 0,
  },
  _taught: {},              // 首次提示只弹一次
};

/* ---------------------------------------------------------------- 初始化
   **`reset()` 不带参数是"重开这一关"，`reset(seed)` 是"换一张图"。**
   两者的区别很重要：断言里到处调 reset() 期望回到同一个状态，
   如果 reset() 每次重新掷骰子，所有"前后对比"的断言都会随机红。
   所以种子存在模块级的 LEVEL_SEED 里，只有 newLevel() 会换掉它。 */
function newLevel(seed) {
  LEVEL_SEED = (seed == null ? (Math.random() * 1e9) : seed) >>> 0;
  reset();
}

function reset(seed) {
  if (seed != null) LEVEL_SEED = seed >>> 0;
  if (LEVEL_SEED == null) LEVEL_SEED = (Math.random() * 1e9) >>> 0;
  const L = buildLevel(LEVEL_SEED);
  /* **FR 必须在造怪之前重置。** 它原来在函数末尾才赋值，
     而 `S.foes = L.spawns.map(makeFoe)` 在中间就调用了 makeFoe ——
     于是每张新关卡的第一批怪吃的是**上一张关**的随机流。
     后果不是"怪长错了"这种小事：同一个种子跑两遍，宠物的种类和初始朝向都不一样，
     "出图和断言可复现"这条直接作废（_snowlab-feel2.js 的⑤就是这么抓到的）。 */
  FR = rngFrom((LEVEL_SEED ^ 0x51ED) >>> 0);
  S.level = L;
  S.t = 0; S.phase = 'play'; S.clearT = 0;
  S.plats = L.plats;
  S.deco = L.deco || [];
  S.boxes = L.boxes.map(b => ({ ...b }));
  S.door = { ...L.door };
  S.foes = L.spawns.map(sp => makeFoe(sp.x, sp.y, sp.kind));
  S.nests = (L.nests || []).map(n => ({ ...n, born: 0, t: 0 }));
  S.shots = []; S.balls = []; S.frags = []; S.texts = []; S.shards = []; S.rings = [];
  S.ebullets = [];
  S.ammo = NUM.ammoStart;
  S.belly = NUM.bellyStart;
  S.hp = NUM.hpStart;
  S.invuln = 0;
  S.killed = 0;
  S.killedTarget = NUM.killTarget;
  /* 金箱计数。总数来自关卡，玩家能看出"这关还有几个没找到" ——
     **这是"探索"唯一的量化反馈**，没有它玩家不知道自己漏了东西。 */
  S.loot = 0;
  S.lootTotal = L.boxes.filter(b => b.loot).length;
  S.shake = 0; S.flash = 0; S.hitStop = 0;
  S._taught = {};
  S.stat = {
    shots: 0, hitFoe: 0, hitBox: 0,
    coats: 0, shotsPerCoat: [],
    boxByShot: 0, boxByBall: 0,
    ballChain: 0, ballChainMax: 0,
    kills: 0, killByBall: 0, hardHint: 0,
  };
  S.cam = { y: 0, k: 0 };
  S.p = {
    x: L.start.x, y: L.start.y, vx: 0, vy: 0,
    w: PLAYER_W, h: PLAYER_H, onGround: true, face: 1,
    runD: 0, lockT: 0, shotCd: 0, anim: 0, shotAnim: 0,
    jumps: NUM.hero.airJump, jumpHeld: false, onBall: null,
    /* 从楼板上下跳的窗口（见 stepPlayer 里的"下跳"）。
       0 = 没在下跳；> 0 时 stepBody 会跳过楼板的碰撞。 */
    dropT: 0, downHeld: false,
  };
}

/* ---------------------------------------------------------------- 敌人 */
/* **breed 由 kind 决定，不是随机的。**
   kind 是行为（crawler 巡逻 / runner 追人），breed 是外观和投掷物。
   两者分开是为了让断言能继续用 `spawnFoe(x, y, 'crawler')` 指"一只会巡逻的怪"，
   不用关心它长什么样；同时场上又能有三种不同的剪影。
   追人的那个是尖牙兽 —— 跑得快、甩牙甩得直，行为和外形的说法是一致的。

   **别再用 bunny/doggy/hoggy。** 那是"我方宠物"的形象，2026-10-28 用户
   明确问过「敌方为什么用我方的宠物」—— 敌人得有敌人的样子。 */
function breedOf(kind) {
  if (kind === 'runner') return 'fang';
  const r = FR();
  return r < 0.52 ? 'moss' : 'grub';
}

function makeFoe(x, y, kind, breed) {
  const br = breed || breedOf(kind);
  const cfg = NUM.breed[br] || NUM.breed.moss;
  const speed = cfg.speed;
  /* **vx 和 face 必须一开始就一致。** 原来 face 写死 1、vx 随机左右，
     第一帧就成了"面朝右往左走"，再被换向锁一锁，怪就永远倒着走。 */
  const dir = FR() < 0.5 ? -1 : 1;
  return {
    x, y, kind, breed: br,
    w: FOE_W, h: FOE_H,
    vx: dir * speed,
    turnLock: 0,             // 刚折返时的锁，见 stepFoes
    vy: 0,
    hits: 0,                 // 已吃雪点数
    needAt: 0,               // 开始挨第一发时的 need 快照（量具用）
    hitT: 0,
    dead: false,
    face: dir,
    onGround: false,
    homeX: x,
    homeY: y,
    patrolT: 0,
    speed,
    /* ---- 行为状态 ----
       idleT > 0 就是"站着待机"。**待机不是省事，是让它看起来活着** ——
       一直匀速横移的单位读起来像巡逻机器人，停一下、耸一下背，才像个活物。 */
    idleT: 0,
    walkT: 0.8 + FR() * 1.6,
    aim: 0,                  // 蓄力进度，到 windup 就发射
    fireCd: 0.8 + FR() * 1.4,
    jumpCd: 0,
    hopT: 0,                 // 纯表演性的小跳（原地），不影响碰撞
  };
}

/* ---------------------------------------------------------------- 饱食 */
function bellyTier() {
  if (S.belly >= NUM.bellyFull) return 'full';
  if (S.belly >= NUM.bellyHalf) return 'half';
  return 'hungry';
}
function snowNeed() { return NUM.snowShots[bellyTier()]; }
const TIER_CN = { full: '满饱', half: '半饱', hungry: '全饿' };

/* ---------------------------------------------------------------- 球档位 */
function ballTier(n) {
  if (n >= 6) return 3;
  if (n >= 4) return 2;
  if (n >= 2) return 1;
  return 0;
}
const BALL_TIER_CN = ['小', '中', '大', '特大'];
function ballR(n) { return Math.min(NUM.ball.maxR, NUM.ball.baseR + NUM.ball.perAbsorb * Math.min(n, NUM.ball.maxAbsorb)); }
/** 动量。**破冰墙的判据必须是球径 × 速度，不是单看体积** ——
    否则玩家把怪清光就永远攒不出特大球，而冰墙后面是门，直接死局。 */
/** 球的横向动量（速度 × 体径比）。**只用于"横向撞箱"**；
    落砸看的是 vy，见 `ballHitBox` 的第四个参数 —— 别拿这个函数去量落球。 */
function ballPow(b) { return Math.abs(b.vx) * (b.r / NUM.ball.baseR); }

/* ---------------------------------------------------------------- 飘字 */
function addText(x, y, s, color, size, lifeT) {
  S.texts.push({ x, y, s, color: color || '#fff', size: size || 16, t: 0, life: lifeT || 0.9 });
}
/** 碎片。`shape` 决定"碎成了什么样" —— 这是打击感的一半：
    木箱碎成**板条**（长条、会转），石箱碎成**棱角块**，雪/血碎成点。
    **全一样的方点会让所有材质碎得一样**，玩家就读不出"这是什么做的"。 */
function addFrag(x, y, n, color, spd, shape, bias) {
  const bx = (bias && bias.x) || 0, by = (bias && bias.y) || 0;
  /* **有方向时把角度收进扇形，而不是"全向撒 + 整体漂移"。**
     后者只改变碎片整体的重心，不改变扩散形状 —— 出图上看还是一次爆炸。
     收进 ±66° 之后，木片才会朝球飞去的方向扑出去，读作"被撞开"。 */
  const hasDir = bx !== 0 || by !== 0;
  const baseA = hasDir ? Math.atan2(by, bx) : 0;
  for (let i = 0; i < n; i++) {
    const a = hasDir ? baseA + rnd(-1.15, 1.15) : rnd(0, Math.PI * 2);
    const v = rnd(60, spd || 260);
    const f = {
      x, y,
      vx: Math.cos(a) * v + bx, vy: Math.sin(a) * v - 80 + by,
      t: 0, life: rnd(0.35, 0.8), color,
      r: rnd(2, 4.5), rot: rnd(0, Math.PI * 2), vr: rnd(-11, 11),
      w: 0, h: 0,
      /* **碎片带着自己的形状名。** 「木碎成板条 / 石碎成棱角块」这条
         只能查形状，不能查 `w > h*1.6` —— 后者会把随机撞出来的一块瘦长
         棱角也算成板条（实测石箱 156 片里 22 片被判成板条，全是几何巧合，
         看起来像"石箱也碎出木板了"）。 */
      shape: shape || 'dot',
    };
    if (shape === 'plank') { f.w = rnd(7, 15); f.h = rnd(2.4, 4.2); }
    else if (shape === 'slab') {
      /* **大块残骸。** 只有小块的时候，箱子碎完读作"箱子消失了"；
         大块是它的"尸体"，玩家看得见它被撞到哪去了。飞得慢、活得久，
         所以撞击后一两秒画面里还留着几块斜插的木板 —— 这才是"碎了"，
         而不是"被删了"。 */
      f.w = rnd(16, 26); f.h = rnd(7, 12);
      f.life = rnd(0.85, 1.25);
      f.vr = rnd(-6, 6);
    }
    else if (shape === 'chunk') { f.w = rnd(3.4, 7.5); f.h = f.w * rnd(0.55, 1.15); }
    else { f.w = f.r; f.h = f.r; f.vr = 0; }
    if (f.w) f.r = Math.max(f.w, f.h);
    S.frags.push(f);
  }
}
function hitStop(t) { S.hitStop = Math.max(S.hitStop, t); }
/** 一次性提示。**「太硬了」只在首次弹一次**，之后靠火花 + 无裂痕表达。
    常驻文字会把屏幕变成一个一直在喊的提示板。 */
function once(key, x, y, s, color) {
  if (S._taught[key]) return;
  S._taught[key] = 1;
  addText(x, y, s, color || '#FFD08A', 16, 1.3);
}

/* ---------------------------------------------------------------- 实体碰撞 */
function aabb(a, b) {
  return a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y;
}
/** 场景里所有实心块：平台 + 没碎的箱子。
    **箱子必须参与碰撞** —— 它要能挡人、站人、挡子弹。
    只当贴图的话，「箱墙」这个设计就无从谈起。 */
function solids() {
  const out = S.plats.slice();
  for (const b of S.boxes) if (!b.dead) out.push(b);
  return out;
}

/** 某个 x 处、y 下方最近的可站立面。碎片落地、找回掉出世界的敌人要用。
    直接拿 GROUND_Y 当"地面"在单屏时代是对的，三层之后不对了 ——
    底层掉下来的碎片会一路穿过 L2、L3 的地面落到底。 */
function groundAt(x, y) {
  let best = WORLD_H;
  for (const s of solids()) {
    if (x < s.x || x > s.x + s.w) continue;
    const top = surfY(s, x);
    if (top < y - 6) continue;          // 只找脚底下的
    if (top < best) best = top;
  }
  return best;
}

/** 把 `w×h` 摆到 (x, y) 会不会插进什么实体里。`ignore` 是"算它托着我"的那块。
    **给瞬移类修正用（扒边）。** 只判 > 2px 的重叠：贴着台面站时包围盒和台面
    正好相切，相切不算"插进去"。 */
function blockedAt(x, y, w, h, ignore) {
  for (const s of solids()) {
    if (s === ignore) continue;
    if (s.kind === 'ramp') continue;
    const ox = Math.min(x + w, s.x + s.w) - Math.max(x, s.x);
    const oy = Math.min(y + h, s.y + s.h) - Math.max(y, s.y);
    if (ox > 2 && oy > 2) return true;
  }
  return false;
}

/* ---------------------------------------------------------------- 移动体物理
   **顺序必须是「先垂直分离、再水平分离」，而且水平那一轮要跳过"站在上面"的块。**
   反过来做会出一个非常隐蔽的致命 bug：站在地面上的身体，包围盒和地面平台
   永远是重叠的（y+h 比平台顶低一丁点），水平轮会把它当成撞墙，按 vx 的符号
   推到 `s.x + s.w` 或 `s.x - o.w` —— 也就是**场地最左边或最右边**。
   第一版就是这样：所有怪在第一帧瞬移到 x=902 挤成一堆。 */
function stepBody(o, dt) {
  o.vy = Math.min(o.vy + 2100 * dt, 1250);

  // ---- 垂直
  const prevBottom = o.y + o.h;
  const prevTop = o.y;
  /* **上一帧是不是站在地上。** 下坡贴地要用它 —— 见垂直段落末尾。
     必须在 `o.onGround = false` 之前取，之后这个值就没了。 */
  const wasGround = o.onGround;
  o.y += o.vy * dt;
  o.onGround = false;
  for (const s of solids()) {
    /* ================= 楼板是"半透层"（只对玩家，2026-10-28 第四轮）=================
       用户原话：「这个横梁我方是可以跳上去的　也可以下来　只要没箱子
       　不需要在空档里才能跳」。

       也就是：楼板**只挡落下、不挡上跳**。判据放在这里而不是给楼板换一种
       实体类型，是因为所有碰撞、地面查询、镜头吸附都在认 `solids()`，
       换类型要改十几处；这里加一条 skip，其余系统一行都不用动。

       三条限定，缺一条就出事：
         ① **只给玩家**（`o === S.p`）。怪一旦也能穿过楼板，它们会跳进上一层，
            而它们的巡逻走廊是按本层量出来的，上去就再也回不来 —— 满屏怪
            挤在上一层，玩家那一层一只都没有。
         ② **只在上升（vy < 0）或主动下跳（dropT）时 skip。** 下落时照旧接住，
            否则人站在楼板上每一帧都在"穿过再被接住"之间闪。
         ③ 箱子的碰撞一行没改 —— 楼板上摞着箱子的那一格，人跳上去会**撞到
            箱底**（箱底正好在楼板顶面），于是"有箱子的地方上不去"这条
            不需要单独写判据：它就是箱子本身。 */
    if (s.floor && o === S.p && (o.vy < 0 || o.dropT > 0)) continue;
    if (s.kind === 'ramp') {
      /* 斜坡：**只认顶面，不参与侧面阻挡。**
         横向不挡是故意的 —— 玩家走过来时脚底被下方地板托着，每一帧的
         垂直落地再把他贴回斜面，看上去就是"顺着坡走上去"，不会像台阶
         那样一格一格卡住。反过来，如果让斜坡参与水平阻挡，人会在坡脚
         撞一下停住，斜坡就退化成一堵墙。 */
      if (o.x + o.w <= s.x || o.x >= s.x + s.w) continue;
      const top = surfY(s, o.x + o.w / 2);
      /* **三个条件缺一不可：往下走 + 上一帧在坡面之上 + 这一帧确实穿过了坡面。**
         少了最后一条，人从上层往下掉、x 正好落在某个坡的区间里时，
         `prevBottom <= top + 14` 一样成立（人家在上面几十米呢），
         于是被判成"落地"，一发瞬移到那个坡顶上 —— 掉五层变成掉半层。 */
      if (o.vy >= 0 && prevBottom <= top + 14 && o.y + o.h >= top) {
        o.y = top - o.h; o.vy = 0; o.onGround = true;
      }
      continue;
    }
    if (!aabb(o, s)) continue;
    // 只认"从上方落下来"和"从下方顶上去"，侧面的事交给下一轮
    if (o.vy >= 0 && prevBottom <= s.y + 8) {
      o.y = s.y - o.h; o.vy = 0; o.onGround = true;
    } else if (o.vy < 0 && o.y < s.y + s.h) {
      /* **顶天花板也要判"上一帧在下面"。**
         少了 prevTop 这一条，斜着往上跳、身体从侧面啃进箱子/平台边缘时，
         这一帧会被当成"头顶撞到"，把人**按到块的底面**去 —— 也就是
         一脚踩进下一格箱子里面。实测贴着箱墙起跳，48 次里有 46 次
         身体插进箱体 26~30px，玩起来就是"往上跳反而掉进箱子"。
         判据：上一帧的头顶还在块的底边以下，才算是从下面顶上来。 */
      if (prevTop >= s.y + s.h - 2) { o.y = s.y + s.h; o.vy = 0; }
    }
  }

  /* ---- 下坡贴地（只在"上一帧还站在地上"时生效）----
     **这是"移动发抖"的真正原因，不在镜头。**
     斜坡的承托是"这一帧脚底穿过了坡面才贴上去"，上坡时坡面往上升，
     每帧都穿得过，所以顺；下坡时坡面在往下跑，而人只靠重力往下掉
     （一帧 0.6px），坡面一帧却能掉 4px —— 于是人和坡面越离越远、
     腾空、再砸下来。60 帧里 onGround 翻转 4 次，肉眼看就是一路抖。

     修法：上一帧站在地上、这一帧正在下落、脚下 16px 内有坡面 → 直接贴上去。
     16px 是"一帧最多能漏掉的距离"的两倍多，再宽就会把"从平台边缘走下去"
     也吸住。往上跳（vy < 0）不吸，起跳不受影响。 */
  if (!o.onGround && wasGround && o.vy >= 0) {
    for (const s of solids()) {
      if (s.kind !== 'ramp') continue;
      if (o.x + o.w <= s.x || o.x >= s.x + s.w) continue;
      const top = surfY(s, o.x + o.w / 2);
      /* **符号：`top − 脚底`，正值才是"坡面在脚下面"。**
         第一版写成 `脚底 − top`，于是所有该吸的情况都算成了负值被跳过 ——
         探针数字一动不动，还以为是公差不够。y 向下增大，记住方向。 */
      const gap = top - (o.y + o.h);
      if (gap < -1 || gap > 16) continue;
      o.y = top - o.h; o.vy = 0; o.onGround = true; break;
    }
  }

  // ---- 水平
  o.x += o.vx * dt;
  for (const s of solids()) {
    if (s.kind === 'ramp') continue;      // 斜坡不挡横移，见上
    /* **楼板对玩家不参与水平阻挡。** 穿过楼板的那些帧，身体和楼板在 y 上
       是重叠的 —— 如果这里照旧按撞墙处理，人会被横向"推"到最近的一段楼板
       边缘上（多半就是那个洞口），表现为"跳起来人被甩到一边"。
       站在楼板顶上时本来就会被下面那条 `脚底 ≤ 顶面 + 2` 跳过，所以
       这条 skip 对"在楼上走路"没有任何影响。 */
    if (s.floor && o === S.p) continue;
    if (!aabb(o, s)) continue;
    // 站在这块上面（脚底贴着顶面）就不算撞墙
    if (o.y + o.h <= s.y + 2) continue;
    /* ---- 台阶助步（step-up）----
       坡顶和台面接头处有一个 `半身宽 × 坡度` ≈ 18px 的垂直落差：
       贴坡面用的是**身体中心**那一点的高度（斜坡要这样才不抖，
       见上面那段注释），所以走到坡顶时脚底还差 18px 才到台面，
       于是被台面的侧面摁住 —— **永远走不到坡顶**，球也就跟着推不上去
       （用户 2026-10-29：「比如上坡 完全推不上去了」）。

       给"站着"的身体一次 ≤20px 的抬腿，和 2D 平台游戏里的台阶助步一样。
       只抬 20px：箱子是 48 一格、平台离地 96/114，都跨不过去，
       所以这条只对"坡与台面的缝"生效，不会变成"人能直接上箱子"。 */
    if (o.onGround) {
      const stepUp = (o.y + o.h) - s.y;
      if (stepUp > 0.5 && stepUp <= 20) { o.y = s.y - o.h; o.vy = 0; o.onGround = true; continue; }
    }
    if (o.vx > 0) { o.x = s.x - o.w; }
    else if (o.vx < 0) { o.x = s.x + s.w; }
    else {
      /* 静止时被挤进块里（典型场景：箱子塌下来砸在玩家头上）。
         只按 vx 的符号推开的话，vx=0 两条分支都不进，人就永远卡在箱子里动不了。
         这里按"最近的一条边"顶出去。 */
      const outTop = Math.abs(o.y + o.h - s.y);
      const outL = Math.abs(s.x + s.w - o.x);
      const outR = Math.abs(o.x + o.w - s.x);
      if (outTop < Math.min(outL, outR)) { o.y = s.y - o.h; o.vy = 0; o.onGround = true; }
      else if (outL < outR) o.x = s.x + s.w;
      else o.x = s.x - o.w;
    }
    o.vx = 0;
  }
  o.x = clamp(o.x, WALL_L, WALL_R - o.w);

  /* ---- 扒边（只给玩家）----
     **没有这一条，玩家就永远回不到上一层。**
     上行通道是上一层地板上的那个洞，而洞是**镂空**的：玩家从井梯箱顶
     跳起来，脚确实越过了上一层地板（144 + 123 = 267 > 240），但落点正好
     在洞里，于是又原样掉回去 —— 实测"跳起来再按方向键"的窗口只有三四帧，
     81 次里成功 7 次。那不是难度，是动作根本没做出来。

     判据收得很窄，只在"脚已经够到台面、横向还差一口气"时扶一把：
       ① 台面比脚高不超过 30px（跳得起来才给，矮处不给）
       ② **必须在上升或最高点（vy ≤ 0）。** 这里差点写成 vy ≤ 60 ——
          那样玩家刚踏进洞口往下掉的第一帧（vy 只有 35）也会被判定成
          "上升中"，于是被扶回地板，永远掉不下去（逐层挖穿的断言直接红）。
       ③ 和台子边缘的横向距离 < 40px（就在边上）
       ④ **人站住了就别扒。** onGround 的 vy 也是 0，不排掉的话，
          贴着箱子走路会被一路"扶"上箱顶。
       ⑤ **落点必须是空的。** 这一条是后补的，代价是踩了一次大坑：
          "贴墙起跳会被塞进箱子里"（48 次里 46 次，最深 30px）。
          原因是扒边会把人横向瞬移 26px 挪到台面上，却没问过台面上方
          有没有东西 —— 冰墙上面摞着箱子时，那 26px 正好把人推进上一格
          箱体内部。**瞬移类的修正必须验落点，不能只验出发点。**
     普通平台跳上去本来就会正常落地，走不到这里。 */
  if (o === S.p && o.vy <= 0 && !o.onGround) {
    const foot = o.y + o.h;
    for (const s of solids()) {
      if (s.kind === 'ramp') continue;
      const dy = s.y - foot;
      if (dy < -1 || dy > 30) continue;
      /* 玩家在台子的右边（往左扒） */
      /* 40px 的吸附范围：洞口 96~144 宽，梯子列在洞内、离边缘还能有
         三十来像素 —— 收太紧就成了"必须像素级对位"，手感等于没做。 */
      let nx = null;
      if (o.x >= s.x + s.w && o.x < s.x + s.w + 40) nx = s.x + s.w - o.w + 4;
      else if (o.x + o.w <= s.x && o.x + o.w > s.x - 40) nx = s.x - 4;
      if (nx == null) continue;
      /* ---- 2026-10-28 第三轮：两条闸，修「跳起来一起往后走」 ----
         用户原话：「现在跳起来 一起往后走　跳起来有问题」。

         这段扒边是"把人整段横移一个身位"（玩家 45 宽、台面 48 宽，
         从台子外侧挪到台面上正好 ≈ 44px）。方向还**不看玩家想往哪走** ——
         往右跑跳、脚一接近某个台面，人可以被挪到左边 44px。
         那就是"跳一下人往后闪一截"，而且一帧完成，看不出发生了什么。

         ① **不往运动的反方向扒。** 有水平速度时，只有"往台面那个方向"
            才允许扒；vx = 0（原地起跳）不限制，否则不按方向键就上不去。
         ② **一帧最多挪 20px。** 差得更远就说明人还在台子外面老远，
            那不是"差一口气"，是自己的走位还没到 —— 这一帧不扒，
            下一帧再看。20px 够救"脚已经悬在台沿外"的所有情况。 */
      const dx = nx - o.x;
      if (o.vx !== 0 && Math.sign(o.vx) !== Math.sign(dx)) continue;
      if (Math.abs(dx) > 20) continue;
      const ny = s.y - o.h;
      if (blockedAt(nx, ny, o.w, o.h, s)) continue;
      o.x = nx; o.y = ny; o.vy = 0; o.onGround = true; break;
    }
  }

  /* 兜底：真的掉出世界了才拉回来。**不能写 GROUND_Y** ——
     GROUND_Y 现在是世界最底（1500），写它等于把中层掉下去的东西
     全部瞬移到洞窟底，玩家会看到怪物凭空出现在脚边。 */
  if (o.y + o.h > WORLD_H + 80) { o.y = groundAt(o.x + o.w / 2, 0) - o.h; o.vy = 0; o.onGround = true; }
}

/* ---------------------------------------------------------------- 吐雪 */
function shoot() {
  const p = S.p;
  if (p.shotCd > 0 || S.phase !== 'play') return;
  if (S.ammo <= 0) {
    once('noammo', p.x, p.y - 40, '没雪了 · 去砸箱子', '#FF9E8E');
    return;
  }
  S.ammo--;
  S.stat.shots++;
  const cfg = NUM.shot.pets[HERO_ID] || NUM.shot.pets.cat;
  p.shotCd = NUM.shot.cd;
  p.lockT = NUM.shot.lock;      // 喷时不能移动：这是「喷的代价」第 ②条
  p.shotAnim = 0.18;
  S.shots.push({
    x: p.x + p.w / 2 + p.face * 16,
    y: p.y + p.h * 0.42,
    vx: p.face * cfg.speed,
    /* **横向丢出去，但要掉下来。** vy0 轻微上扬让弹道先平后坠 ——
       没有这一下，子弹读起来是"射出去的激光"；有了它才是"扔出去的东西"。
       重力 520 是角色重力（2100）的四分之一：子弹比人轻，但不该飘。 */
    vy: cfg.vy0, grav: cfg.grav, kind: cfg.kind,
    t: 0, life: cfg.life, r: cfg.r, dead: false,
  });
  for (let i = 0; i < 3; i++) addFrag(p.x + p.w / 2 + p.face * 14, p.y + p.h * 0.42, 1, '#EAF6FF', 120);
}

function stepShots(dt) {
  for (const s of S.shots) {
    if (s.dead) continue;
    s.t += dt;
    s.x += s.vx * dt;
    /* 抛物线：**先加速度、再动位置**。顺序反了的话同一帧里下落晚半拍，
       连射三发能看出来高低不一，像是三颗不同重量的子弹。 */
    if (s.grav) { s.vy += s.grav * dt; s.y += s.vy * dt; }
    if (s.t >= s.life) { s.dead = true; continue; }

    /* **命中判定必须取"最近的那个"，不能分两轮先怪后箱。**
       先怪后箱的话，怪站在箱子后面照样被打中 —— 箱子就等于没挡住子弹，
       「先清怪再推球」永远比「冻住一箭双雕」省事，整条取舍线断掉。
       雪弹一帧只走 10px，所以"最近"用一个简单比较就够。 */
    let best = null, bestD = Infinity, bestKind = null;
    for (const f of S.foes) {
      if (f.dead) continue;
      if (s.x + s.r < f.x || s.x - s.r > f.x + f.w) continue;
      if (s.y + s.r < f.y || s.y - s.r > f.y + f.h) continue;
      const d = Math.abs((f.x + f.w / 2) - s.x);
      if (d < bestD) { bestD = d; best = f; bestKind = 'foe'; }
    }
    for (const b of S.boxes) {
      if (b.dead) continue;
      if (s.x + s.r < b.x || s.x - s.r > b.x + b.w) continue;
      if (s.y + s.r < b.y || s.y - s.r > b.y + b.h) continue;
      const d = Math.abs((b.x + b.w / 2) - s.x);
      if (d < bestD) { bestD = d; best = b; bestKind = 'box'; }
    }
    /* 平台挡子弹。原来没有这一条 —— 子弹只会被 enemies / boxes 吃掉，
       于是站在台上往下喷，雪弹直接穿地板打到下面的怪。 */
    for (const pl of S.plats) {
      if (pl.kind === 'ramp') continue;        // 斜坡不挡子弹：它是地板，不是墙
      if (s.x + s.r < pl.x || s.x - s.r > pl.x + pl.w) continue;
      if (s.y + s.r < pl.y || s.y - s.r > pl.y + pl.h) continue;
      s.dead = true;
      break;
    }
    if (s.dead) continue;

    if (!best) continue;

    if (bestKind === 'foe') {
      coatFoe(best, 1);
      S.stat.hitFoe++;
    } else {
      shotBox(best, s);
    }
    s.dead = true;
  }
  S.shots = S.shots.filter(s => !s.dead);
}

function shotBox(b, s) {
  const def = NUM.box[b.mat];
  S.stat.hitBox++;
  if (def.hp === Infinity) {
    // 免疫：冒火花、一点裂痕都没有。玩家两次就懂，不需要常驻文字
    addFrag(s.x, s.y, 6, '#FFE0A0', 200);
    b.hitT = 0.12;
    S.stat.hardHint++;
    once('hard_' + b.mat, b.x + b.w / 2, b.y - 14, '太硬了', '#FFD08A');
    return;
  }
  b.hp--;
  b.hitT = 0.12;
  addFrag(s.x, s.y, 4, '#E8DCC8', 160);
  if (b.hp <= 0) breakBox(b, 'shot');
}

/* ---------------------------------------------------------------- 裹雪 */
function coatFoe(f, n) {
  if (f.dead) return;
  if (f.hits === 0) f.needAt = snowNeed();
  f.hits += n;
  f.hitT = 0.16;
  for (let i = 0; i < 4; i++) addFrag(f.x + f.w / 2, f.y + f.h / 2, 1, '#DCF0FF', 150);

  const need = f.needAt || snowNeed();
  if (f.hits >= need) {
    S.stat.shotsPerCoat.push(need);
    S.stat.coats++;
    makeBallFrom(f);
  }
}

/** 雪点满 → 变球。**这一步之后敌人就不存在了，球是唯一的击杀通道。** */
function makeBallFrom(f) {
  f.dead = true;
  S.belly = Math.max(0, S.belly - NUM.bellyPerBall);
  const n = 1;
  S.balls.push({
    x: f.x + f.w / 2, y: f.y + f.h / 2,
    vx: 0, vy: 0, r: ballR(n), absorbed: n,
    life: NUM.ball.life, onGround: false, chain: 0, hitCd: 0, dead: false,
  });
  addText(f.x + f.w / 2, f.y - 18, '裹成球了', '#9BE86E', 18, 1.1);
  S.shake = Math.max(S.shake, 5);
  hitStop(0.04);
}

/* ---------------------------------------------------------------- 推球 */
function pushBalls(dt) {
  const p = S.p;
  const runUp = clamp((p.runD || 0) / NUM.push.runFull, 0, 1);
  const pow = NUM.push.base * (1 + NUM.push.runGain * runUp);

  for (const b of S.balls) {
    if (b.dead) continue;
    /* **踩在脚下的球不推。** 站在球顶时脚底与球顶只差浮点误差，
       `aabb` 偶尔会重叠 0.1px —— 那一帧就会把球推出去，人立刻掉下来。
       用户反馈的"站不住"里，除了"球不在碰撞世界"这一条，还有这个。 */
    if (p.onBall === b) continue;
    /* ================= 推球判"够不够近"，不判"包围盒相不相交" =================
       （2026-10-28 第四轮）用户：「这种1级平面 球很难撞击到　最好想想机制上
       去规避」。

       用包围盒判有两个死角，恰好都是"1 级平面"上最常见的两种站位：
         ① **人站在一格矮箱顶上、球在脚下的地面上。** 玩家脚底（-48）比球顶
            （-44）还高 4px，包围盒**不相交** —— 明明挨着，推不动。
            一层全是矮箱的平地，人几乎一直在箱顶上走，于是"球推不动"。
         ② **球卡在一格宽的缝里。** 人 45 宽、球 44 宽，缝只有 48 ——
            人根本挤不进去，也就永远挨不到球。
       改成"圆心到圆心"的判定，两个方向各留 12px 余量就够了：
         · 垂直：站一格箱顶差 57.5，阈值 31.5+22+12 = 65.5 ✓
           站两格箱顶差 105.5 —— 依旧推不动（往上不该顺手推球）
         · 水平：贴着缝边就差不到 12px ✓

       **方向判据没变**：必须朝球的方向跑（`sign(p.vx) === dir`），
       所以站着不动、从球旁边走过都不会误推。 */
    const REACH = 12;
    const dx0 = b.x - (p.x + p.w / 2), dy0 = b.y - (p.y + p.h / 2);
    if (Math.abs(dx0) > p.w / 2 + b.r + REACH) continue;
    if (Math.abs(dy0) > p.h / 2 + b.r + REACH) continue;
    // 只在玩家朝球方向推时才给速度，站着碰不推
    const dir = b.x > p.x + p.w / 2 ? 1 : -1;
    if (Math.abs(p.vx) < 10) continue;
    if (sign(p.vx) !== dir) continue;
    if (Math.abs(b.vx) >= pow) continue;
    b.vx = dir * pow;
    /* **推一次回满，不是回 60%。**
       "正在用的球不该中途蒸发" —— 回满之后，融化只清理被丢下的球。 */
    b.life = NUM.ball.life;
    if (runUp > 0.85) {
      addText(b.x, b.y - b.r - 12, '助跑推!', '#FFE9A8', 16, 0.7);
      S.shake = Math.max(S.shake, 6);
    }
  }
}

/* ---------------------------------------------------------------- 球 */
function stepBalls(dt) {
  for (const b of S.balls) {
    if (b.dead) continue;
    b.life -= dt;
    if (b.life <= 0) { burstBall(b); continue; }

    // 重力 + 水平移动
    b.vy = Math.min(b.vy + 2100 * dt, 1250);
    const prevX = b.x, prevBottom = b.y + b.r;
    b.x += b.vx * dt;
    b.y += b.vy * dt;

    // --- 撞箱子。**必须先分清"从上面来"和"从侧面来"** ——
    //     只看包围盒重叠的话，球在箱顶滚也会被当成侧撞，把脚下的箱子砸了。
    for (const box of S.boxes) {
      if (box.dead) continue;
      const overlapX = b.x + b.r > box.x && b.x - b.r < box.x + box.w;
      /* **`box.y + 6` → `box.y`（2026-10-28 第三轮）。**
         那 6px 是当年为"别把箱顶滚动的球判成侧撞"留的余量，可它同时
         让**停在箱顶的球每帧漏检**：球底贴住箱顶时 `球底 > 箱顶 + 6`
         不成立 → 这一帧不算落地 → 球继续掉 0.58px，要掉满 6px 才重新
         被接住。于是球静止时以 5 帧为周期上下抖 6.2px，玩家踩上去
         整个人跟着抖 —— 这是"站不住"体感的一半来源。
         "从上方来"这件事已经由下面的 `prevBottom <= box.y + 10` 判得很准，
         这里不需要再垫 6px。 */
      const overlapY = b.y + b.r > box.y && b.y - b.r < box.y + box.h;
      if (!overlapX || !overlapY) continue;

      // 从上方落下 / 在箱顶滚：当作地板 —— **但"落下"和"滚"不是一回事**
      if (prevBottom <= box.y + 10) {
        /* **落下来的球会砸碎脚下的箱子（2026-10-28 第四轮）。**
           用户：「球掉下去 是可以杂碎箱子」。

           以前这一分支一律"接住"，于是球从洞口掉进箱堆只是安静地停在最上面，
           "把球推下洞"完全没有收益 —— 而它本该是这颗游戏里最爽的一下。

           判据是**落地那一帧的 vy**（见 NUM.ball.crushVy）：滚上来的球 vy=0，
           一次真下落 vy ≥ 320。砸碎之后 vy 只乘 `keepSpeed`（木箱 0.82），
           所以一颗球能从三格箱堆里一路犁到底 —— 这就是"落球"的回报，
           砸一颗就停的球没有意义。 */
        if (b.vy >= NUM.ball.crushVy) {
          ballHitBox(b, box, 0, b.vy);
          if (b.dead) break;
          if (box.dead) continue;       // 碎了就继续往下掉，不要贴到箱顶
        }
        b.y = box.y - b.r; b.vy = 0; b.onGround = true;
        continue;
      }
      // 侧面撞击
      /* **慢速贴住：不碎箱，但绝不许留在箱体里。**
         旧版这一行是 `continue`，于是被轻轻碰一下的球会钻进箱子里停住 ——
         画面上就是"球明明撞到箱子了，什么都没发生"，而且球从此卡在箱体
         内部，看起来像穿模。用户说的「球很难撞击到」有一半是它。
         慢球只做位置解算：推到箱面上停住，读起来是"球抵着箱子"。 */
      if (Math.abs(b.vx) < 40) {
        b.x = (b.x < box.x + box.w / 2) ? box.x - b.r : box.x + box.w + b.r;
        b.vx = 0;
        continue;
      }
      const dir = sign(b.vx);
      ballHitBox(b, box, dir);
      if (b.dead) break;
    }
    if (b.dead) continue;

    // --- 撞平台（左右墙 + 落地）
    for (const pl of S.plats) {
      if (pl.kind === 'ramp') {
        /* 球走坡：贴顶面，并**顺着坡自己往下滚**。
           这是全场唯一给球加的外力 —— 不加的话球能停在一段 30° 的坡上不动，
           一眼就假。顺带它把斜坡变成一条"加速跑道"：从坡顶滚下来撞箱，
           动量比平地推大得多，斜坡因此有了战术价值，不只是过路地形。 */
        if (b.x + b.r <= pl.x || b.x - b.r >= pl.x + pl.w) continue;
        const top = surfY(pl, b.x);
        /* **必须判"从上方来"（prevBottom 在坡面附近），只看 x 重叠会出事：**
           球在下面几层往右滚，只要 x 恰好落在某个上层斜坡的区间里，
           `b.y + b.r > top - 4` 就成立（球底当然在坡面以下），
           球会被一发瞬移到那个坡顶上 —— 看起来像"球凭空飞上去了"。
           加 prevBottom 之后，只有真的从坡上方落下来才贴面。 */
        /* ---- 接触是"连续的"，不是"每帧重新判"（2026-10-29）----
           用户原话：「球进入了死胡同　比如上坡　完全推不上去」。
           斜坡上坡时球没有任何东西把它抬起来 —— 它靠的是
           "这一帧水平走了 dx，坡面高了 dx×坡度，落差 ≤16 就当接住"。
           dx 一大就接不住：助跑推 1209 px/s 在 60fps 一帧走 20px，
           0.79 的坡度抬 15.9px（擦线），30fps 走 40px 抬 31.7px（必穿）。
           **一旦穿下去，坡面从此再也接不到它** —— 球在坡体内部，
           看不见、推不动，这就是"完全推不上去"。

           修法：上一帧球底就贴着坡面（`wasOn`）时，不论这一帧坡面抬多少
           都直接贴过去。接触本来就是连续的，不该每帧重新证明一次。
           `wasOn` 用的是 prevX 那一点的坡面，所以"从坡脚平地上坡"也成立
           （低端坡面高度 == 地面高度）；而在下面一层滚的球，
           prevTop 在几十米之上，`wasOn` 为假 —— 不会误吸。 */
        const prevTop = surfY(pl, prevX);
        const wasOn = prevBottom <= prevTop + 6;
        if (b.vy >= 0 && (wasOn || prevBottom <= top + 16) && b.y + b.r > top - 4) {
          b.y = top - b.r; b.vy = 0; b.onGround = true;
          b.vx += (pl.rise > 0 ? -1 : 1) * 420 * dt;
        }
        continue;
      }
      const overlapX = b.x + b.r > pl.x && b.x - b.r < pl.x + pl.w;
      const overlapY = b.y + b.r > pl.y && b.y - b.r < pl.y + pl.h;
      if (!overlapX || !overlapY) continue;
      if (b.vy > 0 && prevBottom <= pl.y + 12) {
        b.y = pl.y - b.r; b.vy = 0; b.onGround = true;
      } else if ((b.y + b.r) - pl.y <= 24) {
        /* **台阶助步：坡顶与台面之间有 ≈18px 的缝。**
           球的贴面用圆心高度（和玩家同一套理由：斜坡要这样才不抖），
           滚到坡顶时球底比台面低 `半径 × 坡度` ≈ 17px，于是侧面把它
           原样弹回去 —— 这就是"推到坡顶再也不动"。
           和 stepBody 一样给一次 ≤24px 的抬腿（球比人宽，给宽 4px）。 */
        b.y = pl.y - b.r; b.vy = 0; b.onGround = true;
      } else {
        b.x = prevX; b.vx *= -0.35;
      }
    }

    // --- 撞墙
    if (b.x - b.r < WALL_L) { b.x = WALL_L + b.r; b.vx = Math.abs(b.vx) * 0.45; }
    if (b.x + b.r > WALL_R) { b.x = WALL_R - b.r; b.vx = -Math.abs(b.vx) * 0.45; }

    // --- 地面摩擦
    if (b.onGround) {
      const d = NUM.ball.fric * dt;
      if (Math.abs(b.vx) <= d) b.vx = 0; else b.vx -= sign(b.vx) * d;
      b.onGround = false;
    }

    // --- 碾敌。**球是唯一的击杀通道**，这里就是那条通道的收口。
    if (Math.abs(b.vx) > 60) {
      for (const f of S.foes) {
        if (f.dead) continue;
        if (b.x + b.r < f.x || b.x - b.r > f.x + f.w) continue;
        if (b.y + b.r < f.y || b.y - b.r > f.y + f.h) continue;
        killFoe(f, b);
      }
    }
  }
  S.balls = S.balls.filter(b => !b.dead);
}

/* **撞击动量只有一个数（`pow`），横向和垂直各取各的。**
   横向撞看 vx、落下砸看 vy —— 箱子表里的 `minPow` 因此只需要一列，
   不用维护"横撞阈值 / 垂直阈值"两套（两套表的第一个后果就是有人只改一套）。
   量纲是一致的：`速度 × 体径比`，所以"多大球 + 多快"这层关系没变。
   `vDown` 非空即"这是落砸"，返回时的处理不同：横向要穿透继续滚，
   垂直要保留一部分下落速度继续往下掉。 */
function ballHitBox(b, box, dir, vDown) {
  const def = NUM.box[box.mat];
  const pow = Math.max(Math.abs(b.vx), vDown || 0) * (b.r / NUM.ball.baseR);
  const tier = ballTier(b.absorbed);

  if (pow >= def.minPow && tier >= def.minTier) {
    /* 冲击方向：横向撞 = 球的速度符号；落砸 = 自上而下。
       碎片、震屏、冲击环都吃这一个向量，三者才是一件事。 */
    const ddx = vDown ? 0 : (b.vx >= 0 ? 1 : -1);
    const ddy = vDown ? 1 : 0;
    breakBox(box, 'ball', pow, ddx, ddy);
    if (vDown) b.vy = vDown * def.keepSpeed;   // 落砸：继续往下犁
    else b.vx *= def.keepSpeed;                // 穿透：撞碎之后继续滚，这是爽感的来源
    b.chain++;

    /* **撞碎箱子不给体积。**
       即时回报已经够了：`keepSpeed` 让球继续滚、`chain` 记连碎数、
       9 点震屏 + 45ms 顿帧。体积只认"吞掉敌人"这一条来源，
       否则裹怪这个核心操作会被"随便砸三口箱"替代掉。 */
    S.stat.ballChain = b.chain;
    S.stat.ballChainMax = Math.max(S.stat.ballChainMax, b.chain);
    S.shake = Math.max(S.shake, 9);
    hitStop(0.045);
  } else {
    // 砸不动：反弹 + 冒火花。**「太硬」这件事必须让玩家在物理上感到**
    /* ---- 但"砸不动的一格台阶"不该是一堵墙（2026-10-29）----
       用户原话：「球进入了死胡同　比如上坡　完全推不上去了」。
       球没有跳跃，被推进一个四周都比它高一格的坑里就永远出不来 ——
       只要那个坑壁是砸不动的（铁箱 / 冰墙 / 地形石台），推一百下也是弹回来。

       规则改成：**球能翻过它砸不动的一格台阶。** 判据用"箱顶比球底高多少"：
         ≤ 56（一格 + 一点余量）→ 起跳翻上去；
         ≥ 96（两格）→ 仍然是墙，得绕、或者换更大的球。
       这样"铁箱 = 墙"这条没被破坏（墙都是两格起的），而
       "一格高的硬边 = 死胡同"这条被消掉了。起跳高度按 60px 反算，
       刚好让球落到箱顶而不是飞过去。
       这一跳只在**被推着撞上去**时发生（|vx| ≥ 200）：轻轻蹭一下还是弹回来，
       否则球会在硬墙前面自己弹弹跳跳，看起来很傻。 */
    const stepH = (b.y + b.r) - box.y;
    if (!vDown && stepH > 4 && stepH <= 56 && Math.abs(b.vx) >= 200) {
      b.y = box.y - b.r - 1;
      b.vy = -Math.sqrt(2 * 2100 * 60);
      b.vx *= 0.86;
      addFrag(b.x, b.y + b.r, 6, '#EAF6FF', 180);
      S.shake = Math.max(S.shake, 3);
      return;
    }
    if (vDown) {
      b.y = box.y - b.r; b.vy = 0; b.onGround = true;   // 落在箱顶，不动
    } else {
      b.x = dir > 0 ? box.x - b.r : box.x + box.w + b.r;
      b.vx = -dir * Math.max(140, Math.abs(b.vx) * 0.4);
    }
    addFrag(b.x, b.y, 8, '#FFE0A0', 220);
    S.shake = Math.max(S.shake, 5);
    if (box.mat === 'ice' && tier < def.minTier) {
      once('ice_tier', box.x + box.w / 2, box.y - 14, '球再大点才行', '#9AD8F5');
    } else {
      once('hard_ball_' + box.mat, box.x + box.w / 2, box.y - 14, '太硬了 · 换球砸', '#FFD08A');
    }
  }
}

function burstBall(b) {
  b.dead = true;
  addFrag(b.x, b.y, 14, '#DCF0FF', 300);
  addText(b.x, b.y - b.r - 6, '散了', '#9FB4C4', 14, 0.7);
}

/* **打击感的三件套，缺一件就"软"：**
     ① 碎片要有材质形状（木 = 板条、石 = 棱角块）—— 碎成一样的方点，
        所有东西就都一样了；
     ② 球砸要有**顿帧 + 冲击环**。顿帧让"力"有时间落地，环给出方向；
     ③ 震屏按"撞的动量"分级，不是一律 10 —— 小球轻轻蹭一下和特大球
        正面撞，手感该是不一样的。
   2026-10-29 补第四条：
     ④ **碎片和震屏都要有方向。** 全向均匀炸开读作"爆了"，
        沿撞击方向喷出去才叫"被撞碎"。`dirX/dirY` 是冲击的单位向量。 */
function breakBox(box, how, pow, dirX, dirY) {
  box.dead = true;
  const cx = box.x + box.w / 2, cy = box.y + box.h / 2;
  const byBall = how === 'ball';
  const wood = box.mat === 'wood';
  const hard = byBall ? 360 : 210;
  /* 定向喷出的偏置。**只有球撞才给方向** —— 子弹是一点一点啃的，
     它不该把整口箱子掀飞，否则"子弹 vs 球"的力气差就没了。 */
  const BX = byBall ? (dirX || 0) * 210 : 0;
  const BY = byBall ? (dirY || 0) * 210 : 0;
  const bias = { x: BX, y: BY };

  if (wood) {
    /* 木：一堆**板条** + 几块小碎块。板条会转，转起来才像"被撞散的"。 */
    addFrag(cx, cy, byBall ? 4 : 2, '#B08A5E', 130, 'slab', bias);      // 大块残骸，飞得慢
    addFrag(cx, cy, byBall ? 14 : 6, '#C9A273', hard, 'plank', bias);
    addFrag(cx, cy, byBall ? 9 : 4, '#E8C79A', hard * 0.8, 'chunk', bias);
    addFrag(cx, cy, byBall ? 5 : 2, '#8A6236', hard * 0.6, 'chunk', bias);
    /* 第三层：**极小的木屑，飞得慢、活得久。** 大块负责"撞开",
       这层负责"余韵" —— 大块 0.35~0.8 秒就落干净了，画面会突然安静；
       屑子飘到 1.1 秒，撞击的"尾巴"才留得住。 */
    if (byBall) addFrag(cx, cy, 10, '#F0DCC0', 130, 'chunk', bias);
  } else {
    /* 石 / 铁：没有板条，全是**棱角块**，飞得近、落得快。 */
    addFrag(cx, cy, byBall ? 16 : 7, '#9AA6B0', hard * 0.9, 'chunk', bias);
    addFrag(cx, cy, byBall ? 8 : 3, '#6E7A86', hard * 0.65, 'chunk', bias);
    addFrag(cx, cy, byBall ? 5 : 2, '#CFD8E0', hard * 1.1, 'chunk', bias);
    if (byBall) addFrag(cx, cy, 7, '#FFE9A8', 240, 'chunk', bias);   // 石屑里迸的火星
  }

  if (byBall) {
    /* 球有动量，顿帧和震动跟着动量走。`pow` 是 ballPow（速度 × 体径比）。 */
    const k = clamp((pow || 1) / 2.6, 0.55, 1.5);
    hitStop(0.05 + 0.04 * k);
    /* **震屏上限压到 14。** 再大整个画面就在"跳"，玩家会晕。 */
    S.shake = Math.max(S.shake, Math.min(14, 8 + 5 * k));
    /* 方向跟着冲击走：横向撞是球的速度方向，落砸是"从上往下"。 */
    S.shakeDX = dirX || 0;
    S.shakeDY = dirY || 0;
    /* **同时最多 4 个环。** 特大球会连着碾碎 4~5 个箱子，每个箱子两圈 ——
       十来个环叠在一起就是一团结，什么也读不出来（放大图里像一堆泡泡）。
       旧环直接丢掉：它们本来就快消失了，留着只添乱。 */
    if (S.rings.length > 3) S.rings.splice(0, S.rings.length - 3);
    S.rings.push({ x: cx, y: cy, r: 6, r0: 6, r1: 54 + 26 * k, t: 0, life: 0.26, color: '#FFF6E0' });
    /* 第二圈慢半拍、暗一档：两圈才有"冲击波"的层次，一圈只是一个圆 */
    S.rings.push({ x: cx, y: cy, r: 4, r0: 4, r1: 82 + 34 * k, t: -0.05, life: 0.36, color: 'rgba(255,226,170,.85)' });
  } else {
    S.shake = Math.max(S.shake, 3);
  }

  if (how === 'ball') S.stat.boxByBall++; else S.stat.boxByShot++;

  /* ---- 金箱 ----
     **必掉一片雪之碎片。** 概率掉的话"探索"就成了抽奖：玩家爬上箱山、
     拆开金箱、什么都没拿到，下次就不想为它绕路了。
     探索的回报必须是确定的，只是要花力气去够。 */
  if (box.loot) {
    S.loot = (S.loot || 0) + 1;
    S.flash = Math.max(S.flash, 0.22);
    addText(cx, box.y - 10, '宝物 +1', '#FFD45E', 15, 1.2);
    addFrag(cx, cy, 10, '#FFD45E', 240);
    S.shards.push({ x: cx, y: cy, vy: -260, t: 0 });
    return;                       // 金箱不再走下面那段随机掉落
  }

  // 掉弹：价值差就写在这一行
  /* **木桶比木箱更值钱一点。** 它只有 2 发耐久，砸开却按 1.35 倍算 ——
     玩家会自己发现"先拆桶"，而拆桶的动作恰好和"清出射界"是同一件事。 */
  const rate = (how === 'ball' ? NUM.drop.shardByBall : NUM.drop.shardByShot) * (box.barrel ? 1.35 : 1);
  if (Math.random() < rate) {
    S.shards.push({ x: cx, y: cy, vy: -220, t: 0 });
  }
}

/* ---------------------------------------------------------------- 敌人 AI */
function killFoe(f, byBall) {
  if (f.dead) return;
  f.dead = true;
  S.killed++;
  S.stat.kills++;
  if (byBall) S.stat.killByBall++;
  addFrag(f.x + f.w / 2, f.y + f.h / 2, 12, '#FFC8B0', 260);
  /* 打中敌人也要有"打中"的感觉：一小圈白环 + 短顿帧。
     **不加的话，怪就是"凭空变成一堆碎片"** —— 玩家感受不到自己打中了。 */
  S.rings.push({ x: f.x + f.w / 2, y: f.y + f.h / 2, r: 5, r0: 5, r1: 30, t: 0, life: 0.2, color: '#FFE8D8' });
  if (byBall) hitStop(0.055);
  S.shake = Math.max(S.shake, 7);
  if (byBall) {
    byBall.absorbed = Math.min(NUM.ball.maxAbsorb, byBall.absorbed + NUM.ball.absorbFoe);
    byBall.r = ballR(byBall.absorbed);
  }
  checkDoor();
}

/* **怪物的"巡逻走廊"。**
   量出它身前身后这一段地面能走到哪、走不到哪，之后用 clamp 限制，
   而不是靠"撞墙就换向"。原来那套写法有两个后果：

   ① 撞墙检测每帧触发一次换向，绕过换向锁 —— 怪被夹在两口箱子之间
      （只有 14px 宽的凹槽）时，位置每 0.2 秒来回一次，肉眼就是抽搐；
   ② 每次撞墙都要靠 stepBody 把人推出来，贴墙的那几帧位置都是被修正的，
      画面上人会一抖一抖。

   走廊一旦量好，怪在自己的走廊里来回走，永远不会撞到墙。 */
function foeRoam(f) {
  const hit = (x) => solids().some(s => {
    if (s.kind === 'ramp') return false;
    if (x >= s.x + s.w || x + f.w <= s.x) return false;
    if (f.y + f.h <= s.y + 2) return false;          // 站在这块上面不算
    /* **矮台不算墙。**（2026-10-28 加，配合"宠物会跳"）
       高差 ≤ 56 的块（一格箱子 48）是宠物一步就能跳上去的台阶，
       如果还当墙算，走廊就会被切成一格一格，宠物永远只能在自己那块
       箱顶上来回 —— 用户说的"怪物只能横向走"一大半是这个。
       真正挡住它的是 2 格以上（96 > 跳高 64）的箱墙，那个照旧算墙。 */
    if (s.y >= f.y + f.h - 58) return false;
    return f.y < s.y + s.h && f.y + f.h > s.y;
  });
  /* **走到台子边缘就停，不许走空。**
     原来只挡"前面有实体"，站在箱顶上的怪走到箱边时前面是空气 → 走廊算到
     地面尽头 → 它一步踩空掉下去。表现是"怪凭空下坠 / 摔到地板上站着"，
     而且它再也爬不回箱顶（只会横向走）。
     判据用"脚下 10px 内有没有地"：`groundAt` 取最近的可站面，脚下就是
     这块箱顶时差值 0，箱顶外侧会退回到本层地板（差 48）→ 判成悬崖，停。 */
  const foot = f.y + f.h;
  /* **一格高差也放行。** 宠物会跳（jump 470~545，跳高 52~70），
     48 的台阶是它该走的路，不是悬崖。两格（96）才算掉下去 ——
     那种地方它宁可站着不打，也不该自己跳崖去找玩家。 */
  const cliff = (x) => (groundAt(x + f.w / 2, foot + 2) - foot) > 54;
  let a = f.x, b = f.x;
  for (let t = 0; t < 60 && a > WALL_L && !hit(a - 6) && !cliff(a - 6); t++) a -= 6;
  for (let t = 0; t < 60 && b + f.w < WALL_R && !hit(b + 6) && !cliff(b + 6); t++) b += 6;
  return [a, b];
}

/* =========================================================================
   黑洞（吐怪巢）
   ---------------------------------------------------------------------------
   **"怪打光就没球了"是这一关结构上的缺口。** 球的唯一来源是敌人：
   裹住一只 → 那颗球本金 1（tier 0），球再碾死一只 → 2，才够破冰墙。
   怪打完，玩法就断了。黑洞补一条"还会长"的来源。

   但没有配额的生成器会变成刷怪场，所以卡死三条：
     · **总配额 3~5 只**，吐完就暗下去（仍然挂在那儿当场景，不会凭空消失）；
     · **同时只允许存活 1 只**（自己吐出来的那些），不会堆成一群；
     · **走得慢**（26px/s）—— 用户说"可以到处走"，但走快了就成了追命鬼。

   漂移不用物理：碰到墙 / 前方没有地面就折返。它不需要遵守碰撞，
   因为它本来就是个"贴在地面上的洞"。 */
const NEST = { speed: 26, period: 5.2, maxAlive: 1 };

function stepNests(dt) {
  for (const n of S.nests) {
    n.t += dt;
    n.born = Math.max(0, (n.born || 0) - dt);
    if (n.left <= 0) continue;
    n.cd -= dt;

    /* ---- 缓步挪动 ---- */
    const nx = n.x + n.dir * NEST.speed * dt;
    if (nx < WALL_L + 22 || nx > WALL_R - 22) n.dir = -n.dir;
    else if (Math.abs(groundAt(nx, n.y + 4) - n.y) > 10) n.dir = -n.dir;
    else n.x = nx;

    /* ---- 吐怪 ---- */
    if (n.cd <= 0) {
      const alive = S.foes.filter(f => f.nest === n && !f.dead).length;
      if (alive < NEST.maxAlive) {
        const f = makeFoe(n.x - 17, n.y - FOE_H, 'crawler');
        f.nest = n;
        f.roamL = null;
        f.homeX = n.x - 17;
        f.homeY = n.y - 30;
        S.foes.push(f);
        n.left--;
        n.cd = NEST.period;
        n.born = 0.8;
        addText(n.x, n.y - 58, '有东西爬出来', '#C6A8FF', 13, 1.2);
      } else {
        n.cd = 0.5;                    // 名额占着，过会儿再看
      }
    }
  }
}

/* ---------------------------------------------------------------- 宠物子弹
   **宠物不是"会走的障碍物"，是会打你的单位。** 用户原话：「没有发射子弹
   攻击的地方」。原来整场的威胁只有"撞到你"，玩家站在两格高的箱顶就
   完全安全 —— 没有远程，就没有"该躲什么"，跳跃也就只是移动。

   三条设计约束，都是为了让它不变成"必中弹"：
     · **不瞄准玩家，只朝自己面朝的方向扔。** 会瞄准的话，玩家只能靠
       跑出射界来躲，那和"必中"没区别；朝一个方向扔，玩家侧一下身就躲开了。
     · **有 0.42 秒的举手动前摇。** 这一拍是给玩家的反应窗口，
       也是画面上唯一能读出"要来了"的信号。
     · **全场同时最多 7 发。** 怪一多就会打成弹幕，那不是这个游戏的难度曲线。
*/
function fireFoeBullet(f) {
  if (S.ebullets.length >= NUM.ebullet.maxAlive) return;
  const cfg = NUM.breed[f.breed] || NUM.breed.moss;
  const E = NUM.ebullet;
  const spd = (E.spd && E.spd[cfg.bullet]) || 320;
  S.ebullets.push({
    kind: cfg.bullet,
    x: f.x + f.w / 2 + f.face * 17,
    /* **出手位置在头顶下方 6px（离地约 24px）。**
       再高一点（f.y−2）会贴着这一层箱子的顶跑 —— 敌人站在箱堆边上时，
       子弹一出生就撞进旁边的箱体里，飞出 5 帧就没了，"射程"变成了一句空话。
       离地 24px 是"够高、能拉开弧线，又不至于一出膛就撞头"的分界。 */
    y: f.y + 2,
    vx: f.face * spd,
    vy: E.vy,
    t: 0, r: E.r, face: f.face, spin: 0, dead: false,
  });
  addFrag(f.x + f.w / 2 + f.face * 17, f.y, 3, '#E8E2D2', 110);
}

function stepEBullets(dt) {
  const p = S.p;
  for (const b of S.ebullets) {
    if (b.dead) continue;
    b.t += dt;
    /* 抛物线在这里成型：只有 vy 吃重力，vx 恒定 —— 这就是用户要的
       "平行丢出去、但有下落感"。 */
    b.vy += NUM.ebullet.g * dt;
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    b.spin += b.vx * dt * 0.02;

    if (b.t >= NUM.ebullet.life) { b.dead = true; continue; }
    if (b.x < WALL_L - 24 || b.x > WALL_R + 24 || b.y > WORLD_H) { b.dead = true; continue; }

    /* 打到玩家。**只有这一处会掉血** —— 撞人的那条在 stepFoes 里，两条
       共用 hurtPlayer 的 invuln，所以不会一帧掉两滴。 */
    if (S.invuln <= 0 && S.phase === 'play' &&
        b.x + b.r > p.x && b.x - b.r < p.x + p.w &&
        b.y + b.r > p.y && b.y - b.r < p.y + p.h) {
      b.dead = true;
      addFrag(b.x, b.y, 8, '#FFD9A8', 200);
      hurtPlayer();
      continue;
    }

    /* 撞地形就砸碎。**箱子不掉血。** 让宠物子弹能砸箱等于给玩家一条
       "引怪帮你开路"的捷径，弹药经济就白算了。 */
    let blocked = false;
    for (const s of solids()) {
      if (s.kind === 'ramp') continue;
      if (b.x + b.r < s.x || b.x - b.r > s.x + s.w) continue;
      if (b.y + b.r < s.y || b.y - b.r > s.y + s.h) continue;
      blocked = true; break;
    }
    if (blocked) {
      b.dead = true;
      addFrag(b.x, b.y, 5, '#E8DCC8', 150);
    }
  }
  S.ebullets = S.ebullets.filter(b => !b.dead);
}

function stepFoes(dt) {
  const p = S.p;
  for (const f of S.foes) {
    if (f.dead) continue;
    f.hitT = Math.max(0, f.hitT - dt);
    f.turnLock = Math.max(0, (f.turnLock || 0) - dt);

    /* ---- 巡逻走廊 ----
       落地之后量一次（脚底高度变了说明箱子塌了，要重量）。 */
    const feetNow = f.y + f.h;
    /* **脚底要有地，不能只剩一条边。**
       引擎的落地判据是"包围盒和平台有重叠"，所以身体 99% 悬在崖外、
       只压住 0.6px 的时候它依然算站着 —— 一旦在这里停住（待机或蓄力），
       画面上就是一只浮在半空的兔子。出图和断言都抓到过这个。
       这里用身体中段单独探一次，给"会停住"的两个动作当闸门。 */
    const solidFoot = Math.abs(groundAt(f.x + f.w / 2, feetNow) - feetNow) < 6;
    if (f.roamL == null || Math.abs(feetNow - (f.roamY == null ? feetNow : f.roamY)) > 20) {
      const r = foeRoam(f);
      f.roamL = r[0]; f.roamR = r[1];
      f.roamY = feetNow;
    }
    /* 走廊太窄就站定 —— 与其让它在凹槽里每 0.2 秒来回一次（抽搐），
       不如让它守在那里。
       **门槛必须跟着走速走，不能是常数 46。** runner 是 148，47px 的走廊
       0.32 秒就横穿一趟，而换向锁正好是 0.3s —— 锁一解锁就翻，探针量到
       「2 秒换向 6 次」，画面上是一只贴着玩家原地抽搐的怪。
       46 + speed/2 的意思：走廊至少要够它走半秒多，否则原地待命。 */
    const canWalk = f.roamR - f.roamL >= 46 + f.speed * 0.5;

    /* ================= 敌方行为 ==================
       用户的四条要求都落在这里：会跳、会待机、会远程打人、弹道有下落。
       **优先级：瞄准 > 待机 > 走路。** 顺序反过来的话，宠物会在"该开枪了"
       的时候还在东张西望，玩家永远等不到那一发。 */
    const pcfg = NUM.breed[f.breed] || NUM.breed.moss;
    f.fireCd = Math.max(0, (f.fireCd || 0) - dt);
    f.jumpCd = Math.max(0, (f.jumpCd || 0) - dt);

    const dxp = (p.x + p.w / 2) - (f.x + f.w / 2);
    const dyp = (p.y + p.h / 2) - (f.y + f.h / 2);
    /* 射界：水平在射程内、垂直差 < 78（小半层），而且自己站得住。
       **垂直判据不能省。** 少了它，它会隔着两层楼朝天花板扔东西。 */
    const inSight = S.phase === 'play' && f.onGround && solidFoot &&
                    Math.abs(dxp) < pcfg.range && Math.abs(dyp) < 78;
    const aiming = inSight && f.fireCd <= 0;

    if (aiming) {
      f.aim += dt;
      /* 转身朝玩家，但**留 6px 死区** —— 玩家站正上方时 dxp 会在 ±2 之间
         抖，没有死区就是每帧翻面。 */
      if (Math.abs(dxp) > 6) f.face = dxp > 0 ? 1 : -1;
      f.vx = 0;
      if (f.aim >= NUM.ebullet.windup) {
        fireFoeBullet(f);
        f.aim = 0;
        f.fireCd = pcfg.cdA + FR() * (pcfg.cdB - pcfg.cdA);
      }
    } else {
      f.aim = Math.max(0, f.aim - dt * 4);
      /* ---- 待机 ---- 走一阵停一阵。停的时候它会耸背（画在 drawFoe），
         所以"不动"不等于"卡住了"。 */
      if (f.idleT > 0) {
        f.idleT -= dt;
      } else {
        f.walkT -= dt;
        if (f.walkT <= 0) {
          /* 崖边不许待机：先迈回去，脚踩实了再停。 */
          if (solidFoot) {
            f.idleT = 0.55 + FR() * 0.9;
            f.walkT = 1.1 + FR() * 1.5;
          } else {
            f.walkT = 0.12;
          }
        }
      }
      /* ---- 跳 ---- **一个箱子高的台阶要能上去。**
         探前方 8px、往上 112px 找最近的可站面：落差 18~104 就起跳。
         上限 104 是"两格 96 也跳"，下限 18 是别为了 10px 的坎一直弹。 */
      if (f.onGround && f.jumpCd <= 0) {
        const ahead = f.face > 0 ? f.x + f.w + 8 : f.x - 8;
        const rise = (f.y + f.h) - groundAt(ahead, f.y + f.h - 112);
        /* **会不会跳，由体态决定，不由关卡决定。**
           多足甲虫（jump = 0）永远走这条 else：矮坎直接蹭上去、高坎掉头。
           以前它被塞进和四足兽同一套跳跃里，一遇到箱堆就原地连蹦 ——
           十几条腿的东西弹起来，比什么动画都出戏。 */
        if (pcfg.jump > 0) {
          if (rise > 18 && rise < 104) {
            f.vy = -pcfg.jump;
            f.onGround = false;
            f.jumpCd = 0.75;
          }
        } else if (rise > 2 && rise <= NUM.crawlStep) {
          /* 蹭坎：**位移不是跳，是贴着地往上抬**。一点点把脚落上去，
             不做抛物线、不改 vy，读起来就是"爬过去了"。 */
          f.y -= Math.min(rise, NUM.crawlStep);
        }
      }
    }

    /* ---- 选方向 ----
       **任何一次真正的换向都上锁（0.3s）。** 缺了锁，最大的问题是
       runner 每帧算"朝玩家走"：玩家一旦和它重叠，左右判定就每帧翻转，
       位置在 3px 里来回震（探针量到 120 帧换向 120 次）。 */
    const standing = aiming || f.idleT > 0;
    /* 钉住：**runner 被地形卡住时不来回走，站住等**（理由见走廊边界那一段）。 */
    let pinned = false;
    let want = f.face || 1;
    if (standing) {
      want = f.face || 1;
    } else if (f.kind === 'runner') {
      /* **贴身死区。** runner 的朝向每帧由"玩家在哪边"重算：一旦走到玩家
         中心线上，左右判定就翻；turnLock 掐住以后变成"每 0.3 秒翻一次"，
         148×0.3 = 44px 的来回 —— 画面上是一只绕着玩家抽搐的怪
         （探针前 40 帧的 x 在 42px 里来回，就是这个数）。
         进了 30px（两个身位贴住）就保持原朝向并且站定，
         等玩家走开再追。30 远小于它的射击距离（350），"够得着就打"不受影响。 */
      const dx = (p.x + p.w / 2) - (f.x + f.w / 2);
      if (Math.abs(dx) < 30) { want = f.face || 1; pinned = true; }
      else want = dx > 0 ? 1 : -1;
    } else {
      f.patrolT -= dt;
      if (f.patrolT <= 0) {
        f.patrolT = 1.4 + FR() * 1.2;
        want = FR() < 0.5 ? -1 : 1;
      } else {
        want = f.face || 1;
      }
      if (Math.abs(f.x - f.homeX) > 120) want = -sign(f.x - f.homeX);
    }
    /* **怪不许走下平台。**
       三层之后这是一个很隐蔽的塌方：一只巡逻怪顺着台边走下来、再走下来，
       最后整场的怪都聚在洞窟底，上面两层变成空台子 —— 玩家爬上去只看到
       空房间，会以为这关坏了。实测 crawler 从 (740,826) 一路走到 (801,826)
       然后掉层，就是这么发生的。
       所以在台边折返。runner 也照样折返：它该在台上等你，不是自己跳崖。

       **门槛从 40 放到 56（2026-10-28）：一格箱子是 48，49 不是悬崖。**
       宠物现在会跳，下去还能跳回来；继续按 40 卡着，它就永远困在箱顶上，
       用户说的"怪物只能横向走"就还是那句老话。两格（96）它跳不上来，
       那种地方照样折返。 */
    if (f.onGround && !standing) {
      const fy = f.y + f.h;
      const ahead = want > 0 ? f.x + f.w + 6 : f.x - 6;
      if (groundAt(ahead, fy + 2) - fy > 56) {
        /* crawler 在崖边回头是巡逻；runner 回头就是"朝玩家冲 → 撞崖 →
           回头 → 再冲"的来回，1 秒三次。它该在台边等人，不是原地抽。 */
        if (f.kind === 'runner') pinned = true;
        else want = -want;
      }
    }
    /* ---- 撞到走廊边界 ----
       **runner 撞边不是"回头"，是"站住等"。**
       crawler 的 want 由巡逻计时器给，在边上回头就是它该做的事；
       但 runner 的 want 每帧由"玩家在哪边"重算 —— 玩家在走廊外面时，
       它撞 Left 边 → 反弹 0.3s（148×0.3 = 44px）→ 锁一解又朝玩家 →
       再撞。探针量到"2 秒换向 6 次"，前 40 帧的 x 在 44px 里来回，
       画面上就是一只贴着墙原地抽搐的怪（44 这个数字就是这么来的）。
       所以 runner 在这里改成钉住 + 停步，朝向保持指向玩家那一侧。 */
    if (want < 0 && f.x <= f.roamL + 0.5) {
      if (f.kind === 'runner') { pinned = true; want = 1; }
      else want = f.turnLock > 0 ? f.face : 1;
    }
    if (want > 0 && f.x >= f.roamR - 0.5) {
      if (f.kind === 'runner') { pinned = true; want = -1; }
      else want = f.turnLock > 0 ? f.face : -1;
    }
    if (want !== f.face) {
      if (f.turnLock > 0) want = f.face;      // 锁内不许换
      else f.turnLock = 0.30;
    }
    f.face = want;
    /* **窄台面上走慢点。** 巡逻走廊只有 70px 时，84px/s 的宠物 0.4 秒就横穿
       一趟，来回的频率和"抽搐"没有区别。按走廊长度衰减到 0.35 倍，
       看起来才像"在台边小心地踱步"，而不是原地抖。 */
    const paceK = clamp((f.roamR - f.roamL) / 260, 0.35, 1);
    f.vx = (standing || !canWalk || pinned) ? 0 : want * f.speed * paceK;

    /* stepBody 里已经把「水平位移 + 水平碰撞 + 重力 + 垂直落地」全做完了。
       **这里不能再补位移或重力** —— 叠上去会让速度翻倍、一帧穿过地面
       （第一版就是这么写的：crawler 直接掉出画面）。 */
    stepBody(f, dt);

    /* 掉出世界就送回**自己原来那一层**，不是送回洞窟底。
       三层之后 H 已经不是世界高度了，用 H 会把 L2 掉下去的怪
       拉到底层（离玩家 1000px 外），看起来像凭空消失了。 */
    if (f.y > WORLD_H + 80) {
      f.y = (f.homeY !== undefined ? f.homeY : f.y);
      f.x = f.homeX;
      f.vy = 0; f.hits = 0; f.needAt = 0;
      f.roamL = null;
    }
    f.x = clamp(f.x, WALL_L, WALL_R - f.w);
    /* 走廊 clamp 放在最后：stepBody 的碰撞修正偶尔会把人挤出走廊一两个像素，
       下一帧选方向就会看到"已经出界"，来回抖。这里直接夹回去。 */
    if (f.roamL != null) {
      if (f.x < f.roamL) f.x = f.roamL;
      if (f.x > f.roamR) f.x = f.roamR;
    }

    // 撞玩家
    if (S.invuln <= 0 && aabb(p, f)) {
      hurtPlayer();
      // 贴脸保底：自己掉血，敌人吃两点雪。零弹时唯一的出路
      coatFoe(f, NUM.bodyCoat);
    }
  }
  S.foes = S.foes.filter(f => !f.dead);
  separateFoes();
}

/* =========================================================================
   敌人之间**不许互相穿过去**
   -------------------------------------------------------------------------
   用户说「乱的都没办法辨」—— 这三分之一来自这里：
   出生点隔了 96px，但敌人跑起来互不碰撞，苔藓团 84px/s 三秒就能走 250px，
   于是"蓝色甲虫压着一团绿色苔藓"，看起来像一只长了两层壳的怪。

   做法是最轻的一种分离（boids 里的 separation）：
     · **只推同一层的**（脚底高度差 > 20 视为不同层，不干预）；
     · 需要分开到 `(w1+w2) * 0.46` —— 留 8% 重叠，贴死反而像连体；
     · **每帧推 55% 的缺口、上限 3.2px**。第一版给的是 28% / 1.6px，
       想着"温柔一点"，结果探针量到两只甲虫贴了 100 多帧没分开：
       它们自己以 1.67px/帧 走近，分离力只有 1.6px/帧 —— **正好抵消**，
       于是僵在原地互相顶着走，画面上就是两只叠在一起平移。
       推力必须明显大于走速，才叫"挤开"；3.2px 也不会突跳（一个身位 37）。
     · 推完的 x 会被 `roamL/roamR` 和两侧墙夹回去 —— 不能因为避让
       把怪推进箱子里（那比重叠更糟：下一帧它会卡在箱子里抽搐）。

   为什么不做真碰撞（互相挡路）：那会让"两只怪并排走"变得极难实现
   —— 一只停下另一只就堵，然后两只一起在狭窄处原地抖。
   分离力只在重叠时生效，不重叠时完全是零成本。 */
function separateFoes() {
  const list = S.foes;
  for (let i = 0; i < list.length; i++) {
    const a = list[i];
    if (a.dead) continue;
    for (let j = i + 1; j < list.length; j++) {
      const b = list[j];
      if (b.dead) continue;
      if (Math.abs((a.y + a.h) - (b.y + b.h)) > 20) continue;      // 不同层，不管
      const dx = (b.x + b.w / 2) - (a.x + a.w / 2);
      const ad = Math.abs(dx);
      const need = (a.w + b.w) * 0.46;
      if (ad >= need || ad < 0.01) continue;                       // 不重叠，零成本
      const push = Math.min((need - ad) * 0.55, 3.2);
      const dir = dx > 0 ? 1 : -1;
      const clampX = (f, nx) => {
        let v = Math.max(WALL_L, Math.min(WALL_R - f.w, nx));
        if (f.roamL != null && f.roamR != null) {
          v = Math.max(f.roamL, Math.min(f.roamR - f.w, v));
        }
        return v;
      };
      a.x = clampX(a, a.x - dir * push);
      b.x = clampX(b, b.x + dir * push);
    }
  }
}

function hurtPlayer() {
  S.hp--;
  S.invuln = NUM.hpInvuln;
  S.shake = Math.max(S.shake, 12);
  S.flash = Math.max(S.flash, 0.10);
  const p = S.p;
  p.vx = -p.face * 260;
  p.vy = -320;
  addText(p.x, p.y - 24, '-1', '#FF7E6E', 20, 0.8);
  if (S.hp <= 0) {
    // 不做死亡惩罚。缓一缓，原地满血，补一点弹 —— 卡关比失败更难受
    S.hp = NUM.hpStart;
    S.ammo = Math.min(NUM.ammoStart, S.ammo + 20);
    addText(W / 2, 220, '缓一缓 · 弹药补 20', '#9BE86E', 22, 1.6);
    S.flash = Math.max(S.flash, 0.2);
  }
}

/* ---------------------------------------------------------------- 雪之碎片 */
function stepShards(dt) {
  const p = S.p;
  for (const s of S.shards) {
    s.t += dt;
    s.vy = Math.min(s.vy + 1600 * dt, 900);
    s.y += s.vy * dt;
    const gy = groundAt(s.x, s.y) - 12;
    if (s.y > gy) { s.y = gy; s.vy = 0; }
    // 吸附
    const dx = (p.x + p.w / 2) - s.x, dy = (p.y + p.h / 2) - s.y;
    const d = Math.hypot(dx, dy);
    if (d < 90) { s.x += dx / d * 340 * dt; s.y += dy / d * 340 * dt; }
    if (d < 26) {
      s.dead = true;
      const add = Math.round(rnd(NUM.drop.shardAmmoMin, NUM.drop.shardAmmoMax));
      S.ammo = Math.min(NUM.ammoStart + 40, S.ammo + add);
      S.belly = Math.min(100, S.belly + NUM.bellyPerShard);
      addText(s.x, s.y - 12, '+' + add + ' 发', '#BFE8FF', 16, 0.9);
    }
  }
  S.shards = S.shards.filter(s => !s.dead);
}

/* ---------------------------------------------------------------- 箱子承重
   **砸掉下面一格，上面的必须塌下来。**
   不做这件事的话，玩家只要拆掉箱墙最下面一格，就能从 48px 的缝里钻过去 ——
   「砸开整面墙」立刻降级成「拆一块砖」，箱墙就不再是关卡结构了。
   顺带这也是"破坏场景"最直接的一眼反馈：整摞往下沉。 */
function stepBoxFall(dt) {
  // 从下往上处理，让链式承重一帧内算对
  const live = S.boxes.filter(b => !b.dead).sort((a, b) => b.y - a.y);
  for (const b of live) {
    let supported = false;
    /* 站在平台上？
       **容差必须是 +2 而不是 -1。** 填洞的盖板箱正好从平台边缘那一格开始
       （L3 的洞在 300，左平台到 300 结束），数学上是"刚好接触、零重叠"，
       `b.x >= s.x + s.w - 1` 会把它判成不支撑 —— 三口盖板箱于是全掉到中层，
       地表看起来是个凭空多出来的大坑。这个 bug 机器断言全绿、只有出图能看出来。 */
    for (const s of S.plats) {
      if (b.x + b.w <= s.x || b.x >= s.x + s.w) continue;
      if (Math.abs((b.y + b.h) - s.y) < 2.5) { supported = true; break; }
    }
    /* 站在别的箱子上？
       **这里的水平判定必须是严格重叠，不能给容差。** 给 2px 容差的后果：
       792 那列和 840 那列是肩并肩的（792+48 = 840），容差一开，它们就
       互认"我在你上面"，于是砸掉 840 的底座、上面那口会赖在 792 上不动，
       箱子塌落整个失效。接触和重叠是两件事，只有"夹住"那条可以认接触。 */
    if (!supported) {
      for (const o of live) {
        if (o === b) continue;
        if (b.x + b.w <= o.x || b.x >= o.x + o.w) continue;
        if (Math.abs((b.y + b.h) - o.y) < 2.5) { supported = true; break; }
      }
    }
    /* 嵌在洞里：**左右都被实心块夹住**才算支撑。
       填洞的盖板箱是"嵌"进去的，不是"站"在平台上 —— 它的箱底（528）
       和平台顶（480）根本不在同一高度，靠的是被两边的洞壁夹住。
       所以上面那两条（站在平台上 / 站在箱子上）对盖板全部失效，
       第一版没有这一条，三口盖板箱一开局就整排掉到中层，
       地表凭空多出一个大坑（机器断言全绿，只有出图能看出来）。

       **必须是"左 && 右"。** 写成"贴着一个就算"的话，竖直叠着的两块
       也会互相认作支撑 —— 砸掉 840 那列底下的冰墙，上面那口会赖在
       792 那列上不掉，箱子塌落这个设计就废了。

       **已经掉下来过的箱子不再认这一条。**（2026-10-28 加）
       这条规则的判据是"侧面有重叠"，所以一口箱子只要掉 12px，就会
       和刚才那个台子的**侧面**重叠上，然后被"夹"在半空不动 ——
       实测：砸掉地表最左边那口盖板，它上方压着的木箱掉到 304 就停住，
       又反过来给右边的盖板当了"左壁"，整排该塌的没塌。
       落过一次的箱子只认真正的顶面（平台顶 / 别的箱子顶），不再当门闩。 */
    if (!supported && !(b.fell > 0)) {
      let left = false, right = false;
      for (const o of solids()) {
        if (o === b) continue;
        const overlapY = Math.min(o.y + o.h, b.y + b.h) - Math.max(o.y, b.y);
        if (overlapY < -2) continue;                       // y 方向根本不挨着
        if (Math.abs(o.x + o.w - b.x) <= 2.5) left = true;
        if (Math.abs(b.x + b.w - o.x) <= 2.5) right = true;
      }
      if (left && right) supported = true;
    }
    if (!supported) {
      b.fell = (b.fell || 0) + dt;
      b.y += 900 * dt;
    } else if (b.fell) b.fell = 0;
  }
}

/* ---------------------------------------------------------------- 门 */
/** 门是不是还被箱子盖着。
    **这是「门藏在箱子里」的唯一实现**：不看任何标记位，直接问"门这块地方
    还有没有活着的箱子"。砸掉最后一口，函数自己就变 false，门露出来。
    比维护一个 hiddenBy 数组稳得多 —— 箱子会被塌落、会被连锁砸碎，
    引用很容易失效，坐标判定永远不会。 */
function doorBlocked() {
  const d = S.door;
  if (!d) return false;
  for (const b of S.boxes) {
    if (b.dead) continue;
    if (b.x + b.w <= d.x + 1 || b.x >= d.x + d.w - 1) continue;
    if (b.y + b.h <= d.y + 1 || b.y >= d.y + d.h - 1) continue;
    return true;
  }
  return false;
}

function checkDoor() {
  if (!S.door || S.door.open) return;
  if (S.killed >= S.killedTarget) {
    S.door.open = true;
    S.door.openT = 0;
    S.flash = Math.max(S.flash, 0.16);
    S.shake = Math.max(S.shake, 10);
    addText(S.door.x + S.door.w / 2, S.door.y - S.door.h - 16, '门开了', '#9BE86E', 24, 1.8);
  }
}

function stepDoor(dt) {
  const d = S.door;
  if (!d) return;

  /* 门刚露出来的那一帧，给一次闪光 + 飘字。
     「砸开最后一口箱、门出现在那里」这个瞬间就是这套设计要卖的惊喜，
     它必须有声音（这里是视觉）反馈，否则玩家会以为自己眼花了。 */
  const blocked = doorBlocked();
  if (d.wasBlocked === undefined) d.wasBlocked = blocked;
  if (d.wasBlocked && !blocked) {
    d.revealT = 0;
    S.flash = Math.max(S.flash, 0.18);
    S.shake = Math.max(S.shake, 8);
    addText(d.x + d.w / 2, d.y - d.h - 14, '找到门了', '#FFE08A', 24, 1.8);
    checkDoor();
  }
  d.wasBlocked = blocked;

  if (d.open) d.openT += dt;
  if (d.open && S.phase === 'play' && !blocked) {
    if (aabb(S.p, d)) {
      S.phase = 'clear';
      S.clearT = 0;
      S.flash = Math.max(S.flash, 0.3);
    }
  }
}

/* ---------------------------------------------------------------- 输入 */
function onKey(e, down) {
  const k = e.key;
  S.keys[k] = down;
  /* R 换一关（不是重开）。**布局是随机的，重开等于没有 R 键。** */
  if (down && (k === 'r' || k === 'R')) newLevel();
  if (down && (k === 'j' || k === 'J' || k === 'k' || k === 'K')) shoot();
  if ([' ', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].indexOf(k) >= 0) e.preventDefault();
}

/* ---------------------------------------------------------------- 井梯攀爬
   **光靠"跳"回不到上一层，得能"爬"。**
   上行通道是上一层地板上的那个洞，而洞是镂空的：玩家从井梯箱顶跳起来，
   脚越过上一层地板（144 + 123 = 267 > 240）之后落点正好在洞里，又原样
   掉回去 —— 实测"跳起来再按方向键"的 81 次里成功 7 次。那不是难度，
   是这个动作根本没做出来。

   井梯的视觉本来就是"井底竖着一把梯子"，那就按梯子处理：
   站在梯顶、头顶是敞开的洞口、按 W 就爬上去。
   盖板没砸开时爬不上去（洞口里还有箱子），正好复习一次"先砸开才能走"。 */
function wellClimb(p) {
  const L = S.level;
  if (!L) return null;
  /* **踩在球上时按 W 一律是跳，不给爬。**（2026-10-28 第三轮）
     井梯判据只看"脚离上层地板多远 + 人在不在洞口范围里"，
     而球的半径 22~46、球顶又会随球沉浮 —— 站在球上时很容易
     恰好落进这个窗口，于是按 W 不是起跳，是人被"搬"到井口另一侧。
     玩家看到的是「跳起来人往后走了一截」，实测复现。
     球顶本来就是个可以借高的台阶，这里该跳就跳。 */
  if (p.onBall) return null;
  const feet = p.y + p.h;
  for (let k = 1; k < L.floors.length; k++) {
    const upper = L.floors[k - 1];
    /* **符号别写反。** 玩家在下一层，脚在 upper 的"下面"，feet 比 upper 大。
       站 2 格时 feet - upper = 144；站 1 格时是 192，够不着，不给爬。
       （写成 upper - feet 的话恒为负，整段永远跳过 —— 白改一遍。）

       **窗口上限从 120 放宽到 160（2026-10-28 第二轮）。** 井梯从 3 格降到
       2 格之后，井梯顶离上层地板是 144，120 这个上限正好把"按 W 爬"这条
       路堵死了 —— 而那正是"不卡关"的保底。160 仍然拦得住"站在 1 格箱顶
       就想爬"（那是 192）。 */
    const d = feet - upper;
    if (d < -2 || d > 160) continue;
    const h = L.layers[k - 1].holes.filter(o => p.x + p.w > o.x + 6 && p.x < o.x + o.w - 6)[0];
    if (!h) continue;
    /* 洞口里还有活箱子 = 盖板没砸，爬不上去。 */
    if (S.boxes.some(b => !b.dead && b.x + b.w > h.x && b.x < h.x + h.w &&
        b.y + b.h > upper - 200 && b.y < upper + 4)) return null;
    const segs = L.layers[k - 1].segs;
    const onLeft = segs.some(s => s.x + s.w >= h.x - 2 && s.x < h.x);
    const onRight = segs.some(s => s.x <= h.x + h.w + 2 && s.x + s.w > h.x + h.w);
    const dl = (p.x + p.w) - h.x;              // 玩家离洞口左边多近
    const dr = (h.x + h.w) - p.x;              // 离右边多近

    /* **落点必须验，而且验不到就换一边、再不行就站箱顶。**
       踩到的实况：洞口左边那列的上层地面上正好摞着一口木箱，
       人爬到 63 号位、身体和木箱横向重叠 30px —— 紧接着的水平碰撞
       把人推到 `box.x + box.w = 96`，也就是**又推回洞口里**，然后原样掉下去。
       表现是"按 W 明明爬上去了，人却落回井底"，而且十个种子里有一半中招。

       兜底顺序：① 近的那边地面 → ② 远的那边地面 → ③ 洞口边那口箱子的顶上。
       ③ 不是妥协：洞口卡着一口箱子时，站到箱子上是玩家唯一合理的落点，
       而且箱子最高 3 格（144），站上去头顶还剩 14px，不会顶穿。 */
    const cands = [];
    if (onLeft) cands.push({ x: h.x - p.w - 3, d: dl });
    if (onRight) cands.push({ x: h.x + h.w + 3, d: dr });
    cands.sort((a, b) => a.d - b.d);
    for (const c of cands) {
      if (c.x < WALL_L || c.x + p.w > WALL_R) continue;
      if (!blockedAt(c.x, upper - p.h, p.w, p.h, null)) return { x: c.x, y: upper - p.h };
      for (const s of solids()) {
        if (s.kind === 'ramp') continue;
        if (s.y > upper + 2 || s.y < upper - 146) continue;
        if (c.x + p.w < s.x || c.x > s.x + s.w) continue;
        if (blockedAt(c.x, s.y - p.h, p.w, p.h, s)) continue;
        return { x: c.x, y: s.y - p.h };
      }
    }
  }
  return null;
}

/* ---------------------------------------------------------------- 主步进 */
function stepPlayer(dt) {
  const p = S.p;
  if (S.phase !== 'play') { p.vx = 0; return; }

  p.shotCd = Math.max(0, p.shotCd - dt);
  p.lockT = Math.max(0, p.lockT - dt);
  p.shotAnim = Math.max(0, p.shotAnim - dt);
  S.invuln = Math.max(0, S.invuln - dt);

  const K = S.keys;
  const left = K['a'] || K['A'] || K['ArrowLeft'];
  const right = K['d'] || K['D'] || K['ArrowRight'];

  /* 喷时锁移动。这一条让「喷」有成本 —— 没有它，玩家会站在原地
     把全场喷一遍再统一推球，两个动作就彻底脱钩了。 */
  if (p.lockT > 0) {
    p.vx = 0;
    p.runD = 0;
  } else {
    let ax = 0;
    if (left) ax -= 1;
    if (right) ax += 1;
    p.vx = ax * 300;
    if (ax !== 0) { p.face = ax; p.runD = Math.min(NUM.push.runFull, p.runD + 300 * dt); }
    else p.runD = Math.max(0, p.runD - 600 * dt);
  }

  /* ---- 跳 ----
     用户 2026-10-28（第二轮）：「注意处理的太直了吧　太陡」
     「宠物需要轻松的上下层跳动」。

     **三件事一起改：**

     ① **二段跳。** 层高 240、单跳 123 —— 一跳永远上不了上层。而井里
        能站的地方只有那摞 3 格箱子（144），从地面上去还得先找 2 格箱顶。
        二段跳把 240 跨过去：240 → 117 → −6（越过上层地板面 0）。
        层内二段跳会被净空（214）压住，最多到 151，比单跳只多 28 ——
        3 格箱山（144）依然要绕，"箱子是路"没被破坏。

     ② **地面按 W 就是跳，不再先试 `wellClimb` 的瞬移。** 原来站井梯顶
        按一下人就整个被搬到上一层，那不是跳，是电梯 —— 看不到上升过程，
        也学不会"这里能上去"。瞬移现在退到第三下（两次跳都用完还在空中
        时）当兜底，唯一作用是不卡关。

     ③ **按键必须判边沿。** `S.keys` 是"按住为真"的状态，写成 `&& K['w']`
        会在空中一路续跳（等于无限跳）。 */
  const wantJump = !!(K['w'] || K['W'] || K['ArrowUp'] || K[' ']);
  const jumpEdge = wantJump && !p.jumpHeld;
  p.jumpHeld = wantJump;

  if (jumpEdge && p.lockT <= 0) {
    if (p.onGround) {
      /* **站在井梯顶（离上层地板 ≤120）时按 W 仍然是"爬"，其余全是跳。**
         保留爬梯这一下不是偷懒：它是"不卡关"的保底 —— 洞口被箱子堵、
         起跳点被挤在斜角里跳不满高度时，还有一条确定的路。
         而只要不在梯顶（比如站在地面），按 W 就是实打实的跳 ——
         二段跳 + 翻越能自己上去，这才是用户要的「轻松的上下层跳动」。 */
      const cw = wellClimb(p);
      if (cw) {
        p.x = cw.x; p.y = cw.y; p.vx = 0; p.vy = 0; p.onGround = true;
        p.jumps = NUM.hero.airJump;
        once('well_climb', p.x + p.w / 2, p.y - 12, '爬上来了', '#CFEFFF');
      } else {
        p.vy = -NUM.hero.jump;
        p.onGround = false;
        p.jumps = NUM.hero.airJump;
      }
    } else if (p.jumps > 0) {
      /* 二段跳。**不改变水平速度** —— 空中变向会让"跳上井口边缘"
         变成一件靠微操的事，而这一步本来就该轻松。
         速度用 `airJumpV`（790 > 720），理由见 NUM.hero 的注释：
         楼板能跳上去之后，两跳的合计高度必须明显超过层高 240。 */
      p.vy = -NUM.hero.airJumpV;
      p.jumps -= 1;
    } else {
      /* 两次跳都用完还在空中，再按 W 才允许 `wellClimb` 接一把。
         此时人已经在上层楼板附近（它只认 `d ≤ 120`），补的是最后一截。 */
      const cw = wellClimb(p);
      if (cw) {
        p.x = cw.x; p.y = cw.y; p.vx = 0; p.vy = 0; p.onGround = true;
        p.jumps = NUM.hero.airJump;
        once('well_climb', p.x + p.w / 2, p.y - 12, '爬上来了', '#CFEFFF');
      }
    }
  }

  /* ---- 从楼板上下跳（2026-10-28 第四轮）----
     用户：「这个横梁我方是可以跳上去的　也可以下来」。
     上去是二段跳（楼板半透，见 stepBody），下来就是这里：
     **站在楼板上按 S / ↓ 就从板里穿下去。**

     为什么需要这个键 —— 楼板半透之后，人跳上去就再也下不来了：
     唯一的缺口是那个洞，而洞在几百像素之外。上去一次就下不来，
     玩家只会觉得"这游戏把人关在上面了"，比不能上更糟。

     判据里 `Math.abs(pl.y - feet) < 2` 是"脚下就是楼板顶面"；
     30 帧的窗口（0.20s）比"穿过 26px 厚楼板"需要的 0.16s 略长一点，
     短了会在板里被重新接住（表现为"按 S 只沉了半格"）。
     箱子顶不参与 —— 箱子是实心的，从箱子顶上下跳等于钻进箱子里。 */
  p.dropT = Math.max(0, p.dropT - dt);
  {
    const down = !!(K['s'] || K['S'] || K['ArrowDown']);
    if (down && !p.downHeld && p.onGround && p.dropT <= 0) {
      const feet = p.y + p.h;
      if (S.plats.some(pl => pl.floor && Math.abs(pl.y - feet) < 2 &&
          p.x + p.w > pl.x + 2 && p.x < pl.x + pl.w - 2)) {
        p.dropT = 0.20;
        p.onGround = false;
        p.vy = 60;                 // 给一点初速，第一帧就开始往下走
      }
    }
    p.downHeld = down;
  }

  const prevFeet = p.y + p.h;
  stepBody(p, dt);
  /* 落地回满空中跳次数。放在 stepBody 之后 —— `onGround` 是它写的。 */
  if (p.onGround) p.jumps = NUM.hero.airJump;

  /* ---- 洞口翻越 ----
     **"跳上去了"和"站得住"是两件事。** 二段跳能把脚送过上层地板面，
     但人还在洞口正上方：一松手就落回井里。原来只有 `wellClimb` 的瞬移
     能跨过这最后半步，而它只认"站在井梯顶"这一个站位 —— 换个起跳点
     按 W 完全没反应，这就是"跳不上去"的真实体感。

     这里补的是那半步：**这一帧脚下从楼板面下方穿到上方时**，把人横移到
     洞口外那侧的楼板顶上。判据用"穿过"而不是"接近" ——
     用接近的话，在楼板下面横着跑也会被翻上去。

     **不要求按方向键。** 洞口两边的楼板哪边近就往哪边翻（有按键则按键），
     否则"跳起来还得同时按住方向"这件事本身就不轻松。

     ---- 2026-10-28 第三轮：这一段曾经把普通跳跃整废了 ----
     用户原话：「现在跳起来 一起往后走　跳起来有问题」。

     第一版判据只写了"这一帧脚从 f 下方穿到 f 上方"，而**站在 f 这层地面上
     起跳的那一帧，prevFeet 恰好等于 f**（不是小于）—— 于是判据成立，
     人刚起跳就被横移 20px 并按回地面。实测：站在地面按 W+D，第一帧
     x 51 → 71、vy 0、onGround true，**一跳都跳不出去，人还往按键方向挪**。
     按 A 跳就是用户说的"跳起来一起往后走"。

     现在补三条前提，缺一不可：
       ① `prevFeet > f + 8`：脚原本确实在楼板面**下面**（站在这层起跳时
          prevFeet === f，差 0，被挡掉）；
       ② 人此刻水平方向**确实在洞口的范围内**：没有洞的地方头顶是实心
          楼板，stepBody 会挡住，根本穿不过去，也就不该翻；
       ③ 翻上去之后得真的更高（`gh < prevFeet - 4`）。 */
  if (!p.onGround && p.vy < -30) {
    const feet = p.y + p.h;
    for (let k = 0; k < FLOORS.length; k++) {
      const f = FLOORS[k];
      if (prevFeet <= f + 8) continue;         // ① 从下面上来的，不是站这层起跳
      if (feet > f + 6 || feet < f - 40) continue;
      /* ② 洞口。`LAYERS[k].holes` 就是 f 这层楼板上的洞。 */
      const holes = (LAYERS[k] && LAYERS[k].holes) || [];
      if (!holes.some(h => p.x + p.w > h.x - 6 && p.x < h.x + h.w + 6)) continue;
      const dirs = (left || right) ? [left ? -1 : 1] : [-1, 1];
      for (const dir of dirs) {
        for (const step of [20, 34, 48, 62, 78, 96, 112]) {
          const nx = p.x + dir * step;
          if (nx < WALL_L || nx + p.w > WALL_R) continue;
          if (blockedAt(nx, f - p.h, p.w, p.h, null)) continue;
          /* **落点不一定是楼板，也可能是箱子顶。** 只要它在上层地板面
             往上 96 以内（`f-96` ~ `f+2`），人就确实上到那一层了。
             只认楼板的话，洞口旁边那摞箱子会把"已经成功"判成失败。 */
          const gh = groundAt(nx + p.w / 2, f - 1);
          if (gh < f - 96 || gh > f + 2) continue;
          if (gh >= prevFeet - 4) continue;      // ③ 翻过去得更低，不是原地
          p.x = nx; p.y = gh - p.h; p.vx = 0; p.vy = 0; p.onGround = true;
          p.jumps = NUM.hero.airJump;
          break;
        }
        if (p.onGround) break;
      }
      if (p.onGround) break;
    }
  }

  /* ---- 踩球（2026-10-28 第三轮）----
     用户原话：「没办法站在球上」。

     查下来不是 bug，是**从来没做过**：`solids()` 只返回平台和箱子，
     球根本不在碰撞世界里 —— 球顶对玩家来说是一层空气，人穿过去继续落地。
     而"跳上球、踩球借高"恰恰是雪人兄弟里唯一的垂直机动手段。

     三个细节，都是踩上去好不好用的关键：
       ① **只在"从上方落下来"时接住**（`prevFeet <= 球顶 + 10`）。
          不加这条，人从球下方走过、球从人身上飞过时都会被吸到顶上；
       ② **上升中不接**（`vy < 0`）：起跳穿过球体不该被粘住 ——
          那会让"从球旁边跳过去"变成一件做不到的事；
       ③ **水平对准球心 ±(r−4) 才踩得稳**，边缘踩空就掉下去。
          判据用球心而不是包围盒：圆的东西用盒子量，角落会站得住，
          视觉上就是"站在空气上"。 */
  p.onBall = null;
  {
    const feetNow = p.y + p.h;
    for (const b of S.balls) {
      if (b.dead) continue;
      const top = b.y - b.r;
      const cx = p.x + p.w / 2;
      if (cx < b.x - b.r + 4 || cx > b.x + b.r - 4) continue;
      if (p.vy < 0) continue;
      if (prevFeet > top + 10) continue;
      if (feetNow < top - 3) continue;
      /* **头顶塞不下就别踩。** 球顶是"人凭空被抬高 2r"，而这块地方的
         天花板高度是按"人站在地面上"留的 —— 在低矮处（比如紧贴上层
         楼板或箱子下沿）球顶会把人顶进天花板里。踩上去的结果是
         一起跳就撞头，人被压回原高度，看起来像"跳不动"。
         这里直接放弃接住：人落回地面，球从身上滚过去，读起来清楚。 */
      if (blockedAt(p.x, top - p.h, p.w, p.h, null)) continue;
      p.y = top - p.h; p.vy = 0; p.onGround = true;
      p.jumps = NUM.hero.airJump;
      p.onBall = b;
      /* **踩住就把球压慢。** 不压的话 620px/s 的球一踩就窜出去，
         人站在原地看球跑 —— 那不是"站上去"，是"被弹开"。压到 35%
         之后球滚三五步就停，站在上面能看清自己站在哪。 */
      if (Math.abs(b.vx) > 40) b.vx *= 0.35;
      /* 球滚人也跟着滚。**球动人不跟 = 球从脚下滑走**，看起来像是
         人站在冰面上被抽走了毯子。 */
      p.x = clamp(p.x + b.vx * dt, WALL_L, WALL_R - p.w);
      break;
    }
  }

  p.anim += dt;
}

/* ---------------------------------------------------------------- 镜头
   **纵向按层吸附 —— 层内一格都不跟。**

   原来是 `玩家中心 − 300` 每帧缓动。站着不动时它是稳的，可是上坡、
   下坡、起跳、下落的时候整个画面会跟着上下挪。探针量出来的数字：
   **原地跳一次画面晃 19px，走一段平路晃 11px。** 用户说的"抖动很明显"，
   一大半是它，跟"怪物只能横向走"没关系。

   改成：镜头的目标只由**玩家站在哪一层上**决定，而且只有"已经落地 +
   脚离某层地板 60px 以内"时才换层。于是
     · 走平路 / 上坡 / 下坡 / 跳跃 / 下落 —— 画面一动不动；
     · 真的换了一层，才用 7/s 缓过去（那是"换层"，不是抖）。
   站在箱堆顶上落地**不算**换层（脚离地板 144，哪层都够不着），
   否则爬到箱山半腰画面就跳一层，比原来的抖还难受。 */
function camViewOffset() { return (GEN.floorH - GEN.thick) / 2 + H / 2; }

function camGoalFloor() {
  const p = S.p, feet = p.y + p.h;
  /* 兜底：真的掉到画面下沿之外了才强行跟 —— 宁可晃一下，也不能把人留在屏幕外。
     **判据是"脚下最近的那层地板"，不是"脚上方最后一层"。**
     原来写 `FLOORS[k] <= feet`，站在 48px 高的箱子上（脚在 1252、本层地板 1300）
     就会算成**上一层**（1060）—— 镜头直接跳高一层，玩家在画面下沿外只露个头。 */
  if (feet > S.cam.y + H - 30) {
    let best = FLOORS.length - 1;
    for (let k = 0; k < FLOORS.length; k++) {
      if (FLOORS[k] >= feet - 8) { best = k; break; }
    }
    return best;
  }
  if (!p.onGround) return -1;
  for (let k = 0; k < FLOORS.length; k++) if (Math.abs(feet - FLOORS[k]) < 60) return k;
  return -1;
}

function updateCamera(dt) {
  const k = camGoalFloor();
  if (k >= 0) S.cam.k = k;
  const target = clamp(FLOORS[Math.min(S.cam.k, FLOORS.length - 1)] - camViewOffset(), 0, WORLD_H - H);
  S.cam.y += (target - S.cam.y) * Math.min(1, 7 * dt);
  if (Math.abs(target - S.cam.y) < 0.5) S.cam.y = target;
}

function step(dt) {
  dt = Math.min(dt, 1 / 30);
  if (S.hitStop > 0) { S.hitStop = Math.max(0, S.hitStop - dt); S.t += dt * 0.25; return; }

  S.t += dt;
  /* **指数衰减，不是线性。** 线性的毛病在尾段：从 14 掉到 1 和从 1 掉到 0
     用的时间一样长，最后那一下是"匀速停下"，读起来是机械。
     指数是先猛后缓 —— 撞上去那一下最重，然后迅速收住，
     和真实的震动一致。低于 0.4 直接归零，不拖看不见的尾巴。 */
  S.shake = S.shake > 0.4 ? S.shake * Math.exp(-7.5 * dt) : 0;
  if (S.shake === 0) { S.shakeDX = 0; S.shakeDY = 0; }
  S.flash = Math.max(0, S.flash - 2.4 * dt);

  stepPlayer(dt);
  stepNests(dt);
  stepFoes(dt);
  stepEBullets(dt);
  stepShots(dt);
  pushBalls(dt);
  stepBalls(dt);
  stepBoxFall(dt);
  stepShards(dt);
  stepDoor(dt);

  updateCamera(dt);

  if (S.phase === 'clear') S.clearT += dt;

  // 粒子与飘字
  for (const f of S.frags) {
    f.t += dt; f.x += f.vx * dt; f.y += f.vy * dt; f.vy += 900 * dt;
    f.rot += f.vr * dt;
  }
  S.frags = S.frags.filter(f => f.t < f.life).slice(-400);
  for (const r of S.rings) {
    r.t += dt;
    /* **t 可以是负数 = 延迟出生。** 第二圈故意晚 50ms 出现，
       两圈错开才有"冲击波"的层次；但进度必须夹住，
       负数传进去会把半径算成负的，canvas 直接抛 IndexSizeError。 */
    r.r = r.r0 + (r.r1 - r.r0) * clamp(r.t / r.life, 0, 1);
  }
  S.rings = S.rings.filter(r => r.t < r.life);
  for (const t of S.texts) { t.t += dt; t.y -= 26 * dt; }
  S.texts = S.texts.filter(t => t.t < t.life);
}

/* =========================================================================
   渲染
   ========================================================================= */
const COL = {
  /* ---- Q 版卡通的着色逻辑 ----
     和"低饱和 + 暗角"的写实路子相反：底色要**亮**，对比靠**深色粗描边**拉。
     整套色只守两条：
       ① 每个面都比自己的描边亮两档以上，不然描边会糊进色块里
       ② 明度顺序固定：地面 > 墙面 > 天花板，让"上 / 下"一眼读得出来
     描边统一用**暖褐**而不是纯黑 —— 纯黑在卡通里显脏，暖褐才像手绘。 */
  ink: '#4A3A2C',
  inkSoft: 'rgba(74,58,44,.30)',

  /* ---- 地表：寒地雪原 ----
     整套色的分工只有一条：**外面冷、里面暖**。天空与雪原全用青蓝，
     木箱与墙全用暖黄，两者在地表那条板线上交接。
     上一版是绿草丘 + 蓝天白云 —— 那是"免费素材卡通"的默认长相：
     看不出地点、看不出时间，也读不出和地下那些暖木箱是同一个世界。 */
  sky: ['#5E9BC4', '#9CCDE4', '#D3E9F4', '#EFE3D2'],
  snowFar: '#AECDE0', snowMid: '#C9E0EC', snowNear: '#E9F4FA',
  pine: '#54727C',

  /* ---- 主角的四个色阶 ----
     **一个色相要铺成四档才叫"体积"，两档只能叫"明暗"。**
     catLight 走高光，catShade 走远侧/底面。

     **色号是照立绘抄的，不是自己调的**（`art/03-candidate/01-pets/sugar-stand@v1.png`）。
     2026-10-28 之前这里是 '#FFA85C' 深橙 —— 那是另画的一只橙猫，
     和主界面里正在用的「砂糖」不是同一只：立绘是**奶油米黄**的短毛猫，
     战斗里换成深橙之后，同一只宠物在家和在路上是两个颜色。
     立绘在 `assets/ui/home/pets/` 里一直是用着的，断掉的只有战斗这一个环节。 */
  cat: '#F7D7A4', catDark: '#D9A868', catLight: '#FFF2DE', catShade: '#B98A55',
  /* 立绘身上那三样"一眼认出是谁"的东西，单独给色：
     绿松领巾、粉色内耳、奶白脚掌。少了它们，奶油色的猫和奶油色的雪会糊在一起。 */
  scarf: '#7FB896', scarfDark: '#5C9673', earIn: '#E8A08A',
  paw: '#FFF4E4', pawDark: '#F0DFC4',

  wood: '#E0A96D', woodDark: '#B77F44', woodTop: '#F8DFB6', woodInk: '#7A5127',
  stone: '#B9A992', stoneDark: '#94856F', stoneInk: '#6E655C',
  iron: '#9FB0BE', ironLit: '#C6D5E1', ironInk: '#5E6E7C',
  ice: 'rgba(168,228,248,.88)', iceEdge: '#E4F8FF', iceInk: '#4E9CC4',
  loot: '#FFD45E', lootInk: '#A8761F',
  snow: '#F4FAFE',
  door: '#7FD8A8', doorInk: '#2F7A5A', doorLock: '#E8564C',
};

/* ---------------------------------------------------------------- 角色尺度
   **这一组数字决定"画面里的东西有多大"，是 2026-10-28 那一轮的落点。**

   原来玩家只有 30×42 —— 屏幕上 600 高，角色占 **7%**。比木箱（48）还矮，
   读起来就是"小矮人站在一堆大箱子里"。用户的原话是"立绘精致""战斗空间合理"，
   但这两件事卡在同一个前提上：**尺寸不够，细节就全被像素吃掉。**
   实测（client/art/02-concept/03-battle-target/立绘-30px实测对比.png）：
   立绘缩到 30px 时，草叶、牙齿、冰棱全部糊掉，"精致"无从谈起。

   所以先把尺度提到 1.5 倍。三条一起改，缺一条就会露馅：

     ① **形象**（`ART_K`）—— 绘制函数里全是 `by - 33` 这种硬编码坐标，
        按 30×42 的手画比例铺的。不去逐个重写，而是在脚底中心套一个 1.5 倍
        缩放：矢量重绘，不会糊，而且改比例只要动一个数。
     ② **碰撞框**（`PLAYER_W/H`、`FOE_W/H`）—— **必须和形象同步放大**。
        只放大形象、不动碰撞框，就是"看着能挤过去、其实过不去"，
        踩在箱沿上也会莫名掉下去 —— 那正是用户说的"空间不合理"。
     ③ **关卡里的空当** —— 洞最窄 96、走廊门槛 `46 + speed*0.5`，
        45 宽的角色都还有余量；净空 214 对 63 高的角色也够（详见断言）。

   形象比碰撞框高一点（72 vs 63），是**故意的**：头顶的呆毛、耳朵本来就该
   允许穿进天花板一点点，卡死反而显得僵。原来也是这个比例（48 vs 42）。 */
const ART_K = 1.5;
/* **宽 ≤ 箱宽、高 ≥ 箱高，两个都要。**（2026-10-29 用户提出第 4 条）
   用户原话：「我方宠物大小 比箱子大 没办法独立站一个箱子的空格？」

   一量就清楚了 —— 碰撞盒 45 本来是能站的（45 < 48 箱宽），但**贴图实际
   画出来 68.7 宽**，是箱宽的 1.43 倍。所以是"看着站不进去"，
   不是"真的站不进去"。根因是上一轮把 `PET_VIS_K` 提到 1.0 时只对齐了
   **高度**（体高 = 碰撞高），**宽度没人管**：cat.png 宽高比 0.716，
   体高一撑到 63，视觉宽就跟着到 68.7。

   **不能靠降碰撞高来解决。** 试过 63 → 55（视觉 46.3 宽、53.1 高，
   两条都成立，碰撞和视觉只差 2px），但一跑断言就掉三条：
   比箱高 1.15、高度 ≥ 56 承载立绘细节、占屏 10.5% ——
   那三条是"角色别缩回去变小"的红线，缩宽度不能拿高度去换。

   所以反过来：**高度守住 63，只压视觉宽度**。要视觉 ≤ 48（= 一箱宽），
   图高 = 48/0.716 = 67，对应 VIS = 67×0.656/63 = 0.70。
   验证：视觉 48.1 宽 / 55.2 高（含耳），箱 48 —— 宽刚好一格，高 1.15 格。
   代价是碰撞顶比耳朵尖高 7.8px，跳起来会"没碰到就弹下来"。
   这 7.8px 只能认：0.716 的宽高比决定了"宽进一格"和"碰撞=视觉"不可兼得，
   而宁可空一点碰撞，也不要角色缩成一小团。 */
const PLAYER_W = 45, PLAYER_H = 63;

/* ---- 敌人：**不跟玩家共用系数** -------------------------------------------
   **这一条是 2026-10-28 晚补的，因为一刀切把尺寸层次压塌了。**
   第一版让敌人一起乘 `ART_K`（34×30 → 51×45），结果出图一看，
   蓝色霜甲虫和木箱（48）几乎一样宽、红色尖牙兽比两个箱子还长 ——
   读起来不是"小兵"，是"和箱子同级的障碍物"。用户的原话：
   「敌方体态都超过了箱子 是不是不太好」。

   根子是把一个统一系数套到了所有东西上。**三者的尺寸是三个独立问题：**

     箱子 48  —— 地形单位，关卡按 48 一格生成，**永远不动**
     玩家 45×63 —— 主角，要撑得住细节，比箱子窄、比箱子高
     敌人 37×33 —— 小兵，**必须明显小于箱子**，才读得出"可以踩/可以打"

   所以敌人单独一个 `FOE_K = 1.1`：比放大前（34×30）大一点点找回细节，
   但 37/48 = 0.77，离箱子还差一格，层次保住了。
   想再调只动这一个数，别去动 `ART_K` —— 那是玩家的。 */
const FOE_K = 1.1;
const FOE_W = 37, FOE_H = 33;

/* 每层的"房间主题"。**换主题不只是换颜色 —— 形状语言也换**：
   木板是竖条、砖是错缝、石头是圆块、地窖是拱形壁龛。
   顺序是"越来越往里"：天空 → 木屋 → 砖房 → 石洞 → 地窖。
   这比单纯把颜色调暗更能传达"我又下了一层"。 */
const ROOM = [
  null,
  { key: 'wood',  bg1: '#F9E0B8', bg2: '#E8C79A', line: '#C99B66' },
  { key: 'brick', bg1: '#F7D2C8', bg2: '#E3B0A4', line: '#C18D7F' },
  { key: 'rock',  bg1: '#E4DACC', bg2: '#CCBEAD', line: '#A6947F' },
  { key: 'vault', bg1: '#DED2E8', bg2: '#C4B4D6', line: '#9E8CB2' },
];
const roomOf = k => ROOM[clamp(k, 1, ROOM.length - 1)];

/* 一面墙。**纹理必须每帧一模一样** —— 用坐标当种子、不开 Math.random，
   否则砖缝和木纹会在屏幕上抖（和岩体那次的教训同一条）。 */
function drawRoomWall(g, k, cY, fY) {
  const r = roomOf(k);
  const h = fY - cY;
  if (h <= 0) return;

  /* ================= 房间是个盒子，不是一块墙纸 =================
     原来是 WALL_L..WALL_R 铺满一整块，纹理一直画到边上。
     出图上的结果是"一张壁纸贴在屏幕后面"：没有进深、没有角落，
     墙上挂的每件东西都像贴纸（用户 2026-10-28：「就是个图贴上去」）。
     现在按盒子来画：
       ① 整幅先铺房间的底色（原来外侧是裸露的世界底色，一圈深棕框）；
       ② 左右两条**侧墙**，垂直板缝向内角**压缩**（等距缝读不出透视）；
       ③ 后墙内收 DI 之后画纹理；
       ④ 内角一条亮缝 + 一道 AO 暗边 —— "内角亮、拐角暗"是画盒子最省的两笔；
       ⑤ 后墙整体压一层极淡的暖灰（空气透视），和前景的箱子拉开对比度。
     DI 定 54：小于 40 读不出透视，大于 70 会吃掉一整列箱子（列宽 48）。 */
  const DI = 54, DY = 11;
  const BX0 = WALL_L + DI, BX1 = WALL_R - DI;
  const BCY = cY + DY;

  const bg = g.createLinearGradient(0, cY, 0, fY);
  bg.addColorStop(0, r.bg1);
  bg.addColorStop(1, r.bg2);
  g.fillStyle = bg;
  g.fillRect(0, cY, W, h);

  /* ---- ② 侧墙 ----
     **材质必须跟着房间主题走。** 木屋画竖板缝，砖房画横砖缝 ——
     第一版所有房间都画竖板缝，出图上砖房的墙角变成"一截木板接在砖墙上"，
     等于当场把"这是同一间屋子"这件事打掉。
     木屋的竖缝位置按 1-(1-t)^1.55 分布，**越靠内角越密**。
     方向反了（越靠内角越疏）看起来像"墙越往里越宽"，比等距更假 ——
     等距至少读作"栅栏"，反着的透视读作"画错了"。 */
  /* 消失点。**镜头停在这一层时，正好落在房间的竖直中线上** ——
     camViewOffset() 把 FLOORS[k]-214..FLOORS[k] 这段居中在屏幕 300，
     所以这里直接用房间中点，不必读 S.cam.y：镜头平移时几何关系不跟着抖。
     SIDE_K 是"前框相对后墙的放大比"（近大远小）。1.22 是能看出收敛、
     又不会让最上面那两道砖缝提前冲出天花板的档位。 */
  const vpY = (cY + fY) / 2;
  const SIDE_K = 1.22;
  const fanY = yy => vpY + (yy - vpY) * SIDE_K;

  for (const side of [0, 1]) {
    const xc = side ? BX1 : BX0;
    const xe = side ? W : 0;
    const span = Math.abs(xc - xe);
    const x0 = Math.min(xe, xc);
    g.save();
    g.beginPath(); g.rect(x0, cY, span, h); g.clip();
    if (r.key === 'wood') {
      for (let i = 1; i <= 7; i++) {
        const px = xe + (xc - xe) * (1 - Math.pow(1 - i / 8, 1.55));
        g.strokeStyle = 'rgba(58,40,24,.28)'; g.lineWidth = 1.5;
        g.beginPath(); g.moveTo(px, cY); g.lineTo(px, fY); g.stroke();
        g.strokeStyle = 'rgba(255,244,222,.09)';
        g.beginPath(); g.moveTo(px + 1.6, cY); g.lineTo(px + 1.6, fY); g.stroke();
      }
    } else if (r.key === 'brick') {
      /* 砖房画**朝消失点收的横砖缝**，不画竖缝（78px 宽的侧墙上排竖缝只是格子纸）。
         两个讲究：
         ① 起始相位和后墙一致（都是 cY-42 起步、步长 42），墙角两侧的缝
            在 BX 处**接得上** —— 这一笔比任何描边都更能说明"墙拐过去了"；
         ② 缝必须斜，不能是平行横线。平行横线读作"砖缝画歪了"，
            斜线才读作"这条缝顺着墙往后退"。 */
      for (let yy = cY - 42; yy < fY + 42; yy += 42) {
        const yf = fanY(yy);
        g.strokeStyle = 'rgba(60,40,26,.22)'; g.lineWidth = 1.4;
        g.beginPath(); g.moveTo(xc, yy); g.lineTo(xe, yf); g.stroke();
        g.strokeStyle = 'rgba(255,246,228,.08)';
        g.beginPath(); g.moveTo(xc, yy + 1.6); g.lineTo(xe, yf + 1.6); g.stroke();
      }
    } else if (r.key === 'rock') {
      /* 石头房两道顺墙延伸的裂缝。同样必须朝消失点收 ——
         石墙上的平行横线会被读成"砖缝"，和石头对不上。 */
      for (let i = 0; i < 2; i++) {
        const yy = cY + h * (0.34 + i * 0.34) + ((k * 37 + i * 61) % 15);
        const yf = fanY(yy);
        g.strokeStyle = 'rgba(44,31,20,.34)'; g.lineWidth = 2.2;
        g.beginPath(); g.moveTo(xc, yy);
        g.quadraticCurveTo((xc + xe) / 2, (yy + yf) / 2 + 5, xe, yf);
        g.stroke();
      }
    }
    /* AO：两面墙的夹角本来就照不到光。靠屏幕边缘那头也压暗一档 ——
       侧墙是"斜着被看到"的，落到它上面的光本来就比后墙少。 */
    const ao = g.createLinearGradient(xe, 0, xc, 0);
    ao.addColorStop(0, 'rgba(44,29,17,.34)');
    ao.addColorStop(0.55, 'rgba(44,29,17,.17)');
    ao.addColorStop(1, 'rgba(34,22,12,.62)');
    g.fillStyle = ao;
    g.fillRect(x0, cY, span, h);
    g.restore();
  }

  /* ---- ③ 后墙 ---- */
  g.save();
  g.beginPath(); g.rect(BX0, BCY, BX1 - BX0, fY - BCY); g.clip();

  if (r.key === 'wood') {
    /* 竖木板，每 64 一条，板缝 3px。**钉子画在板的两端** ——
       这一笔几乎没成本，但"钉住的板"和"一块纯色"是两种画面。 */
    for (let x = WALL_L; x < WALL_R; x += 64) {
      g.fillStyle = 'rgba(255,255,255,.14)';
      g.fillRect(x + 1, cY, 60, h);
      g.fillStyle = r.line;
      g.fillRect(x + 61, cY, 3, h);
      g.strokeStyle = 'rgba(150,110,70,.20)';
      g.lineWidth = 1.5;
      for (let j = 0; j < 3; j++) {
        const yy = cY + 24 + ((x * 7 + j * 97 + k * 31) % Math.max(24, h - 48));
        g.beginPath();
        g.moveTo(x + 7, yy);
        g.bezierCurveTo(x + 22, yy - 5, x + 40, yy + 5, x + 57, yy - 2);
        g.stroke();
      }
      g.fillStyle = 'rgba(120,88,54,.32)';
      g.beginPath(); g.arc(x + 31, cY + 15, 1.8, 0, Math.PI * 2); g.fill();
    }
  } else if (r.key === 'brick') {
    /* 错缝砖。**缝必须错开** —— 对齐的砖格会读成"方格纸"，不是砖墙。 */
    const BW = 84, BH = 42;
    g.fillStyle = r.line;
    g.fillRect(WALL_L, cY, WALL_R - WALL_L, h);
    for (let row = 0, yy = cY - BH; yy < fY + BH; row++, yy += BH) {
      const off = (row % 2) * (BW / 2);
      for (let x = WALL_L - BW; x < WALL_R + BW; x += BW) {
        const bx = x + off;
        g.fillStyle = row % 3 === 0 ? 'rgba(255,255,255,.16)' : 'rgba(255,255,255,.08)';
        g.fillRect(bx + 3, yy + 3, BW - 6, BH - 6);
        g.fillStyle = 'rgba(255,255,255,.20)';
        g.fillRect(bx + 3, yy + 3, BW - 6, 3);
      }
    }
  } else if (r.key === 'rock') {
    // 圆石：抖过顶点的不规则块。**不用正圆** —— 正圆读作"污渍"
    for (let i = 0; i < 30; i++) {
      const bx = WALL_L + ((i * 137) % (WALL_R - WALL_L));
      const by = cY + ((i * 211 + k * 53) % Math.max(30, h));
      const bw = 44 + ((i * 61) % 76);
      const bh = 28 + ((i * 43) % 46);
      g.fillStyle = i % 3 === 0 ? 'rgba(255,255,255,.20)' : 'rgba(120,102,84,.10)';
      g.beginPath();
      for (let v = 0; v < 8; v++) {
        const a = v / 8 * Math.PI * 2;
        const wob = 0.66 + 0.34 * Math.abs(Math.sin(v * 3.1 + i));
        const px = bx + Math.cos(a) * bw / 2 * wob;
        const py = by + Math.sin(a) * bh / 2 * wob;
        if (v === 0) g.moveTo(px, py); else g.lineTo(px, py);
      }
      g.closePath(); g.fill();
    }
  } else {
    // 拱形壁龛：一排矮拱。地窖靠"重复的拱"和其他墙区分开
    for (let x = WALL_L + 24; x < WALL_R - 80; x += 152) {
      const bw = 66, bh = Math.min(130, h * 0.6);
      g.fillStyle = 'rgba(78,56,96,.12)';
      g.beginPath();
      g.moveTo(x, fY - 6);
      g.lineTo(x, cY + h - bh);
      g.arc(x + bw / 2, cY + h - bh, bw / 2, Math.PI, 0);
      g.lineTo(x + bw, fY - 6);
      g.closePath(); g.fill();
      g.strokeStyle = 'rgba(78,56,96,.16)';
      g.lineWidth = 3; g.stroke();
    }
  }

  /* 上下两道明暗：天花板背光、地面反光。
     **必须压在纹理之上** —— 否则纹理把明暗关系盖掉，"上下"又读不出来了。
     天花板那一段从 .26 加到 .34、范围从 24% 拉到 30%：木屋和砖房的墙本身是亮米色，
     原来的暗压根本压不住，挂灯的光晕等于打在一块白纸上 —— 看不出"亮"。
     压暗之后同一盏灯的亮度差才成立，房间的"上暗下亮"也才读得出来。 */
  const shade = g.createLinearGradient(0, BCY, 0, fY);
  shade.addColorStop(0, 'rgba(70,46,26,.34)');
  shade.addColorStop(0.14, 'rgba(70,46,26,.18)');
  shade.addColorStop(0.30, 'rgba(70,46,26,.02)');
  shade.addColorStop(0.84, 'rgba(255,250,238,.12)');
  shade.addColorStop(1, 'rgba(255,250,238,.24)');
  g.fillStyle = shade;
  g.fillRect(BX0, BCY, BX1 - BX0, fY - BCY);

  /* ---- ⑤ 空气透视 ----
     **往后退的东西不能和前景一个对比度。** 箱子和玩家的颜色原封不动，
     后墙只降一档，前后就分开了 —— 这比"糊一层黑"干净，也不会把木色压脏。 */
  g.fillStyle = 'rgba(230,219,199,.10)';
  g.fillRect(BX0, BCY, BX1 - BX0, fY - BCY);
  g.restore();

  /* ---- ④ 内角亮缝 ----
     侧墙压暗之后后墙那头就"亮"了，但只靠明暗对比还不够硬 —— 墙角要有一条真缝。
     **上淡下亮**：地面反光照在墙角的下半截。画在两侧墙之外会被后墙盖住，
     所以必须在 restore 之后画。 */
  for (const bx of [BX0, BX1]) {
    const cg = g.createLinearGradient(0, BCY, 0, fY);
    cg.addColorStop(0, 'rgba(255,246,226,.07)');
    cg.addColorStop(0.50, 'rgba(255,246,226,.20)');
    cg.addColorStop(1, 'rgba(255,250,236,.42)');
    g.fillStyle = cg;
    g.fillRect(bx - 1.6, BCY, 3.2, fY - BCY);
  }

  /* ---- ⑥ 天花板背光 ----
     一条横向的渐变压暗，**横跨整幅** —— 只压后墙的话，两块侧墙的顶上是亮的，
     天花板就"飞"起来了。用渐变而不是硬边的一条黑带：硬边读成"又一根横梁"。 */
  const cap = g.createLinearGradient(0, cY, 0, cY + 16);
  cap.addColorStop(0, 'rgba(52,35,21,.46)');
  cap.addColorStop(0.60, 'rgba(52,35,21,.18)');
  cap.addColorStop(1, 'rgba(52,35,21,0)');
  g.fillStyle = cap;
  g.fillRect(0, cY, W, 16);

  /* ---- ⑦ 侧墙脚下的地面反光 ----
     后墙那段在 shade 里已经有了，这里只补两侧 —— 补满整幅会把后墙下沿再提亮一遍。 */
  for (const x0 of [0, BX1]) {
    const w0 = x0 === 0 ? BX0 : W - BX1;
    const bot = g.createLinearGradient(0, fY - 30, 0, fY);
    bot.addColorStop(0, 'rgba(255,250,238,0)');
    bot.addColorStop(1, 'rgba(255,250,238,.16)');
    g.fillStyle = bot;
    g.fillRect(x0, fY - 30, w0, 30);
  }
}

/* ---- 背景立绘 ----
   地表天空现在是一张 960×340 的厚涂条，base64 内嵌在 `#art-bg` 里。
   **必须有程序化回退**：断言和出图工具跑在 jsdom 里，没有 <img> 解码，
   `BG_IMG` 永远是 null —— 少了回退，那些工具会画出一片空白天空，
   然后把"工具环境不支持"误判成"背景坏了"。
   为什么内嵌不外链：preview 的静态服务只给这一个文件，兄弟图片 404
   之后静默回退，看起来像"改了没生效"，这类静默失败最难查。 */
let BG_IMG = null;
function snowlabInitBackdrop() {
  if (typeof Image === "undefined") return;
  const src = (INLINE_ART["bg"] || "").trim();
  if (!src) return;
  const im = new Image();
  im.onload = () => { BG_IMG = im; };
  im.onerror = () => { BG_IMG = null; };
  im.src = src;
}

/* ---- 宠物贴图（可选；没有就走下面的代码图形） ----
   **主角不是这里画的，是 `assets/resources/grove/pet/cat.png` 那张图。**
   2026-10-28 晚用户提醒：「之前是雪人关卡那个，单位也是侧着施法的，
   pet 资源以前在这」。确实 —— 那批图（六只，统一高 292）是美术管道从
   `ui/home/` 的立绘收缩出来的**游戏内版本**，`GroveBattle.ts` 的
   `ART_MANIFEST` 里一直挂着 `pet-<id>`，雪人关卡（grove.html）就在贴。
   侧视、能施法、和主界面是同一只 —— 这三件事它本来就满足。

   所以这里的规矩照抄 grove：**有贴图贴图，没有才走代码图形**。
   代码那套不退场，它是回退路径（jsdom 出图、贴图加载失败、以后换角色没出图时）。
   注入键沿用 `pet-<id>`，和 GroveBattle 的 ART_MANIFEST 是同一套名字。 */
const ART = Object.create(null);
function artOf(key) { return ART[key] || null; }

/* ---- 内嵌角色贴图：**浏览器里也要有贴图** ----
   上面 `#art-bg` 那套只解决了背景。角色贴图原来只有出图工具会注入
   （`setArt`），于是出现了最难解释的一种不一致：**评审图上是我画的贴图版，
   用户双击打开看到的还是代码图形的小猫**。两边都没报错，只是长得不一样。

   现在角色贴图同样内嵌（`tools/_inline-art.js` 生成，`#art-pet-cat` 那一批），
   加载完就覆盖代码图形；加载不上就保持代码图形 —— 回退路径一条没少。
   内嵌块是生成物，`_snowlab-check.js` 里有一条按 sha256 比对"内嵌字节 vs
   磁盘 png"，改了图忘了重跑工具会当场变红。 */
const ART_KEYS = ['pet-cat', 'foe-moss', 'foe-fang', 'foe-grub'];
function snowlabInitArt() {
  if (typeof Image === 'undefined') return;
  for (const k of ART_KEYS) {
    const src = (INLINE_ART[k] || '').trim();
    if (!src) continue;
    const im = new Image();
    im.onload = () => { ART[k] = im; };
    im.onerror = () => { /* 静默保持代码图形：这条路径本来就是兜底 */ };
    im.src = src;
  }
}

/* ================= 地表：寒地雪原 =================
   这一层负责回答"这是哪儿"。规矩就一条 —— **外面冷、里面暖**：
   天空和雪原全是青蓝，木箱和墙全是暖黄。有了这条关系，
   "往地下走越来越暖"才成立，而不是四套颜色随便挑的。
   底边必须卡在 380（地表板底）：多画一像素，浅井里就会露出天空。 */
function drawSky(g) {
  /* 有立绘就整段交给立绘 —— 程序化那套是"没有美术资源时也不至于难看"的
     兜底，不是备用方案。两张一起画只会互相打架（雪粒盖在画好的雪上）。 */
  if (BG_IMG) { g.drawImage(BG_IMG, 0, 0, W, 340); return; }

  const sky = g.createLinearGradient(0, -80, 0, 380);
  sky.addColorStop(0, COL.sky[0]);
  sky.addColorStop(0.42, COL.sky[1]);
  sky.addColorStop(0.8, COL.sky[2]);
  sky.addColorStop(1, COL.sky[3]);
  g.fillStyle = sky;
  g.fillRect(-40, -80, W + 80, 460);

  /* 云：**扁云**。底边压平、顶上两三个扁圆、底沿一条冷灰蓝。
     纯白圆叠出来读作"棉花糖"；加了底沿的冷色，云才有厚度和光向。 */
  for (let i = 0; i < 5; i++) {
    const cx = ((i * 247 + 60) % 1080) - 60;
    const cy = 40 + ((i * 73) % 96);
    const r = 16 + ((i * 13) % 9);
    const puffs = [[-r * 1.0, r * 0.2, r * 0.95], [r * 0.95, r * 0.24, r * 1.0],
                   [0, -r * 0.3, r * 1.25], [r * 0.3, r * 0.3, r * 1.1]];
    for (const pass of [0, 1]) {
      g.fillStyle = pass ? '#FCFEFF' : 'rgba(116,148,174,.55)';
      const dy = pass ? 0 : 6;
      g.beginPath();
      for (const pf of puffs) {
        g.moveTo(cx + pf[0] + pf[2], cy + pf[1] + dy);
        g.ellipse(cx + pf[0], cy + pf[1] + dy, pf[2], pf[2] * 0.62, 0, 0, Math.PI * 2);
      }
      g.fill();
    }
  }

  /* 地平线薄雾：**把远山和天空"接"起来**。没有这层，山是一块贴在
     天空上的剪影；有了它，远处才有空气，画面才不是"两层平面"。 */
  /* 地平线薄雾：**把最远那道脊"化"进天空里**。没有这层，远山是一块
     贴在天空上的剪影；有了它，远处才有空气。注意它只压在远脊之上、
     中脊之下 —— 压全部就变成一层灰罩子，画面立刻脏。 */
  const haze = g.createLinearGradient(0, 238, 0, 330);
  haze.addColorStop(0, 'rgba(236,247,253,.50)');
  haze.addColorStop(1, 'rgba(236,247,253,0)');
  g.fillStyle = haze;
  g.fillRect(-40, 238, W + 80, 94);

  /* 三道雪脊，由远到近、由冷到亮。**雪的白靠脊上那条亮边读出来**，
     不靠填色 —— 只填浅蓝的话，三道脊会在缩略图里糊成一片。 */
  const RIDGE = [
    { c: COL.snowFar,  f: x => 246 - Math.sin(x / 236) * 30 - Math.sin(x / 84) * 12 - Math.sin(x / 37) * 6 - Math.sin(x / 17) * 2.2, rim: 'rgba(255,255,255,.46)', lw: 3 },
    { c: COL.snowMid,  f: x => 300 - Math.sin(x / 153) * 26 - Math.sin(x / 61) * 9 - Math.sin(x / 29) * 3.4, rim: 'rgba(255,255,255,.74)', lw: 3 },
    { c: COL.snowNear, f: x => 338 - Math.sin(x / 99) * 16 - Math.sin(x / 44) * 5,   rim: '#FFFFFF', lw: 4 },
  ];
  const ridgePath = (R, dy) => {
    g.beginPath();
    for (let x = -40; x <= W + 40; x += 20) {
      if (x === -40) g.moveTo(x, R.f(x) + dy); else g.lineTo(x, R.f(x) + dy);
    }
  };
  const paintRidge = R => {
    g.fillStyle = R.c;
    ridgePath(R, 0);
    g.lineTo(W + 40, 400); g.lineTo(-40, 400); g.closePath(); g.fill();
    g.strokeStyle = R.rim; g.lineWidth = R.lw; g.lineJoin = 'round';
    ridgePath(R, 1.5); g.stroke();
  };
  paintRidge(RIDGE[0]);
  paintRidge(RIDGE[1]);

  /* 松林：**成排**的三角松，压在中景雪脊上。
     必须画在近景雪坡**之前** —— 后画就会被雪坡压住，先画才有
     "一片林子站在雪丘后面"的纵深。三条硬规矩：
     ① 树尖高低必须抖开（等高 = 一排栅栏）；
     ② 每棵只把**上半截**刷白，整棵全白就成了三角旗；
     ③ 树要够大（46~80）。之前 32~64 太小，雪坡一挡只剩几个尖，
        看起来像插了一排三角尺，不像林子。 */
  for (let i = 0; i < 11; i++) {
    const px = -20 + i * 92 + ((i * 47) % 34);
    const base = RIDGE[1].f(px) + 14;
    const hh = 46 + ((i * 53) % 34);
    const ww = hh * 0.42;
    g.fillStyle = COL.pine;
    g.beginPath();
    g.moveTo(px, base - hh);
    g.lineTo(px + ww, base - hh * 0.1); g.lineTo(px + ww * 0.56, base - hh * 0.1);
    g.lineTo(px + ww * 1.02, base); g.lineTo(px - ww * 1.02, base);
    g.lineTo(px - ww * 0.56, base - hh * 0.1);
    g.lineTo(px - ww, base - hh * 0.1);
    g.closePath(); g.fill();
    g.fillStyle = 'rgba(232,244,250,.72)';
    g.beginPath();
    g.moveTo(px, base - hh);
    g.lineTo(px + ww * 0.62, base - hh * 0.36);
    g.lineTo(px - ww * 0.62, base - hh * 0.36);
    g.closePath(); g.fill();
  }

  /* 远处那间木棚 + 一缕炊烟。**这一笔是"有人住"的信号**，
     也是地表唯一和地下那堆暖木箱属于同一个世界的东西：
     工坊的门开在雪原上，玩家从这间棚子的位置往下挖。
     没有它，地表只是一片好看的雪景，跟关卡没有任何关系。 */
  {
    const hx = 246, hy = RIDGE[1].f(246) + 16;
    g.fillStyle = '#8A6A4E';
    g.fillRect(hx - 34, hy - 40, 68, 42);
    g.fillStyle = '#6E5240';
    g.beginPath();                       // 屋顶：两条斜边 + 一层积雪
    g.moveTo(hx - 44, hy - 38); g.lineTo(hx, hy - 66); g.lineTo(hx + 44, hy - 38);
    g.closePath(); g.fill();
    g.fillStyle = '#EAF4FB';
    g.beginPath();
    g.moveTo(hx - 44, hy - 38); g.lineTo(hx, hy - 66); g.lineTo(hx + 44, hy - 38);
    g.lineTo(hx + 34, hy - 38); g.lineTo(hx, hy - 58); g.lineTo(hx - 34, hy - 38);
    g.closePath(); g.fill();
    g.fillStyle = '#FFD98A';             // 窗：唯一一点暖光，呼应地下吊灯
    g.fillRect(hx - 20, hy - 30, 15, 13);
    g.fillRect(hx + 6, hy - 30, 15, 13);
    g.fillStyle = '#5E5248';
    g.fillRect(hx + 26, hy - 60, 9, 22);  // 烟囱
    for (let i = 0; i < 4; i++) {         // 炊烟：越往上越大越淡
      const sy = hy - 66 - i * 13;
      const sr = 5 + i * 2.6;
      g.fillStyle = 'rgba(252,254,255,' + (0.5 - i * 0.1).toFixed(2) + ')';
      g.beginPath();
      g.ellipse(hx + 30 + Math.sin(S.t * 0.5 + i) * 3 + i * 2, sy, sr, sr * 0.86, 0, 0, Math.PI * 2);
      g.fill();
    }
  }

  paintRidge(RIDGE[2]);

  /* **边角两棵大树。** 树站在近脊上、画在近脊之后，才完整；
     但站在近脊上的树会挡住玩家跳跃的那 100px，所以只准放在
     左右两侧 —— 那里是边界箱墙，玩家到不了。
     这两棵树干的是"框景"：把画面两边锁住，视线自然收进中间。 */
  for (const tx of [34, 96, 918, 858]) {
    const base = RIDGE[2].f(tx) + 10;
    const hh = 74 + ((tx * 7) % 22);
    const ww = hh * 0.40;
    g.fillStyle = COL.pine;
    g.fillRect(tx - 4, base - hh * 0.9, 8, hh * 0.9);
    for (let t = 0; t < 3; t++) {
      const ty = base - hh + t * hh * 0.26;
      const tw = ww * (0.66 + t * 0.24);
      g.beginPath();
      g.moveTo(tx, ty); g.lineTo(tx + tw, ty + hh * 0.42);
      g.lineTo(tx - tw, ty + hh * 0.42);
      g.closePath(); g.fill();
      g.fillStyle = 'rgba(232,244,250,.66)';
      g.beginPath();
      g.moveTo(tx, ty); g.lineTo(tx + tw * 0.5, ty + hh * 0.2);
      g.lineTo(tx - tw * 0.5, ty + hh * 0.2);
      g.closePath(); g.fill();
      g.fillStyle = COL.pine;
    }
  }

  /* 落雪。**位置只由下标和 S.t 决定，不能每帧随机** ——
     随机的话雪粒会原地闪，比不下雪更难看。 */
  for (let i = 0; i < 52; i++) {
    const bx = -20 + ((i * 149) % 1000);
    const spd = 16 + (i % 7) * 7;
    const by = -30 + ((i * 61 + S.t * spd) % 380);
    const r = 1.1 + (i % 4) * 0.65;
    g.globalAlpha = 0.32 + (i % 5) * 0.11;
    g.fillStyle = '#FFFFFF';
    g.beginPath();
    g.arc(bx + Math.sin(S.t * 0.8 + i * 1.7) * 9, by, r, 0, Math.PI * 2);
    g.fill();
  }
  g.globalAlpha = 1;
}

function draw() {
  if (!ctx) return;
  const g = ctx;

  /* 世界外的底色。**必须先铺满再画世界** —— 镜头一往下走，屏幕上方就是
     世界 y 之外的空白，不铺底会露出画布的黑。 */
  g.fillStyle = '#6B4C34';
  g.fillRect(0, 0, W, H);

  g.save();

  /* 震屏。**不能是白噪声。**
     原来每帧独立随机 `rnd(-sh, sh)`，帧与帧之间毫无关系 ——
     肉眼读作"画面在抖"，而不是"被什么东西撞了一下"。
     真实的冲击是「沿一个方向被推出去，然后弹回来」。

     做法：两条**非整数倍频**（1.0 / 2.31）的正弦叠加。
     非整数比意味着它不会周期性回到同一点，看起来就不像机械摆动；
     再叠一个方向偏置 `shakeDX/DY`，让大震有明确的来向。
     大震才吃得进方向（乘 sh/14），小震（擦碰、落地）保持纯震颤 ——
     否则每一颗子弹打到箱子都让画面横移，会晕。 */
  const sh = S.shake;
  if (sh > 0) {
    const tt = S.t * 42;
    const dirK = Math.min(1, sh / 14) * 0.55;
    const dx = (Math.sin(tt) * 0.62 + Math.sin(tt * 2.31 + 1.7) * 0.38) * sh + S.shakeDX * sh * dirK;
    const dy = (Math.cos(tt * 1.37) * 0.55 + Math.sin(tt * 3.07) * 0.45) * sh + S.shakeDY * sh * dirK;
    g.translate(dx, dy);
  }

  // 镜头
  g.translate(0, -S.cam.y);

  /* ---- 地表 ----
     画在**世界坐标**里，不固定在屏幕上。这样它们只属于地表：
     下到地下之后天自然看不见 —— 这才是"越来越深"该有的样子。 */
  drawSky(g);

  /* ================= 地下 =================
     每一层是一个**房间**，不是一个洞。层与层之间挨着，中间那条就是楼板。
     主题按层号换（木屋 → 砖房 → 石洞 → 地窖），形状语言跟着换。
     **地板不在这里画** —— 地板是实体（S.plats），由 drawPlat 负责。 */
  for (let k = 1; k < FLOORS.length; k++) {
    drawRoomWall(g, k, FLOORS[k - 1] + GEN.thick, FLOORS[k]);
  }

  /* ================= 洞里的光 =================
     **敞开的下行口一定漏光。** 这一笔同时干两件事：
     一是给地下一个光源叙事（不然全是平光，画面没有戏剧性）；
     二是"这里能下去"的最高优先级提示 —— 那几种封法里，
     只有敞开是靠眼睛找的，光就是在替玩家找。
     光柱画在地形**之前**，让地板把它自然截断；落地的光斑另画在地形之后。 */
  for (let k = 0; k + 1 < FLOORS.length; k++) {
    for (const h of LAYERS[k].holes) {
      /* **不能只看 `h.cover`。** 那是生成时的初始封法，砸开之后它不会变
         —— 结果"挖穿了却一点光都不漏"，最该有光的时刻反而没有。
         按此刻洞口上还有没有箱子来定强弱：堵着只剩一线微光，通了就整束下来。 */
      const covered = S.boxes.some(b => !b.dead && b.x < h.x + h.w && b.x + b.w > h.x &&
        b.y < h.floorY + 4 && b.y + b.h > h.floorY - 100);
      /* 堵着只剩一线微光 0.055 —— 再高就成了一块淡蓝色的板子，
         比"洞里有光"更像"贴了张色纸"。 */
      const a0 = covered ? 0.055 : 0.30;
      const y1 = FLOORS[k + 1];
      /* **一整个梯形填上去，边是硬的** —— 看起来像贴了块半透明色板。
         改成 7 层由窄到宽的梯形叠加：中间叠得厚、边缘只有一两层，
         自然就有了"光越往外越淡"的软边。这是不依赖 blur 滤镜的做法。 */
      const cxh = h.x + h.w / 2;
      for (let j = 1; j <= 7; j++) {
        const sfx = 0.40 + 0.60 * (j / 7);
        const tw = h.w * sfx + 6;
        const bw = (h.w + 84) * sfx;
        const al = a0 * 0.16;
        const lg = g.createLinearGradient(0, h.floorY, 0, y1);
        lg.addColorStop(0, 'rgba(202,236,252,' + al.toFixed(3) + ')');
        lg.addColorStop(0.45, 'rgba(200,236,252,' + (al * 0.55).toFixed(3) + ')');
        lg.addColorStop(1, 'rgba(200,236,252,0)');
        g.fillStyle = lg;
        g.beginPath();
        g.moveTo(cxh - tw / 2, h.floorY);
        g.lineTo(cxh + tw / 2, h.floorY);
        g.lineTo(cxh + bw / 2, y1);
        g.lineTo(cxh - bw / 2, y1);
        g.closePath(); g.fill();
      }
    }
  }

  /* 场景道具分成两批：**挂件在地形之前，落地件在地形之后**。
     原来的做法是一批全画在地形之前，理由是"木桶在箱子后面"这种前后关系免费。
     但箱子是 48×48、木桶只有 26 宽，只要相邻列高出一格，木桶就被整块盖掉 ——
     地表层箱子最密，整层的装饰在图上等于不存在（出图时才发现）。
     挂件本来就在箱子后面（挂在天花板下），落地件本来就该在最前面（踩在地上）。 */
  for (const dc of S.deco) if (dc.ceil) drawDeco(g, dc);

  // 平台
  for (const pl of S.plats) drawPlat(g, pl);

  /* 主通道的地面标记。**画在平台之后、箱子之前** ——
     它贴在地面上，箱子站在旁边会压住它一点，这正是想要的前后关系。 */
  for (let k = 0; k < LAYERS.length; k++) {
    const cs = LAYERS[k].corridor;
    if (!cs) continue;
    for (let i = 0; i < cs.length; i++) if (cs[i]) drawTrail(g, i * 48, LAYERS[k].floorY);
  }

  // 洞光落在地板上的光斑（地板之后、箱子之前：箱子会站上去遮住一块，对）
  for (let k = 0; k + 1 < FLOORS.length; k++) {
    for (const h of LAYERS[k].holes) {
      const covered = S.boxes.some(b => !b.dead && b.x < h.x + h.w && b.x + b.w > h.x &&
        b.y < h.floorY + 4 && b.y + b.h > h.floorY - 100);
      if (covered) continue;
      const y1 = FLOORS[k + 1];
      const rg = g.createRadialGradient(h.x + h.w / 2, y1, 2, h.x + h.w / 2, y1, h.w * 0.95);
      rg.addColorStop(0, 'rgba(216,242,255,.20)');
      rg.addColorStop(1, 'rgba(216,242,255,0)');
      g.fillStyle = rg;
      g.beginPath(); g.ellipse(h.x + h.w / 2, y1 - 1, h.w * 0.95, 10, 0, 0, Math.PI * 2); g.fill();
    }
  }

  // 箱子
  for (const b of S.boxes) if (!b.dead) drawBox(g, b);

  /* 落地件在箱子之后补画（见上面那段的说明）。玩家还在这之后，不会挡人。 */
  for (const dc of S.deco) if (!dc.ceil) drawDeco(g, dc);

  /* 黑洞画在箱子**之后**：它是个"贴在地面上的洞"，被箱子挡住就不像洞了。 */
  for (const n of S.nests) drawNest(g, n);

  // 门
  drawDoor(g, S.door);

  // 雪之碎片
  for (const s of S.shards) {
    g.save(); g.translate(s.x, s.y); g.rotate(s.t * 3);
    g.fillStyle = '#CFEFFF';
    g.beginPath();
    for (let i = 0; i < 6; i++) {
      const a = i / 6 * Math.PI * 2;
      g.lineTo(Math.cos(a) * 9, Math.sin(a) * 9);
      g.lineTo(Math.cos(a + 0.52) * 4, Math.sin(a + 0.52) * 4);
    }
    g.closePath(); g.fill();
    g.restore();
  }

  // 敌人
  for (const f of S.foes) drawFoe(g, f);

  /* 宠物扔出来的东西。**画在敌人之后、玩家之前** —— 它必须压在宠物身上，
     不然宠物一走动就把自己扔出去的胡萝卜挡住了。 */
  for (const b of S.ebullets) drawEBullet(g, b);

  // 球
  for (const b of S.balls) drawBall(g, b);

  // 雪弹
  for (const s of S.shots) drawShot(g, s);

  // 玩家
  drawPlayer(g, S.p);
  drawClimbHint(g);
  drawBallHint(g);

  // 粒子
  for (const f of S.frags) {
    g.globalAlpha = Math.max(0, 1 - f.t / f.life);
    g.fillStyle = f.color;
    if (f.vr) {
      g.save();
      g.translate(f.x, f.y); g.rotate(f.rot);
      g.fillRect(-f.w / 2, -f.h / 2, f.w, f.h);
      /* 板条的一侧压一道暗边：没有这道，旋转起来读作"一根黄条" */
      g.fillStyle = 'rgba(60,42,26,.35)';
      g.fillRect(-f.w / 2, f.h / 2 - 1, f.w, 1);
      g.restore();
    } else {
      g.fillRect(f.x - f.r / 2, f.y - f.r / 2, f.r, f.r);
    }
  }
  g.globalAlpha = 1;
  /* 冲击环：画在碎片之上，一眼就看见"力是从哪发出来的" */
  for (const r of S.rings) {
    if (r.t < 0) continue;
    const k2 = 1 - r.t / r.life;
    /* **环要"双色"。** 单画一圈浅黄，在雪地/木箱这种浅底色上等于隐形 ——
       第一次出图就是这样：碎片看得见，环完全找不到。
       先用一圈深棕打底（保证任何底色上都读得出来），再用浅色压上去。 */
    g.globalAlpha = k2 * 0.55;
    g.strokeStyle = 'rgba(96,54,24,1)'; g.lineWidth = 1.6 + 3.0 * k2;
    g.beginPath(); g.arc(r.x, r.y, r.r, 0, Math.PI * 2); g.stroke();
    g.globalAlpha = k2 * 0.9;
    g.strokeStyle = r.color; g.lineWidth = 1 + 2.6 * k2;
    g.beginPath(); g.arc(r.x, r.y, r.r - 1.2, 0, Math.PI * 2); g.stroke();
  }
  g.globalAlpha = 1;

  // 飘字
  for (const t of S.texts) {
    g.globalAlpha = Math.max(0, Math.min(1, (t.life - t.t) * 3));
    g.font = '700 ' + t.size + 'px "PingFang SC","Microsoft YaHei",sans-serif';
    g.textAlign = 'center';
    g.lineWidth = 4; g.strokeStyle = 'rgba(20,30,36,.55)';
    g.strokeText(t.s, t.x, t.y);
    g.fillStyle = t.color;
    g.fillText(t.s, t.x, t.y);
  }
  g.globalAlpha = 1;

  g.restore();

  /* ---- 纵向纵深：越往下越暗，光只跟着玩家走 ----
     不加这一层，三层看起来就是"同一张图上下拼了三段"，
     空格感有了、深度感还是没有。 */
  const depth = clamp(S.cam.y / (WORLD_H - H), 0, 1);
  if (depth > 0.03) {
    const px = S.p.x + S.p.w / 2;
    const py = S.p.y + S.p.h / 2 - S.cam.y;      // 已经是屏幕坐标
    /* 光圈半径 340 —— 再宽就等于没暗化（整屏都在圈里），
       再窄玩家就看不到自己要往哪走。340 大致是"能看清一跳的距离 + 一点余量"。
       **最深处的黑度上限是 0.54，不是 0.78。**
       层数从 6 变成 4~8 之后，8 层的门厅 depth 会顶到 1；
       原来那条曲线在 0.78 上，出来是一整屏黑，门和冰全糊在一起 ——
       出图才看出来。深度感靠"越往下越暗"就够，不需要真的看不见。 */
    const a = 0.10 + depth * 0.34;
    const grd = g.createRadialGradient(px, py, 90, px, py, 400);
    grd.addColorStop(0, 'rgba(8,14,20,0)');
    grd.addColorStop(0.45, 'rgba(8,14,20,' + (a * 0.3).toFixed(3) + ')');
    grd.addColorStop(1, 'rgba(8,14,20,' + a.toFixed(3) + ')');
    g.fillStyle = grd;
    g.fillRect(0, 0, W, H);
  }

  /* ---- 空气里的雪尘 ----
     屏幕坐标、纯公式驱动（不开随机），60 颗慢慢往下飘。
     这一层几乎没有性能成本，但"空气里有东西"和"空的"是完全两种画面。 */
  const T = S.t;
  for (let i = 0; i < 60; i++) {
    const sp = 12 + (i % 7) * 5;
    const px = (i * 97 + Math.sin(T * 0.5 + i) * 26 + T * 6) % (W + 40) - 20;
    const py = (i * 61 + T * sp) % (H + 40) - 20;
    const r = 0.8 + (i % 5) * 0.36;
    g.globalAlpha = 0.10 + (i % 4) * 0.05;
    g.fillStyle = '#EAF6FD';
    g.beginPath(); g.arc(px, py, r, 0, Math.PI * 2); g.fill();
  }
  g.globalAlpha = 1;

  /* 屏幕四角的暗角。纵深暗化是**跟着玩家走的光圈**，
     这个是**固定的构图框** —— 两个都要，画面才"收得住"。 */
  const vg = g.createRadialGradient(W / 2, H * 0.46, H * 0.30, W / 2, H * 0.46, H * 0.92);
  vg.addColorStop(0, 'rgba(5,10,15,0)');
  vg.addColorStop(0.65, 'rgba(5,10,15,.14)');
  vg.addColorStop(1, 'rgba(5,10,15,.46)');
  g.fillStyle = vg;
  g.fillRect(0, 0, W, H);

  drawHud(g);

  if (S.flash > 0) {
    g.fillStyle = 'rgba(255,255,255,' + (S.flash * 0.8) + ')';
    g.fillRect(0, 0, W, H);
  }
  if (S.phase === 'clear') drawClear(g);
}

/* ---------------------------------------------------------------- 岩体
   **纹理必须每帧一模一样。** 用坐标当种子（不开 Math.random），
   否则石头会在屏幕上"沸腾"。 */
function rockFill(g, x, y, w, h, seed) {
  /* **暖土色，不是冷灰岩。** 整个场景已经换成暖色调（木箱 / 木墙），
     灰蓝的岩体是上一版写实路子的残留，会在画面里显脏。
     纹理仍然用坐标当种子 —— 开 Math.random 土纹会"沸腾"。 */
  const grd = g.createLinearGradient(0, y, 0, y + h);
  grd.addColorStop(0, '#CFAB80');
  grd.addColorStop(0.42, '#B78F64');
  grd.addColorStop(1, '#8F6C48');
  g.fillStyle = grd;
  g.fillRect(x, y, w, h);

  g.save();
  g.beginPath(); g.rect(x, y, w, h); g.clip();
  /* 层理：**土层是水平的，石头才是随机点。** 之前只有碎石小点，
     一块 200×140 的坡体看起来就是一块均匀的土色三角，读不出厚度。
     三条微弯的水平暗线一加，立刻有"这是挖开的土"的体积感。
     **薄板（h<40）不加** —— 20px 高的楼板里塞三条线，反而像划痕。 */
  if (h > 40) {
    g.strokeStyle = 'rgba(96,66,40,.14)';
    g.lineWidth = 1.6;
    for (let i = 1; i <= 3; i++) {
      const ly = y + h * (i / 4) + Math.sin(seed * 0.7 + i) * 3;
      g.beginPath();
      g.moveTo(x - 4, ly);
      for (let sx = 0; sx <= w; sx += 26) {
        g.lineTo(x + sx, ly + Math.sin((seed + sx * 0.09 + i * 2.1)) * 2.2);
      }
      g.stroke();
    }
  }
  // 碎石：亮暗两种小点，疏密由面积定
  const n = Math.min(46, Math.round(w * h / 240));
  for (let i = 0; i < n; i++) {
    const px = x + ((seed * 37 + i * 131) % Math.max(1, Math.floor(w)));
    const py = y + 4 + ((seed * 53 + i * 79) % Math.max(1, Math.floor(h - 6)));
    const r = 1.6 + ((i * 7) % 3.4);
    g.fillStyle = i % 3 === 0 ? 'rgba(255,240,215,.30)' : 'rgba(96,66,40,.20)';
    g.beginPath(); g.arc(px, py, r, 0, Math.PI * 2); g.fill();
  }
  g.restore();
}

/* 雪盖（现在是"草皮 / 木顶"）。顶面在碰撞面上 —— **不许高出去，高出去人就悬空**，
   所以"自然"只能靠左右圆角 + 起伏的边缘 + 底部的一条暗边。 */
function snowCap(g, x, y, w, thick, seed, grass, stone) {
  const wob = px => Math.sin(px * 0.083 + seed) * 0.8 + Math.sin(px * 0.031) * 0.5;
  g.beginPath();
  g.moveTo(x - 2, y + thick);
  for (let px = x - 2; px <= x + w + 2; px += 8) g.lineTo(px, y + wob(px));
  g.lineTo(x + w + 2, y + thick);
  g.closePath();
  /* 顶面是**木板**，不是草皮。场景在地下（工坊 / 砖房 / 石洞），
     一层绿草长在楼板上会立刻出戏。地表那一层是**雪面** ——
     绿草配雪原是这一版最早也最明显的穿帮，一看就是两套素材拼的。 */
  const sg = g.createLinearGradient(0, y, 0, y + thick);
  if (grass) {
    sg.addColorStop(0, '#F6FCFF');
    sg.addColorStop(0.55, '#E2F2FB');
    sg.addColorStop(1, '#C3DDEC');
  } else if (stone) {
    /* 悬空台子的顶面是**石头**，不是木地板。
       原来所有顶面都走木色渐变，台子于是读成"一块钉在墙上的木板" ——
       用户说的"横向的太规矩"，一半来自这个。 */
    sg.addColorStop(0, '#CFC8BC');
    sg.addColorStop(0.6, '#B4AB9D');
    sg.addColorStop(1, '#958B7C');
  } else {
    sg.addColorStop(0, '#F1D3A4');
    sg.addColorStop(0.65, '#E0B87F');
    sg.addColorStop(1, '#C7975E');
  }
  g.fillStyle = sg;
  g.fill();
  // 顶面高光：一条 2px 的亮边，卡通感就靠这一笔
  g.beginPath();
  for (let px = x - 2; px <= x + w + 2; px += 8) {
    const py = y + 1 + wob(px);
    if (px === x - 2) g.moveTo(px, py); else g.lineTo(px, py);
  }
  g.strokeStyle = 'rgba(255,255,255,.55)';
  g.lineWidth = 2.5;
  g.stroke();
}

/* ---------------------------------------------------------------- 地形绘制
   **这一版把"平台 / 坡"从几何体改成了"长在地里的东西"。**
   用户 2026-10-28：「你这斜坡和横向的也太规矩了吧 不能看起来自然点吗」。

   原来是什么：平台 = 18px 高的圆角矩形 + 一条雪盖；坡 = 一条完美三角 + 等宽
   木板。那是在编辑器里拖出来的形状，不是挖出来的土。现在三条一起改：
     · **轮廓是有机的**：底面瘤状起伏、端头缺口、坡脚堆碎石；
     · **顶面严格压在碰撞线上** —— 画高一个像素人就浮空，所以"自然"
       只能从轮廓和贴面物上找，不能在顶边上找（这一条是硬约束，别改）；
     · **坡面铺装三选一**（木阶 / 乱石 / 素土 + 碎石），同一个画面里
       两条坡不会穿同一件衣服。
   所有"随机"都用坐标当种子 —— 用 Math.random 的话土纹每帧重排，
   看起来像在沸腾。 */

function drawRamp(g, pl) {
  const x0 = pl.x, x1 = pl.x + pl.w;
  const topL = pl.y, topR = pl.y - pl.rise;
  const base = pl.base;
  const s = Math.round(x0 * 1.7 + base * 0.3);
  const snowy = base === GEN.topY;            // 地表那层的坡是"雪坡"，不是"木坡"
  const botAt = px => base + 2 + Math.sin(px * 0.058 + s) * 2.0 + Math.sin(px * 0.021 + s * 0.6) * 1.6;
  const surfAt = px => topL + (topR - topL) * ((px - x0) / pl.w);

  /* 土体轮廓。上沿逐点走过去、**一点抖动都不加**（它就是碰撞面），
     自然感交给下面那条瘤状的底边。 */
  const bodyPath = () => {
    g.beginPath();
    g.moveTo(x0, topL);
    const step = Math.max(8, pl.w / 24);
    for (let px = x0 + step; px < x1; px += step) g.lineTo(px, surfAt(px));
    g.lineTo(x1, topR);
    g.lineTo(x1, base + 3);
    for (let px = x1; px > x0; px -= 13) g.lineTo(px, botAt(px));
    g.lineTo(x0, base + 3);
    g.closePath();
  };

  g.save();
  bodyPath(); g.clip();
  if (snowy) {
    /* **地表那层的坡整块是雪**，不是"土坡盖一条白边"。
       上一版是土体 + 一条 10px 的白边，在雪原上一眼就是"褐色三角 + 白边"，
       像贴上去的。整块换成雪之后，它才是"被风吹堆起来的一道雪梁"。 */
    const sg = g.createLinearGradient(0, Math.min(topL, topR), 0, base);
    sg.addColorStop(0, '#FFFFFF');
    sg.addColorStop(0.5, '#EDF7FE');
    sg.addColorStop(1, '#C9DFEE');
    g.fillStyle = sg;
    g.fillRect(Math.min(x0, x1) - 2, Math.min(topL, topR) - 2, pl.w + 4, base - Math.min(topL, topR) + 6);
    /* 背光面：靠坡脚压一条冷影，雪堆才有厚度 */
    g.fillStyle = 'rgba(150,188,214,.28)';
    g.beginPath();
    g.moveTo(x0, base + 3);
    for (let px = x0; px <= x1; px += 12) g.lineTo(px, surfAt(px) + 16 + Math.sin(px * 0.05) * 5);
    g.lineTo(x1, base + 3);
    g.closePath(); g.fill();
  } else {
    rockFill(g, Math.min(x0, x1), Math.min(topL, topR), pl.w, base - Math.min(topL, topR) + 4, s);
  }

  /* ---- 坡面铺装 ----
     **坡度决定铺什么，不是随机决定。**
     陡坡（>23°）是人踩出来的路，铺木板或垫石头；缓坡（土丘那种 20°）
     铺装只会显得莫名其妙 —— 谁会在一个小土包上钉木板。
     另外**地表那层一律不铺**：雪原上的土丘被木板盖住，一眼就是"人造坡道"，
     这是上一版最假的一处（整块读成了船底）。 */
  const steep = Math.abs(pl.rise) / pl.w > 0.42;
  const variant = (!steep || snowy) ? 2 : (Math.abs(Math.round(pl.x * 3.1 + pl.base * 0.7)) % 2);
  if (variant !== 2) {
    const N = Math.max(5, Math.round(pl.w / 26));
    for (let i = 0; i < N; i++) {
      const t0 = i / N, t1 = (i + 1) / N;
      const ax = x0 + pl.w * t0, ay = surfAt(ax);
      const bx = x0 + pl.w * t1, by = surfAt(bx);
      if (variant === 0) {
        /* 木阶：**每一级要留缝、下垂高度要抖开**。
           全宽等高的排板读出来是"百叶窗"，抖开之后才像一块块钉歪的板。 */
        const drop = 13 + ((i * 7) % 6);
        g.beginPath();
        g.moveTo(ax + 2, ay + 1.5); g.lineTo(bx - 2, by + 1.5);
        g.lineTo(bx - 2, by + drop); g.lineTo(ax + 2, ay + drop + 1);
        g.closePath();
        g.fillStyle = i % 2 ? '#E0A96C' : '#C98C51';
        g.fill();
        g.strokeStyle = 'rgba(74,58,44,.5)'; g.lineWidth = 1.8; g.stroke();
      } else {
        /* 乱石：一块一块圆头的石头，中间露土 */
        const drop = 15 + ((i * 5) % 9);
        const cx = (ax + bx) / 2, cy = (ay + by) / 2;
        g.beginPath();
        g.moveTo(ax + 3, ay + 3);
        g.lineTo(bx - 4, by + 3);
        g.quadraticCurveTo(bx - 3, by + drop, cx, by + drop + 1);
        g.quadraticCurveTo(ax + 3, ay + drop, ax + 3, ay + 3);
        g.closePath();
        g.fillStyle = i % 2 ? '#C2BAAD' : '#ABA396';
        g.fill();
        g.strokeStyle = 'rgba(58,48,40,.4)'; g.lineWidth = 1.6; g.stroke();
        g.fillStyle = 'rgba(255,250,240,.30)';
        g.beginPath(); g.ellipse(cx, cy + 5, Math.max(3, (bx - ax) * 0.3), 2.2, 0, 0, Math.PI * 2); g.fill();
      }
    }
  }
  /* 半埋的石头 + 被踩秃的顶边。
     **一块 240×114 的纯土色三角，无论纹理怎么调都是一块"纸板"。**
     能救它的只有两样：往下压几块石头（有体积感）、顶边磨出一道浅色
     （人和球天天从这儿过）。石头一律**画在坡面以下**，不许露头 ——
     露头就是玩家脚下多出来的 6px 空气。 */
  if (!snowy) {
    for (let i = 0; i < 4; i++) {
      const t = 0.13 + i * 0.23 + ((s + i * 31) % 7) / 100;
      const px = x0 + pl.w * t;
      const py = surfAt(px) + 15 + ((i * 13 + s) % 20);
      const r = 6 + ((i * 7 + s) % 6);
      g.fillStyle = i % 2 ? '#C0B5A4' : '#A79B8A';
      g.beginPath(); g.ellipse(px, py, r * 1.35, r * 0.86, (i % 3 - 1) * 0.22, 0, Math.PI * 2); g.fill();
      g.strokeStyle = 'rgba(74,58,44,.28)'; g.lineWidth = 1.6; g.stroke();
      g.fillStyle = 'rgba(255,252,244,.26)';
      g.beginPath(); g.ellipse(px - r * 0.3, py - r * 0.34, r * 0.7, r * 0.34, 0, 0, Math.PI * 2); g.fill();
    }
    g.strokeStyle = 'rgba(255,248,228,.45)';
    g.lineWidth = 3.2;
    g.beginPath();
    for (let px = x0 + 6; px <= x1 - 6; px += 12) g.lineTo(px, surfAt(px) + 2.4);
    g.stroke();
  }
  if (variant === 2 && !snowy) {
    /* 素土：不铺装，只撒碎石和几道被踩出来的浅槽 —— 读起来是
       "这里本来就是土坡，人走多了压出来的路"。
       **地表那块不能撒**：雪面上撒土色碎石，看起来像脏了。 */
    for (let i = 0; i < 10; i++) {
      const t = ((i * 137 + s) % 1000) / 1000;
      const px = x0 + pl.w * t;
      const py = surfAt(px) + 5 + ((i * 53) % 18);
      g.fillStyle = i % 3 === 0 ? 'rgba(255,244,222,.42)' : 'rgba(96,66,40,.32)';
      g.beginPath(); g.ellipse(px, py, 2.6 + (i % 3), 1.7 + (i % 2), 0.3, 0, Math.PI * 2); g.fill();
    }
  }

  g.restore();

  /* 描边。**只描上沿那一条，不闭合。**
     闭合描边会在两段土丘共用的那条竖直边上画出两道线 ——
     人字坡正中间一道黑缝，看上去就是"两个楔子拼起来的"，
     一眼假。高端永远接着别的东西（平台侧面或另一半土丘），
     那条竖边交给对面去画，这里留空。 */
  g.beginPath();
  g.moveTo(x0, topL);
  for (let px = x0; px <= x1; px += 8) g.lineTo(px, surfAt(px));
  g.strokeStyle = COL.ink;
  g.lineWidth = 3;
  g.lineCap = 'round';
  g.lineJoin = 'round';
  g.stroke();

  /* 坡脚的碎石堆。`rise > 0` 是"右端更高"，所以低端在左（x0）。
     这条写反过一次：两段坡的土全堆到顶点，山坡正中间一道弧，像张嘴。 */
  const lowX = pl.rise > 0 ? x0 : x1;
  const dir = pl.rise > 0 ? 1 : -1;
  g.fillStyle = snowy ? '#E4F2FA' : '#B78F64';
  g.beginPath(); g.ellipse(lowX, base - 1, 26, 7, 0, Math.PI, 0); g.fill();
  g.strokeStyle = 'rgba(74,58,44,.55)'; g.lineWidth = 2.2;
  g.beginPath(); g.ellipse(lowX, base - 1, 26, 7, 0, Math.PI, 0); g.stroke();
  for (let i = 0; i < 3; i++) {
    const px = lowX + dir * (10 + i * 14) + (i % 2 ? 3 : -2);
    const r = 3.6 + (i % 2) * 1.4;
    g.fillStyle = snowy ? (i % 2 ? '#F2FAFF' : '#D8EAF6') : (i % 2 ? '#C6A585' : '#A8815C');
    g.beginPath(); g.arc(px, base - 2 - r * 0.4, r, 0, Math.PI * 2); g.fill();
    g.strokeStyle = 'rgba(74,58,44,.45)'; g.lineWidth = 1.5; g.stroke();
  }

  /* 土丘的**压顶石**。两段坡拼成一个人字，顶点那一下太尖 ——
     一眼就是个三角屋顶。压一块石头上去，人字立刻读成"被石头压住的山包"。
     石头**整体画在顶点以下**，顶面正好压在顶点那条线上，
     所以站上去不会浮空。 */
  if (pl.cap) {
    const cx = pl.rise > 0 ? x1 : x0, cy = Math.min(topL, topR);
    if (snowy) {
      /* 地表的顶点扣一顶**雪帽**，不是压石头。
         雪原上出现一块石头本来就没道理；而人字顶点又太尖（像个三角屋顶）。
         雪帽是"风把雪堆到梁顶上"的样子，顶面正好压在顶点那条线上。 */
      g.fillStyle = '#FFFFFF';
      g.beginPath();
      g.moveTo(cx - 30, cy + 15);
      g.quadraticCurveTo(cx - 28, cy + 4, cx - 12, cy + 1.2);
      g.quadraticCurveTo(cx, cy - 0.4, cx + 12, cy + 1.4);
      g.quadraticCurveTo(cx + 28, cy + 4, cx + 30, cy + 15);
      g.quadraticCurveTo(cx, cy + 20, cx - 30, cy + 15);
      g.closePath(); g.fill();
      g.strokeStyle = COL.ink; g.lineWidth = 2.6; g.lineJoin = 'round'; g.stroke();
      g.fillStyle = 'rgba(160,198,222,.22)';
      g.beginPath(); g.ellipse(cx, cy + 12, 22, 4.6, 0, 0, Math.PI * 2); g.fill();
    } else {
      g.fillStyle = '#B3ABA0';
      g.beginPath();
      g.moveTo(cx - 25, cy + 13);
      g.quadraticCurveTo(cx - 24, cy + 2, cx - 12, cy + 0.5);
      g.quadraticCurveTo(cx + 4, cy - 0.5, cx + 14, cy + 1.5);
      g.quadraticCurveTo(cx + 25, cy + 3, cx + 26, cy + 14);
      g.lineTo(cx + 18, cy + 21);
      g.lineTo(cx - 18, cy + 21);
      g.closePath(); g.fill();
      g.strokeStyle = COL.ink; g.lineWidth = 2.6; g.lineJoin = 'round'; g.stroke();
      g.strokeStyle = 'rgba(255,252,244,.55)'; g.lineWidth = 2;
      g.beginPath(); g.moveTo(cx - 14, cy + 4); g.lineTo(cx + 11, cy + 3.5); g.stroke();
    }
  }
}

/* =========================================================================
   主通道的地面标记
   ---------------------------------------------------------------------------
   用户 2026-10-29：「主通道没有视觉提示」。

   走廊现在是**几何上的硬保证**（那一列恒 0 格、相邻列 ≤2 格），
   可玩家看不出来 —— 在一屏「两堆箱山 + 若干空地」里，"这条空列是路"
   和"这条空列只是恰好没摆箱子"长得一模一样。于是玩家的走法变成
   "哪里高往哪里爬"，而不是"沿着路走"。

   画法只有两件东西：
     ① 地面上一段被踩脏的暗带（两端渐隐），像被人反复踩过的木板；
     ② 后墙上一对粉笔画的箭头（⌃⌃），30px 高，**这一对才是给人看的**。
   两次试错：
     · 第一版画"浅色亮带 + 三粒暖点"—— 地板本身就是奶白的，0.2 的奶白色
       画上去等于没画，出图上一块都找不到；
     · 第二版画"一对脚印"—— 3px 的椭圆在 1× 下和地板上原本就有的小石子
       长得一样，读成污渍。
   所以提示必须**离开地面、画到墙面上去**：那里是空的，而且粉笔箭头
   本来就是这个工坊世界里的东西（墙上有管道、铆钉、蛛网）。
   ========================================================================= */
function drawTrail(g, x, fy) {
  const cx = x + 24;
  /* **地表层没有后墙** —— 它是最上面那层雪地，后面直接是天空/远山。
     粉笔箭头画在那里会变成"浮在空中的两个 V"（出图才看出来），
     所以室外只留"被踩实的雪"，箭头留给有墙的下面几层。 */
  const outdoor = Math.abs(fy - GEN.topY) < 1;
  if (outdoor) {
    /* 踩实的雪：一条比周围略灰、略低的带子 —— 雪被踩过就是这个样子。
       低那一条用两道极淡的暗线暗示"陷下去"，比画脚印稳（48px 一格里
       脚印只有 7px，读出来是石子）。 */
    const sg = g.createLinearGradient(cx - 24, 0, cx + 24, 0);
    sg.addColorStop(0, 'rgba(150,170,196,0)');
    sg.addColorStop(0.5, 'rgba(150,170,196,.26)');
    sg.addColorStop(1, 'rgba(150,170,196,0)');
    g.fillStyle = sg;
    g.fillRect(cx - 24, fy - 4, 48, 4);
    g.strokeStyle = 'rgba(120,142,170,.22)'; g.lineWidth = 1.4;
    g.beginPath(); g.moveTo(cx - 14, fy - 6); g.lineTo(cx + 14, fy - 6); g.stroke();
    /* 箭头**压在雪面线上**（往上一步就进天空了）。雪是白的，
       所以这里让暗描边说话、亮面几乎不管 —— 和室内正好反过来。 */
    g.lineCap = 'round'; g.lineJoin = 'round';
    for (let i = 0; i < 2; i++) {
      const by = fy - 15 - i * 9;
      const path = () => {
        g.beginPath();
        g.moveTo(cx - 9, by + 7);
        g.lineTo(cx, by);
        g.lineTo(cx + 9, by + 7);
      };
      g.strokeStyle = 'rgba(58,72,96,.34)'; g.lineWidth = 4.4; path(); g.stroke();
      g.strokeStyle = 'rgba(255,255,255,.55)'; g.lineWidth = 2; path(); g.stroke();
    }
    return;
  }
  /* ① 被踩脏的地面 */
  const lg = g.createLinearGradient(cx - 24, 0, cx + 24, 0);
  lg.addColorStop(0, 'rgba(92,62,36,0)');
  lg.addColorStop(0.5, 'rgba(92,62,36,.13)');
  lg.addColorStop(1, 'rgba(92,62,36,0)');
  g.fillStyle = lg;
  g.fillRect(cx - 24, fy - 4, 48, 4);
  /* ② 粉笔箭头：两个 ⌃ 叠起来 = "从这里往上"。
     **描两遍**：先一道暗底再一道亮面，等于给箭头自带描边 ——
     砖墙有深有浅，只描一遍时在浅墙上"看不见"、在深墙上"像裂缝"。
     这和整个游戏"万物一圈 COL.ink"的视觉语言同源，不是新发明。 */
  g.lineCap = 'round';
  g.lineJoin = 'round';
  for (let i = 0; i < 2; i++) {
    const by = fy - 26 - i * 11;
    const path = () => {
      g.beginPath();
      g.moveTo(cx - 10, by + 8);
      g.lineTo(cx, by);
      g.lineTo(cx + 10, by + 8);
    };
    g.strokeStyle = 'rgba(44,28,16,.26)'; g.lineWidth = 5; path(); g.stroke();
    g.strokeStyle = 'rgba(255,250,232,.62)'; g.lineWidth = 2.4; path(); g.stroke();
  }
}

function drawPlat(g, pl) {
  if (pl.kind === 'ramp') { drawRamp(g, pl); return; }
  const seed = Math.round(pl.x) + Math.round(pl.y);
  const snowy = pl.y === GEN.topY;
  const isGround = (S.level ? S.level.floors : []).some(f => Math.abs(f - pl.y) < 1);
  const x0 = pl.x, x1 = pl.x + pl.w, yT = pl.y, hh = pl.h;
  /* 底面的瘤状起伏。**只在悬空台子上用** —— 地板的下沿就是下一层的天花板，
     把它画成波浪等于把下一层的净空挖掉一块。 */
  const botAt = px => yT + hh - 3 + Math.sin(px * 0.071 + seed * 1.3) * 3.2 + Math.sin(px * 0.023 + seed) * 2;

  /* ---- 断口 ----
     **楼板断成几段之后，两端的截面必须有画法。**
     原来是"矩形直切" —— 一整排看过去就是被人用剪刀剪断的胶带，
     比"一条又厚又长的横梁"更廉价。
     真楼板断在洞口边上是这样的：木板被掰断，茬口参差、里侧压着阴影。
     所以断口处走 3 个锯齿点（内凹 0~4px），再在里侧压一条暗竖带。 */
  /* **断口茬口不再只给地表层。** 用户 2026-10-28（第二轮）说「处理的太直了
     吧　太陡」—— 地下的楼板断在洞口边上原来是一刀切的直角，两层之间的
     洞口读起来就是"两堵垂直的墙"，又直又陡。地表层早就有茬口画法，
     地下一直没享受到，因为 `isGround` 这个条件把它拦在外面。 */
  const cutL = x0 > WALL_L + 1;
  const cutR = x1 < WALL_R - 1;
  const nA = 1.6 + (seed % 3) * 0.9;
  const nB = 1.6 + ((seed >> 2) % 3) * 0.9;

  const bodyPath = () => {
    g.beginPath();
    if (cutL) {
      g.moveTo(x0 + nA, yT + 1.5);
      g.lineTo(x0 + nA * 0.35, yT + hh * 0.42);
      g.lineTo(x0 + nA + 1.2, yT + hh * 0.72);
      g.lineTo(x0 + nB * 0.5, yT + hh + 1);
    } else {
      g.moveTo(x0 - 1, yT + 2);
    }
    for (let px = x0 + 8; px < x1; px += 8) g.lineTo(px, yT + 2);
    if (cutR) {
      g.lineTo(x1 - nB, yT + 1.5);
      g.lineTo(x1 - nB * 0.35, yT + hh * 0.42);
      g.lineTo(x1 - nB - 1.2, yT + hh * 0.72);
      g.lineTo(x1 - nA * 0.5, yT + hh + 1);
    } else {
      g.lineTo(x1 + 1, yT + 2);
    }
    if (isGround) {
      if (!cutL) g.lineTo(x0 - 1, yT + hh + 1);
    } else {
      g.lineTo(x1 + 1, botAt(x1));
      for (let px = x1; px >= x0; px -= 9) g.lineTo(px, botAt(px));
      g.lineTo(x0 - 1, botAt(x0));
    }
    g.closePath();
  };

  g.save();
  bodyPath(); g.clip();
  rockFill(g, x0 - 1, yT + 2, pl.w + 2, hh + 2, seed);
  /* 地板的**板缝**。一整条 960 宽的色带上什么都没有，看不出这是"铺出来的
     地面"；每 64px 一道缝，才有工坊/砖房的地板感。悬空台子不画（太窄）。 */
  if (isGround && !snowy) {
    /* **板缝不能等距。** 每 64px 一道的等距缝，一整条屏看过去就是"栅栏"，
       而且四条缝一模一样长 —— 这是"太规矩"里最容易被一眼看穿的一种。
       间距抖到 46~82，偶尔一块板换个深浅、再点一个节疤。 */
    let px = x0 + 30 + (seed % 26);
    for (let i = 0; px < x1; i++) {
      if (i % 4 === 2) {
        g.fillStyle = 'rgba(96,66,40,.10)';
        g.fillRect(px, yT + 8, 52, hh - 6);
      }
      g.strokeStyle = 'rgba(96,66,40,.26)';
      g.lineWidth = 1.5;
      g.beginPath(); g.moveTo(px, yT + 8); g.lineTo(px + 1.2, yT + hh); g.stroke();
      if (i % 5 === 3) {
        g.fillStyle = 'rgba(96,66,40,.22)';
        g.beginPath(); g.ellipse(px - 18, yT + hh * 0.55, 4.6, 2.6, 0.2, 0, Math.PI * 2); g.fill();
        g.fillStyle = 'rgba(96,66,40,.16)';
        g.beginPath(); g.ellipse(px - 18, yT + hh * 0.55, 8.4, 4.4, 0.2, 0, Math.PI * 2); g.fill();
      }
      px += 46 + ((i * 37 + seed * 11) % 36);
    }
  }
  g.restore();

  if (!isGround) {
    /* 台底下挂的东西：一两根根须 + 一颗悬着的石子。
       **不挂东西的悬浮台子看起来就是个贴纸** —— 玩家不会觉得它能站人。 */
    const rootX = x0 + 14 + (seed % Math.max(8, Math.round(pl.w - 28)));
    g.strokeStyle = 'rgba(122,86,52,.85)';
    g.lineWidth = 2.4; g.lineCap = 'round';
    g.beginPath();
    g.moveTo(rootX, botAt(rootX) - 4);
    g.quadraticCurveTo(rootX + 5, botAt(rootX) + 9, rootX - 3, botAt(rootX) + 20);
    g.stroke();
    g.strokeStyle = 'rgba(122,86,52,.55)';
    g.lineWidth = 1.8;
    g.beginPath();
    g.moveTo(rootX + 22, botAt(rootX + 22) - 3);
    g.quadraticCurveTo(rootX + 26, botAt(rootX + 22) + 7, rootX + 20, botAt(rootX + 22) + 13);
    g.stroke();
    g.fillStyle = '#A8815C';
    g.beginPath(); g.arc(rootX + 44, botAt(rootX + 44) + 8, 4.6, 0, Math.PI * 2); g.fill();
    g.strokeStyle = 'rgba(74,58,44,.6)'; g.lineWidth = 1.6; g.stroke();
  }

  /* 断口里侧的暗竖带：**没有它就是一块被切平的蛋糕**，
     有它才读得出"这块板在这里断了、里面是暗的"。 */
  if (cutL) {
    const gr = g.createLinearGradient(x0, 0, x0 + 13, 0);
    gr.addColorStop(0, 'rgba(46,34,24,.46)');
    gr.addColorStop(1, 'rgba(46,34,24,0)');
    g.fillStyle = gr;
    g.fillRect(x0, yT + 1, 13, hh);
  }
  if (cutR) {
    const gr = g.createLinearGradient(x1, 0, x1 - 13, 0);
    gr.addColorStop(0, 'rgba(46,34,24,.46)');
    gr.addColorStop(1, 'rgba(46,34,24,0)');
    g.fillStyle = gr;
    g.fillRect(x1 - 13, yT + 1, 13, hh);
  }

  bodyPath();
  g.strokeStyle = COL.ink;
  g.lineWidth = 3;
  g.lineJoin = 'round';
  g.stroke();

  snowCap(g, pl.x, pl.y, pl.w, isGround ? 9 : 13, seed * 0.7, snowy, !isGround);

  /* 顶面上的小东西：**两三颗石子 + 一撮苔**。
     它们只有 4~6px 高，压在碰撞线上也看不出来（人的鞋本来就在这条线里），
     但没它们，台面就是一条剃刀一样平的直边。 */
  const nTop = Math.round(pl.w / 46);
  for (let i = 0; i < nTop; i++) {
    const px = x0 + 12 + ((i * 97 + seed * 13) % Math.max(16, pl.w - 24));
    if (i % 3 === 2) {
      g.fillStyle = 'rgba(126,158,104,.9)';
      for (let k = 0; k < 3; k++) {
        g.beginPath();
        g.moveTo(px + k * 3 - 3, yT + 3);
        g.quadraticCurveTo(px + k * 3 - 4, yT - 4, px + k * 3 + (k - 1) * 2, yT - 7);
        g.quadraticCurveTo(px + k * 3 - 1, yT - 3, px + k * 3 + 1, yT + 3);
        g.closePath(); g.fill();
      }
    } else {
      g.fillStyle = i % 2 ? '#C6A585' : '#A8815C';
      g.beginPath(); g.ellipse(px, yT + 3, 3.4 + (i % 2), 2.4, 0.2, 0, Math.PI * 2); g.fill();
      g.strokeStyle = 'rgba(74,58,44,.42)'; g.lineWidth = 1.2; g.stroke();
    }
  }

  /* 地表的雪堆：**贴着板顶的几坨低雪包**。
     一整条平板雪面看着像"刷了白漆的木板"，加几坨吹雪堆才有"积雪"的意思。
     位置按列号取，不用随机 —— 否则每帧风一吹雪包就换地方。 */
  if (snowy) {
    for (let i = 0; i < 9; i++) {
      const sx = pl.x + 26 + ((i * 137 + seed * 7) % Math.max(40, pl.w - 52));
      const sr = 16 + ((i * 29) % 13);
      g.fillStyle = '#F2FAFF';
      g.beginPath();
      g.ellipse(sx, pl.y + 6, sr, sr * 0.42, 0, Math.PI, 0);
      g.closePath(); g.fill();
      g.fillStyle = 'rgba(255,255,255,.85)';
      g.beginPath();
      g.ellipse(sx - sr * 0.18, pl.y + 5, sr * 0.62, sr * 0.2, 0, Math.PI, 0);
      g.closePath(); g.fill();
    }
  }
}
/* 黑洞（吐怪巢）。**地面上塌出来的一个口**，不是飘着的传送门 ——
   飘着的传送门在横向平台里读作"出口"，玩家会去撞它；
   贴地的破口读作"危险"，绕开是本能反应。

   **2026-10-28 重画。** 用户指着截图说「黑洞是怎么回事 太突兀了点
   你可以地下做个玄关地方出来」。上一版确实像贴纸，三个原因都得改：

   ① **它悬在箱子顶上。** 生成侧用 `colTop` 取高度，那一列堆了两格箱子
      它就浮在半空 —— 先在地形这一层修掉（见 genLevel ⑥.5），这里只管画；
   ② **它是一块规整的椭圆。** 规整 = 贴图。所以底面先画一块**塌陷区**
      （不规则的破口 + 地板断面），洞是从这块断面里往下陷的，不是压在上面的；
   ③ **顶部那道高光弧把它画成了"眼睛"。** 那道弧是为了表现"口沿有厚度"，
      结果紫光 + 椭圆 + 亮上沿 = 一只竖着的眼睛。现在厚度改用**内壁**表达：
      口沿往下收两圈、越深越暗，光从**洞里往外透**，不从头顶照。

   埋进去的那点"玄关"：口的内侧有两级塌下去的石阶。它们不承担玩法，
   只是让这个口读起来"通向某个地方"，而不是"地上破了个洞"。 */
function drawNest(g, n) {
  const alive = n.left > 0;
  const cx = n.x;
  const cy = n.y;                     // 地板面。破口就开在这条线上
  const t = n.t || 0;
  const pulse = 0.5 + 0.5 * Math.sin(t * 2.2 + (n.seed || 0));
  const w = 32, h = 12;
  /* 楼板厚度。**破口必须挖穿它**，否则只是"地板上一个凹坑" —— 那是贴花，
     不是入口。26 是这个原型里楼板的固定厚度（GEN.thick）。 */
  const SLAB = 27;

  g.save();

  /* ---- ① 塌陷区：先把地板"啃掉"一块 ----
     上沿不规整（口沿），往下**收成漏斗**一直到楼板底 —— 收口才叫"塌"，
     直上直下叫"挖了个方坑"。边界抖动用固定伪随机（由 seed 决定），
     不能用 Math.random：那会每帧变一次，坑会像在呼吸一样抖。 */
  const jag = (i, base, amp) => {
    const s = Math.sin((n.seed || 0) * 12.9 + i * 7.13) * 0.5 + 0.5;
    return base + (s - 0.5) * amp;
  };
  const rimL = cx - (w + 9), rimR = cx + (w + 9);
  const rimPtsO = [];
  for (let i = 0; i <= 10; i++) {
    const a = Math.PI + (i / 10) * Math.PI;      // 上半圈：口沿
    const rx = w + 9 + jag(i, 0, 7);
    const ry = h + 6 + jag(i + 3, 0, 4);
    rimPtsO.push([cx + Math.cos(a) * rx, cy + Math.sin(a) * ry + 3]);
  }
  g.beginPath();
  rimPtsO.forEach((pt, i) => { if (i === 0) g.moveTo(pt[0], pt[1]); else g.lineTo(pt[0], pt[1]); });
  /* 漏斗：从口沿外缘收到楼板底，左右各收 12px。**底边要越过楼板底**
     （+5）—— 停在楼板底的话，下面会出现一条干净的直边，读作"洞下面贴了块补丁"，
     而不是"这一块楼板没了"。 */
  g.lineTo(rimR - 14, cy + SLAB + 5);
  g.lineTo(rimL + 14, cy + SLAB + 5);
  g.closePath();
  const funnel = g.createLinearGradient(0, cy - 12, 0, cy + SLAB);
  funnel.addColorStop(0, '#5A412A');    // 上沿：受光的地板断面
  funnel.addColorStop(0.55, '#4A3526');
  funnel.addColorStop(1, '#1B120C');    // 底：楼板下面，黑的
  g.fillStyle = funnel;
  g.fill();
  /* **只描口沿，不描下沿。** 整条闭合描边会让这块断面变成一个"贴在楼板上的
     单独图形"；只描上沿，它就是"楼板缺了一块"。 */
  g.beginPath();
  rimPtsO.forEach((pt, i) => { if (i === 0) g.moveTo(pt[0], pt[1]); else g.lineTo(pt[0], pt[1]); });
  g.strokeStyle = COL.ink; g.lineWidth = 2.4; g.stroke();

  /* ---- ② 光先打在地面和断面上，③ 洞壁再压上去 ----
     **顺序反过来会把洞壁照成一块紫色的垫子。** 光是从洞里往外跑的，
     它照亮的是口沿四周的地板，不是洞的内壁。
     —— 用户原话「太突兀」，一半是这个：紫光把整个洞口连同内壁糊成一团。 */
  /* ---- ③ 光：从**洞里**往外透，不是从头顶照下来 ----
     用加色混合，紫光才会真的把木地板推亮（亮色墙上 source-over 只涨 3%）。 */
  if (alive) {
    g.globalCompositeOperation = 'lighter';
    const gl = g.createRadialGradient(cx, cy + 2, 3, cx, cy + 2, 74);
    gl.addColorStop(0, 'rgba(196,110,255,' + (0.26 + 0.14 * pulse).toFixed(3) + ')');
    gl.addColorStop(0.5, 'rgba(140,80,224,' + (0.12 + 0.08 * pulse).toFixed(3) + ')');
    gl.addColorStop(1, 'rgba(110,70,200,0)');
    g.fillStyle = gl;
    g.beginPath(); g.ellipse(cx, cy + 2, 74, 34, 0, 0, Math.PI * 2); g.fill();
    g.globalCompositeOperation = 'source-over';
  }

  /* ---- ③ 内壁：往下一圈比一圈暗，深度是靠"层的颜色"读出来的 ----
     三圈，最后一圈贴到楼板底 —— 有这三圈，口才不是"地上印了个黑椭圆"。 */
  const rings = [
    { dx: 13, dy: 5, col: '#57402C' },
    { dx: 8,  dy: 3, col: '#33251A' },
    { dx: 3,  dy: 1, col: '#17100A' },
  ];
  for (const r of rings) {
    g.beginPath();
    g.ellipse(cx, cy + r.dy, w + r.dx, h + r.dy * 0.6, 0, Math.PI, Math.PI * 2);
    g.lineTo(cx + w + r.dx, cy + SLAB - 2);
    g.lineTo(cx - w - r.dx, cy + SLAB - 2);
    g.closePath();
    g.fillStyle = r.col; g.fill();
  }

  /* ---- ④ 洞口本身 ----
     中心纯黑、边缘带紫。**纯黑一块读不出深度**，得靠边缘那一圈紫说明
     "光在往外跑"。 */
  /* **口沿要"破"，不能是椭圆。** 一个规整的椭圆 + 一圈均匀描边，
     在放大图里就是"一个紫色铁盆"（第一版出图就是这样）。改成 14 个点的
     不规则闭合路径，半径按 seed 抖动 ±5px —— 它得看起来像"被顶开的"。 */
  const rimPts = [];
  for (let i = 0; i < 14; i++) {
    const a = (i / 14) * Math.PI * 2;
    const rj = 1 + jag(i + 9, 0, 0.16);
    rimPts.push([cx + Math.cos(a) * w * rj, cy + Math.sin(a) * h * rj * 1.02]);
  }
  /* **紫只留在最外一圈（12%）。** 上一版从 55% 就开始转紫，整个口读成
     "一块发光的紫色圆饼"——洞应该是黑的，紫是"光从里面跑出来"的那点边缘。 */
  const hole = g.createRadialGradient(cx, cy + 2, 2, cx, cy, w);
  hole.addColorStop(0, '#000000');
  hole.addColorStop(0.62, alive ? '#040209' : '#1C1C22');
  hole.addColorStop(0.88, alive ? '#150A26' : '#24242C');
  hole.addColorStop(1, alive ? '#2E1750' : '#2C2C34');
  g.fillStyle = hole;
  g.beginPath();
  rimPts.forEach((pt, i) => { if (i === 0) g.moveTo(pt[0], pt[1]); else g.lineTo(pt[0], pt[1]); });
  g.closePath(); g.fill();
  g.strokeStyle = COL.ink; g.lineWidth = 2.6; g.stroke();

  /* 口沿上缘的**细亮线**。只留 1.4px，跟着口沿走半圈 ——
     上一版是 2.4px 的整条亮弧，加上紫光就成了"眼白"。 */
  if (alive) {
    g.strokeStyle = 'rgba(212,182,255,' + (0.26 + 0.20 * pulse).toFixed(3) + ')';
    g.lineWidth = 1.4; g.lineCap = 'round';
    g.beginPath();
    for (let i = 0; i < 7; i++) {
      const pt = rimPts[i];
      if (i === 0) g.moveTo(pt[0], pt[1]); else g.lineTo(pt[0], pt[1]);
    }
    g.stroke();
    g.lineCap = 'butt';
  }

  /* ---- ⑤ 内侧三级石阶：这一点"玄关感"是用户直接点名的 ----
     一阶比一阶低、一阶比一阶窄，往洞底消失。
     它们不可交互，也不该被当成路 —— 所以只用弱光画台阶面、不描边，
     而且越往下越被洞口的黑吃掉。 */
  if (alive) {
    for (let i = 0; i < 3; i++) {
      const sy = cy + 5 + i * 5.6;
      const half = w * (0.78 - i * 0.19);
      /* **石阶是"石头"色，不是紫的。** 紫色台阶会把整个口读成"发光的碗"；
         石头只是被洞里的紫光照到，所以是"暖灰 + 一点点紫"，越往下越暗。 */
      g.fillStyle = 'rgba(122,108,96,' + (0.55 - i * 0.13).toFixed(3) + ')';
      g.beginPath();
      g.moveTo(cx - half, sy); g.lineTo(cx + half, sy);
      g.lineTo(cx + half * 0.9, sy + 3.4); g.lineTo(cx - half * 0.9, sy + 3.4);
      g.closePath(); g.fill();
      /* 台阶前沿的亮线：有它才读得出"这一级是往下踩的" */
      g.fillStyle = 'rgba(196,184,176,' + (0.34 - i * 0.09).toFixed(3) + ')';
      g.fillRect(cx - half, sy, half * 2, 1.1);
    }
  }

  /* ---- ⑥ 掀起的板边：**这是"从下面顶开"的关键一笔** ----
     左右各一块，朝外上方翘。没有它，口就只是"地上印了个黑椭圆"；
     有了它，地板是"被弄破"的，破坏留下了痕迹。 */
  const plank = (dir) => {
    g.save();
    /* **一头埋进地板、一头翘起来。** 上一版是整块浮在口沿上，读出两只"把手"；
       现在平移点压在口沿外侧、旋转幅度更大（0.62），埋进去的那一端被地板盖住，
       只留翘起的那半截 —— 这才是"被顶开"的板。 */
    g.translate(cx + dir * (w + 8), cy + 6);
    g.rotate(dir * -0.62);
    g.fillStyle = '#A87C4E';
    g.strokeStyle = COL.ink; g.lineWidth = 2.4;
    rr(g, -20, -3.2, 24, 6.4, 2);
    g.fill(); g.stroke();
    /* 断面（浅一档的木茬），让"厚度"读得出来 */
    g.fillStyle = '#D8B486';
    g.beginPath();
    g.moveTo(3, -3.2); g.lineTo(3, 3.2); g.lineTo(-2, 3.2); g.lineTo(-2, -3.2);
    g.closePath(); g.fill();
    /* 板头的一根木刺：断口不是平的 */
    g.fillStyle = '#A87C4E';
    g.beginPath(); g.moveTo(3.6, -2.6); g.lineTo(7.4, 0.4); g.lineTo(3.6, 1.4); g.closePath(); g.fill(); g.stroke();
    g.restore();
  };
  plank(-1); plank(1);

  /* ---- ⑦ 口沿的碎石与木屑：静态的（不用 sin 动），证明"这里碎过" ---- */
  for (let i = 0; i < 8; i++) {
    const a = Math.PI * (1.04 + (i / 7) * 0.92);
    const rx = w + 11 + jag(i + 5, 0, 5);
    const px = cx + Math.cos(a) * rx;
    const py = cy + Math.sin(a) * (h + 7) + 4;
    const sz = 1.6 + ((i * 37) % 5) * 0.42;
    g.fillStyle = i % 3 === 0 ? '#6B5236' : '#8A6C46';
    g.strokeStyle = 'rgba(40,28,18,.65)'; g.lineWidth = 1.1;
    g.beginPath();
    g.moveTo(px, py - sz);
    g.lineTo(px + sz, py);
    g.lineTo(px + sz * 0.4, py + sz * 0.8);
    g.lineTo(px - sz, py + sz * 0.3);
    g.closePath(); g.fill(); g.stroke();
  }

  /* ---- ⑧ 绕口沿转的光点（活着的巢才有）---- */
  if (alive) {
    for (let i = 0; i < 5; i++) {
      const a = t * 1.4 + i * (Math.PI * 2 / 5) + (n.seed || 0);
      const px = cx + Math.cos(a) * (w - 1);
      const py = cy + Math.sin(a) * (h - 1);
      const s = 1.4 + 1.2 * (0.5 + 0.5 * Math.sin(a * 2 + t * 3));
      g.fillStyle = 'rgba(204,176,255,' + (0.42 + 0.38 * Math.sin(a + t * 2)).toFixed(3) + ')';
      g.beginPath(); g.arc(px, py, Math.max(0.8, s), 0, Math.PI * 2); g.fill();
    }
  }

  /* ---- ⑨ 往上升的紫烟。**这一笔才让人读出"它在往外冒东西"** ----
     烟不到 20px 高：太高就会糊住上一层的箱子。 */
  if (alive) {
    for (let i = 0; i < 3; i++) {
      const ph = (t * 0.55 + i / 3 + (n.seed || 0) * 0.01) % 1;
      const wx = cx + Math.sin(ph * 6.4 + i * 2.1) * 9;
      const wy = cy - 4 - ph * 22;
      g.fillStyle = 'rgba(196,150,255,' + ((1 - ph) * 0.32).toFixed(3) + ')';
      g.beginPath(); g.arc(wx, wy, 3.2 + ph * 3.4, 0, Math.PI * 2); g.fill();
    }
  }

  /* 刚吐完那一瞬口沿发亮 */
  if (n.born > 0) {
    g.globalAlpha = n.born / 0.8 * 0.55;
    g.strokeStyle = '#D8C4FF'; g.lineWidth = 2.6;
    g.beginPath(); g.ellipse(cx, cy, w + 3, h + 3, 0, 0, Math.PI * 2); g.stroke();
    g.globalAlpha = 1;
  }
  g.restore();
}


function drawBox(g, b) {
  const def = NUM.box[b.mat];
  const hit = b.hitT > 0;
  /* **每一口箱子都有 3px 深描边。** 这一条是"Q 版卡通"最关键的东西 ——
     箱子铺满整层之后，没有描边的色块会连成一片"砖墙"，
     玩家读不出"这是一口一口独立的箱子"，也就读不出"能拆"。 */
  const INK = 3;

  /* ---- 木桶 ----
     **一个圆柱插进方块阵列，整片画面立刻就"不那么规矩"了。**
     画法只有三笔：鼓出来的桶身（两条二次曲线）、椭圆顶面、两道铁箍。
     桶身比格子收窄 4px：不收的话它和旁边的木箱严丝合缝贴在一起，
     又变回一块方砖了。 */
  if (b.barrel) {
    /* ================= 木桶重画（2026-10-29）=================
       用户：「箱子 桶 门 都需要重新规划　太不像了」。

       上一版是"两条二次曲线 + 一个椭圆 + 两道横线"：曲线鼓得不够、
       箍是两根直棍、桶口是一个扁椭圆 —— 48px 上读起来像一个**枕头**。

       这一版按真桶的三件事拆：
         ① **桶板（staves）**：竖着的 4 条微弯缝，从桶口通到桶底。
            没有它，桶就是一个上色的圆柱。
         ② **箍（hoops）**：不是两条线，是两条**带子** —— 有上沿高光、
            有下沿暗边、还比桶身宽 2px（真箍是箍在外面的）。
         ③ **桶口**：一个椭圆环（外沿亮、内圈暗）+ 一撮"里面是空的"的暗。
            原来的桶口是纯色椭圆，读起来像"桶封着盖"。
       桶身收口：上下各收 3px，中间鼓出去 —— 三条弧线定轮廓。 */
    const bx = b.x + 5, bw = b.w - 10;
    const top = b.y + 7, bot = b.y + b.h - 2;
    const mid = (top + bot) / 2;
    const cx = bx + bw / 2;
    const belly = bw / 2 + 2.5;        // 腰最鼓处
    const neck = bw / 2 - 3;           // 口/底收进来

    /* 桶身轮廓：上口 → 腰 → 底，左右各一条三次曲线 */
    const body = () => {
      g.beginPath();
      g.moveTo(cx - neck, top);
      g.bezierCurveTo(cx - belly, top + (bot - top) * 0.30, cx - belly, top + (bot - top) * 0.70, cx - neck, bot);
      g.lineTo(cx + neck, bot);
      g.bezierCurveTo(cx + belly, top + (bot - top) * 0.70, cx + belly, top + (bot - top) * 0.30, cx + neck, top);
      g.closePath();
    };
    body();
    g.fillStyle = hit ? '#FFE4BE' : '#C98F52';
    g.fill();

    /* 桶板缝：跟着轮廓微微外扩。**只在桶身内部**，用 clip 保证不出界。 */
    g.save(); body(); g.clip();
    g.strokeStyle = 'rgba(122,80,42,.42)'; g.lineWidth = 1.5;
    for (const t of [-0.62, -0.21, 0.21, 0.62]) {
      g.beginPath();
      g.moveTo(cx + neck * t, top + 1);
      g.bezierCurveTo(cx + belly * t, top + (bot - top) * 0.30, cx + belly * t, top + (bot - top) * 0.70, cx + neck * t, bot);
      g.stroke();
    }
    /* 左侧受光（光源统一左上）：一条竖着的高光，宽度只有桶身的 1/5 */
    const hl = g.createLinearGradient(bx, 0, bx + bw, 0);
    hl.addColorStop(0, 'rgba(255,240,214,.42)');
    hl.addColorStop(0.38, 'rgba(255,240,214,0)');
    hl.addColorStop(1, 'rgba(72,42,18,.20)');
    g.fillStyle = hl; g.fillRect(bx - 4, top, bw + 8, bot - top);
    g.restore();

    /* 箍：**带子，不是线。** 比桶身宽 2px，上有高光下有暗边。 */
    for (const t of [0.30, 0.72]) {
      const hy = top + (bot - top) * t;
      const hw = belly * (0.86 + 0.14 * Math.sin(Math.PI * t));
      g.fillStyle = 'rgba(74,58,44,.95)';
      rr(g, cx - hw - 1, hy - 3, hw * 2 + 2, 6, 2.4); g.fill();
      g.fillStyle = 'rgba(236,214,186,.5)';
      g.fillRect(cx - hw, hy - 2.6, hw * 2, 1.4);
    }

    /* 桶口：外沿 + 内圈暗 + 板头 */
    g.fillStyle = hit ? '#F6DFC0' : '#A96C36';
    g.beginPath(); g.ellipse(cx, top, neck + 0.5, 5.2, 0, 0, Math.PI * 2); g.fill();
    g.fillStyle = 'rgba(58,36,18,.55)';
    g.beginPath(); g.ellipse(cx, top + 0.6, neck - 3.2, 3.4, 0, 0, Math.PI * 2); g.fill();
    g.strokeStyle = 'rgba(255,240,214,.55)'; g.lineWidth = 1.2;
    for (const t of [-0.55, 0, 0.55]) {
      g.beginPath();
      g.moveTo(cx + (neck - 3) * t, top - 1.6);
      g.lineTo(cx + (neck - 3) * t, top + 3.2);
      g.stroke();
    }

    /* 统一描边（和木箱同一套） */
    g.strokeStyle = COL.ink; g.lineWidth = 3; g.lineJoin = 'round';
    body(); g.stroke();
    g.strokeStyle = COL.ink; g.lineWidth = 2.4;
    g.beginPath(); g.ellipse(cx, top, neck + 0.5, 5.2, 0, 0, Math.PI * 2); g.stroke();
    return;
  }

  /* ---- 陶罐 ----
     **它以前是装饰（能穿过去），现在是实体（能撞碎）。** 用户 2026-10-28
     的原话是「又不形成阻挡啥的 就是个图贴上去」—— 一个"看着能装东西"的罐子
     如果人能从它身上走过去，那这个场景就没有可信度。
     现在凡是落地的东西都走这套碰撞：撞得动、打得碎、碎了掉雪弹。 */
  if (b.jar) {
    const jx = b.x + b.w / 2;
    const jw = b.w * 0.36;
    const jTop = b.y + 5, jBot = b.y + b.h;
    g.fillStyle = hit ? '#FFF2DC' : '#D3BE9C';
    g.beginPath();
    g.moveTo(jx - jw * 0.62, jTop + 3);
    g.quadraticCurveTo(jx - jw * 1.25, jTop + (jBot - jTop) * 0.55, jx - jw * 0.7, jBot - 3);
    g.lineTo(jx + jw * 0.7, jBot - 3);
    g.quadraticCurveTo(jx + jw * 1.25, jTop + (jBot - jTop) * 0.55, jx + jw * 0.62, jTop + 3);
    g.closePath(); g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.8; g.lineJoin = 'round'; g.stroke();
    /* 罐口：一小段椭圆 + 里面一点暗，证明"口是开着"的 */
    g.fillStyle = hit ? '#FFF6E6' : '#BFA985';
    g.beginPath(); g.ellipse(jx, jTop + 3, jw * 0.66, 3.4, 0, 0, Math.PI * 2); g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.2; g.stroke();
    /* 腰上两道釉纹：有它们才像个陶器而不是一颗蛋 */
    g.strokeStyle = 'rgba(112,88,58,.42)'; g.lineWidth = 1.8;
    for (const yy of [jTop + (jBot - jTop) * 0.36, jTop + (jBot - jTop) * 0.60]) {
      g.beginPath();
      g.moveTo(jx - jw * 1.02, yy); g.lineTo(jx + jw * 1.02, yy);
      g.stroke();
    }
    g.fillStyle = 'rgba(255,250,238,.5)';
    g.beginPath(); g.ellipse(jx - jw * 0.42, jTop + (jBot - jTop) * 0.46, 2.2, (jBot - jTop) * 0.24, 0, 0, Math.PI * 2); g.fill();
    return;
  }

  if (b.mat === 'wood') {
    /* ================= 木箱重画（2026-10-29）=================
       用户：「箱子 桶 门 都需要重新规划　太不像了」。

       上一版是"填色 + 一圈木框 + 一条腰板 + 一条顶亮"。
       问题是这三笔都在说同一件事（"这是个盒子"），而且都在**平面**上：
       一整层铺过去就是一片带横线的色块，用户读成"砖墙"。

       这一版补的是**结构**，不是装饰：
         ① 竖板缝 —— 证明箱壁是几块板拼的；
         ② **对角撑 X** —— "板条箱"最省也最准的一笔（不斜撑扛不住竖着摞），
            也是上一版最缺的一笔；
         ③ 四角护铁 —— "钉起来的"，不是糊起来的；
         ④ 顶盖亮边 —— 光源统一左上。
       全部走"细、淡、贴着轮廓"的路子，因为一屏有几十口箱子：
       任何一笔重了，整层就变成噪点。 */
    const X = b.x, Y = b.y, W = b.w, H = b.h;
    g.fillStyle = hit ? '#FFDDB0' : COL.wood;
    rr(g, X, Y, W, H, 5); g.fill();

    /* ① 板缝 */
    g.strokeStyle = 'rgba(132,90,46,.20)'; g.lineWidth = 1.4;
    for (const t of [0.26, 0.5, 0.74]) {
      g.beginPath(); g.moveTo(X + W * t, Y + 4); g.lineTo(X + W * t, Y + H - 4); g.stroke();
    }

    /* ② 对角撑 X（裁在箱体内） */
    g.save();
    rr(g, X, Y, W, H, 5); g.clip();
    g.strokeStyle = 'rgba(206,158,100,.88)'; g.lineWidth = 5.5; g.lineCap = 'round';
    g.beginPath(); g.moveTo(X + 6, Y + 6); g.lineTo(X + W - 6, Y + H - 6); g.stroke();
    g.beginPath(); g.moveTo(X + W - 6, Y + 6); g.lineTo(X + 6, Y + H - 6); g.stroke();
    /* 斜撑下沿一根暗线：给出"板条压在箱面上"的厚度，不至于两条亮带飘着 */
    g.strokeStyle = 'rgba(112,72,34,.45)'; g.lineWidth = 1.6; g.lineCap = 'butt';
    g.beginPath(); g.moveTo(X + 8, Y + 10); g.lineTo(X + W - 10, Y + H - 8); g.stroke();
    g.beginPath(); g.moveTo(X + W - 10, Y + 10); g.lineTo(X + 8, Y + H - 8); g.stroke();
    g.restore();

    /* ③ 木框（内缩一圈的深色边）。**X 之后必须有它** ——
       只有 X 的话箱面是一块"打了叉的板"，加上这圈框才读成"箱体"。 */
    g.strokeStyle = 'rgba(122,81,39,.42)'; g.lineWidth = 3.5;
    rr(g, X + 4, Y + 4, W - 8, H - 8, 3); g.stroke();

    /* ④ 四角护铁 + 钉眼 */
    for (const sx of [0, 1]) {
      for (const sy of [0, 1]) {
        const px = X + (sx ? W - 12 : 1), py = Y + (sy ? H - 12 : 1);
        g.fillStyle = 'rgba(78,54,32,.42)';
        rr(g, px, py, 11, 11, 3); g.fill();
        g.fillStyle = 'rgba(232,206,170,.55)';
        g.beginPath(); g.arc(px + (sx ? 8 : 3), py + (sy ? 8 : 3), 1.2, 0, Math.PI * 2); g.fill();
      }
    }

    /* ⑤ 顶盖亮边 */
    g.fillStyle = 'rgba(255,246,228,.50)';
    rr(g, X + 4, Y + 3, W - 8, 5, 2.5); g.fill();
  } else if (b.mat === 'stone') {
    g.fillStyle = hit ? '#E2D3BE' : COL.stone;
    rr(g, b.x, b.y, b.w, b.h, 6); g.fill();
    /* 高光比木箱弱一档。**石箱占总数的 20% 左右，它不该比主材质更抢眼** ——
       上一版石箱冲到 '#CFC7BE' 还带 .42 的白条，一整层看过去先看到的是灰块。 */
    g.fillStyle = 'rgba(255,255,255,.24)';
    rr(g, b.x + 5, b.y + 4, b.w - 10, 7, 3); g.fill();
    /* 石纹：**绝对不能画成折线。** 48px 的箱子里，「↗ + ↘」两笔就是一个
       正正经经的向上箭头 —— 一整排石箱连起来像一排路标，玩家会以为
       那些箱子能往上爬。改用低透明度的斑块，只表达"这是块石头"。 */
    g.fillStyle = 'rgba(110,92,74,.20)';
    g.beginPath(); g.ellipse(b.x + 17, b.y + 31, 7, 4.4, -0.4, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.ellipse(b.x + 33, b.y + 21, 4.4, 3.2, 0.5, 0, Math.PI * 2); g.fill();
  } else if (b.mat === 'iron') {
    g.fillStyle = hit ? '#D8E6F0' : COL.iron;
    rr(g, b.x, b.y, b.w, b.h, 4); g.fill();
    g.strokeStyle = 'rgba(80,100,118,.6)';
    g.lineWidth = 3;
    rr(g, b.x + 5, b.y + 5, b.w - 10, b.h - 10, 2); g.stroke();
    // 四角铆钉
    g.fillStyle = '#E8F2FA';
    for (const [dx, dy] of [[9, 9], [39, 9], [9, 39], [39, 39]]) {
      g.beginPath(); g.arc(b.x + dx, b.y + dy, 3, 0, Math.PI * 2); g.fill();
    }
  } else if (b.mat === 'ice') {
    /* 冰墙。**必须看起来像一整块冰，不能像瓷砖。** */
    const ig = g.createLinearGradient(b.x, b.y, b.x + b.w, b.y + b.h);
    ig.addColorStop(0, 'rgba(212,244,255,.95)');
    ig.addColorStop(0.55, 'rgba(140,206,238,.92)');
    ig.addColorStop(1, 'rgba(178,228,250,.95)');
    g.fillStyle = ig;
    rr(g, b.x, b.y, b.w, b.h, 5); g.fill();
    g.fillStyle = 'rgba(255,255,255,.5)';
    for (const [dx, dy, r] of [[14, 13, 3], [31, 21, 2], [19, 35, 2.4], [37, 39, 1.7], [9, 27, 1.4]]) {
      g.beginPath(); g.arc(b.x + dx, b.y + dy, r, 0, Math.PI * 2); g.fill();
    }
    g.strokeStyle = 'rgba(255,255,255,.85)';
    g.lineWidth = 2.5;
    g.beginPath();
    g.moveTo(b.x + 7, b.y + b.h - 9);
    g.lineTo(b.x + 19, b.y + 15);
    g.lineTo(b.x + b.w - 7, b.y + 7);
    g.stroke();
  }

  /* ---- 体积：一层斜向的明暗 ----
     **一笔管住全部材质。** 木框、腰板、石斑、铆钉、冰晶各自的细节其实都写了，
     但每一个都是"平涂 + 点缀" —— 一屏几十口箱子铺过去，整片就是纸片，
     角色反倒成了画面里唯一有立体的东西，比不画还割裂。

     不去逐个材质改，是因为逐改必然改出五六种不同的受光方向（木箱亮右上、
     石箱亮左上……），那比平涂更乱。这里在统一描边**之前**压一层从左上到
     右下的渐变：左上提亮、右下压暗，所有材质同时获得同一个光源。
     放在描边之前，是为了让那圈 3px 的深色轮廓始终保持干净 ——
     描边一旦被渐变盖住，箱子之间就连成一片，读不出"一口一口"了。 */
  if (!b.jar && !b.barrel) {
    g.save();
    rr(g, b.x, b.y, b.w, b.h, b.mat === 'iron' ? 4 : 6);
    g.clip();
    const vg = g.createLinearGradient(b.x - b.w * 0.1, b.y - b.h * 0.1,
                                      b.x + b.w * 0.95, b.y + b.h * 1.05);
    vg.addColorStop(0, 'rgba(255,252,240,.20)');
    vg.addColorStop(0.40, 'rgba(255,255,255,0)');
    vg.addColorStop(1, 'rgba(58,36,16,.22)');
    g.fillStyle = vg;
    g.fillRect(b.x, b.y, b.w, b.h);
    g.restore();
  }

  // 统一描边（冰用蓝墨，其余用暖褐）
  g.strokeStyle = b.mat === 'ice' ? COL.iceInk : COL.ink;
  g.lineWidth = INK;
  g.lineJoin = 'round';
  rr(g, b.x + 1, b.y + 1, b.w - 2, b.h - 2, b.mat === 'iron' ? 4 : 6);
  g.stroke();

  /* ---- 金箱 ----
     **它是"探索"的招牌**：箱山最高处那一口、金色、会闪。
     要做成一眼能从几十口箱子里挑出来的东西，所以除了换色，
     还要加"描边更亮 + 中间一个锁孔 + 一圈呼吸光"。 */
  if (b.loot) {
    g.fillStyle = COL.loot;
    rr(g, b.x, b.y, b.w, b.h, 6); g.fill();
    g.fillStyle = 'rgba(255,255,255,.5)';
    rr(g, b.x + 5, b.y + 4, b.w - 10, 8, 4); g.fill();
    g.strokeStyle = COL.lootInk;
    g.lineWidth = 3;
    rr(g, b.x + 6, b.y + 6, b.w - 12, b.h - 12, 4); g.stroke();
    // 锁孔
    g.fillStyle = COL.lootInk;
    g.beginPath(); g.arc(b.x + b.w / 2, b.y + b.h * 0.46, 5, 0, Math.PI * 2); g.fill();
    g.fillRect(b.x + b.w / 2 - 2.5, b.y + b.h * 0.46, 5, 10);
    // 呼吸光
    const pulse = 0.35 + 0.25 * Math.sin(S.t * 3.4 + b.x * 0.02);
    g.strokeStyle = 'rgba(255,224,130,' + pulse.toFixed(3) + ')';
    g.lineWidth = 5;
    rr(g, b.x - 3, b.y - 3, b.w + 6, b.h + 6, 9); g.stroke();
  }

  /* 覆霜木箱。**这是"这里能挖穿"的唯一线索** ——
     不是图标、不是箭头，就是一层霜和几缕往上飘的寒气。 */
  if (b.frost) {
    g.globalAlpha = 0.55 + 0.14 * Math.sin(S.t * 2.2 + b.x * 0.03);
    g.fillStyle = '#EAF8FF';
    rr(g, b.x + 5, b.y + 4, b.w - 10, b.h - 10, 5); g.fill();
    g.globalAlpha = 1;
    g.strokeStyle = 'rgba(120,190,225,.9)';
    g.lineWidth = 2;
    rr(g, b.x + 7, b.y + 6, b.w - 14, b.h - 14, 4); g.stroke();
    for (let i = 0; i < 3; i++) {
      const ph = (S.t * 0.5 + i * 0.34 + b.x * 0.01) % 1;
      g.globalAlpha = (1 - ph) * 0.65;
      g.fillStyle = '#DCF4FF';
      g.beginPath();
      g.arc(b.x + 12 + i * 12, b.y - 3 - ph * 22, Math.max(0.6, 2.8 - ph * 1.6), 0, Math.PI * 2);
      g.fill();
    }
    g.globalAlpha = 1;
  }

  // 拆到一半：裂痕密度跟着 HP 走，玩家能看出"还差几发"
  if (def.hp !== Infinity && b.hp < def.hp) {
    g.globalAlpha = 0.55;
    g.strokeStyle = '#5B4A32';
    g.lineWidth = 2;
    const n = def.hp - b.hp;
    for (let i = 0; i < n; i++) {
      g.beginPath();
      g.moveTo(b.x + 8 + i * 13, b.y + 10);
      g.lineTo(b.x + 16 + i * 13, b.y + 28);
      g.lineTo(b.x + 10 + i * 13, b.y + 40);
      g.stroke();
    }
    g.globalAlpha = 1;
  }
}

/* 场景道具。**全部是纯装饰，不碰碰撞。**
   它们的作用是给"空的那一大块"填可读的内容，同时说一句"这里有人住过"：
   吊灯 = 有人点灯；木桶罐子 = 有人存货；路牌 = 有人留过路；
   蛛网 = 很久没人来了。**每一件都必须有描边** —— 和箱子同一套视觉语言，
   不描边的道具在卡通画面里读作"贴纸"。 */
/* ================= 挂在墙上的东西要"退到墙里去" =================
   原来挂件和箱子用同一套描边（COL.ink 2.5px）、同样的饱和度，
   在画面上读起来和"能撞的东西"是同一层 —— 用户 2026-10-28 的原话是
   「有一些和战斗无关的凸显出来 …… 就是个图贴上去」。
   两件事解决：
   ① 先垫一片贴墙的柔影。**贴纸没有影子**，有影子才会被读成"挂在墙上的实体"；
   ② 整体降到 66% 不透明度，颜色自动混向墙色 —— 这就是最廉价的空气透视，
      不用改任何一支笔画里的颜色。
   **自发光的三件（吊灯 / 枝形吊灯 / 灯笼）不做降透明**：光不跟着距离变淡，
   把光也压掉会变成"屋里点着灯却一片黑"。它们只吃影子那一笔（其实也没有，
   光源不给自己投影下方）。 */
const DECO_LIGHT = ['lamp', 'chandelier', 'lantern'];
/* 影子尺寸按"这件东西在墙上的占地"给：[半宽, 半高, 中心偏移x, 中心偏移y]。
   没有表项的（三盏灯）就不画影子。 */
const DECO_SHADOW = {
  beam: [84, 13, 0, 12],
  rope: [15, 33, 0, 30],
  vine: [14, 42, -4, 40],
  web: [26, 26, 18, 20],
  flag: [22, 18, 16, 24],
};
function drawDecoShadow(g, d) {
  const sh = DECO_SHADOW[d.kind];
  if (!sh) return;
  const rx = sh[0], ry = sh[1], cx = d.x + sh[2], cy = d.y + sh[3];
  const rr0 = Math.max(rx, ry);
  const rg = g.createRadialGradient(cx, cy, 1, cx, cy, rr0);
  rg.addColorStop(0, 'rgba(50,32,18,.32)');
  rg.addColorStop(0.55, 'rgba(50,32,18,.15)');
  rg.addColorStop(1, 'rgba(50,32,18,0)');
  g.save();
  g.translate(cx, cy);
  g.scale(1, ry / rr0);
  g.translate(-cx, -cy);
  g.fillStyle = rg;
  g.beginPath(); g.arc(cx, cy, rr0, 0, Math.PI * 2); g.fill();
  g.restore();
}
/* 退后的程度**按"它像不像能站的东西"分档**，不是一刀切。
   横梁最像平台（一整条水平线、还带描边），压得最狠；
   蛛网本来就该是半透明的，跟着压一档；其余 0.66。 */
const DECO_FAR = { beam: 0.54, web: 0.56 };
function drawDeco(g, d) {
  if (!d.ceil) { drawDecoBody(g, d); return; }
  drawDecoShadow(g, d);
  if (DECO_LIGHT.indexOf(d.kind) >= 0) { drawDecoBody(g, d); return; }
  g.save();
  g.globalAlpha = (DECO_FAR[d.kind] != null) ? DECO_FAR[d.kind] : 0.66;
  drawDecoBody(g, d);
  g.restore();
}
function drawDecoBody(g, d) {
  const k = d.kind;
  const s = d.seed || 0;
  const x = d.x, y = d.y;
  g.save();
  g.lineJoin = 'round';

  if (k === 'lamp') {
    const sway = Math.sin(S.t * 1.1 + s) * 2;
    g.strokeStyle = '#6B4C34'; g.lineWidth = 2.5;
    g.beginPath(); g.moveTo(x, y); g.lineTo(x + sway, y + 30); g.stroke();
    /* 暖光。**这是地下唯一的光源叙事** —— 没有它，木墙是一块均匀的米色；
       有了它，画面上就有"亮处"和"暗处"，房间才有体积。 */
    const rg = g.createRadialGradient(x + sway, y + 44, 3, x + sway, y + 44, 84);
    rg.addColorStop(0, 'rgba(255,238,186,.46)');
    rg.addColorStop(.5, 'rgba(255,214,130,.16)');
    rg.addColorStop(1, 'rgba(255,222,140,0)');
    /* **加色混合（lighter）。** 木屋/砖房的墙本身是亮米色，
       用 source-over 叠一层暖黄，亮度只涨 3%~5% —— 出图上等于没打光。
       lighter 是逐通道相加，同样的颜色能把墙面从 (232,211,174) 推到 (250,242,205)，
       光斑这才成立。三个光源（lamp/chandelier/lantern）都走这条路。 */
    g.globalCompositeOperation = 'lighter';
    g.fillStyle = rg;
    g.beginPath(); g.arc(x + sway, y + 44, 80, 0, Math.PI * 2); g.fill();
    g.globalCompositeOperation = 'source-over';
    g.beginPath();
    g.moveTo(x + sway - 15, y + 40);
    g.lineTo(x + sway - 7, y + 31);
    g.lineTo(x + sway + 7, y + 31);
    g.lineTo(x + sway + 15, y + 40);
    g.closePath();
    g.fillStyle = '#FFD45E'; g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.stroke();
    g.fillStyle = '#FFF6D2';
    g.beginPath(); g.arc(x + sway, y + 42, 4.5, 0, Math.PI * 2); g.fill();
  } else if (k === 'chandelier') {
    /* 枝形吊灯 = 这层的**主灯**。和 lamp 的分工是"面"与"点"：
       lamp 是一个光锥，chandelier 是一圈大底光 + 三簇跳动的火苗。
       远看一眼就知道这是有主人的房间，不是废弃走廊 —— 这是"丰富"里最省力的一笔。 */
    const sw = Math.sin(S.t * 0.8 + s) * 1.6;
    /* 先铺光晕再画灯体。**顺序反了烛火会被暖光糊掉**，只剩一团黄。 */
    const rg = g.createRadialGradient(x + sw, y + 36, 5, x + sw, y + 36, 104);
    rg.addColorStop(0, 'rgba(255,242,200,.52)');
    rg.addColorStop(.42, 'rgba(255,214,130,.20)');
    rg.addColorStop(1, 'rgba(255,206,110,0)');
    g.globalCompositeOperation = 'lighter';
    g.fillStyle = rg;
    g.beginPath(); g.arc(x + sw, y + 36, 104, 0, Math.PI * 2); g.fill();
    g.globalCompositeOperation = 'source-over';

    g.strokeStyle = '#6B4C34'; g.lineWidth = 2.5;
    g.beginPath(); g.moveTo(x, y); g.lineTo(x + sw, y + 13); g.stroke();
    /* 顶盘 + 中轴 */
    g.beginPath(); g.ellipse(x + sw, y + 17, 8, 4, 0, 0, Math.PI * 2);
    g.fillStyle = '#C9A24E'; g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.stroke();
    /* 两条外扬的臂 + 中间一根短臂。**臂要下垂再上挑**，直线臂读作"衣架"。 */
    g.strokeStyle = '#8C6B3A'; g.lineWidth = 3; g.lineCap = 'round';
    for (const dir of [-1, 1]) {
      g.beginPath();
      g.moveTo(x + sw, y + 20);
      g.quadraticCurveTo(x + sw + dir * 12, y + 32, x + sw + dir * 21, y + 26);
      g.stroke();
    }
    g.beginPath(); g.moveTo(x + sw, y + 20); g.lineTo(x + sw, y + 28); g.stroke();
    /* 三根蜡烛 + 火苗。火苗半径随 t 抖，"活着"的感觉全靠这一点。 */
    for (let i = 0; i < 3; i++) {
      const cx = x + sw + (i - 1) * 21;
      const cy = y + (i === 1 ? 28 : 26);
      g.fillStyle = '#F6E6CE';
      g.fillRect(cx - 2.5, cy - 9, 5, 10);
      g.strokeStyle = COL.ink; g.lineWidth = 1.8; g.strokeRect(cx - 2.5, cy - 9, 5, 10);
      const fl = 3.4 + Math.sin(S.t * 6.5 + i * 2.1 + s) * 0.9;
      g.beginPath();
      g.moveTo(cx, cy - 9 - fl * 2);
      g.quadraticCurveTo(cx + fl, cy - 9 - fl * 0.4, cx, cy - 8);
      g.quadraticCurveTo(cx - fl, cy - 9 - fl * 0.4, cx, cy - 9 - fl * 2);
      g.fillStyle = '#FFCE5A'; g.fill();
      g.fillStyle = '#FFF6D2';
      g.beginPath(); g.arc(cx, cy - 10.5, 1.4, 0, Math.PI * 2); g.fill();
    }
  } else if (k === 'lantern') {
    /* 挂灯笼。**比吊灯矮、比吊灯软**，是画面里的暖色点缀 ——
       一层全是硬邦邦的木箱和石砖时，只有这种圆的东西能救节奏。 */
    const sw = Math.sin(S.t * 1.4 + s) * 2.4;
    const bx = x + sw, by = y + 18;
    const rg = g.createRadialGradient(bx, by + 15, 3, bx, by + 15, 70);
    rg.addColorStop(0, 'rgba(255,222,164,.42)');
    rg.addColorStop(.5, 'rgba(255,204,140,.14)');
    rg.addColorStop(1, 'rgba(255,200,120,0)');
    g.globalCompositeOperation = 'lighter';
    g.fillStyle = rg;
    g.beginPath(); g.arc(bx, by + 15, 74, 0, Math.PI * 2); g.fill();
    g.globalCompositeOperation = 'source-over';

    g.strokeStyle = '#6B4C34'; g.lineWidth = 2;
    g.beginPath(); g.moveTo(x, y); g.lineTo(bx, by); g.stroke();
    /* 灯身：上下收口的鼓形 */
    g.beginPath();
    g.moveTo(bx - 8, by);
    g.quadraticCurveTo(bx - 16, by + 15, bx - 8, by + 29);
    g.lineTo(bx + 8, by + 29);
    g.quadraticCurveTo(bx + 16, by + 15, bx + 8, by);
    g.closePath();
    g.fillStyle = '#E8564C'; g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.stroke();
    /* 三道亮肋 —— 只为了让人读出"这是布/纸糊的"，不是铁皮桶。 */
    g.strokeStyle = 'rgba(255,212,94,.85)'; g.lineWidth = 1.6;
    for (const dx of [-5, 0, 5]) {
      g.beginPath(); g.moveTo(bx + dx, by + 3); g.lineTo(bx + dx, by + 26); g.stroke();
    }
    g.fillStyle = '#8C6B3A';
    g.fillRect(bx - 9, by - 3, 18, 4);
    g.strokeStyle = COL.ink; g.lineWidth = 1.8; g.strokeRect(bx - 9, by - 3, 18, 4);
    g.fillRect(bx - 9, by + 28, 18, 4);
    g.strokeRect(bx - 9, by + 28, 18, 4);
    /* 下面一撮流苏 */
    g.strokeStyle = '#C9A24E'; g.lineWidth = 2;
    for (const dx of [-3, 0, 3]) {
      g.beginPath(); g.moveTo(bx + dx, by + 32); g.lineTo(bx + dx * 1.6, by + 40); g.stroke();
    }
  } else if (k === 'beam') {
    g.fillStyle = '#B77F44';
    g.fillRect(x - 80, y + 5, 160, 14);
    g.strokeStyle = COL.ink; g.lineWidth = 2.5;
    g.strokeRect(x - 80, y + 5, 160, 14);
    g.fillStyle = 'rgba(255,240,210,.32)';
    g.fillRect(x - 78, y + 7, 156, 4);
  } else if (k === 'rope') {
    g.strokeStyle = '#C79A64'; g.lineWidth = 3;
    g.beginPath(); g.moveTo(x - 9, y); g.lineTo(x - 9, y + 58); g.stroke();
    g.beginPath(); g.moveTo(x + 9, y); g.lineTo(x + 9, y + 58); g.stroke();
    for (let i = 0; i < 4; i++) {
      const yy = y + 9 + i * 14;
      g.beginPath(); g.moveTo(x - 9, yy); g.lineTo(x + 9, yy); g.stroke();
    }
  } else if (k === 'vine') {
    g.strokeStyle = '#6FAE5C'; g.lineWidth = 3;
    g.beginPath(); g.moveTo(x, y);
    for (let i = 0; i <= 8; i++) g.lineTo(x + Math.sin(i * 0.9 + s) * 7, y + i * 9);
    g.stroke();
    g.fillStyle = '#8CCB74';
    for (let i = 1; i < 7; i += 2) {
      g.beginPath();
      g.ellipse(x + Math.sin(i * 0.9 + s) * 7 + 5, y + i * 9, 5, 3, 0.5, 0, Math.PI * 2);
      g.fill();
    }
  } else if (k === 'web') {
    g.strokeStyle = 'rgba(255,255,255,.5)'; g.lineWidth = 1.5;
    for (let i = 0; i < 5; i++) {
      const a = Math.PI * i / 8;
      g.beginPath(); g.moveTo(x, y); g.lineTo(x + Math.cos(a) * 40, y + Math.sin(a) * 40); g.stroke();
    }
    for (let r = 12; r <= 36; r += 12) {
      g.beginPath();
      for (let i = 0; i < 5; i++) {
        const a = Math.PI * i / 8;
        const px = x + Math.cos(a) * r, py = y + Math.sin(a) * r;
        if (i === 0) g.moveTo(px, py); else g.lineTo(px, py);
      }
      g.stroke();
    }
  } else if (k === 'flag') {
    g.strokeStyle = '#6B4C34'; g.lineWidth = 2;
    g.beginPath(); g.moveTo(x, y); g.lineTo(x, y + 15); g.stroke();
    const wave = Math.sin(S.t * 2.2 + s) * 3;
    g.beginPath();
    g.moveTo(x, y + 15);
    g.quadraticCurveTo(x + 16, y + 15 + wave, x + 32, y + 19);
    g.lineTo(x + 32, y + 33);
    g.quadraticCurveTo(x + 16, y + 29 + wave, x, y + 31);
    g.closePath();
    g.fillStyle = '#E8564C'; g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2; g.stroke();
  } else if (k === 'barrel') {
    g.beginPath();
    g.moveTo(x - 13, y - 30);
    g.quadraticCurveTo(x - 18, y - 15, x - 13, y);
    g.lineTo(x + 13, y);
    g.quadraticCurveTo(x + 18, y - 15, x + 13, y - 30);
    g.closePath();
    g.fillStyle = '#C99358'; g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.stroke();
    g.strokeStyle = 'rgba(122,81,39,.7)'; g.lineWidth = 2;
    g.beginPath(); g.moveTo(x - 16, y - 21); g.lineTo(x + 16, y - 21); g.stroke();
    g.beginPath(); g.moveTo(x - 16, y - 9); g.lineTo(x + 16, y - 9); g.stroke();
    g.fillStyle = '#E0A96D';
    g.beginPath(); g.ellipse(x, y - 30, 13, 4.5, 0, 0, Math.PI * 2); g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2; g.stroke();
  } else if (k === 'jar') {
    g.beginPath();
    g.moveTo(x - 9, y - 24);
    g.quadraticCurveTo(x - 13, y - 10, x - 9, y);
    g.lineTo(x + 9, y);
    g.quadraticCurveTo(x + 13, y - 10, x + 9, y - 24);
    g.closePath();
    g.fillStyle = '#8FC4E4'; g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.stroke();
    g.fillStyle = '#C6E6F6';
    g.fillRect(x - 7, y - 27, 14, 5);
    g.strokeStyle = COL.ink; g.lineWidth = 2; g.strokeRect(x - 7, y - 27, 14, 5);
  } else if (k === 'sign') {
    g.fillStyle = '#A9713F';
    g.fillRect(x - 3, y - 26, 6, 26);
    g.strokeStyle = COL.ink; g.lineWidth = 2; g.strokeRect(x - 3, y - 26, 6, 26);
    g.beginPath();
    g.moveTo(x - 20, y - 40); g.lineTo(x + 16, y - 40); g.lineTo(x + 26, y - 32);
    g.lineTo(x + 16, y - 24); g.lineTo(x - 20, y - 24);
    g.closePath();
    g.fillStyle = '#E8C79A'; g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.stroke();
    g.strokeStyle = 'rgba(74,58,44,.7)'; g.lineWidth = 2;
    g.beginPath(); g.moveTo(x - 12, y - 32); g.lineTo(x + 8, y - 32); g.stroke();
  } else if (k === 'mush') {
    const hh = 12 + (s % 6);
    g.fillStyle = '#F6E6CE';
    g.fillRect(x - 3, y - hh, 6, hh);
    g.strokeStyle = COL.ink; g.lineWidth = 2; g.strokeRect(x - 3, y - hh, 6, hh);
    g.beginPath();
    g.ellipse(x, y - hh, 12, 9, 0, Math.PI, 0);
    g.closePath();
    g.fillStyle = '#E8564C'; g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.stroke();
    g.fillStyle = 'rgba(255,255,255,.85)';
    g.beginPath(); g.arc(x - 4, y - hh - 3, 2.4, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(x + 4, y - hh - 1, 1.8, 0, Math.PI * 2); g.fill();
  } else if (k === 'shelf') {
    g.fillStyle = '#B77F44';
    g.fillRect(x - 26, y - 5, 52, 7);
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.strokeRect(x - 26, y - 5, 52, 7);
    g.fillStyle = '#8FC4E4';
    g.fillRect(x - 18, y - 21, 11, 16);
    g.strokeStyle = COL.ink; g.lineWidth = 2; g.strokeRect(x - 18, y - 21, 11, 16);
    g.fillStyle = '#FFD45E';
    g.fillRect(x + 4, y - 17, 10, 12);
    g.strokeStyle = COL.ink; g.strokeRect(x + 4, y - 17, 10, 12);
  } else if (k === 'crate') {
    g.save();
    g.translate(x, y);
    g.rotate(0.12);
    g.fillStyle = '#D49A5F';
    g.fillRect(-16, -19, 32, 19);
    g.strokeStyle = COL.ink; g.lineWidth = 2.5; g.strokeRect(-16, -19, 32, 19);
    g.strokeStyle = 'rgba(74,58,44,.6)'; g.lineWidth = 2;
    g.beginPath(); g.moveTo(-16, -9); g.lineTo(16, -9); g.stroke();
    g.restore();
  } else if (k === 'stones') {
    /* 一小堆碎石。**这类东西撞不撞无所谓** —— 它是地面本身的质感，
       玩家从上面走过去不会觉得被骗。所以它留在装饰层，不进碰撞。 */
    for (let i = 0; i < 5; i++) {
      const sx = x + (i - 2) * 5.4 + ((s >> i) % 5) - 2;
      const sz = 2.6 + (i % 3) * 1.4;
      g.fillStyle = i % 2 ? '#9A948C' : '#BBB3A6';
      g.strokeStyle = COL.ink; g.lineWidth = 1.6;
      g.beginPath();
      g.ellipse(sx, y - sz * 0.72, sz, sz * 0.78, (i - 2) * 0.22, 0, Math.PI * 2);
      g.fill(); g.stroke();
    }
  } else if (k === 'stump') {
    /* 树桩：地表层专属的"这里以前是林子"。
       和山石、雪堆一起把地面从"一条直线"打碎。 */
    const hh = 15 + (s % 7);
    g.fillStyle = '#8A6A46';
    g.beginPath();
    g.moveTo(x - 9, y); g.lineTo(x - 7, y - hh); g.lineTo(x + 7, y - hh); g.lineTo(x + 9, y);
    g.closePath(); g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.4; g.stroke();
    /* 顶面的年轮：这一笔是"它是被锯断的树"而不是"一根木桩" */
    g.fillStyle = '#C9A472';
    g.beginPath(); g.ellipse(x, y - hh, 7.4, 2.9, 0, 0, Math.PI * 2); g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2; g.stroke();
    g.strokeStyle = 'rgba(92,66,42,.55)'; g.lineWidth = 1.2;
    g.beginPath(); g.ellipse(x, y - hh, 4.2, 1.6, 0, 0, Math.PI * 2); g.stroke();
    /* 侧面一小片苔 */
    g.fillStyle = '#7FA05E';
    g.beginPath(); g.ellipse(x - 6, y - hh * 0.42, 3.2, 5.2, 0.2, 0, Math.PI * 2); g.fill();
  } else if (k === 'ladder') {
    /* 靠墙的旧木梯，**顶上是断的**。
       这是全场唯一一件"叙事道具"：它说明有人从这里上下过、后来塌了。
       **断必须画清楚**（左轨比右轨矮一截 + 中间缺一根横档 + 断口有毛刺）——
       不断的话玩家会去踢它、以为这条路能走，那就是骗人。
       它只有 100px 高、够不到上层，所以读作"痕迹"而不是"通道"。 */
    const H = 100;
    /* 10° 的倾斜是"靠墙"和"立着"的分界线 —— 只在 3px 上做文章（1.7°）读不出来，
       直上直下的梯子看起来就是一条能走的路。 */
    const tilt = 16;
    const lx = x - 14, rx = x + 12;
    const lt = y - H + 20;     // 左轨断得低一截
    const rt = y - H;          // 右轨多出 20px，断口错开才像"折了"
    /* 先粗深色打底、再细木色压上去 = 统一描边的廉价做法。 */
    g.lineCap = 'round';
    g.strokeStyle = COL.ink;
    g.lineWidth = 9;
    g.beginPath(); g.moveTo(lx, y); g.lineTo(lx + tilt, lt); g.stroke();
    g.beginPath(); g.moveTo(rx, y); g.lineTo(rx + tilt, rt); g.stroke();
    g.strokeStyle = '#C99358'; g.lineWidth = 5.5;
    g.beginPath(); g.moveTo(lx, y); g.lineTo(lx + tilt, lt); g.stroke();
    g.beginPath(); g.moveTo(rx, y); g.lineTo(rx + tilt, rt); g.stroke();
    /* 横档：第 3 根缺失，只留一截断头 */
    g.lineCap = 'butt';
    for (let i = 0; i < 4; i++) {
      const yy = y - 18 - i * 22;
      const f = (y - yy) / H;                            // 横档在梯身上的实际比例
      const ax = lx + tilt * f, bx2 = rx + tilt * f;
      if (i === 2) {
        g.strokeStyle = COL.ink; g.lineWidth = 6;
        g.beginPath(); g.moveTo(ax, yy); g.lineTo(ax + 8, yy); g.stroke();
        g.strokeStyle = '#C99358'; g.lineWidth = 3.5;
        g.beginPath(); g.moveTo(ax, yy); g.lineTo(ax + 7, yy); g.stroke();
        continue;
      }
      g.strokeStyle = COL.ink; g.lineWidth = 6;
      g.beginPath(); g.moveTo(ax, yy); g.lineTo(bx2, yy); g.stroke();
      g.strokeStyle = '#C99358'; g.lineWidth = 3.5;
      g.beginPath(); g.moveTo(ax, yy); g.lineTo(bx2, yy); g.stroke();
    }
    /* 断口的木刺：两根短斜刺，靠它把"折了"和"画歪了"区分开。 */
    g.strokeStyle = '#A9713F'; g.lineWidth = 2;
    g.beginPath(); g.moveTo(lx + tilt, lt); g.lineTo(lx + tilt - 5, lt - 6); g.stroke();
    g.beginPath(); g.moveTo(rx + tilt, rt); g.lineTo(rx + tilt + 5, rt - 6); g.stroke();
  }
  g.restore();
}

function drawDoor(g, d) {
  if (!d) return;
  /* 被箱子盖着就不画。**不是画成"模糊的门"** —— 门只要露头，
     玩家就会去撞箱子试，那就又变成"逐箱砸过去"的扫图了。 */
  if (doorBlocked()) return;
  /* ================= 一扇小拱门（2026-10-29 重画）=================
     用户：「箱子 桶 门 都需要重新规划　太不像了」「门不需要那么大」。

     上一版是"48×92 的圆角矩形 + 一条拱顶 + 一个大红锁"：
     尺寸上是两格高，画法上是三块色块叠起来，**读不出"这是一扇门"** ——
     没有门框、没有门板缝、没有把手、没有铰链，只有"一个绿色的洞"。

     这一版按真实的木门来组：门洞（拱）→ 门框（厚木）→ 门板（三块竖板）→
     两条铁横带 + 铆钉 → 把手。尺寸收到 32×40（一格之内），
     靠"门框比门板厚"和"竖板缝"把"门"这个东西说清楚，
     不再靠尺寸大来显眼。 */
  const { x, y, w, h } = d;
  const cx = x + w / 2;
  const R = w / 2;                      // 拱顶半径
  const arch = () => {
    g.beginPath();
    g.moveTo(x, y + h);
    g.lineTo(x, y + R);
    g.arc(cx, y + R, R, Math.PI, 0);
    g.lineTo(x + w, y + h);
    g.closePath();
  };

  /* ① 门框：比门板外扩 4，深木色。**这一圈是"门"和"洞"的分界** ——
     没有它，门在深色墙上就是一个亮块。 */
  g.save();
  g.translate(cx, y + h / 2);
  g.scale((w + 8) / w, (h + 4) / h);
  g.translate(-cx, -(y + h / 2));
  arch();
  g.fillStyle = d.open ? '#3E6B52' : '#4A3324';
  g.fill();
  g.restore();
  g.strokeStyle = COL.ink; g.lineWidth = 2.6; g.lineJoin = 'round';
  g.save(); g.translate(cx, y + h / 2); g.scale((w + 8) / w, (h + 4) / h);
  g.translate(-cx, -(y + h / 2)); arch(); g.stroke(); g.restore();

  /* ② 门板 */
  arch();
  g.fillStyle = d.open ? '#8FE3B4' : '#B3803F';
  g.fill();

  if (d.open) {
    /* 开着的门：洞里的光 + 一层往外的光晕。**先画光再画门框的暗边**，
       否则门框会把光切成一个方框，看起来像"亮着的矩形"。 */
    const k = Math.min(1, d.openT * 2.2);
    g.save(); arch(); g.clip();
    const lg = g.createLinearGradient(0, y, 0, y + h);
    lg.addColorStop(0, 'rgba(232,255,240,.95)');
    lg.addColorStop(1, 'rgba(150,225,180,.55)');
    g.fillStyle = lg; g.fillRect(x, y, w, h);
    g.restore();
    g.globalAlpha = 0.30 + 0.16 * Math.sin(S.t * 6);
    g.fillStyle = '#DFFFEE';
    g.beginPath(); g.ellipse(cx, y + h * 0.62, w * 0.85, h * 0.5, 0, 0, Math.PI * 2); g.fill();
    g.globalAlpha = 1;
    if (k < 1) {
      g.globalAlpha = 1 - k; g.fillStyle = '#FFFFFF';
      g.beginPath(); g.arc(cx, y + h * 0.5, 16 + k * 54, 0, Math.PI * 2); g.fill();
      g.globalAlpha = 1;
    }
  } else {
    /* ③ 门板：三块竖板 + 板缝。**缝要压在板子上，不能只画两条线** ——
       两条细线在 32px 宽的门上读成"划痕"，三条带阴影的缝才读成"拼板"。 */
    g.save(); arch(); g.clip();
    g.strokeStyle = 'rgba(92,60,30,.55)'; g.lineWidth = 2;
    for (const t of [0.34, 0.67]) {
      g.beginPath();
      g.moveTo(x + w * t, y + 2); g.lineTo(x + w * t, y + h);
      g.stroke();
      g.strokeStyle = 'rgba(255,226,180,.35)'; g.lineWidth = 1.4;
      g.beginPath();
      g.moveTo(x + w * t + 2, y + 2); g.lineTo(x + w * t + 2, y + h);
      g.stroke();
      g.strokeStyle = 'rgba(92,60,30,.55)'; g.lineWidth = 2;
    }
    /* ④ 两条铁横带 + 铆钉。**横带是"门"的第二身份证**：
       竖板只说明"这是木板拼的"，加上横带才说明"这是能开合的门"。 */
    for (const t of [0.30, 0.74]) {
      const by = y + h * t;
      g.fillStyle = 'rgba(74,84,94,.92)';
      g.fillRect(x + 1, by, w - 2, 5);
      g.fillStyle = 'rgba(190,206,220,.55)';
      g.fillRect(x + 1, by, w - 2, 1.6);
      g.fillStyle = '#CFD9E2';
      for (const dx of [0.22, 0.78]) {
        g.beginPath(); g.arc(x + w * dx, by + 2.5, 1.6, 0, Math.PI * 2); g.fill();
      }
    }
    /* ④-2 **合页。** 两条横带 + 一张锁脸 = "保险柜"，不是门 ——
       出图上这一扇一直被读成"小型金库门"。合页是唯一能直接说出
       "这扇门是绕着左边这条轴转的"的东西，比再加一条横带有效得多。
       画在门板左缘（x+1 起，宽 5），跟着横带的高度走。 */
    for (const t of [0.24, 0.76]) {
      const hy = y + h * t;
      g.fillStyle = 'rgba(78,88,98,.95)';
      rr(g, x + 1.5, hy, 5, 8, 1.6); g.fill();
      g.fillStyle = 'rgba(198,212,226,.60)';
      g.fillRect(x + 2, hy + 0.8, 1.4, 6.4);
      g.fillStyle = '#DCE6EE';
      g.beginPath(); g.arc(x + 4, hy + 4, 1.1, 0, Math.PI * 2); g.fill();
    }
    g.restore();

    /* ⑤ 把手：一个圆环 + 一点高光。**位置靠右上**，因为门是朝右开的
       （把手永远在开合边的反侧）。 */
    const hx = x + w * 0.74, hy = y + h * 0.56;
    g.strokeStyle = '#E8C66A'; g.lineWidth = 2.6;
    g.beginPath(); g.arc(hx, hy, 4.2, 0, Math.PI * 2); g.stroke();
    g.fillStyle = 'rgba(255,246,206,.85)';
    g.beginPath(); g.arc(hx - 1.2, hy - 1.4, 1.2, 0, Math.PI * 2); g.fill();
    /* 锁：门没开的时候要能看出"锁着"。比原来那个大圆锁小一半 ——
       32 宽的门上再挂一个 18px 的锁，门就只剩锁了。 */
    if (!d.open) {
      const lx = x + w * 0.30, ly = y + h * 0.56;
      g.fillStyle = COL.doorLock;
      rr(g, lx - 4.5, ly - 3, 9, 8, 2); g.fill();
      g.strokeStyle = COL.doorLock; g.lineWidth = 2.4;
      g.beginPath(); g.arc(lx, ly - 3, 3.4, Math.PI, 0); g.stroke();
    }
  }

  /* ⑥ 门板的外描边压在最上面（在门框之后画，免得被框吃掉） */
  g.strokeStyle = COL.ink; g.lineWidth = 2.4; g.lineJoin = 'round';
  arch(); g.stroke();
}
/* 三种**敌人**的配色。**剪影决定"这是谁"，颜色只是加分项** ——
   在 34×30 的尺寸上，外轮廓的体块关系比色相可读得多：
   苔泥团是"一团"、尖牙兽是"横着拉长 + 前突的嘴"、霜甲虫是"拱起的硬壳"。

   **配色偏冷偏暗。** 上一版是宠物的奶油白 / 蜂蜜黄 / 雾蓝，那是"我方"的读法；
   敌人要在浅色的木屋墙、雪地面上都能一眼拎出来，所以三只都压到中低明度，
   和场景的暖米底色形成冷暖对比 —— 玩家扫一眼就知道"那不是我的人"。 */
/* **每只两个色阶，body 夹在中间。**
   原来只有 body 一个主色，身上所有面都是同一个值 —— 放大看就是剪纸。
   lit 走受光面（左上），shade 走背光面（右下），body 留在中间当过渡。
   三档就够，再多反而会脏（Q 版卡通靠的是"少而准"，不是层次多）。 */
const FOE_SKIN = {
  /* `belly`（肚皮浅色）**必须和基色只差一档**。原来 moss 的 belly 是
     '#A8C39B' 对 body '#6F8F6A'，差了两档多，在 37px 上读起来不是
     "肚子受光"而是一块**贴在身上的椭圆色块** —— 放大图里那只尖牙兽
     背上那枚明显的亮斑就是这个。Q 版的色块可以分档，但相邻两档不能差太远。 */
  moss: { body: '#7D9E75', ink: '#2F4230', belly: '#90AE88', gill: '#C9DD9E',
          lit: '#9DBE92', shade: '#587A52' },
  fang: { body: '#BB6650', ink: '#43190F', belly: '#CB7C64', gill: '#F0C79E',
          lit: '#D2876E', shade: '#8F4534' },
  /* grub 原来 body '#7C90AE' —— 出图上是"深蓝灰"，离商业 Q 版差一截：
     那种颜色适合"盔甲"，不适合"卡通虫子"。整组提亮一档，
     暗面也只比基色深一点点（Q 版的明暗差本来就小）。 */
  grub: { body: '#93AACB', ink: '#2A3A52', belly: '#C3D5EA', gill: '#EDF6FF',
          lit: '#BDD2EA', shade: '#6B82A4' },
};

/** 一只敌人的"受光球"渐变。坐标在敌人的局部坐标系里（原点=脚底中点），
    所以每个敌人每次绘制都要新建一个 —— Canvas 渐变在创建时就绑定了变换矩阵，
    跨敌人复用会错位。数量最多十几只，这个开销可以忽略。 */
/* =========================================================================
   敌人的上色：**两层硬边色块，一个渐变都没有**
   -------------------------------------------------------------------------
   用户 2026-10-28 明确了风格：「我要的美术风格是 Q 版卡通」。

   而这里原来的实现是径向渐变（lit→body→shade）加一层柔光顶亮 +
   半透明接触阴影 —— **那是厚涂的语言**：用连续过渡塑造体积。
   Q 版卡通正相反，靠**色块的硬边界**塑造体积，边界一模糊就不 Q 了。

   这两件事在 37px 上差别是压倒性的：三层渐变缩到那个尺寸会糊成一片
   脏灰（放大图里霜甲虫的壳就是这个观感），两笔硬边色块反而干净、
   清楚、像"画上去的"。

   判据很简单：**这个函数里没有一处 colorStop。**
   以后想加强体积，加的是"多一档色块"，不是"多一个渐变停靠点"。

   为什么"暗面在外圈、亮面在左上"：全局光源统一在左上（箱子、主角、
   球都一样）。先用暗色铺满整个轮廓，再拿一块**偏移到左上**的基色椭圆
   盖上去，右下方就自然留下一圈硬边暗面 —— 偏移量和半径差决定暗面宽度，
   不用描边、不用渐变，边界天生是硬的。
   ========================================================================= */
function foeCel(g, x, y, rx, ry, skin) {
  g.save();
  g.beginPath(); g.ellipse(x, y, rx, ry, 0, 0, Math.PI * 2); g.clip();

  /* ① 整块铺暗色（这一层最终只会剩下右下一圈） */
  g.fillStyle = skin.shade;
  g.fillRect(x - rx, y - ry, rx * 2, ry * 2);

  /* ② 偏移到左上的基色椭圆 —— **偏移量就是暗面宽度，方向就是受光方向**。

     两个坑：
       · 宽窄：0.17/0.21 只留 2~3px，读起来是"平涂加一条细边"，没有体积。
       · **方向：暗面不能只往右下压。** 尖牙兽是横长身体、头在前，
         右下那块暗面正好被自己的头挡掉，身体又变平了。
         真实情况里趴着的东西最暗的是**下沿**（贴地的部分接不到光），
         所以把偏移改成"以下为主、以右为辅"（0.20 / 0.45）——
         这一处同时照顾了圆团（moss）、拱壳（grub）和横长身体（fang）。 */
  g.beginPath();
  g.ellipse(x - rx * 0.20, y - ry * 0.45, rx * 0.93, ry * 0.93, 0, 0, Math.PI * 2);
  g.fillStyle = skin.body; g.fill();

  /* ③ **没有第三步。** 只用"基色 + 一圈暗面"这两层。

     中间试过加一块左上高光，两种尺寸都试了：
       0.44×0.33 → 在 fang 背上是一枚明显的椭圆贴片（形状太规整）
       0.24×0.17 → 变成背上长了一块斑，比贴片更像画错
     结论是**这个尺寸上根本不该有独立高光**。Q 版卡通塑造体积靠的是
     "暗面从哪开始"，不是"亮点在哪"—— 参考那版（浅蓝灰的霜甲虫
     + 一圈粗描边）也是纯两层，读起来一样结实。
     真要加强，走"多一档暗面"，不走"加一块亮面"。 */
  g.restore();
}

/* **侧视，不是正面。**（2026-10-28 用户：「敌方和我方宠物不应该是朝向玩家
   应该是个侧视的」）

   正面画法（两只对称的眼睛 + 一个正面肚皮）在横版里有一个硬伤：它只说明
   "这是谁"，不说明"它在往哪走"。而在这款里朝向是**唯一要紧的信息** ——
   雪弹打哪边、它往哪边跑、这一发躲不躲得开。侧视把"朝向"直接写进剪影。

   实现上整块绘制都翻到"永远朝右"的坐标系里（`g.scale(face, 1)`）：
   朝左只是镜像，不用写两套坐标。局部原点放在**脚底中点**，
   于是 y 向上为负、x 向前为正，画腿、画嘴都是直觉坐标。 */
/* ---- 敌人贴图（2026-10-28 第四轮）--------------------------------------
   **三张图是从 `art/02-concept/02-foes/enemy-sheet-三只侧视怪物.png` 抠出来的**
   （`tools/_cut-foe-sheet.js`），落在 `assets/snowlab/foe/`。

   为什么不用 `grove/foe` 里现成那四张：那是另一个游戏的敌人（野猪 / 紫鸟 /
   两条毛毛虫）。体态能凑上两只（boar→fang、bug→grub），但**苔泥团没有对应**
   —— 它是「无腿、贴地滑行的圆团」，那四张里一只都不是。
   而这张概念图里本来就是 snowlab 的这三只：苔团带白芽、四足带獠牙、
   拱壳带冰棱。用不着凑、用不着改配色，笔触也和主角那张猫是同一套。

   `h` 是**形象高（世界像素，含耳朵/冰棱这类凸起）**，不是碰撞高。
   碰撞框还是 FOE_W×FOE_H = 37×33，形象比它略矮一点点 ——
   **轮廓一旦比判定框大 5px 以上，就会读成"看着过不去却能过"。**

   三只的宽度是推出来的：宽 = 高 × 原图宽高比（0.874 / 1.129 / 1.041）。
   最宽的 fang = 30 × 1.129 ≈ 34，仍明显窄于木箱 48（0.71）。
   **这条要守住**：用户原话「敌方体态都超过了箱子　是不是不太好」。
   苔团给 40 是因为它头顶还挑着三片芽 —— 按整体高缩会让**身体**只剩 25，
   比冰棱甲虫还小，图上读起来像"它的孩子"。 */
const FOE_ART = {
  moss: { key: 'foe-moss', h: 44 },
  fang: { key: 'foe-fang', h: 34 },
  grub: { key: 'foe-grub', h: 33 },
};

/* 在**局部坐标系**里画敌人贴图（原点 = 脚底中心，已经过 FOE_K 与朝向镜像）。
   返回身体包围盒，给后面的"雪覆盖"和"蓄力"定位用。

   **动法照抄体态推出来的那套（`NUM.breed.*.gait`），不是三只共用一套。**
   这是 user 10-28 那条「很多脚的昆虫只适合爬　有的可以跳」的直接后果：
     slide 苔团 —— 横向压扁拉长，**不做上下起伏**（没有腿，起伏就是"在弹"）
     run   四足 —— 跑起来有小跳，腾空时纵向拉长
     crawl 多足 —— 只左右轻晃，脚不离地
   频率也不共用：苔团最慢（0.55）、四足最快（0.5 但幅度大）、甲虫居中。

   贴图只有一张，所以**不做腿部切块对摆**（主角那张做了，因为它有 6 套 WALK_CUT）。
   30px 的敌人身上，切块对摆的收益抵不过接缝的风险。 */
function drawFoeSpriteLocal(g, img, A, f, ph, moving, flash) {
  const ah = A.h / FOE_K;
  const aw = ah * ((img.width || img.naturalWidth) / (img.height || img.naturalHeight));
  const br = NUM.breed[f.breed] || NUM.breed.moss;
  let sx = 1, sy = 1, dy = 0;
  if (br.gait === 'slide') {
    const w2 = Math.sin(ph * 0.55) * (moving ? 0.045 : 0.018);
    sx = 1 + w2; sy = 1 - w2 * 0.8;
  } else if (br.gait === 'run') {
    dy = moving ? -Math.abs(Math.sin(ph * 0.5)) * 2.2 : 0;
    if (!f.onGround) { sx = 0.94; sy = 1.08; }
  } else {
    const w3 = Math.sin(ph * 0.7) * (moving ? 0.03 : 0.012);
    sx = 1 + w3; sy = 1 - w3 * 0.5;
  }
  g.save();
  if (flash) g.filter = 'brightness(1.75)';
  g.translate(0, dy);
  g.scale(sx, sy);                      /* 原点在脚底，缩放不会把人抬离地面 */
  g.drawImage(img, -aw / 2, -ah, aw, ah);
  g.restore();
  return { cx: 0, cy: -ah / 2 + dy, rx: aw / 2, ry: ah / 2, top: -ah + dy };
}

function drawFoe(g, f) {
  const cx = f.x + f.w / 2;
  const by = f.y + f.h;
  const skin = FOE_SKIN[f.breed] || FOE_SKIN.moss;
  const flash = f.hitT > 0;
  const B = flash ? '#FFFFFF' : skin.body;
  const moving = Math.abs(f.vx) > 1;
  const ph = S.t * 11 + f.x * 0.09;
  /* ---- 曾经的 `breathe` 就删在这里 ------------------------------------
     原来是 `1 + sin(t*4.4) * 0.04`，挂在身体椭圆的**纵向半径**上，
     所以每只怪都在原地一胀一缩，永远不停。
     注释当时写的是"停一下、身体微微起伏，才像个活物" —— 但那是**人的**呼吸，
     一条虫子没有横膈膜。放大到 37px 之后它读起来不是"活着"，是"在弹"，
     而且玩家会本能地躲一个根本不存在的起跳。
     用户的原话是「不希望（上下跳动）」。要走得像活物，该动的是**腿**，
     不是胸腔。（腿的相位错开在下面 gait 分支里做。）
     留着这个名字只为减少 diff 噪音，值恒为 1。 */
  const breathe = 1;

  /* ---- 影子：画在镜像坐标系外面，它不该跟着翻转 ---- */
  g.save();
  g.globalAlpha = 0.18; g.fillStyle = '#33281F';
  g.beginPath(); g.ellipse(cx, by - 1, 17, 4.2, 0, 0, Math.PI * 2); g.fill();
  g.restore();

  g.save();
  g.translate(cx, by);
  g.scale(FOE_K, FOE_K);      /* 敌人的系数和玩家分开，理由见 FOE_K 的注释 */
  g.scale(f.face, 1);

  const leg = (lx, phase, r) => {
    const lift = moving ? Math.max(0, Math.sin(ph + phase * Math.PI)) * 3.2 : 0;
    g.fillStyle = skin.ink;
    g.beginPath(); g.ellipse(lx, -2.2 - lift, r || 4.8, 3.0, 0, 0, Math.PI * 2); g.fill();
  };
  /* 侧视只画**一只**眼。两只眼在 34px 上会挤成两个点，反而读不出它在盯谁；
     一只眼 + 瞳孔朝前，就是"它在看这边"。 */
  const eye = (ex, ey, rx, ry) => {
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.ellipse(ex, ey, rx, ry, 0, 0, Math.PI * 2); g.fill();
    g.strokeStyle = skin.ink; g.lineWidth = 1.8; g.stroke();
    g.fillStyle = '#20180F';
    g.beginPath(); g.ellipse(ex + rx * 0.34, ey + 0.5, rx * 0.5, ry * 0.62, 0, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(ex + rx * 0.5, ey - ry * 0.34, 0.95, 0, Math.PI * 2); g.fill();
  };

  /* ---- 贴图优先，代码图形兜底 ----
     `bodyG` 只在贴图那条路上有值，后面"雪覆盖 / 蓄力"靠它定位。 */
  const FA = FOE_ART[f.breed];
  const foeImg = FA ? artOf(FA.key) : null;
  const bodyG = foeImg ? drawFoeSpriteLocal(g, foeImg, FA, f, ph, moving, flash) : null;

  /* ================================================================ 苔泥团
     一团矮胖的苔，慢、皮厚。**外形是一整块，没有脖子** —— "圆团"这个体块
     和另外两只（横长 / 拱壳）在任何缩放下都不会混。 */
  if (bodyG) {
    /* 贴图这条路什么都不用再画 —— 腿、眼、苔斑、冰棱全在图里。 */
  } else if (f.breed === 'moss') {
    /* 背上的苔草：先画，根埋在身体里，尖朝后上方探出来 */
    g.strokeStyle = skin.ink; g.lineWidth = 2.4; g.lineCap = 'round';
    for (let i = 0; i < 4; i++) {
      const bx = -9.5 + i * 3.4, sway = Math.sin(S.t * 3 + i * 1.7 + f.x * 0.05) * 1.6;
      const len = 8 + (i % 2) * 3.4;
      g.beginPath();
      g.moveTo(bx, -24);
      g.quadraticCurveTo(bx - 2.6 + sway, -24 - len * 0.6, bx - 1.4 + sway, -24 - len);
      g.stroke();
    }
    g.lineCap = 'butt';

    leg(-7.2, 0.5);
    g.beginPath();
    g.ellipse(0, -14.5, 15.4, 13.2 * breathe, 0, 0, Math.PI * 2);
    g.fillStyle = flash ? '#FFFFFF' : skin.body;
    g.fill();
    g.strokeStyle = skin.ink; g.lineWidth = 3; g.stroke();
    /* 受击闪白时不叠体积 —— 这一帧的全部信息就是"打中了"，
       再压一层高光会把闪白读成"变亮了"而不是"被打中了"。 */
    if (!flash) foeCel(g, 0, -14.5, 15.4, 13.2 * breathe, skin);

    /* 背面的苔斑 —— 提示"这一团是有正反的" */
    g.fillStyle = skin.gill; g.globalAlpha = 0.75;
    g.beginPath(); g.ellipse(-7, -17, 6.4, 5.2, -0.3, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.ellipse(-3.5, -9.5, 4.2, 3.4, 0.2, 0, Math.PI * 2); g.fill();
    g.globalAlpha = 1;

    /* 脸盘：前侧一块浅色，替代"正面肚皮" */
    g.fillStyle = skin.belly;
    g.beginPath(); g.ellipse(7.6, -14.5, 7.4, 8.6, 0, 0, Math.PI * 2); g.fill();
    g.strokeStyle = skin.ink; g.lineWidth = 1.6; g.stroke();

    leg(7.6, 0);
    eye(10.4, -17.4, 4.2, 5.0);
    /* 嘴：一条小弧 + 一颗露出来的牙 */
    g.strokeStyle = skin.ink; g.lineWidth = 2;
    g.beginPath(); g.moveTo(7.4, -8.6); g.quadraticCurveTo(10.2, -7.2, 12.6, -9.2); g.stroke();
    g.fillStyle = '#FFFDF2';
    g.beginPath(); g.moveTo(9.4, -9.4); g.lineTo(11.2, -9.4); g.lineTo(10.3, -6.6); g.closePath(); g.fill();
    g.strokeStyle = skin.ink; g.lineWidth = 1.3; g.stroke();

    /* ============================================================ 尖牙兽
       横着拉长 + 前突的长口鼻 + 一排牙。跑得最快，所以"低伏"是它的姿态语言。 */
  } else if (f.breed === 'fang') {
    /* 背刺：朝后上方，先画 */
    g.fillStyle = B; g.strokeStyle = skin.ink; g.lineWidth = 2.2;
    for (let i = 0; i < 3; i++) {
      const bx = -13 + i * 6.4;
      g.beginPath();
      g.moveTo(bx - 3, -18);
      g.lineTo(bx - 5.4, -26 - (i === 1 ? 2 : 0));
      g.lineTo(bx + 2.6, -18);
      g.closePath(); g.fill(); g.stroke();
    }
    /* 尾巴 */
    g.strokeStyle = skin.ink; g.lineWidth = 4.4; g.lineCap = 'round';
    g.beginPath();
    g.moveTo(-15, -14);
    g.quadraticCurveTo(-24, -18, -22.5, -26 + Math.sin(S.t * 6 + f.x) * 1.6);
    g.stroke(); g.lineCap = 'butt';

    leg(-9, 0.5, 4.4);
    /* 身体：横向长条，低伏 */
    g.beginPath();
    g.ellipse(-2, -12.4, 16.2, 9.4 * breathe, 0, 0, Math.PI * 2);
    g.fillStyle = flash ? '#FFFFFF' : skin.body;
    g.fill();
    g.strokeStyle = skin.ink; g.lineWidth = 3; g.stroke();
    if (!flash) foeCel(g, -2, -12.4, 16.2, 9.4 * breathe, skin);
    /* 腹部浅色（侧视：贴地那一条）。
       **它必须比身体下沿高出至少一个暗面的宽度。** 原来是
       `ellipse(-1, -8.4, 12.4, 4.4)`，下沿到 -4.0，而身体下沿是 -3.0 ——
       只差 1px，等于把 cel 的整个下半圈暗面盖掉了，于是身体又变平。
       现在压扁上移，下沿留到 -7.2，暗面才露得出来。 */
    g.fillStyle = skin.belly;
    g.beginPath(); g.ellipse(-1, -9.8, 10.2, 2.8, 0, 0, Math.PI * 2); g.fill();

    /* 头：比身体高、朝前偏 */
    g.beginPath();
    g.arc(11.2, -16.6, 9.4, 0, Math.PI * 2);
    g.fillStyle = flash ? '#FFFFFF' : skin.body;
    g.fill();
    g.strokeStyle = skin.ink; g.lineWidth = 3; g.stroke();
    if (!flash) foeCel(g, 11.2, -16.6, 9.4, 9.4, skin);
    /* 长口鼻：往前探出 12px，这是它和"圆团"最不像的地方 */
    g.beginPath();
    g.moveTo(15, -19.6);
    g.quadraticCurveTo(25.4, -17.4, 24.6, -12.4);
    g.quadraticCurveTo(23.8, -9.4, 16.4, -10.6);
    g.closePath();
    /* 口鼻是异形，做不了圆形 clip。**但这么小的一块根本不需要明暗。**
       原来用线性渐变（根部暗、尖端亮），在 37px 上是三色糊成一团，
       而且渐变语言和 Q 版打架。给小形体留纯色，靠那条 3px 描边交代形体就够。 */
    g.fillStyle = flash ? '#FFFFFF' : skin.body;
    g.fill();
    g.strokeStyle = skin.ink; g.lineWidth = 2.6; g.stroke();
    /* 张开的嘴 + 上排牙 */
    g.fillStyle = '#3A1410';
    g.beginPath();
    g.moveTo(15.6, -12.2);
    g.lineTo(24.4, -12.0);
    g.lineTo(23.4, -9.2);
    g.lineTo(16.2, -9.6);
    g.closePath(); g.fill();
    g.fillStyle = '#FFFDF2'; g.strokeStyle = skin.ink; g.lineWidth = 1.2;
    for (let i = 0; i < 4; i++) {
      const tx = 17 + i * 2.1;
      g.beginPath();
      g.moveTo(tx, -12.1); g.lineTo(tx + 1.5, -12.1); g.lineTo(tx + 0.75, -10.2);
      g.closePath(); g.fill(); g.stroke();
    }
    /* 一只尖耳 */
    g.fillStyle = B; g.strokeStyle = skin.ink; g.lineWidth = 2.4;
    g.beginPath();
    g.moveTo(8.2, -24.6); g.lineTo(10.4, -31); g.lineTo(14.6, -24.2);
    g.closePath(); g.fill(); g.stroke();
    eye(13.6, -19.6, 4.0, 4.8);
    leg(11.4, 0, 4.4);
    /* 眉骨：跑得快的那个要有跑得快的脸 */
    g.strokeStyle = skin.ink; g.lineWidth = 2.4; g.lineCap = 'round';
    g.beginPath(); g.moveTo(9.4, -24.4); g.lineTo(16.6, -22.2); g.stroke();
    g.lineCap = 'butt';

    /* ============================================================ 霜甲虫
       拱起的硬壳 + 分节 + 背上一排冰棱 + 六条小腿。**"拱"是它的体块语言**：
       另外两只是"团"和"条"，它是一道弧，缩到指甲盖大也分得开。 */
  } else {
    /* 冰棱：沿壳的拱形排，先画 */
    g.fillStyle = '#DCEFFF'; g.strokeStyle = skin.ink; g.lineWidth = 2;
    for (let i = 0; i < 4; i++) {
      const a = Math.PI * (1.06 + i * 0.17);
      const bx = Math.cos(a) * 15.4, byy = -10 + Math.sin(a) * 15.4 * 0.9;
      const tx = Math.cos(a) * (15.4 + 7.5), ty = -10 + Math.sin(a) * (15.4 + 7.5) * 0.9;
      g.beginPath();
      g.moveTo(bx - 2.6, byy + 1.4);
      g.lineTo(tx, ty);
      g.lineTo(bx + 2.6, byy + 1.4);
      g.closePath(); g.fill(); g.stroke();
    }
    /* 三条后腿（侧视里被壳挡住一半，所以画得比前腿短） */
    for (let i = 0; i < 3; i++) {
      const lx = -11 + i * 7.4;
      const lift = moving ? Math.max(0, Math.sin(ph + i * 2.1)) * 2.6 : 0;
      g.strokeStyle = skin.ink; g.lineWidth = 2.6; g.lineCap = 'round';
      g.beginPath(); g.moveTo(lx, -8.4); g.lineTo(lx - 1.4, -1.4 - lift); g.stroke();
      g.lineCap = 'butt';
    }
    /* 壳：半圆拱。
       **壳用线性渐变而不是径向** —— 硬壳的受光是"一条从左上扫到右下"的带，
       径向会把它画成一个软球，那就不是甲虫了。 */
    g.beginPath();
    g.moveTo(-16.4, -5.6);
    g.bezierCurveTo(-16.4, -25.6, 13.6, -25.6, 15.6, -6.4);
    g.closePath();
    if (!flash) { g.fillStyle = skin.shade; } else { g.fillStyle = '#FFFFFF'; }
    g.fill();
    /* 壳的暗面：**同一个 path 偏移 2.4px 再填一次基色**，右下方就留下一圈硬边。
       原来是三停靠点的线性渐变（lit→body→shade）—— 那确实是"硬壳的斜向受光"，
       但在 37px 上三层渐变糊成一块脏灰，而且和 Q 版语言冲突。
       用偏移 path 做暗面，边界天生是硬的，还顺手省掉一次渐变对象开销。 */
    if (!flash) {
      g.save();
      g.beginPath();
      g.moveTo(-16.4, -5.6);
      g.bezierCurveTo(-16.4, -25.6, 13.6, -25.6, 15.6, -6.4);
      g.closePath();
      g.clip();
      g.beginPath();
      g.moveTo(-16.4 - 2.4, -5.6 - 2.8);
      g.bezierCurveTo(-16.4 - 2.4, -25.6 - 2.8, 13.6 - 2.4, -25.6 - 2.8, 15.6 - 2.4, -6.4 - 2.8);
      g.closePath();
      g.fillStyle = skin.body; g.fill();
      g.restore();
    }
    g.strokeStyle = skin.ink; g.lineWidth = 3; g.stroke();
    /* 壳下沿的接触阴影：壳和地面之间那道暗，让它"坐"在地上 */
    if (!flash) {
      g.save();
      g.beginPath();
      g.moveTo(-16.4, -5.6);
      g.bezierCurveTo(-16.4, -25.6, 13.6, -25.6, 15.6, -6.4);
      g.closePath();
      g.clip();
      g.beginPath(); g.ellipse(0, -3.4, 17, 6.2, 0, 0, Math.PI * 2);
      g.fillStyle = 'rgba(18,28,40,.24)';
      g.fill();
      g.restore();
    }
    /* 分节：三道竖弧，读作"硬壳拼片" */
    g.strokeStyle = skin.ink; g.lineWidth = 2; g.globalAlpha = 0.6;
    for (let i = 0; i < 3; i++) {
      const sx = -8 + i * 6.6;
      g.beginPath();
      g.moveTo(sx, -5.8);
      g.quadraticCurveTo(sx + 1.4, -16, sx + 0.6, -22.4 + i * 0.8);
      g.stroke();
    }
    g.globalAlpha = 1;
    /* 壳顶的高光条 */
    g.strokeStyle = skin.gill; g.lineWidth = 2.6; g.lineCap = 'round'; g.globalAlpha = 0.7;
    g.beginPath(); g.moveTo(-9.6, -18.6); g.quadraticCurveTo(-2, -23.6, 6.4, -20.4); g.stroke();
    g.globalAlpha = 1; g.lineCap = 'butt';

    /* 头：小、前突、两片钳 */
    g.beginPath(); g.arc(15.2, -10.6, 6.4, 0, Math.PI * 2);
    g.fillStyle = flash ? '#FFFFFF' : skin.body;
    g.fill();
    g.strokeStyle = skin.ink; g.lineWidth = 2.6; g.stroke();
    if (!flash) foeCel(g, 15.2, -10.6, 6.4, 6.4, skin);
    g.fillStyle = '#DCEFFF'; g.strokeStyle = skin.ink; g.lineWidth = 1.8;
    g.beginPath(); g.moveTo(19.6, -12.6); g.lineTo(24.6, -13.6); g.lineTo(20.4, -9.4); g.closePath(); g.fill(); g.stroke();
    g.beginPath(); g.moveTo(19.2, -8.2); g.lineTo(23.8, -5.6); g.lineTo(19.0, -6.4); g.closePath(); g.fill(); g.stroke();
    eye(16.2, -12.6, 3.4, 4.2);
    /* 前腿：撑在最前，走路时和三条后腿错开 */
    const lift0 = moving ? Math.max(0, Math.sin(ph + Math.PI)) * 2.6 : 0;
    g.strokeStyle = skin.ink; g.lineWidth = 2.8; g.lineCap = 'round';
    g.beginPath(); g.moveTo(10.4, -8.4); g.lineTo(12.4, -1.4 - lift0); g.stroke();
    g.lineCap = 'butt';
  }

  /* ---- 蓄力：嘴前那一团 ----
     **这是"它要扔东西了"的唯一提示。** 0.42 秒的前摇如果画面上什么都没有，
     玩家只会觉得"莫名其妙掉血"。形状跟着投掷物走：泥球是圆的、牙是尖的、
     冰锥是竖的一条。 */
  if (f.aim > 0) {
    const k2 = clamp(f.aim / NUM.ebullet.windup, 0, 1);
    /* 出手点跟着**当前画法**走：贴图那三只的嘴在包围盒的右下，代码画的那三只
       是手调的常数。写死一套常数的话，一换贴图这团能量就飘在头顶上。 */
    const mx = bodyG ? bodyG.rx * 0.86 : (f.breed === 'fang' ? 25 : (f.breed === 'grub' ? 21 : 14));
    const my = bodyG ? bodyG.cy + bodyG.ry * 0.28 : (f.breed === 'fang' ? -13 : (f.breed === 'grub' ? -10 : -12));
    const rr2 = 2.4 + 4.4 * k2;
    g.globalAlpha = 0.4 + 0.6 * k2;
    if (f.breed === 'fang') {
      g.fillStyle = '#FFF0D8';
      g.beginPath();
      g.moveTo(mx - rr2 * 0.5, my - rr2); g.lineTo(mx + rr2 * 0.3, my); g.lineTo(mx - rr2 * 0.5, my + rr2);
      g.closePath(); g.fill();
      g.strokeStyle = skin.ink; g.lineWidth = 1.6; g.stroke();
    } else {
      g.fillStyle = f.breed === 'grub' ? '#BFE8FF' : '#8A9E5E';
      g.beginPath(); g.arc(mx, my, rr2, 0, Math.PI * 2); g.fill();
      g.strokeStyle = skin.ink; g.lineWidth = 1.8; g.stroke();
    }
    g.globalAlpha = 1;
  }

  /* ---- 雪覆盖：按 hits/need 上白，这是玩家读"还差几发"的唯一线索 ---- */
  const need = f.needAt || snowNeed();
  const k = clamp(f.hits / need, 0, 1);
  if (k > 0) {
    /* 雪覆盖的椭圆跟着身体包围盒走 —— 贴图那三只的体型和代码画的三只不一样，
       写死 15×11 的话，苔团会被盖成"头上扣了个雪帽"、甲虫会露半个壳。 */
    const bcy = bodyG ? bodyG.cy : -12;
    const brx = bodyG ? bodyG.rx : 15, bry = bodyG ? bodyG.ry : 11;
    g.globalAlpha = 0.42 + k * 0.55;
    g.fillStyle = '#FFFFFF';
    g.beginPath();
    g.ellipse(-1, bcy, brx * (0.55 + k * 0.45), bry * (0.3 + k * 0.7), 0, 0, Math.PI * 2);
    g.fill();
    g.globalAlpha = 1;
    g.strokeStyle = 'rgba(150,215,240,' + (0.3 + k * 0.5).toFixed(2) + ')';
    g.lineWidth = 2;
    g.beginPath();
    g.ellipse(-1, bcy, brx * (0.6 + k * 0.4), bry * (0.35 + k * 0.65), 0, 0, Math.PI * 2);
    g.stroke();
  }
  g.restore();

  /* 进度条画在镜像坐标系外面 —— 否则朝左时会倒着长。
     **位置在 f.y−26**：头比碰撞盒高出 9px、背刺再高 5px，
     留在原处这条永远压在脸上，等于没有。 */
  if (f.hits > 0) {
    const bw = f.w + 4;
    const barY = f.y - 26;
    g.fillStyle = 'rgba(74,58,44,.4)';
    g.fillRect(f.x - 2, barY, bw, 4);
    g.fillStyle = '#9BE86E';
    g.fillRect(f.x - 2, barY, bw * k, 4);
  }
}

/* 敌人扔出来的东西。**二十来像素里要认得出是什么** ——
   它的唯一职责是告诉玩家"这一发躲不开会掉血"，认不出就只是个彩色圆点。
   所以每样都带自己品种的形状语言：牙是尖的、冰锥是细长的、泥球是圆的。

   **这三样都不能用白色。** 地表是浅色雪地、墙面是暖米色，白东西在上面
   直接消失（上一版骨头就吃过这个亏：三发出图只看得见两发）。
   一律给它们"比背景更深一档的底色 + 更深的描边"。 */
function drawEBullet(g, b) {
  g.save();
  g.translate(b.x, b.y);
  if (b.kind === 'tooth') {
    /* 尖牙兽甩出来的牙：一个弯锥。**弯**很关键 ——
       直的三角读作"箭头"，弯的才读作"从嘴里甩出来的牙"。 */
    g.rotate(b.spin * 0.8);
    g.fillStyle = '#FFF6E2';
    g.strokeStyle = '#4A2C1A'; g.lineWidth = 2.6;
    g.beginPath();
    g.moveTo(9.6, 0);
    g.quadraticCurveTo(2, -5.4, -5.6, -3.2);
    g.quadraticCurveTo(-8.4, -1.2, -5.4, 2.4);
    g.quadraticCurveTo(2, 4.2, 9.6, 0);
    g.closePath(); g.fill(); g.stroke();
    /* 牙根那一圈暗色，让它不像一片叶子 */
    g.fillStyle = 'rgba(94,54,30,.5)';
    g.beginPath(); g.ellipse(-5.2, 0, 2.6, 3.0, 0, 0, Math.PI * 2); g.fill();
  } else if (b.kind === 'shard') {
    /* 冰锥：细长的六面体，**朝飞行方向躺着**，带一条高光棱。
       和"牙"的区别在长宽比：牙接近 2:1，冰锥 3:1 且是冷色。 */
    g.scale(b.face, 1);
    g.rotate(Math.sin(b.t * 10) * 0.08);
    g.fillStyle = '#CFEAFA';
    g.strokeStyle = '#2C4A62'; g.lineWidth = 2.4;
    g.beginPath();
    g.moveTo(13, 0);
    g.lineTo(2.4, -5.2);
    g.lineTo(-7.6, -3.4);
    g.lineTo(-9.4, 0);
    g.lineTo(-7.6, 3.4);
    g.lineTo(2.4, 5.2);
    g.closePath(); g.fill(); g.stroke();
    /* 高光棱：只有冰才有的那道亮线 */
    g.strokeStyle = 'rgba(255,255,255,.85)'; g.lineWidth = 1.6; g.lineCap = 'round';
    g.beginPath(); g.moveTo(1.4, -2.6); g.lineTo(11, -0.6); g.stroke();
    g.lineCap = 'butt';
    /* 尾部的霜点 */
    g.fillStyle = 'rgba(210,238,252,.9)';
    g.beginPath(); g.arc(-10.4, 0, 1.6, 0, Math.PI * 2); g.fill();
  } else {
    /* 泥球：苔泥团抛出来的一坨，边缘不圆、带三颗凸起。 */
    g.rotate(b.spin * 1.4);
    g.fillStyle = '#6E7A45';
    g.strokeStyle = '#2C3418'; g.lineWidth = 2.4;
    g.beginPath();
    g.moveTo(8.6, -1.4);
    g.quadraticCurveTo(7.2, -6.4, 1.6, -6.6);
    g.quadraticCurveTo(-4.6, -6.8, -7.8, -1.8);
    g.quadraticCurveTo(-9.2, 2.6, -3.4, 5.8);
    g.quadraticCurveTo(3.4, 7.4, 7.6, 3.2);
    g.quadraticCurveTo(9.4, 1.2, 8.6, -1.4);
    g.closePath(); g.fill(); g.stroke();
    /* 三颗凸起：让它在旋转时能看出"在滚" */
    g.fillStyle = '#8C9A5A';
    g.beginPath(); g.arc(-2.4, -3.2, 2.2, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(3.4, 1.6, 1.7, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(-4.2, 2.6, 1.4, 0, Math.PI * 2); g.fill();
  }
  g.restore();
}


/* 四档球的配色。**档位必须一眼能读出来** ——
   冰墙只认特大球，玩家得能判断"我还差几只"，光靠半径差 1.5 倍不够。 */
/* **雪球的描边必须够深。** 球体是"白 → 浅蓝"的径向渐变，而地表是
   暖白/奶黄的浅色 —— 用小球的浅蓝 edge（#BFE0F0）时，最小那颗
   在草地上等于隐身，四档对照图里只能看见三颗。要么球有深边，
   要么玩家永远数不清自己攒了几档。 */
const BALL_SKIN = [
  { a: '#FFFFFF', b: '#E2F2FB', edge: '#7FB4CC' },   // 小
  { a: '#FFFFFF', b: '#CBE8F8', edge: '#5FA0C4' },   // 中
  { a: '#F7FDFF', b: '#AFDCF3', edge: '#4787B0' },   // 大
  { a: '#EEFAFF', b: '#8FC8E8', edge: '#356F9C' },   // 特大
];

/* ============================================================================
   我方投掷物：六只六种样子
   ----------------------------------------------------------------------------
   **形状就是识别度。** 8~10px 的子弹上，配色几乎没有意义（缩到那个尺寸，
   橙和红是同一个色块），能读出来的只有**外轮廓**和**运动方式**：
   圆的、带两个凸头的、锥形的、细长的 —— 一屏同时出现也不会认错。

   用户 2026-10-29：「要符合宠物的特征」。所以每只扔自己的东西：
   猫的溜溜球、狗的骨头、仓鼠的坚果、兔子的萝卜、牛的飞刀、狐狸的影子。
   这些东西在 `grove.html` 里本来就是各角色的武器（`HEROES[].tag`），
   这里搬的是**形象**，不是伤害 —— snowlab 的子弹只管加雪点、裹球。

   三样东西共用：
   ① 拖尾 —— 一条按速度方向拖出去的淡影。**没有它，抛物线读不出来**：
      单帧只是一颗球，玩家分不清它在往上飘还是往下掉。
   ② 统一 `COL.ink` 描边 —— 和场景里所有实体的语言一致，不描边就是贴纸。
   ③ 飞行中自转（`kind` 决定转速：刀和骨头转得明显，坚果几乎不转）。 */
function drawShot(g, s) {
  const a = clamp(s.t / (s.life || 1), 0, 1);

  /* 拖尾：沿速度反方向拉长。alpha 随飞行时间衰减，
     所以刚出手那一段最"实"，快消失时自己淡掉，不用额外的消失动画。 */
  const sp = Math.hypot(s.vx, s.vy) || 1;
  g.save();
  g.globalAlpha = 0.28 * (1 - a * 0.7);
  g.fillStyle = '#EAF6FF';
  g.beginPath();
  g.ellipse(s.x - s.vx / sp * 7, s.y - s.vy / sp * 7,
            s.r * 1.5, s.r * 0.8, Math.atan2(s.vy, s.vx), 0, Math.PI * 2);
  g.fill();
  g.restore();

  g.save();
  g.translate(s.x, s.y);
  g.lineWidth = 2.4;
  g.strokeStyle = COL.ink;
  g.lineJoin = 'round';

  const R = s.r;
  switch (s.kind) {
    /* 溜溜球：一个厚圆盘 + 中间那条缝线。猫的武器是"甩出去再拉回来"，
       所以它必须看起来像"能转的东西"，不是一个雪块。 */
    case 'yoyo': {
      g.rotate(s.t * 16 * (s.vx < 0 ? -1 : 1));
      g.beginPath(); g.arc(0, 0, R, 0, Math.PI * 2);
      g.fillStyle = '#FFC94E'; g.fill(); g.stroke();
      g.beginPath(); g.moveTo(-R * 0.62, 0); g.lineTo(R * 0.62, 0);
      g.strokeStyle = '#B4781E'; g.lineWidth = 1.6; g.stroke();
      g.beginPath(); g.arc(-R * 0.3, -R * 0.34, R * 0.26, 0, Math.PI * 2);
      g.fillStyle = 'rgba(255,250,230,.85)'; g.fill();
      break;
    }
    /* 骨头：两头大、中间细。狗的武器。**两个凸头是它的全部识别度**，
       画成一根直棍就变成"扔了根木头"。 */
    case 'bone': {
      g.rotate(s.t * 12 * (s.vx < 0 ? -1 : 1));
      g.beginPath();
      g.moveTo(-R * 0.55, -R * 0.30); g.lineTo(R * 0.55, -R * 0.30);
      g.lineTo(R * 0.55, R * 0.30);  g.lineTo(-R * 0.55, R * 0.30);
      g.closePath();
      g.fillStyle = '#F6EFE0'; g.fill();
      g.beginPath(); g.arc(-R * 0.68, -R * 0.30, R * 0.32, 0, Math.PI * 2); g.fill(); g.stroke();
      g.beginPath(); g.arc(-R * 0.68, R * 0.30, R * 0.32, 0, Math.PI * 2); g.fill(); g.stroke();
      g.beginPath(); g.arc(R * 0.68, -R * 0.30, R * 0.32, 0, Math.PI * 2); g.fill(); g.stroke();
      g.beginPath(); g.arc(R * 0.68, R * 0.30, R * 0.32, 0, Math.PI * 2); g.fill(); g.stroke();
      break;
    }
    /* 坚果：椭圆 + 一道中缝。仓鼠的武器贴地滚，所以它几乎是圆的
       （圆的东西滚起来才成立），转速也压到最低。 */
    case 'nut': {
      g.beginPath(); g.ellipse(0, 0, R * 1.05, R * 0.86, s.t * 3, 0, Math.PI * 2);
      g.fillStyle = '#B07A42'; g.fill(); g.stroke();
      g.beginPath(); g.moveTo(-R * 0.7, -R * 0.5); g.quadraticCurveTo(R * 0.1, 0, -R * 0.7, R * 0.5);
      g.strokeStyle = '#7A4E24'; g.lineWidth = 1.5; g.stroke();
      break;
    }
    /* 萝卜：锥身 + 尾部一撮绿。兔子的武器，**全六种里最长的东西**，
       在屏幕上一眼能认出来是"射出去的蔬菜"。 */
    case 'carrot': {
      g.rotate(s.vx < 0 ? Math.PI : 0);
      g.beginPath();
      g.moveTo(R * 1.15, 0); g.lineTo(-R * 0.55, -R * 0.72); g.lineTo(-R * 0.55, R * 0.72);
      g.closePath();
      g.fillStyle = '#F2903F'; g.fill(); g.stroke();
      g.beginPath();
      g.moveTo(-R * 0.55, 0); g.lineTo(-R * 1.15, -R * 0.5); g.lineTo(-R * 1.05, 0);
      g.lineTo(-R * 1.15, R * 0.5);
      g.closePath();
      g.fillStyle = '#79B65A'; g.fill(); g.stroke();
      break;
    }
    /* 飞刀：最细最长、转得最快。牛的武器，读作"穿过"而不是"砸中"。 */
    case 'knife': {
      g.rotate(s.t * 26);
      g.beginPath();
      g.moveTo(R * 1.5, 0); g.lineTo(0, -R * 0.55); g.lineTo(-R * 0.75, 0); g.lineTo(0, R * 0.55);
      g.closePath();
      g.fillStyle = '#DDE8F2'; g.fill(); g.stroke();
      break;
    }
    /* 影子：唯一"不发光"的一种 —— 实心暗紫 + 一圈更暗的边，
       飞的时候还留两道残影，读作"这不是实物"。 */
    default: {
      g.globalAlpha = 0.4;
      g.beginPath(); g.arc(-s.vx * 0.02, -s.vy * 0.02, R * 0.9, 0, Math.PI * 2);
      g.fillStyle = '#A98CFF'; g.fill();
      g.globalAlpha = 1;
      g.beginPath(); g.arc(0, 0, R, 0, Math.PI * 2);
      g.fillStyle = '#6B54A8'; g.fill(); g.stroke();
      break;
    }
  }
  g.restore();
}

function drawBall(g, b) {
  const tier = ballTier(b.absorbed);
  const skin = BALL_SKIN[tier];
  g.save();
  g.translate(b.x, b.y);
  // 影子
  g.globalAlpha = 0.16; g.fillStyle = '#1A2A32';
  g.beginPath(); g.ellipse(0, b.r * 0.95, b.r * 0.9, b.r * 0.28, 0, 0, Math.PI * 2); g.fill();
  g.globalAlpha = 1;

  // 特大球的光晕：远远就能看出这颗是"能破冰墙的"
  if (tier === 3) {
    g.globalAlpha = 0.22 + 0.1 * Math.sin(S.t * 5);
    g.fillStyle = '#9EE0FF';
    g.beginPath(); g.arc(0, 0, b.r + 10, 0, Math.PI * 2); g.fill();
    g.globalAlpha = 1;
  }

  g.rotate(-b.x / b.r * 0.6);
  const grd = g.createRadialGradient(-b.r * 0.3, -b.r * 0.35, b.r * 0.2, 0, 0, b.r);
  grd.addColorStop(0, skin.a);
  grd.addColorStop(1, skin.b);
  g.fillStyle = grd;
  g.beginPath(); g.arc(0, 0, b.r, 0, Math.PI * 2); g.fill();

  /* **这里原来写的是 `b.snowballEdge`（球对象上没有这个字段），
     赋值 undefined 在 canvas 里等于"不改"，于是球沿用了上一个 strokeStyle
     —— 也就是门的锁红，四颗球全戴了一圈红环，看起来像"快散了"。 */
  g.strokeStyle = skin.edge; g.lineWidth = 2.6;
  g.beginPath(); g.arc(0, 0, b.r - 1.2, 0, Math.PI * 2); g.stroke();

  /* 雪团颗粒 + 一道高光弧。
     **不能用同心圆当档位标记** —— 一圈圈往里收的白线读出来是雷达波/音波，
     不像雪。改用黄金角撒开的团块：位置由 i 决定，不会每帧跳；
     外面那层 g.rotate 已经让它们跟着球一起滚。 */
  const nDot = 4 + tier * 3;
  for (let i = 0; i < nDot; i++) {
    const ang = i * 2.39996;
    const rad = b.r * 0.66 * Math.sqrt((i + 0.5) / nDot);
    const pr = 1.5 + ((i * 37) % 5) * 0.45;
    g.fillStyle = i % 3 === 0 ? 'rgba(255,255,255,.85)' : 'rgba(146,200,228,.45)';
    g.beginPath();
    g.arc(Math.cos(ang) * rad, Math.sin(ang) * rad, pr, 0, Math.PI * 2);
    g.fill();
  }
  g.strokeStyle = 'rgba(255,255,255,.8)';
  g.lineWidth = 2;
  g.beginPath(); g.arc(0, 0, b.r * 0.74, -2.5, -1.35); g.stroke();
  g.restore();

  // 气条：球快散了要看得出来
  const lifeK = b.life / NUM.ball.life;
  if (lifeK < 0.55) {
    g.strokeStyle = lifeK < 0.25 ? '#FF9E8E' : '#FFD08A';
    g.lineWidth = 3;
    g.beginPath();
    g.arc(b.x, b.y, b.r + 6, -Math.PI / 2, -Math.PI / 2 + Math.PI * 2 * lifeK);
    g.stroke();
  }
}

/* 站在井梯顶端、头顶的洞口敞着时，给一个「W ↑ 爬上去」的小提示。
   **这是"能上能下"的可发现性。** 玩家看到的只是一列顶到天花板的箱子，
   光看图不会知道"按 W 能爬"；而提示只在他**真的能爬**的时候出现，
   所以既不会变成常驻噪音，也不会骗人。 */
/* 球停在旁边时，告诉玩家"怎么推"。
   **用户 2026-10-28 的原话是「成球之后怎么推呢」—— 这是提示缺失，不是机制缺失。**
   推法本身一直存在（`pushBalls`：朝球的方向走过去撞它，助跑更猛），但画面上
   一颗静止的雪球和一块石头没有区别，玩家不会想到"用身体撞"。
   条件收得很窄，只有三条同时成立才出：
     ① 球几乎是停的（|vx| < 140）—— 滚起来的时候不需要提示；
     ② 玩家就在旁边（横向 110px、纵向 90px 内）—— 远了不提示，避免全场刷屏；
     ③ 只给**最近的那一颗** —— 三颗球各挂一个气泡是噪音不是提示。 */
function drawBallHint(g) {
  const p = S.p;
  if (!p || S.phase !== 'play') return;
  /* 出图开关：评审图里这个气泡正好压着主角（人站在球上时它必出），
     和 `S.showMeter` 一样只在工具里关。 */
  if (S.showHint === false) return;
  let best = null, bestD = 1e9;
  for (const b of S.balls) {
    if (b.dead || Math.abs(b.vx) > 140) continue;
    const dx = b.x - (p.x + p.w / 2), dy = b.y - (p.y + p.h / 2);
    if (Math.abs(dx) > 110 || Math.abs(dy) > 90) continue;
    const d = Math.abs(dx) + Math.abs(dy);
    if (d < bestD) { bestD = d; best = b; }
  }
  if (!best) return;
  const b = best;
  const dir = b.x > p.x + p.w / 2 ? 1 : -1;
  const txt = '走过去顶它';
  const tw = 96, th = 23;
  const bx = clamp(b.x - tw / 2, 6, W - tw - 6);
  const by = b.y - b.r - th - 8;
  const a = 0.72 + 0.28 * Math.sin(S.t * 5);
  g.save();
  g.globalAlpha = a;
  g.fillStyle = 'rgba(20,32,40,.74)';
  rr(g, bx, by, tw, th, 11); g.fill();
  /* 一头小尖角指向球，读起来才像"这话是说这颗球的" */
  g.beginPath();
  g.moveTo(b.x - 5, by + th); g.lineTo(b.x + 5, by + th); g.lineTo(b.x, by + th + 6);
  g.closePath(); g.fill();
  g.fillStyle = '#EAF6FF';
  g.font = '700 13px "PingFang SC","Microsoft YaHei",sans-serif';
  g.textAlign = 'center';
  g.fillText(txt, bx + tw / 2 - 9, by + 16);
  /* 推的方向 */
  g.strokeStyle = '#9BE86E'; g.lineWidth = 2.4; g.lineCap = 'round';
  const ax = bx + tw - 16 + dir * 3;
  g.beginPath();
  g.moveTo(ax - dir * 5, by + 8); g.lineTo(ax + dir * 4, by + 11.5);
  g.lineTo(ax - dir * 5, by + 15);
  g.stroke();
  g.restore();
}

function drawClimbHint(g) {
  const p = S.p, L = S.level;
  if (!p || !L || S.phase !== 'play') return;
  if (!wellClimb(p)) return;
  /* **气泡默认画在头顶，可梯顶离天花板只有 14px。**
     3 格梯（144）+ 身高 42，头顶到上一层楼板**底面**的净空就是
     200 − 144 − 42 = 14px，而气泡要 36px —— 直接画上去会整个跑进
     上一层房间，看着像"楼上有人在喊"。头顶塞不下就挪到**身侧**：
     梯子旁边那列只垫 1 格（48），身体高度上是空气，气泡压在
     奶白墙上最清楚；挪到脚下会变成"贴在箱面上的一张标签"，
     语义反而指向下面的箱子。 */
  let room = 999;
  for (const fy of L.floors) {
    if (fy < p.y - 2) room = Math.min(room, p.y - (fy + GEN.thick));
  }
  let hx = p.x + p.w / 2 - 36, hy = p.y - 36;
  if (room < 38) {
    hy = p.y + 2;
    hx = p.x + p.w + 6 + 72 <= W ? p.x + p.w + 6 : p.x - 78;
  }
  const a = 0.7 + 0.3 * Math.sin(S.t * 5);
  g.save();
  g.globalAlpha = a;
  g.fillStyle = 'rgba(20,32,40,.74)';
  rr(g, hx, hy, 72, 23, 11); g.fill();
  g.fillStyle = '#CFEFFF';
  g.font = '700 13px "PingFang SC","Microsoft YaHei",sans-serif';
  g.textAlign = 'center';
  g.fillText('W ↑ 爬上去', hx + 36, hy + 17);
  g.restore();
}

/* ============================================================================
   贴图版主角：直接贴 `grove/pet/cat.png`
   ----------------------------------------------------------------------------
   这套是从 `prototype/grove.html` 的 `drawPetSprite` 搬过来的，
   连同它踩过的三个坑一起搬 —— 那几个数字不是调出来的，是量出来的：

   ① **按体高缩，不按图高。** 六张图统一高 292，其中脚底到头顶只占 0.656，
      顶上那一段是耳朵和给耳朵的留白。直接按图高缩，身体只有该有的 65.6%，
      六只集体缩水三分之一，站在怪旁边像只幼崽。
   ② **原图朝左。** 翻转判据是 `face > 0` 不是 `face < 0` ——
      写反的那版是"向右跑、脸朝左"，玩家一眼看出在倒着走。
   ③ **出手闪白用 filter 提亮，不是盖白矩形。** 盖矩形会在角色周围留一圈白框。
      系数 0.8 不是 1.8：1.8 会把橙猫提成白猫，读作"换了只宠物"。

   走路不用整只上下蹦（那是跳），是**同一张站立图切三块**、
   绕髋关节前后对摆，身体反方向轻前倾。 */
const PET_BODY_K = 0.656;   // 体高 / 图高
/* **这个系数由"视觉宽 = 一箱宽"倒推，既不是 grove 的 0.78，也不是 1.0。**
   它定义的是「画出来的**体高** / 碰撞高」。

   上一轮取 1.0（体高 = 碰撞高），只对了高度、宽度没人管 ——
   体高 63 撑起来，视觉宽就是 63/0.656×0.716 = 68.7，箱宽的 1.43 倍。
   用户一句"比箱子大 没办法独立站一个箱子的空格"才把它问出来。

   现在按宽度倒推：要视觉 ≤ 48（= 一箱宽），图高 = 48/0.716 = 67，
   而碰撞高 63 不变，所以 63×k/0.656 = 67 → k = 0.70。
   验证：视觉 48.1 宽、55.2 高（含耳朵），箱 48。
   **代价**：体高 44.1 比碰撞高 63 矮 18.9px —— 但视觉总高 55.2 是靠
   耳朵撑起来的，看起来仍比箱子高。碰撞发生在身体上，眼睛看到的是整只。 */
const PET_VIS_K = 0.70;

/* ---- 当前角色 ----
   **这是"换哪只宠物"的唯一开关。** 贴图键是 `pet-` + HERO_ID，
   和 `GroveBattle.ts` 的 ART_MANIFEST 同一套名字（`pet-cat` / `pet-dog` …）。
   以前这里写死 `artOf('pet-cat')`、下面又写死 `'cat'`，两处各改一次就等于
   埋一个"换了角色但走路切腿还是照着猫切的"的坑 —— 猫的髋线 0.87，
   狗是 0.90，差这一点腿就从膝盖断开。 */
const HERO_ID = 'cat';

/* ---- 出手的后坐力（2026-10-28 第四轮）----
   原来出手只有"手上闪一下白"，身体一动不动。闪白读作**"打中了"**，
   不是"我推了一把" —— 少了后坐力，出手在体感上是没有重量的。

   补的是位移，不是姿态：出手后 0.18 秒里，身体沿**朝向的反方向**退
   4.4px、往下压 1.5px，用 `k²` 缓出收回（前段快、尾巴慢，收得像弹簧）。
   30~60px 的角色上，位移比换一张姿势图更有说服力，也不用加状态机。

   **做成函数是为了能断言。** 纯视觉的东西如果没有出口，回归时只能靠眼睛，
   而 4px 的位移在 600px 高的画面上根本看不出来 —— 那种"改坏了没人发现"
   的项，不如一开始就留个量具。 */
function recoilOffset(p) {
  const k = p.shotAnim > 0 ? clamp(p.shotAnim / 0.18, 0, 1) : 0;
  const r = k * k * 4.4;
  return { dx: -p.face * r, dy: r * 0.32 };
}
/** 站立图上前后腿的切法。原图都朝左，split 左侧是前腿。
    hip 是髋在图高上的位置（0 = 图顶，1 = 脚底），对着不透明像素量的。 */
const WALK_CUT = {
  cat: { hip: 0.87, split: 0.54 },
  dog: { hip: 0.90, split: 0.55 },
  fox: { hip: 0.87, split: 0.48 },
  ham: { hip: 0.93, split: 0.55 },
  ox:  { hip: 0.84, split: 0.55 },
  rab: { hip: 0.88, split: 0.52 },
};

function drawPetSprite(g, img, x, footY, w, h, face, A, o, id) {
  const sq = o.squash || 0;
  const dh = h * PET_VIS_K / PET_BODY_K * (1 - sq * 0.14);
  const dw = dh * ((img.width || img.naturalWidth) / (img.height || img.naturalHeight)) * (1 + sq * 0.16);

  g.globalAlpha = 1 * A;
  g.save();
  g.translate(x, footY);
  if (face > 0) g.scale(-1, 1);      // 原图朝左
  if (o.flash > 0) g.filter = "brightness(" + (1 + o.flash * 0.8).toFixed(2) + ")";

  /* 查不到就走猫那套 —— 宁可髋线不准，也不要整只不动（后者读作"卡住了"） */
  const cut = o.stepping && (WALK_CUT[id] || WALK_CUT.cat);
  if (!cut) {
    g.drawImage(img, -dw / 2, -dh, dw, dh);
    g.restore();
    g.globalAlpha = 1;
    return;
  }

  const hipY = -dh * (1 - cut.hip);
  const xL = -dw / 2;
  const xR = dw / 2;
  const split = xL + dw * cut.split;
  const swing = Math.sin(o.gait || 0) * 0.95;
  const rock = Math.sin(o.gait || 0) * 0.10;
  const yTop = hipY - 2;
  const legH = 8 - yTop;

  function part(x0, y0, rw, rh, rot, px, py) {
    g.save();
    g.translate(px, py);
    g.rotate(rot);
    g.translate(-px, -py);
    g.beginPath();
    g.rect(x0, y0, rw, rh);
    g.clip();
    g.drawImage(img, xL, -dh, dw, dh);
    g.restore();
  }

  part(split - 3, yTop, xR - split + 8, legH, swing, (split + xR) / 2, hipY);
  // 身体只压过髋线 3px。再往下会把站立的脚也画出来，和摆出去的腿叠成两双脚。
  part(xL - 4, -dh - 8, dw + 8, hipY + 3 - (-dh - 8), -rock, 0, hipY);
  part(xL - 6, yTop, split - xL + 8, legH, -swing, (xL + split) / 2, hipY);

  g.restore();
  g.globalAlpha = 1;
}

function drawPlayer(g, p) {
  const cx = p.x + p.w / 2;
  const by = p.y + p.h;           // 脚底
  const face = p.face;
  /* **跑动相位只算一次，腿 / 身体起伏 / 尾巴都读它。**
     各算各的话，腿在摆、身体纹丝不动，读起来像"下半身脱节" ——
     这是最容易被一眼看穿的假。
     `moveK` 把起步和刹车平滑掉：直接写 `running ? sin : 0` 的话，
     一松键腿就从半空"啪"地弹回中位。 */
  const moveK = clamp(Math.abs(p.vx) / 200, 0, 1);
  const ph = S.t * 16;
  const step = Math.sin(ph) * moveK;
  const bob = Math.abs(Math.sin(ph)) * 1.2 * moveK + Math.sin(S.t * 2.1) * 0.4;

  /* 出手的后坐力，见 `recoilOffset`。抽出去是因为断言要能量它 ——
     纯视觉的东西没有出口，回归时只能靠眼睛，而 4px 在 600px 画面上看不见。 */
  const rc = recoilOffset(p);
  const dxR = rc.dx, dyR = rc.dy;

  g.save();
  const blinkA = S.invuln > 0 && Math.floor(S.invuln * 14) % 2 ? 0.45 : 1;
  g.globalAlpha = blinkA;

  /* ---- 影子：**永远落在地面上，不跟着人飞** ----
     原来画在脚底（`by - 1`），一跳影子就跟着上天。可影子是玩家判断
     "我离地多高"的唯一尺子 —— 它跟着人走，这一跳就没有参照了。
     现在按 `groundAt` 找真正的地面，离地越远越小越淡。 */
  const gy = groundAt(cx, by + 6);
  const drop = clamp(gy - by, 0, 240);
  if (drop < 232) {
    const k = 1 - drop / 240;
    g.globalAlpha = blinkA * 0.34 * (0.32 + 0.68 * k);
    g.fillStyle = '#33281F';
    g.beginPath();
    g.ellipse(cx, gy - 1.5, 17 * k + 4, 4.8 * k + 1.4, 0, 0, Math.PI * 2);
    g.fill();
    g.globalAlpha = blinkA;
  }

  /* ---- 有贴图就贴图，代码图形退成回退路径 ----
     `stepping` 不只看速度，还要看 `onGround`：在空中切腿会读成"在跑步机上"。
     `flash` 用手上的出手计时归一化到 0~1，`drawPetSprite` 内部再乘 0.8。 */
  const petArt = artOf('pet-' + HERO_ID);
  if (petArt) {
    drawPetSprite(g, petArt, cx + dxR, by + dyR, p.w, p.h, face, blinkA, {
      squash: p.onGround ? 0 : clamp(-p.vy / 900, 0, 0.5),
      flash: p.shotAnim > 0 ? clamp(p.shotAnim / 0.18, 0, 1) : 0,
      stepping: moveK > 0.15 && p.onGround,
      gait: ph,
    }, HERO_ID);
    g.globalAlpha = 1;
    g.restore();
    return;
  }

  /* 后坐力在这里生效：先平移，再进 ART_K 那套缩放 —— 平移写在缩放**外面**，
     所以位移量是屏幕像素，不会被 1.5 倍放大。 */
  if (dxR || dyR) g.translate(dxR, dyR);
  g.translate(cx, by); g.scale(ART_K, ART_K); g.translate(-cx, -by);
  g.lineJoin = 'round';
  g.lineCap = 'round';

  /* ---- 尾巴 ----
     **原来是「10px 黑描边 + 6.6px 橙描边」的叠加笔法 —— 那是给线条用的，
     不是给有面积的形状用的。** 每边只剩 1.7px 彩边，中段又被身体和头盖住，
     露出来的上下两截就成了一根纯黑的弯棍，从左边绕到头顶 ——
     904px 的出图上，它比眼睛还显眼，像给猫扣了个铁丝头罩。用户说的
     "头部描边放大后显杂"有一半是它。

     形状类的东西统一走**闭合路径 fill + stroke**：内填充是面不是线，
     描边宽度只负责轮廓，再细也不会让整块变黑。 */
  const wag = Math.sin(S.t * 7 + p.runD * 0.4) * 0.55;
  g.beginPath();
  g.moveTo(cx - face * 9.0, by - 7 - bob);
  g.quadraticCurveTo(cx - face * 25, by - 10 + wag * 2 - bob,
                     cx - face * 28, by - 22 + wag * 3 - bob);        // 上缘：外拱
  g.quadraticCurveTo(cx - face * 29.5, by - 31 + wag * 4 - bob,
                     cx - face * 22, by - 30 + wag * 3 - bob);        // 圆头（不是尖）
  g.quadraticCurveTo(cx - face * 18, by - 20 + wag * 2 - bob,
                     cx - face * 9.0, by - 3 - bob);                  // 下缘收进臀部
  g.closePath();
  g.fillStyle = COL.cat; g.fill();
  g.strokeStyle = COL.ink; g.lineWidth = 2.8; g.stroke();
  /* 尾背一条亮线：尾巴是圆的，没有它就是一弯月牙贴片。 */
  g.beginPath();
  g.moveTo(cx - face * 11.0, by - 9 - bob);
  g.quadraticCurveTo(cx - face * 23, by - 14 + wag * 2 - bob,
                     cx - face * 26.4, by - 24 + wag * 3 - bob);
  g.strokeStyle = 'rgba(255,246,228,.55)'; g.lineWidth = 2.2; g.stroke();
  /* 尾根一片暗：**尾巴和身体同色时必须靠这一笔分开**，
     否则从剪影上读，尾巴是身体侧面长出来的一只手。 */
  g.beginPath();
  g.moveTo(cx - face * 9.0, by - 7 - bob);
  g.quadraticCurveTo(cx - face * 16, by - 12 + wag * 2 - bob,
                     cx - face * 9.0, by - 3 - bob);
  g.closePath();
  g.fillStyle = 'rgba(120,80,40,.22)'; g.fill();

  /* ---- 腿：**原来根本没有腿** ----
     42px 的时候藏得住（身体椭圆正好贴地），放大到 63 之后，
     "一颗圆球浮在影子上方"就露馅了。两条短腿顺便给了跑动一个能读的节奏：
     远侧腿压暗、近侧腿用主色，前后关系立刻出来。 */
  /* **脚掌必须露在身体外面。** 第一版腿顶在 `by - 5.2`、身体底在 `by - 2.5`，
     只有 2.7px 露头，再被描边一压就彻底看不见了 —— 画面上是一个圆球直接
     "坐"在地上。现在身体整体上移两格，腿从 `by - 10.8` 垂到脚底，
     露出 5 个像素，站立时能看见两只脚掌、跑动时能看见交替抬起。 */
  for (const L of [{ dx: -6, up: Math.max(0, step) * 2.6, dark: true },
                   { dx: 6,  up: Math.max(0, -step) * 2.6, dark: false }]) {
    g.beginPath();
    g.ellipse(cx + L.dx * face, by - 5.4 - L.up, 4.6, 5.4, 0, 0, Math.PI * 2);
    /* **脚掌是白的**（立绘四只爪都是白手套）。原来跟身体同色，
       整只猫从胸到脚是一个橙色团子 —— 立绘里"白袜子"正是把腿
       从身体里分出来的那条线，成本只有一次改色。 */
    g.fillStyle = L.dark ? COL.pawDark : COL.paw;
    g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.6; g.stroke();
  }

  g.save();
  g.translate(0, -bob);

  /* ---- 身体：径向渐变，光从左上来 ----
     **整个场景共用"左上"这一个方向**（箱子顶面、球上的亮斑、敌人都是）。
     光源不统一的时候，每个物件单独看都还行，拼在一起就是拼贴画。 */
  const byy = by - 17;
  /* **主角也走硬边色块，和敌人同一套。**
     原来是径向渐变（catLight → cat → catDark）—— 那是厚涂；
     敌人这一轮已经换成 Q 版的两层硬边，主角要是还留着渐变，
     两者放在一起就是"两个画风拼在同一屏"（上一版出图里那只橙色猫
     明显比旁边的甲虫"软"）。这里直接复用 `foeCel`：
     它只认 { lit, body, shade } 三个颜色，跟是不是敌人无关。 */
  g.beginPath(); g.ellipse(cx, byy, 13.4, 11.8, 0, 0, Math.PI * 2);
  g.fillStyle = COL.cat; g.fill();
  foeCel(g, cx, byy, 13.4, 11.8, { lit: COL.catLight, body: COL.cat, shade: COL.catDark });
  /* **描边前必须重建路径。** `foeCel` 内部有两次 `beginPath()`，
     退出时留在上下文里的是它最后画的**那个偏移椭圆**
     `(x - rx*0.20, y - ry*0.45, rx*0.93, ry*0.93)` —— 偏移到左上、还小一圈。
     直接 `stroke()` 描的是它，不是身体轮廓。
     头和身体各描一次这种偏移椭圆，两条错位的粗弧落在角色身上，
     从左边绕到头顶 —— 904px 出图上像给猫扣了个铁丝头罩。
     上一轮把"头部描边显杂"误判成描边太粗，就是这个原因：
     粗只是让它更容易看见，错才是它难看的原因。 */
  g.beginPath(); g.ellipse(cx, byy, 13.4, 11.8, 0, 0, Math.PI * 2);
  g.strokeStyle = COL.ink; g.lineWidth = 2.8; g.stroke();

  /* ---- 肚皮亮面 —— "圆球"和"有体积的小动物"之间最便宜的一笔。
     **它必须小，而且不能让开 cel 的暗面。** 原来是 7.4×5.8 的半透明浅色，
     几乎盖满身体下半部，正好和"下方一圈暗面"叠在一起 ——
     出图上是小腹上横着一条浅色带子，像围了条围裙。
     缩到 5.4×3.6 之后只是胸口一点暖光，暗面照旧露在下面。 */
  g.beginPath();
  g.ellipse(cx + face * 1.2, byy - 0.6, 5.4, 3.6, 0, 0, Math.PI * 2);
  g.fillStyle = 'rgba(255,238,212,.34)';
  g.fill();

  /* ---- 头（Q 版的比例就是"头比身体大"） ---- */
  const hy = by - 33;
  g.beginPath(); g.arc(cx, hy, 15, 0, Math.PI * 2);
  g.fillStyle = COL.cat; g.fill();
  foeCel(g, cx, hy, 15, 15, { lit: COL.catLight, body: COL.cat, shade: COL.catDark });
  g.beginPath(); g.arc(cx, hy, 15, 0, Math.PI * 2);   // 同上：描边前重建路径
  g.strokeStyle = COL.ink; g.lineWidth = 2.8; g.stroke();

  /* ---- 绿松领巾：**立绘上最强的识别物，之前完全没有** ----
     六只里只有砂糖戴绿松色三角巾（`sugar-stand@v1.png`）。它比配色更能认人：
     玩家在主界面看了一百次的东西，进战斗要能一眼对上。

     **必须画在头之后。** 第一版按"身体之后、头之前"的顺序画 ——
     那是真实遮挡关系，可 Q 版没有脖子：领巾整块落在头的圆里，
     被头吃得一点不剩，出图上一格绿都没有。
     所以顺序上让它压住头的下沿：上沿 ±13.2 正好等于头在 `by-21`
     处的半宽 13.5，弧线就贴着下巴走，读作"系着"而不是"贴在脸上"。 */
  const sy = by - 21.0;
  g.beginPath();
  g.moveTo(cx - 13.2, sy);
  g.quadraticCurveTo(cx, sy + 3.4, cx + 13.2, sy);
  g.quadraticCurveTo(cx + face * 6.6, sy + 9.0, cx + face * 1.6, sy + 12.2);
  g.quadraticCurveTo(cx - face * 3.6, sy + 8.6, cx - 13.2, sy);
  g.closePath();
  g.fillStyle = COL.scarf; g.fill();
  g.strokeStyle = COL.ink; g.lineWidth = 2.4; g.stroke();
  /* 下尖压一档暗 —— 领巾本身也要有正反两面，否则是一块平绿。 */
  g.beginPath();
  g.moveTo(cx + face * 1.6, sy + 12.2);
  g.quadraticCurveTo(cx + face * 6.6, sy + 9.0, cx + 9.0, sy + 3.0);
  g.quadraticCurveTo(cx + face * 4.0, sy + 7.6, cx + face * 1.6, sy + 12.2);
  g.closePath();
  g.fillStyle = COL.scarfDark; g.fill();

  /* 头顶高光：**不描边的亮椭圆，压在描边内侧**。有它才有"球"的感觉，没有就是圆片。 */
  g.beginPath();
  g.ellipse(cx - 5.5 * face, hy - 8.6, 5.4, 3.0, -0.5 * face, 0, Math.PI * 2);
  g.fillStyle = 'rgba(255,250,238,.42)';
  g.fill();

  /* ---- 耳朵（左耳亮、右耳暗 —— 跟着左上光） ----
     **这里原来还留着一条线性渐变**（catLight → catShade）。整只主角改成
     硬边 cel 之后，只剩耳朵还是厚涂 —— 出图上两片耳朵比脸"软"。
     Q 版判据是边界：同一只角色身上不该同时存在渐变和硬边。
     改成两档纯色，光向照样是左上。 */
  for (const s of [-1, 1]) {
    g.beginPath();
    g.moveTo(cx + s * 12.4, hy - 6.4);
    g.lineTo(cx + s * 8.6, hy - 21.4);
    g.lineTo(cx + s * 1.2, hy - 12.2);
    g.closePath();
    g.fillStyle = s < 0 ? COL.catLight : COL.catShade;
    g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 2.6; g.stroke();
    // 耳窝：立绘是橘粉色，不是暗橙 —— 这一笔决定"耳朵是活的还是塑料的"
    g.beginPath();
    g.moveTo(cx + s * 9.6, hy - 8.6);
    g.lineTo(cx + s * 8.2, hy - 17.2);
    g.lineTo(cx + s * 4.6, hy - 11.4);
    g.closePath();
    g.fillStyle = COL.earIn; g.fill();
  }

  /* ---- 呆毛 + 脸侧毛毛 ----
     **轮廓不能是完美圆弧。** 光滑圆 + 粗描边 = 橡皮糖；两三处不规则的凸起，
     才读得出"这是一只有毛的动物"。这两笔是整张脸上性价比最高的。 */
  g.strokeStyle = COL.ink; g.lineWidth = 2.2; g.lineCap = 'round';
  g.beginPath();
  g.moveTo(cx - face * 3.2, hy - 14.2);
  g.quadraticCurveTo(cx - face * 6.4, hy - 19.6, cx - face * 1.6, hy - 20.4);
  g.stroke();
  g.beginPath();
  g.moveTo(cx + face * 4.4, hy - 13.6);
  g.quadraticCurveTo(cx + face * 8.0, hy - 17.4, cx + face * 6.2, hy - 19.8);
  g.stroke();

  /* 眼睛（白眼球 + 虹膜 + 双高光）。
     **眼心必须在头心之下 2px** —— 放头心（hy）时脑门只剩十几像素，
     缩略图下两只眼白会连成一整块白饼，读不出是眼睛。眼睛之间留 4.4px
     鼻梁，瞳孔偏移也从 1.3 收到 0.9：偏太多两只瞳都朝同侧，
     高光叠上去像两个「C」。

     **立绘的瞳仁几乎填满眼白，只留一圈极窄的白边。** 原来虹膜只有 3.0、
     眼白 4.6×5.4 —— 白多黑少，读起来是"瞪着的眼"，不是"水汪汪的眼"。
     六只立绘没有一只长那样。现在白 4.9×5.7、瞳 3.8，白边收到 1.1px。 */
  const ex = face * 3;
  const ey = hy + 2;
  for (const s of [-1, 1]) {
    const ox = cx + ex + s * 6.6;
    g.fillStyle = '#FFFCF6';
    g.beginPath(); g.ellipse(ox, ey, 4.9, 5.7, 0, 0, Math.PI * 2); g.fill();
    g.strokeStyle = COL.ink; g.lineWidth = 1.5; g.stroke();
    /* 虹膜：**不做纯黑瞳。** 纯黑放大之后是个洞；深棕渐变才有"玻璃珠"的厚度。 */
    const igr = g.createRadialGradient(ox + face * 0.2, ey - 1.2, 0.5,
                                       ox + face * 1.0, ey + 0.5, 4.2);
    igr.addColorStop(0, '#6B4528');
    igr.addColorStop(1, '#1C120A');
    g.beginPath(); g.arc(ox + face * 0.8, ey + 0.4, 3.8, 0, Math.PI * 2);
    g.fillStyle = igr; g.fill();
    /* 双高光：大的在左上、小的在右下。**两个都不能省** ——
       只有大高光时眼球是"玻璃球"，加一颗小的才有"湿"的感觉。 */
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(ox + face * 0.8 - 1.3, ey - 1.7, 1.5, 0, Math.PI * 2); g.fill();
    g.fillStyle = 'rgba(255,255,255,.62)';
    g.beginPath(); g.arc(ox + face * 0.8 + 1.5, ey + 1.9, 0.78, 0, Math.PI * 2); g.fill();
  }
  /* 腮红（眼睛下移到 ey 了，腮红跟着让位，否则糊在眼白上）。
     **必须 clip 在头部轮廓里。** 腮红中心在 ±(10.5+ex)=13.5、半径 3.4，
     外沿到了 16.9 —— 头半径才 15，于是每边都有一小块腮红溢到轮廓外面，
     挂在脸颊上像"沾了东西"。放大到 63 之后这条溢出比腮红本身还显眼。 */
  g.save();
  g.beginPath(); g.arc(cx, hy, 14.1, 0, Math.PI * 2); g.clip();
  g.fillStyle = 'rgba(255,128,104,.42)';
  for (const s of [-1, 1]) {
    g.beginPath(); g.ellipse(cx + ex + s * 10.2, hy + 8.5, 3.6, 2.3, 0, 0, Math.PI * 2); g.fill();
  }
  g.restore();

  /* 鼻 + 嘴。**有鼻子才叫"脸"。** 原来眼和嘴之间是一片空的橙色，
     放大之后那块空白是整张脸上最先被注意到的地方。

     **五官全部居中在 `cx + ex`，不再额外偏 `face`。** 第一版鼻嘴又加了
     一次 `face * 3`（`ex` 本身就是朝向偏移），结果整张脸朝前歪了 3px，
     ω 嘴正好压在右眼正下方 —— 放大图里那个"糊在眼睛下面的红块"就是它。
     ω 也不能用两条 `arc`：半圆的起止点接不上，会画成一个问号。
     两条从中心出发的二次曲线才对。 */
  const mx = cx + ex;
  g.fillStyle = '#B4553F';
  g.beginPath();
  g.moveTo(mx - 1.7, hy + 5.2);
  g.lineTo(mx + 1.7, hy + 5.2);
  g.lineTo(mx, hy + 7.0);
  g.closePath(); g.fill();

  if (p.shotAnim > 0) {
    g.fillStyle = '#8A3B2E';
    g.beginPath(); g.ellipse(mx, hy + 10.2, 3.9, 3.5, 0, 0, Math.PI * 2); g.fill();
  } else {
    g.strokeStyle = '#8A3B2E';
    g.lineWidth = 1.7;
    g.lineCap = 'round';
    g.beginPath();
    g.moveTo(mx, hy + 7.0);
    g.lineTo(mx, hy + 8.2);
    g.moveTo(mx, hy + 8.2);
    g.quadraticCurveTo(mx - 1.5, hy + 10.8, mx - 3.5, hy + 8.9);
    g.moveTo(mx, hy + 8.2);
    g.quadraticCurveTo(mx + 1.5, hy + 10.8, mx + 3.5, hy + 8.9);
    g.stroke();
  }

  g.restore();      // 撤掉 bob
  g.globalAlpha = 1;
  g.restore();      // 撤掉 ART_K
}

function drawHud(g) {
  g.save();
  const inClear = S.phase === 'clear';

  // 顶栏
  g.fillStyle = 'rgba(14,22,28,.62)';
  rr(g, 16, 14, W - 32, 52, 12); g.fill();

  g.textAlign = 'left';
  g.font = '700 15px "PingFang SC","Microsoft YaHei",sans-serif';

  // 弹药
  g.fillStyle = S.ammo <= 15 ? '#FF9E8E' : '#DFF2FF';
  g.fillText('弹药', 34, 47);
  g.font = '800 26px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillText(String(S.ammo), 78, 49);

  // 饱食度
  const bx = 160;
  g.font = '700 15px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillStyle = '#C8DCE6';
  g.fillText('饱食', bx, 47);
  g.fillStyle = 'rgba(255,255,255,.16)';
  rr(g, bx + 44, 33, 84, 14, 7); g.fill();
  g.fillStyle = S.belly >= NUM.bellyFull ? '#9BE86E' : S.belly >= NUM.bellyHalf ? '#FFD08A' : '#FF9E8E';
  rr(g, bx + 44, 33, 84 * clamp(S.belly / 100, 0, 1), 14, 7); g.fill();
  /* 只写「N发/只」，**不写档位词**。档位已经由条的颜色和三档数字表达，
     写成「满饱 · 每只要 3 发」有 104px 宽，正好压死右边的「体力」和圆点
     （体力在 344、圆点从 396 起）—— 上一版就是这么把两串字叠在一起的。 */
  g.fillStyle = '#EAF4F8';
  g.font = '700 13px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillText(snowNeed() + '发/只', bx + 136, 45);

  // 血
  const hx = 344;
  g.font = '700 15px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillStyle = '#C8DCE6';
  g.fillText('体力', hx, 47);
  for (let i = 0; i < NUM.hpStart; i++) {
    g.fillStyle = i < S.hp ? '#FF8B7A' : 'rgba(255,255,255,.18)';
    g.beginPath(); g.arc(hx + 52 + i * 17, 41, 6, 0, Math.PI * 2); g.fill();
  }

  // 击杀进度
  g.font = '700 15px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillStyle = '#C8DCE6';
  g.fillText('击杀', 490, 47);
  g.fillStyle = S.killed >= S.killedTarget ? '#9BE86E' : '#EAF4F8';
  g.font = '800 22px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillText(S.killed + ' / ' + S.killedTarget, 528, 48);

  /* 宝物。**这是"探索"唯一的量化反馈** ——
     只写"击杀"的话，玩家拆箱子的收益是看不见的，自然就不会去拆。 */
  g.font = '700 15px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillStyle = '#C8DCE6';
  g.fillText('宝物', 600, 47);
  g.fillStyle = S.loot > 0 ? '#FFD45E' : '#8FA8B8';
  g.font = '800 22px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillText(S.loot + ' / ' + S.lootTotal, 638, 48);

  /* 当前层。**有纵深的关卡必须告诉玩家"我在第几层"** ——
     迷路不等于探索，玩家不知道自己在哪只会烦躁。
     判定用头顶 y 落到哪两个地板之间，别写死边界。 */
  let layerIdx = FLOORS.length - 1;
  for (let i = 0; i < FLOORS.length; i++) if (S.p.y < FLOORS[i]) { layerIdx = i; break; }
  const LAYER_COL = ['#DFF2FF', '#CFE8F5', '#B9DCF0', '#9FCBE8', '#8FC4E4', '#9BE86E'];
  g.font = '700 15px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillStyle = '#C8DCE6';
  g.fillText('所在', 806, 47);
  /* 层数现在是随机的（4~8），所以这里必须写 `第几/共几` ——
     只写名字的话，玩家没法知道自己还剩多深，而这一关唯一的进度感就是深度。 */
  g.fillStyle = LAYER_COL[Math.min(layerIdx, LAYER_COL.length - 1)];
  g.fillText((layerIdx + 1) + '/' + FLOORS.length + ' ' + LAYER_CN[layerIdx], 846, 47);

  // 门的状态（和"所在"拉开 50px，不然两串字会读成一串）
  g.font = '700 14px "PingFang SC","Microsoft YaHei",sans-serif';
  const dHidden = doorBlocked();
  g.fillStyle = S.door && S.door.open ? '#9BE86E' : dHidden ? '#8FA8B8' : '#FF9E8E';
  g.fillText(dHidden ? '门·未找到' : (S.door.open ? '门·开着' : '门·锁着'), 712, 46);

  if (inClear) { g.restore(); return; }

  /* 试验台面板（量具，不是玩家 HUD）。
     **必须放右上角。** 原来放左下角，正好压住玩家出生点（x=60）——
     开局第一眼看到的是一块统计面板，不是自己的角色。 */
  /* 试验台面板（量具）。**压到 4 行、高 88** —— 6 行 / 120 高的版本
     在 L2 会盖住右上那块浮台上的箱子和怪，玩家以为那层是空的。
     量具只留三个真正要看的数：裹一只几发、碎箱分布、一球连碎几口。 */
  const st = S.stat;
  const panelX = W - 256, panelY = 82, panelW = 240, panelH = 88;
  if (S.showMeter) {
    g.fillStyle = 'rgba(14,22,28,.46)';
    rr(g, panelX, panelY, panelW, panelH, 10); g.fill();
    const avg = st.shotsPerCoat.length
      ? (st.shotsPerCoat.reduce((a, b) => a + b, 0) / st.shotsPerCoat.length).toFixed(1)
      : '—';
    const lines = [
      '试验台 · 裹一只 ' + avg + ' 发（' + st.coats + ' 只）',
      '碎箱 子弹 ' + st.boxByShot + ' · 球 ' + st.boxByBall,
      '一球最多连碎 ' + st.ballChainMax + ' 口 · 球杀 ' + st.killByBall,
    ];
    g.font = '600 12.5px "PingFang SC","Microsoft YaHei",sans-serif';
    g.textAlign = 'left';
    for (let i = 0; i < lines.length; i++) {
      g.fillStyle = i === 0 ? '#8FB0C0' : '#D6E6EF';
      g.fillText(lines[i], panelX + 13, panelY + 23 + i * 22);
    }
  }

  /* 操作提示。**开局 9 秒后淡出** —— 常驻的话它会一直压在地面层，
     左下那条路是玩家反复要走的。 */
  const tipA = clamp(9 - S.t, 0, 1);
  if (tipA > 0) {
    g.globalAlpha = tipA;
    g.fillStyle = 'rgba(14,22,28,.5)';
    rr(g, 16, 76, 330, 30, 8); g.fill();
    g.fillStyle = '#C8DCE6';
    g.font = '600 13px "PingFang SC","Microsoft YaHei",sans-serif';
    g.fillText('A/D 移动 · W 跳 · J 吐雪 · 走过去顶球 = 推 · R 换一关', 30, 96);
    g.globalAlpha = 1;
  }

  // 全饿提示
  if (bellyTier() === 'hungry') {
    g.textAlign = 'center';
    g.fillStyle = 'rgba(255,158,142,.95)';
    g.font = '700 15px "PingFang SC","Microsoft YaHei",sans-serif';
    g.fillText('全饿：每只要 ' + NUM.snowShots.hungry + ' 发 —— 去砸箱子吃碎片', W / 2, 124);
  }

  g.restore();
}

function drawClear(g) {
  g.fillStyle = 'rgba(10,18,24,.72)';
  g.fillRect(0, 0, W, H);

  /* 实体卡片。**不能只把字浮在暗化的画面上** ——
     背景里还有箱子、平台、敌人，"子弹碎箱 / 球碎箱"那一行正好压在
     箱子上，白字和木色糊在一起，数字读不出来。 */
  const cw = 460, ch = 424, cx = (W - cw) / 2, cy = 88;
  g.fillStyle = '#16232B';
  rr(g, cx, cy, cw, ch, 18); g.fill();
  g.strokeStyle = 'rgba(155,232,110,.32)'; g.lineWidth = 2;
  rr(g, cx, cy, cw, ch, 18); g.stroke();

  g.textAlign = 'center';
  g.fillStyle = '#EAF8FF';
  g.font = '800 38px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillText('进 门 了', W / 2, cy + 68);

  g.fillStyle = 'rgba(155,232,110,.7)';
  g.font = '600 14px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillText('这一屏的量具数据', W / 2, cy + 96);

  const st = S.stat;
  const avg = st.shotsPerCoat.length
    ? (st.shotsPerCoat.reduce((a, b) => a + b, 0) / st.shotsPerCoat.length).toFixed(2) + ' 发'
    : '—';
  const rows = [
    ['裹一只平均', avg],
    ['子弹碎箱 / 球碎箱', st.boxByShot + ' / ' + st.boxByBall],
    ['一球最多连碎', st.ballChainMax + ' 口'],
    ['剩余弹药', S.ammo + ' 发'],
    ['剩余饱食', Math.round(S.belly) + '（' + TIER_CN[bellyTier()] + '）'],
    ['总发弹数', st.shots + ' 发'],
  ];
  g.font = '600 17px "PingFang SC","Microsoft YaHei",sans-serif';
  for (let i = 0; i < rows.length; i++) {
    const y = cy + 138 + i * 36;
    if (i % 2 === 0) {
      g.fillStyle = 'rgba(255,255,255,.04)';
      rr(g, cx + 26, y - 21, cw - 52, 30, 6); g.fill();
    }
    g.textAlign = 'right'; g.fillStyle = '#8FA8B8';
    g.fillText(rows[i][0], W / 2 - 16, y);
    g.textAlign = 'left'; g.fillStyle = '#DFF2FF';
    g.fillText(rows[i][1], W / 2 + 16, y);
  }

  g.textAlign = 'center';
  g.fillStyle = '#7FA3B5';
  g.font = '600 15px "PingFang SC","Microsoft YaHei",sans-serif';
  g.fillText('按 R 换一关（布局每局随机）', W / 2, cy + ch - 24);
}

/* =========================================================================
   循环 + 测试出口
   ========================================================================= */
/* 主循环（`let last = 0; function loop(ts) {...}`）在这里被抽掉：
   进了 Cocos 由 SnowlabBattle.update(dt) 调 snowlabTick / snowlabRender。
   两条 rAF 一起跑会让步进变双倍速 —— 这类"手感忽然变快"最难查。 */

/* **启动交给 Cocos。**原型的启动段做了四件事：挂键盘、reset、起 rAF 自转、
   兜底画一帧。进 Cocos 之后 rAF 由组件 update() 驱动（不能两条循环一起跑，
   那会让步进变成双倍速），键盘监听留着 —— Web 构建里 window 是有的，
   而且它和原型是同一份代码，键位不会漂。

   `_domBound` 挡住重复挂监听：组件销毁重建（切场景再回来）会二次进这里，
   不挡就是一次按键走两遍 onKey。 */
let _domBound = false;
export function snowlabBoot(seed?: number): void {
  if (typeof window !== 'undefined' && !_domBound) {
    _domBound = true;
    window.addEventListener('keydown', (e: any) => onKey(e, true));
    window.addEventListener('keyup', (e: any) => onKey(e, false));
    window.addEventListener('blur', () => { S.keys = {}; });
  }
  snowlabInitBackdrop();
  snowlabInitArt();
  reset(seed as any);
}

/* **测试出口**。headless 断言全走这里 —— 逻辑不依赖 rAF，也不依赖 canvas。
   `WORLD_H / GROUND_Y / FLOORS / HOLES` 现在是**每关重新生成**的，
   所以必须用 getter 导出：写成字面量的属性会把第一关的值焊死在里面，
   断言在第二关就会拿到上一次的层高。 */
const API = {
  NUM, S, W, H,
  reset, newLevel, step, shoot, draw,
  genLevel, validateLevel, buildLevel, surfY, unreachableCols, ballPits, ballStuckCols,
  bellyTier, snowNeed, ballTier, ballR, ballPow,
  coatFoe, makeBallFrom, ballHitBox, shotBox, breakBox, hurtPlayer,
  checkDoor, doorBlocked, groundAt, stepDoor,
  /* 出图工具用：把单个箱子/门画到任意画布上（**只为评审，不参与游戏逻辑**）。
     道具（箱/桶/门）是这一版重画的重点，靠整关截图看不出"这一笔对不对" ——
     放大到 3~4 倍单独看才判得了。 */
  drawBox, drawDoor,
  /* `pet` 可选：测试要能点名"给我一只兔子 / 一只狗"。
     不传就按 kind 自动挑（见 breedOf），和生成器走同一条路。 */
  spawnFoe: (x, y, kind, breed) => {
    const f = makeFoe(x, y, kind, breed);
    S.foes.push(f);
    return f;
  },
  /** 直接造一颗球（绕过"先冻怪"），用来单独量"球砸箱"的数值 */
  spawnBall: (x, y, vx, absorbed) => {
    const n = absorbed == null ? 1 : absorbed;
    const b = { x, y, vx: vx || 0, vy: 0, r: ballR(n), absorbed: n, life: NUM.ball.life, onGround: false, chain: 0, hitCd: 0, dead: false };
    S.balls.push(b); return b;
  },
  /** 把玩家放到指定位置（测试站位用） */
  placePlayer: (x, y) => { S.p.x = x; S.p.y = y; S.p.vx = 0; S.p.vy = 0; },
  /* 出手后坐力（屏幕像素）。断言靠它守"出手有反馈"这件事。 */
  recoilOffset: (p) => recoilOffset(p || S.p),
  /** 每只敌人贴图在当前尺寸下的世界尺寸（宽 × 高）。给断言与出图工具用。
      **不能用眼睛量**：「敌方体态超过了箱子」这条是用户提的，
      而图上"看着差不多"和实际超没超，差 6px 就看不出。 */
  foeArtSize: (breed) => {
    const A = FOE_ART[breed];
    const im = A ? artOf(A.key) : null;
    if (!im) return null;
    const h = A.h;
    return { h, w: h * ((im.width || im.naturalWidth) / (im.height || im.naturalHeight)) };
  },
  /** 打 N 发雪弹到指定敌人（跳过物理飞行，直接命中） */
  hitFoeN: (f, n) => { for (let i = 0; i < n; i++) coatFoe(f, 1); },
  /** 出图工具用：把已解码的立绘塞进来（jsdom 没有 <img> 解码） */
  setBackdrop: (img) => { BG_IMG = img || null; },
  /** 出图工具用：注入宠物贴图。键名沿用 `GroveBattle.ts` 的 ART_MANIFEST
      （`pet-cat` / `pet-dog` …），两份清单用同一套名字，换角色时不会对不上。 */
  setArt: (map) => { for (const k in map) ART[k] = map[k]; },
};

/* 关卡结构走 getter：每关重新生成，导出时必须实时取。 */
Object.defineProperties(API, {
  /* 角色尺度走 getter：断言要能核对"形象和碰撞是同一个尺度" */
  ART_K: { get: () => ART_K },
  FOE_K: { get: () => FOE_K },
  GEN: { get: () => GEN },
  FOE_W: { get: () => FOE_W },
  FOE_H: { get: () => FOE_H },
  /* 敌人贴图的尺寸表。断言要靠它核「形象宽度 ≤ 0.85 × 箱子」——
     这条用眼睛量不出来（图上"看着差不多"就够了），只能算。 */
  FOE_ART: { get: () => FOE_ART },
  GROUND_Y: { get: () => GROUND_Y },
  WORLD_H: { get: () => WORLD_H },
  FLOORS: { get: () => FLOORS },
  HOLES: { get: () => HOLES },
  LAYERS: { get: () => LAYERS },
  LAYER_CN: { get: () => LAYER_CN },
  SEED: { get: () => LEVEL_SEED },
});

export const SNOWLAB: any = API;


/* ---------- Cocos 侧 API ----------
   原型里"取 canvas"和"起 requestAnimationFrame"是启动段的活；
   进了 Cocos 这两件事由 SnowlabBattle 组件接管，所以在这里开两个小口子。

   **dpr 在这里处理，不在组件里** —— 原型里那段 `cv.width = W * dpr` 就是
   在这一层做的；挪到组件里会让"原型和 Cocos 里的画面清晰度"变成两套开关，
   换机器就歪。后备缓冲 960*dpr、逻辑坐标仍按 960 画，绘制代码一行不动。 */
export function snowlabAttachCanvas(c: any): void {
  cv = c;
  const ratio = Math.min(2, (typeof window !== 'undefined' && (window as any).devicePixelRatio) || 1);
  c.width = W * ratio;
  c.height = H * ratio;
  ctx = c.getContext('2d');
  if (ctx) {
    /* `style` 不一定有：浏览器里的 <canvas> 有，`@napi-rs/canvas` 的没有
       （断言工具用的就是后者）。少了这个判断，工具一调就抛
       "Cannot set properties of undefined"。 */
    if (c.style) {
      c.style.width = W + 'px';
      c.style.height = H + 'px';
    }
    ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  }
}

export function snowlabTick(dt: number): void { step(dt); }
export function snowlabRender(): any { return draw(); }
